def create_test_database(db_path: Path):
    """Create a test database with sample products"""
    
    sample_products = [
        {
            "business_id": "H3JjbID9Zhukpqr9uupHAA", 
            "name": "Jackson's Bar & Bistro - Nashville", 
            "address": "1800 21st Ave S", 
            "city": "Nashville", 
            "state": "TN", 
            "postal_code": "37212", 
            "latitude": 36.1366299, 
            "longitude": -86.8004366, 
            "stars": 3.0, 
            "review_count": 402, 
            "is_open": 0, 
            "categories": "Burgers, Bars, Restaurants, Nightlife, American (New), Breakfast & Brunch, Lounges", 
            "hours": {"Monday": "11:0-22:0", "Tuesday": "11:0-22:0", "Wednesday": "11:0-22:0", "Thursday": "11:0-23:0", "Friday": "10:0-23:0", "Saturday": "9:0-23:0", "Sunday": "9:0-23:0"}, 
            "text": [["This makes my 6th or 7th time to Jackson's in the last 2 years and I thought that after tonight's visit they deserved a review. \n\nI had the panini Reuben.  Panini was amazing. Great use of garlic. Loved the cut of the meat. Not stringy but nicely chinked in thin slices. Cheese was well melted throughout the mix of kraut and meat. Rye Bread was wonderful. Would love to have it as a staple in my house. \n\nSalad came out same time as sandwich which was not good.\n\nPresentation was a little sloppy. \n\nLike every other place I have had a panini (except Panera where they do it right), the sandwich was served directly on a plate. Why don't they serve on a napkin? Particularly when they bring the salad out at the same time as the sandwich?  If the sandwich sits for more than a few moments, the bread gets soggy from the steam.  Nothing serious, but for the price, which is a little high, it seems lacking.  While the price is a little high, i think it is justified considering the food and drink quality. \n\nThey have a great selection of wines and beers that are likely to fit any palette.  \n\nWait staff have always been friendly. But you can tell this is a place where people are expected to hustle. Sometimes short or even distracted the service can be lacking. \n\nThe second time I visited was during a medium lunch rush and the wait time was 15 min to get drinks. My trip tonight it was about 8 min. For a sat night this is not bad. But not great either. My bartenders were awesome and never left me wanting (except for getting my salad with the main course).\n\nOverall a good experience and I will be back."], ["I've been here several times just cause I live in the area. Its kinda a scam ... or maybe its a joke.  Jackson's serves mediocre bar food at best, thats it.... mediocre at BEST.... and its way over priced for the quality and thought put into the dishes.  The bar is nice & I enjoy sitting outside when the weather is agreeable... but the service is pretty horrid.  If I didnt have previous restaurant experience and know what its like to work for tips, I wouldn't tip at all.  I have had several nights where I have walked in with a GROUP of friends and it has taken twenty plus minutes to get a drink order .... then another thirty minutes to get my dos perros to the table.  \n\nMoral of the story: Jackson's thrives off of there location ... Seriously, there is nothing impressive about there menu.  And there hipster prick servers add the topping on the pretentious asshole cake."], ["Will not go back. Food had close to zero taste. Chicken salad bowl. So bland. Biscuits and chicken. Dry. Fried green tomatoes. Hard. \nVery disappointed. Next time the pancake place across the street."], ["We were planning to go to the Pancake Pantry and then Fidos for a Sunday brunch but both were very crowded.   Jackon's is located between the two.  They have great omelets..  I had the ASAP and loved it-never had an omelette like it.  They also have Conecuh  sausage which was a surprise because it is a South Alabama thing.   We love this place and the service!!"], ["Fair food, fantastic patio, great patio, but always packed. The drinks, however, are AWESOME. My favorite? Tennessee stud - Moonshine, lemonade, splash of coke. If you're hungry, the Baltimore BLT is bacon and crab cakes. Sounds fine to me."], ["Found this place online as I am traveling across country with my dog. I was assured it was dog friendly and that they would do \"and and everything to accomodate my dog.\" I dont expect much. I walked in the front entrance and had 2 servers walk within inches of me by the door and look at me as if i was in the way. I walked to the bar and a really friendly brunette bartender was super friendly. Thats the only high point. The server made it clear that we were a burden; 6 different staff members watched me wait for what i thought was a single person bathroom which turned out to be a 6 stall room. I even asked and they told me to wait. Ive worked in F&B for 16 years. I would fire the entire staff minus the one bartender (black hair, rasta tattoo on her shoulder, rasta necklace on; she was cool.) and get this place in shape. what a shame......not to mention the rare tuna panini was beyond well done; nothing like a canned tuna panini and shitty, rude service."], ["I have a hard time imagining a better breakfast than the Chicken biscuits. We were seated with no wait and had great service. Perfect brunch."], ["Great service and phenomenal dessert. The gooey butter cake was delicious. The outdoor patio is pet friendly. Good vibes and good food!"], ["We originally came to eat at Pancake Pantry but it was raining cats and dogs. We didn't want to wait on the 2 hour line for just pancakes. So we looked around and noticed Jackson's. At this point, it was wet and cold and we didn't really care that much where we got a meal. \n\nFortunately, it was a good choice. We got seated right away and was quickly served a cup of Joe. At the time they were serving both breakfast and lunch menus. We all ordered breakfast, but the lunch dishes coming out of the kitchen looked mighty tasty too. I'm not sure if we were just glad to have food but overall the omelets and french toast were very good. Although, the hash browns is not what I consider to be hash browns. They were more like potato cubes."], ["Three things that are good about Jackson's:\n1. Patio\n2. Happy Hour\n3. Good location for after work drinks\n\nThe food really isn't worth the calories or the money. Last time I visited I ordered the Rio Roll which my waitress told me was the most popular torrad. What it was: flavorless grilled chicken, bland probably pre-prepared guacamole, and watery flavorless diced tomatoes, wrapped in a crispy on the outside, gummy on the inside spinach tortilla. Delicious? Not really. The side salad was good with the champagne vinaigrette which was heavy on the vinegar. I've had the nachos and I wouldn't order them again. \n\nWhy only three stars? It's not stellar. It's \"A-OK\". The 2 for 1 happy hour is nice and the location is a great starting point. I would just recommend whipping out your Yelp App if you start to get hungry."], ["Even one star is too much. Rude, slow and ignorant staff. We waited more than 45 minutes only for one scrambled egg. Finally one of the staff came and said that they could not make our order since they were so busy and apologized. However the restaurant was half-empty and quite. In the meantime, we saw customers that arrived after us but received their food and drinks earlier. Disgusting. I think this restaurant likes big orders. They put big orders in the priority. Unprofessional.\n\nI would never come back. Don't waste your time here. Try other places nearby"], ["Meh. It was ok. The meatloaf is more like medallions, and the tuna ahi salad was more like a steak . The place for was very noisy on a Friday night, and the crowd was very yound (as in 22 tops)"], ["3.5 stars \n\nI came here the other day for a lunch with my co workers. I ordered the Croque Monsieur (Brie is my fav cheese, so to see it in a sandwich, AND with french toast?! had to order it). Review: It was all right. It felt very homemade, which to some ppl is a good quality. However, when I go out and pay for my food, I like ordering things that I dont normally encounter in an every day kitchen or something that I can't make myself! The fries were really good though. thin, crispy, and hot right when they come out.\n\nMy friend took a risk from her usual order of the Sonora and ordered the Baltimore BLT. She said the Baltimore BLT was good (crab cakes yall) but the Sonora is still her fav (cajun seasoned shrimp with guac and pico de gallo). Another friend ordered the Tuna Salad which looked good! (Gonna order the salmon salad next time) he said it was great. Unlimited soft drinks refills if you order your stuff and pretty good (artsy grundgy) lookin dude servers. \n\nOverall an ok experience. but excellent service! Around $11 total plus tax and tip for my meal. Meh. A little more than I would've like to spend for lunch but this was fine. It was a great day out so we sat out on the porch and people watched. Bring your sunglasses when you come here in case it becomes a good day and you can sit out and do the same! Recommended if ur in the area and u want a nice relaxing chill sit down place to eat standard american fare. \n\nP.S. they don't have sweet tea.\nP.P.S. I've heard good good things about their Gooey Ooey Cake, must try for myself next time!"], ["Well, they get one star for having a really sweet server who was helpful and nice. But seriously, I wish we had just waited in line for an hour at the Pancake Pantry instead. After ordering, we sat for over an hour waiting for our food. When we finally got it, it was awful - my friend's hamburger was stone cold, my biscuits and gravy had congealed after hanging our under a heat lamp or something, and my other friends eggs were lukewarm. No garnishes on the plates, no toast with the eggs, nothing special. We didn't bother to complain because no one wanted to wait another hour for food. I was really disappointed because other people's food had looked really yummy when we were waiting to be seated. Maybe because of the Easter brunch rush? But really, just no excuse for crappy meals."], ["Wonderfully busy yet graciously homey atmosphere. I have been coming here a few times a month for the incredible Cajun-inspired Pasta Alfredeaux topped off with Cookie Dough Egg Rolls. Bring friends, bring a date, sit on the patio and people watch in this great area of Nashville."], ["The food here is so good, they have a great patio and the staff is very attentive and professional. We had Lindsey from Seattle as our server and she was  awesome. Steak frites and Eggs were AMAZING."], ["i got the rice bowl with salmon and it was okay. rice and fish were both a little dry but overall meal was great. the burgers looked amazing. next time that's what i'll be getting. the brussel sprouts as a side were also a big hit at our table!"], ["Eh. This place just doesn't do it for me. Hipster wonderland. Decent breakfast/brunch type fare. Good mimosas. A little pricey for my taste for what you get, but if the line to Pancake Pantry is ridiculous like it usually is, we'll head across the street here for a spot of brunch. The bigger reason for the 3-stars is more due to the fact that you are usually treated like you are in the way if you are clearly not a hipster when you go in. Sort of like you are bothering them... Just don't care much for attitude when I'm paying good money for a basic service."], ["Jackson's is the probably the best hang-over brunch cafe in Nashvegas! They even have a plate called the hang-over cure or something like that. They also have a good variety of options for food per their menu is the same throughout the day, night, shhhhiiit all day, every day! =] I've had a good amount food there and they're all pretty good. One thing that was questionable to me was one of their dessert. I forget the name, but i think it was fried cook dough egg rolls? Some peeps like it, but there were several of us not really feeling it, so it's a toss up. \n\nThe ambiance of this place is the patio looking at the corner of 21st and Belcort. The patio is especially nice Spring-Autumn, it doesn't matter what time. I've also chilled inside, but the real spot is the patio. Inside, like many other bars in Nashville, is smokey. I just can't deal w/ second hand smoke, it makes me sick. =P\n\nIf you stick to the patio you'll have a good time. It's a great place for people to eat, drink, chill, and people watch. Now is a great time to go and enjoy Jackon's. so... enjoy~!"], ["I came to Jacksons on a Friday afternoon for brunch and enjoyed a good meal with friends. The inside of the restaurant was completely full so we had to sit outside in the tented patio. I wasn't dressed warmly enough and wish they had better heaters in that area so we could have relaxed and enjoy our food a little more.\n\nOur waitress was very friendly and had a good knowledge of their beer list and recommended a great fall brew for me. All of the girls at our table got different entrees and we enjoyed tasting off of each others plates. I got the corned beer hash with a side of grits - though I ended up being too full to finish the grits. My only complaint about my meal was that the corned beer hash only came with one egg and it definitely needed two. I ended up mixing the onions, peppers, and meat into my grits so it wasn't so dry. \n\nOverall we enjoyed our experience but I would sit inside next time! And don't forget to get there early, it fills up fast."], ["I came today for brunch. I've been for dinner before and thought it was just okay, so I figured brunch couldn't be half bad. I was in the area, the weather was nice, and there was no wait, so we decided to stop.\n\nPros: dog friendly patio and a very nice (albeit slow) waiter. He also brought a bowl of water for said dog.\n\nCons: everything else\n\nService was very slow. Parties that ordered after us received their food first.\n\nWe ordered an omelet and the French toast. First of all, the French toast is deep fried. Nothing in the description on the menu alluded to the fact that I would be served deep fried bread for breakfast. In what world does French toast = deep fried bread? It only tasted like oil, and when I poked the bread oil just oozed out. So essentially you're eating oil soaked bread for breakfast. Drowning it in syrup didn't help with the flavor either. \n\nThe omelet also came out and was clearly covered in oil. Surprise surprise, it also just tasted like oil. It was served with 2 cold pieces of toast.\n\nUnless you enjoy eating oil for breakfast, you're better off waiting in line at Fido or heading down the street to J Christopher's. You'll get much better food for a similar (if not cheaper) price."], ["Nice little restaurant/ bar near Vanderbilt. Free parking for 1.5 hours (which is super awesome because there's barely any free parking in this town anymore!) service and food are good. Menu and drinks are also reasonably. The verde dip is one of my favs, as well as the gang feathers on a Caesar salad!"], ["Jackson's is near and dear to my heart for several reasons.\n\nMost importantly, they are in a wonderful location with a great atmosphere. Secondly, the guy who owns this place used to own rumba before it shut down (which evidently only shut down because it was too corporate on west end - probably with rent prices!) and the barros lucos was transported here magically! That is one great sandwich. That, coupled with their buffalo feathers and a cheese panini on the side? Done.\nEven better if you're there for half priced bottle of wine Sundays - super deal! Definitely my favorite day to go to wind down from the weekend. Sometimes it gets overly crowded/stuffed with obnoxious undergrads with popped collars and plaid shorts but generally speaking the atmosphere is awesome on a sunny day."], ["We were referred for the cookie dough egg roll..we decided to try for brunch, although I was very skeptical after reading these reviews. So happy we did not wait on the ridiculous line outside pancake pantry!\nThere was no wait here at 11 am on a beautiful Sunday morning. The bloody Mary's have topping choices!  I went with bacon and olives, my husband added pickled okra!  Delicious!  While the food was not quick to come out, it was time for me to enjoy my drink!\nOur food was hot and delicious- my husband and I had eggs and an omelet.  My boys LOVED the Reuben and French toast!!! The hash browns were good not great. The biscuits were awesome- sweet, and definitely not dry!\nThe mimosa- all 3 varieties were yummy!\nDessert - the cookie dough egg roll is unique and delicious. The butter cake was very good but very sweet and rich. So if you like that go for it.  I totally recommend this place for a great breakfast. Our server was extremely pleasant and attentive. This is my first trip to Nashville, and if I ever come back I would definitely revisit Jacksons."], ["Jackson's is the go-to option for my wife and I. Buffalo Feathers. That is the only small plate with which you should concern yourself. They're that good.\n\nI've had just about everything on their menu- the most memorable dishes being the Hangover Omelet, the Shrimp and Grits, and my absolute favorite, the Pimento Cheeseburger. So rich, so delicious. Well cooked, well seasoned, and served on a Provence bun. Amazing.\n\nMy wife always orders the Cajun Alfredo Pasta. Always."], ["Did not share a lot of other posters' experiences. Service was fast and friendly. The food was hot and flavorful. The grits and casserole were awesome sides and the biscuits were some of the best we've had in the south so far. Give this place a shot and you will be well-satisfied!"], ["Pretty decent food, friendly accommodating staff and dog friendly.\n\nHOWEVER, website states heated dog patio and it is not heated, not at all."], ["I'm very confused by all these \"Great Place for Brunch\" reviews...either Nashville has very low standards or I had a particularly bad brunch day.\n\nFirst, Jackson's brags about their patio A LOT. Bathroom stall doors, magazines, etc. I see advertisements RAVING about the patio. The patio ain't great. They really need fans, a screen/curtains, furniture that isn't broken lawn chairs. Nashville humidity = damp, hot, over-crowded patio and LOTS of flies squirming around your food. No bueno.\n\nThe drinks (both breakfast and non-breakfast) are superb. Their Bloody Marys are very good although some of the drinks are a bit overpriced for what they are. The overpriciness also applies to the food. Very very simple brunch dishes (eggs and bacon, omelets, etc) which are all rather overpriced. They also aren't all that creative for such a hip area and such a diverse evening menu. Definitely not great for vegetarian/fish...very meat-heavy, even for the south.\n\nI had the grits and the salsa/eggs/quesadilla. The grits are pretty great. The main dish,however, was sad. Only 1 egg and the quesadilla was small. The salsa seemed like it came out of a jar. I also found a very long hair in my eggs that was defs. not mine and the waiter didn't offer anything (free drink, re-do it, etc) other than a half-hearted apology.\n\nI must say...I had much higher hopes for this place."], ["The only thing more disgusting than the waiter's scabbed up hands was the food. Everything was cold and the biscuits & gravy arguably tasted worse than dog food. On top of all of this, the bathrooms were so filthy they resemble an underground abortion clinic."], ["My first experience with Jackson's was back in March, when I was traveling to Nashville for the first time with a bunch of friends who were Vandy grads. They love love love Jackson's from their time in college, and therefore it was literally our first stop of the weekend -- and it was wonderful. I wasn't sure what to expect, since it was a favorite from college days -- but the food was simply delicious.\n\nIt has a low-key easy vibe inside, with art from local artists for sale, and the Bistro description is perfect to describe the food. Not heaping portions, but I was stuffed at the end of the meal, and absolutely satisfied.   We started off with martinis which were delightfully strong and full of flavor, and headed for lunch at a table shortly thereafter. Since it was a celebratory weekend, we started with appetizers, and the spinach dip, and the pigs in blankets with the amazing spicy mustard went in seconds. All very flavorful, I just wish I could have had another bite -- and take gallons of the mustard home with me.\n\nHeading to lunch, I got the Rio Panini, and since I do love the standard thick bread one would think of for a panini, I was slightly sad to see white sandwich bread. It was a great sandwich, as were the fries, and the chips that I tasted off my friends plate. I think next time I'll go with the Rio wrap instead -- had ordering envy of my friends who went with that selection. But was in no way dissatisfied with my choice.\n\nI was back again in Nashville this weekend, and stopped again with a large group for lunch. I expected a wait, as the bistro was packed with World Cup fans, but they easily worked with us, and found us a table quickly. Again, each person in the group constantly remarked on the quality of the food, and each had a different drink -- mine, the misery & gin -- pear cider, st. germain ginger liquor, and Tanqueray, was light and refreshing -- perfect for a hot day.  This time, I got this shrimp wrap, and the chopped salad, and ate every morsel off my plate. The shrimp had a slight kick to it, and it had so many flavors in each bite, I savored it until the very end.\n\nI can say without a doubt that every time I'm in Nashville, I will absolutely be back for another boozy lunch at Jackson's!"], ["Me and a friend stop by for happy hour today and I was extremely disappointed and will not be back.  We arrived around 3:45pm on a Wednesday; they were in no way busy and we figured this would go smoothly. I order a glass of Merlot from a new male waiter.  A female waitress comes by and says she's training him and they are out of merlot.  I say that's okay and request a Cab instead; she returns and says they are out of Cab, I request the Pinot Noir, she returns again and says they are out of the Pinot Noir, I end up with the Malbec (4th choice). My friend got the 2 for 1 beer; in 90 degree heat (seated inside, but it's warm) she brings both beers at the same time.  After the food was delivered and finished, no one had checked on us.  I had to go to the bar to request a second glass of wine.  At this point there was a max of 6 people there with 3 at the bar.  The food wasn't good enough to make up for the lack of service.  I brought the lack of service to the \"bartenders\" attention and no one seemed bothered.  I won't be back; there's many places in Nashville with better food, better wine selection, and MUCH better service."], ["Great food and great service. Get the French Toast.   Best I have had.   Just came here for breakfast twice.   Great both times."], ["Jackson's is one of the bars on 21st Ave that is popular with Vandy students and locals alike.  The bar is on a corner the 21st and the West side of Belcourt Ave so they utilize all that people watching real estate by having windows all facing towards the street, and a large patio along 21st Ave that butts up right against the sidewalk. The place is fun because they get a good crowd of young people.  I think that is the secret to success at any place in the world.  Everyone goes to Jackson's to have drinks and just talk, so it gets very busy and very noisy. \n\nThey make nice mixed drinks here.  I had a pretty decent martini and even a Manhattan! So I think of this place as more of a drinks bar than a beer bar; they do serve beer, but you can get beer anywhere.  Order up a martini, sit on the patio, and people watch, it's good times."], ["FOOD WAS AMAZING!!! The wait staff was so nice and basically made seats for us so we could eat (it was very crowded). The price was affordable and the atmosphere was really nice"], ["I'm not one for bad reviews because I don't normally have time to complain about niche issues, but this restaurant was literally deplorable. \n\nMy French toast was white bread covered in batter, dropped in the same deep fryer they cook their fries, chicken, etc. I'm pretty sure the maple syrup was that corn syrup substitute stuff they give you at hospitals or whatever. I also had eggs and they were literally some of the most disgusting eggs I've ever eaten in my life. I prefer my college cafeteria eggs and that's saying something. This was 18$. I didn't even want to pay for it, probably one of the worst meals of my life. \n\nWe also waited around 45 minutes to get our food that apparently they put seconds into preparing. They literally throw these cooked substances on a plate and feed it to you. Staff was nice but the food was just so bad I couldn't see past it. \n\nBest part of the whole experience was how hard me and my friends were laughing about this train wreck of a Saturday brunch. \n\nAvoid avoid avoid."], ["Just this weekend, I went to Jackson's twice in 12 hours... first for a late night drink with friends and then turned around the next morning for a nice brunch. That should tell you just how versatile this Bar & Bistro is...  \n\nWith a great patio in the heart of the hopping Hillsboro Village, it's hard to stay away from Jackson's. There's always an eclectic mix of people day or night. \n\nMost importantly for me, I am a huge fan of the food and the drink selection! The menu has something for everyone! The brunch options are simple, but delish. Some of my friends commented that the presentation of the food was something to be desired, but I didn't really mind because I felt the taste made up for the lack of presentation. If I may make a recommendation...  the ahi tuna sandwich was delightful! \n\nThe bar menu offered at night is also pretty extensive, from sliders to different dips. Most of those items were great to share and under $10, including the Verde dip (some spinach, garlic, and cream cheese concoction) and the nachos! \n\nI hear the desserts are worth trying, so I can't wait til Jackson's and I meet again!"], ["Jackson's seems to be a college kid favorite. I've been there many a time and I have to say I do like their drinks, but the price is a bit much. They have a pomegranate margarita that has gotten me into trouble more than once though. The drink menu is very diverse that everyone can find something they like. \n\nAs for the food, I've never been a huge fan. Their chopped salad isn't very impressive and their torrados (kind of like a wrap that's been grilled like a panini) always give me the impression they'd taste better without the grilling. All their ingredients seem to be high quality, I guess I just dislike their cooking styles. As a Cajun fan I was also very disappointed by their Gumbo, they say it has okra in it but I didn't notice and there wasn't any rice that came with it. My friends love their fried Twinkie dessert but I wasn't impressed. The Cookie-Dough Egg Rolls are fantastic though. \n\nOverall, I love Jackson's. I love the ambiance, atmosphere and drink specials. I don't like going their for dinner, but dessert and drinks is always good."], ["It took me ages to actually eat here.  It always seemed just a bit pretentious.  Once we got around to trying it we were very happily surprised.  Very good food, good atmosphere, good time."], ["I have been to Jackson's on many occasions, some were memorable, some were not so memorable.  But one thing that always sticks in my mind is how nice their outdoor area is.  Seriously, it is right off of 21st avenue close to Vanderbilt.  For smokers this place is great because they have moderately priced drinks and some decent food.  It is not the best in the world, but if you want to sit outside and have some drinks with some buddies, there is no better place than this.  I give it 4 stars as opposed to 5 because the food is some times good and sometimes not so good.\n\nAttention smokers!  Look no further, this is the place, you are welcome here!"], ["The best thing this place has going for it are the beautiful people who eat there.  There is a very LA vibe.  The space inside is kind of cramped and hard to move through.  The patio is great.  The food is fine; unremarkable.  They once gave me an appetizer for free because it was the last one and didn't look as pretty as the rest."], ["I visited this place with my girlfriend this morning and we really enjoyed ourselves. We got there about 11:15 and didn't have to wait at all for a seat. We intentionally wanted to beat the church crowd. \n\nOnce we got seated on the patio, our server, Ally, was right there to get our bloody Mary's ready for us with her infectious energy and smile. (Good job Ally, you were awesome). The bloodys were good, no craft bloody or anything, but an A+ for being a standard bloody. \n\nThe food was spot on country cooking. I got be ASAP and my girlfriend got the Tennessee omelet. This was exactly as described. As Southern As Possible. Everything you want in an omelet and some gravy. \n\nOverall I would suggest this place to anyone looking for brunch in Nashville. This is definitely one of my favorite brunch spots so far."], ["I checked this place out with a couple of buddies, and a guy that we met at the hotel who happened to be a Saints fan as well. This place was suggested by the guy we met, and I can see why. The place has a cool vibe, and a mix of different seating areas. *****\n\nWe ordered the Verde Dip... Spinach and Garlic. The dip was great! The chips were half crushed, and when I brought this up to the waiter he mentioned that they must have come from the bottom of the container. He acted as if that statement made it okay that we got the crumbs at the bottom of the bag, so I then told him that it was interesting that he didn't think we should get decent chips. We'd already ordered some wine/drinks, so I figured he'd be willing to give us some decent service in hopes of a decent tip. The guy returned 7 or so mins later with some chips. I guess the guy gave us something to talk about, and he did try and hustle a bit more later in the evening. ***\n\nMy boys tried a mixed variety from the menu. Their only complaint came from a wrap. It just didn't live up to the expectations. Chicken, Guac, MJ cheese, and tomato. All great ingredients, but under seasoned.***\n\nI ordered the Shrimp and Grits. Part of my family is from NOLA, so I appreciated the good shrimp and sausage. The grits were good too. BUT it was over salted. It didn't ruin the meal, but I was hoping to finish on a high note. ***\n\nI'd rate them 3 1/2, but will give them a 4 since the night would have been better if the waiter wasn't a dumb@$$ during the beginning of the meal. Good times for the most part."], ["Went for breakfast. Not good! My meal came over-cooked. Sent it back and came back still over cooked. How hard is it to make eggs and bacon? Now I know why Fido was packed and Jackson's was half empty."], ["I'm sure this place is good for drinks, but we made the mistake of going here for brunch when we saw the line at Pancake Pantry. The only thing worse than the slow, poor service was the food. I could cry thinking about the disappointment. Do not make the same mistake!"], ["Service is not something this restaurant is concerned with. Not to mention, the time it took to get our food or check. Food was ok, drinks were good."], ["Jacksons is not my favorite restaurant but they seem to have managed to pull out that \"it's cool to be seen there\"  vibe so people keep going back and they have a good drink menu. The outdoor seating is nice as well so I can see the appeal there. However the food is just ho hum as is the service. \n\nThat being said, I have ordered several things on the menu and the only thing I have gotten that I like is the blackened Tuna sandwich. It's seasoned well and cooked rare so if you catch them on a good day, it's quite yummy. Otherwise, it's good. The cookie dough egg roll is disgustingly rich but you know I am surprised more people haven't thought of taking a roll of cooking dough, slathering it in breading, and deep frying it. \n\nStick with the drinks and dessert but if you must have lunch, go with the tuna.  If you are there for breafast and can't stomach the pantry line, then hit Fido, their eggs are delisch.."], ["I'll start by saying that the beer selection is great and the bar staff is wonderful every time we go there.\nTonight we decided to go for dinner and to try their food for the first time. My fiance's dinner (pasta) was excellent. I ordered a \"toasted\" sandwich that came out with soggy, mushy bread that was burnt black on the edges. The ham and brie inside were also overcooked and burnt black on the edges. I was very hungry and don't like to complain, so I picked the less-burnt ham and cheese out of the middle and left the rest on my plate as I nibbled on my fiance's dinner (there was plenty for both of us). I wasn't going to say anything- but the bartender noticed how awful it looked, apologized and took it to the manager. The manager refused to offer us any sort of compensation for the meal- even though it was their own staff who noticed how terrible it was.The bar staff apologized profusely and took care of us in the end, but not thanks to the management or chef who made the sandwich.\nI will continue to go to Jacksons for the friendly staff and excellent craft beer selection. I highly doubt that I will ever return for the food or to be treated with such terrible customer service."], ["This place has pretty good food and an awesome spot.  However, the staff is RUDE and I have only had one nice server here.  I keep going because it is fun to sit on the patio and chill.  Also, there are not many vegetarian options to choose from.  Get a new staff and I'll give you more stars."], ["Yummy Shrimp & Grits! Buffalo feathers are delicious! The ambiance is fun and upbeat! Would recommend it!!"], ["I wound up eating here because every other spot in the area had a line out the door and I was starving.  Perhaps that should have been a hint.  There were only a handful of customers so I was seated quickly and service was prompt.  The food was edible, but not good.  My omelette was completely unseasoned and adding my own salt and pepper didn't improve the taste.  There was no side of fruit or hashbrowns to create a more filling meal, just stale white bread toast.  First of all, who still eats white bread and if that's the only option why would anyone want it stale?  Given the portion size and lack of flavor the price was too high."], ["If you like people watching, enjoy a great patio and enjoy half price bottles of wine on Sunday after 3; then this is your place.\n\nThe food is good, but I honestly can't say spectacular.  I am not a big fan of meatloaf but would recommend the barbecue meatloaf here.  I also love the Torrado's and for starters the sesame barbecue chicken is deli-sh.\n\nParking in Hillsboro village; well it is what it is.  Your options are street parking or in the evenings take advantage of the post office or church parking.  It is very noisy on the street with all the ambulances and fire trucks that usually go by.\n\nThe wait staff while a little peculiar on occasion do a great job keeping up with the flow of traffic; although there socialization skills could be refined!"], ["The breakfast potatoes with Swiss cheese and have been great had it not been swimming in oil. I like the concept but the execution was the issue. Same for the chicken and biscuits. The chicken was thick and tough and lacked seasoning. The biscuits were way too small for the chicken proportions.the server was friendly and attentive. The atmosphere is hip with nice music and local art on display."], ["It's Easter Sunday. The Pancake Pantry had a long, wrap around line so we decided to give this place a try. We were seated right away. There seemed to be a steady flow of food coming out. However, we didn't get our food until 40 minutes later. The waitress apologized for the delay. One of our plates was not hot. We ordered the Grand omelette and biscuits and gravy with side of eggs. The grand was not so grand in flavor.  I was disappointed. The side of eggs was burnt and the biscuits and gravy was cool (not hot) with good flavor but spicy (either not indicated on menu or we missed it). \n\nGoing to the bathroom was a challenge.  The walkway between the front door and bar area was a high traffic area as it was the only way to go from kitchen to the seating area by the open windows and outdoor seating. \n\nMaybe on any other day, with a different menu item would result in a 3 star rating but not today. The customer service was decent but nothing remarkable to mention."], ["Very poor first and only experience at Jacksons. \n\nIt was a busy Saturday right at lunch time. We walked in to find no entryway/hostess stand and stood uncomfortably in the middle of a busy dining area until the hostess arrived and told us we could sit at the bar or wait 30 min (she was seating a party of 2 as she was explaining this to us, which was odd). We sat at the end of the bar which doubles as a server stand/hostess area where 3 servers were polishing silverware and rolling napkins. They were complaining of needing a stiff drink rather which I found rude. \n\nOnce our food arrived we were let down. We had a chicken Caesar salad and a Reuben sandwich. Everything tasted bland but we did eat it. We noticed 2 other couples at the bar struggling with receiving the correct order and the long wait time on food. \n\nThis place was packed though! People seem to love it, so maybe we were missing something but regardless, we won't be back."], ["My daughter and i came here last night and had a very enjoyable dinner. We sat on the patio and though it was busy, our wait time wasn't bad, and our waitress made sure to stop by a few times to check in with us.\n\nWe started with the fried green tomatoes with a horseradish cream sauce. These were very well prepared; piping hot with a crunchy batter. Neither greasy nor burnt. I had the shrimp and grits and it was very good. Just a touch of heat, very smooth, and at least eight medium-sized shrimp. The gravy was a bit oily/greasy but that is to be expected, based on the dish. I would have preferred a little more grits to soak up the sauce, but in all it was nice.\n\nFor desert we shared the flash-fried wonton-wrapped chocolate chip cookie dough. Very rich and heavy! I am not a big fan of sweets or deserts, but my spoon kept slipping back into the dish. They served it with ice cream which provided another texture and cooled the wonton a bit. If you are a fan of any one ingredient listed in this desert, you really ought to try it.\n\nI can't give you a specific reason for less than five stars; there is no one reason. It is a nice, slightly trendy, restaurant that caters to the Vanderbilt students. Now I am scratching my head so there is this. The road is very heavily traveled and it often takes 10 minutes or more to move the few blocks before and after Jackson's. Certainly NOT the restaurant's fault, but it does impact dining experiences."], ["Ok so I'm gonna be honest and say I really only went here for the cookie dough egg roll because I saw a video on Facebook and knew I was going to be in Nashville and HAD to try it! Well, it didn't disappoint. We went and had brunch - I had the breakfast sliders which I thought were just ok because the biscuit was a little dry (not sure why most biscuits I had were dry). The portions were fairly small so I was able to get my dessert and enjoy it. The egg roll wrapper was odd but with the chocolate it really didn't taste any different. Glad I came across the Facebook video about this place"], ["i really like the food here, but the service is hit or miss.  i would definitely go if you have a bit of patience!  the cookie dough egg rolls are delicious, a definite recommendation!  when i ate meat, the best dish was the chicken salad torrado.  i also like their panini's and their cocktails!  have fun!"], ["Definitely a great place for brunch. I usually sit outside on the patio, so I can't say that much for the inside. (But hey, it's summer- flies do happen). \n\nYes, there is no hostess stand. Usually there's someone asking to help you in a couple of moments- so I can't knock that. \n\nNever really had a long wait- I know they get packed on the weekends. \n\nTheir omelette selection is fantastic- definitely worth it. Great mimosas as well. Service can be a little slow sometimes, but I've never had a bad experience here. It's usually one of my go-to spots to take friends from out of town, and they all love Jackson's too!"], ["When in doubt and you need a place to eat at on 21st Ave, just pick Jacksons.  Seriously, you won't regret it.  \n\nFirst off, it wins with a huge patio.  This is ground zero for people watching on 21st.  You can watch all the people buzzing about, getting to work, shopping, etc.  There are big tables and smaller tables so all types of parties can be accommodated outside.  \n\nThe second win is the menu.  Pretty much everything in this place is unique and tastes pretty darn good.  I love the Verde dip as an appetizer.  It is great for a big group of people, but some of my favorite dishes are the Panni Sandwiches.  You can really never go wrong with a Cuban with loads of pork and crisp pickles.  So good!  They also do a brunch too, so anyplace that believes in breakfast on the weekend completely scores.\n\nThe beer, wine and mixed drinks list is amazing.  Jacksons is committed to some serious high gravity beers like BBC Bourbon Stout, Victory Garden Monkey and Abbey.  They do have the good old standards like Yazoo and Jackaloupe on tap too.  The wine list is big and they do feature a wine of the moment for only $6 a glass.  This changes alot.  Jacksons is pretty innovative with drinks.  My favorites is the Misery and Gin:  Gin, Pear Cider, and Ginger is pretty different, but oh so good."], ["Not sure what happened to this place. When I moved to Nashville in 2001, it quickly became a favorite spot for me. I always wanted to take out-of-town guests here, chose it as the place to celebrate birthdays and even named my dog Jackson partially because I loved the place so much.\n\nDecided to drive up from Franklin to meet a friend here yesterday after not having visited in a few years since moving farther south. \n\nThe place was empty and dingy. The menus that were brought were stained and torn. The server was awkward and lingered uncomfortably every time he came to the table.\n\nMy friend ordered something with tuna, which the server was unsure if they still had. He returned to tell us that they were probably getting rid of all of their tuna dishes and that she would need to order something else (if the tears and stains weren't enough reason to reprint their menus, surely that would be?!) The spinach dip I ordered had been clearly microwaved... sort of microwave-burnt on the edges and cool in the middle.\n\nThe bartender was eating behind the bar (how they have a good health score is beyond me!). I got up to use the restroom at one point and passed the server and the cook who were on opposite sides of where food is picked up. They were both munching on something. I got back to my table and found that the server had brought me extra chips... and I can only assume given the timing and the fact that only one other table was in there, that what they had been munching on were my chips. Gross.\n\nWith so many amazing places to eat and spend time with friends in Nashville, I would never, ever recommend doing so here. They should call Gordon Ramsey ASAP if they want to keep their doors open. So disappointed."], ["Jackson's is all about the crowds that it draws; it's not about the service or the food.  I ended up there for lunch yesterday (it wasn't my first trip there and it won't be my last) because the line at Pancake Pantry was too long.  The food is average at best - I had the Ahi Tuna sandwich, which was overseasoned and dry.  I wouldn't order it again.  I have had good food there in the past.  But, the food is pretty hit or miss.  The service seems to be stretched thin, and unable to accomodate the large crowds they draw.  Don't expect quick service.  The atmosphere is pretty good, I do enjoy their patio.  This place is better than two stars, but there's not quite enough to earn that third one."], ["Great dog-friendly place to sit outside and have some beers and cocktails when the weather is nice. The food is uneven - fried green tomatoes need an overhaul - but the staff is friendly and helpful."], ["First the good: I like the location of Jackson's, as Hillsboro Village is a charming little neighborhood and right next to Vanderbilt, which makes it rather convenient as well. The food is ordinary, not bad, just not great. Last month, I made a request for a special occasion meal. I contacted the general manager in advance and found her to be rather rude, unaccommodating, and not very Nashville-like overall. While Jackson's is ok, there is nothing that spectacular about that I would go back until management changes. Too many other awesome places in Nashville to put up with that."], ["I love me some Jackson's.  It's one of those places that can be suggested for a meal and then I can immediately taste the exact food that I will be ordering.  In this case, it's the Rio roll torrado with the chop salad.  Food styles and prices vary significantly between menu items so there really is something for everyone.  They've also got an extensive drink menu.  As for desserts, I absolutely love the gooey butter cake.  I've had many good times sitting with friends on their outdoor patio, and one of my favorite things about the interior, aside from the wine on the wall and the beautiful artwork, is the fact that on pretty days they open the garage doors so that the whole place has a breeze.  This place definitely has a very distinctive culture in addition to delicious food, making it one of my favorite Nash-Vegas places to take out of town visitors."], ["Food was good (sunrise sliders) - even though I got bacon when i asked for sausage. Bartender seemed to rather be anywhere besides there taking care of guests. Used hands to put garnishes in drinks but never saw her(?) wash them."], ["I mostly liked this place for the atmosphere.  They have a huge patio out front that gets busy for weekday lunch... great people watching.  The crowd was a mix of yuppies and students, and the wait staff was extremely friendly.  My first experience with fried green tomatoes was here: delish.  I ordered a tuna salad sandwhich, which was good but not excellent.  I like that they used dill in it.  My friend enjoyed her BLT.  Overall, I'd say this is a nice relaxing place to enjoy a decent meal."], ["Love this place and the locAtion and the food for the most part! But my service this time was awful. Our server didn't greet us and made me feel like I was an inconvenience to him the whole time. Others around me had great service and people continued to get their food before my table. We waited a 50 minute ticket time and drinks were constantly sitting empty. AJ you need to either go find a job you love or suck it up and put on a smiling face for your guests. It is your JOB to serve guests.. If you can't do so... Then get out of  the service industry. Salmon was over cooked and so was the chicken."], ["Place was a 5-star 3 years ago , I am not sure what happened.  The Big Ben was good, but I also looked like my grandma made it and through it on a plate - the $3 side of sausage was 5 small shriveled up pieces of slim jims.  It sucks because I did like this place but now, will probably not come back."], ["I've postponed writing a review just because I have a soft spot for inaugural posts in general. However, seeing as that's not going to help anyone, I'm going for it.\n\nFor the most part, Jackson's works the Nashville grungy-hipster-organic vibe well. I like to imagine the designer of the space saying, \"Hey let's suspend a fireplace in the middle of the restaurant! And might as well bring in the corrugated steel, expose the wood beams, and turn off the lights too. Don't forget the garage door style cabana!\" By the end of the meal, this haphazard schematic made me long to be outside in the afternoon sun, but if the dark, loud, and crowded feel appeals to you, then this is the place to be.\n\nMy party and I were seated promptly, given the bustling Sunday afternoon crowd. Our waitress was friendly and quick. Our food, much less so. It was a good thing that my companions and I had a lot to talk about, because it took a noticeably long time for our food to come out. They even apologized twice and told us the food would be out soon. Ten minutes after that, our meal arrives from exactly three feet away from our table.\n\nI think the best way to describe this meal is in bite-sized thoughts. So, I ordered the Ahi Wasabi Caesar Salad and:\n Bite One: Oh, I miss sesame and boy, do I love the sesame crust.\n Bite Two: The salad looks unattractive. But I'll eat it.\n Bite Three: The salad is all right, but I think it's the dressing I like. I miss wasabi too. \n Bite Four: I thought I ordered my tuna medium rare, but it's definitely medium-well. Chewy, not smooth. \n Bite Five: I'll stick with the sesame crust.\n Bites Six through Eighty-Two: Repeat\n Bite Eighty-Three: Too much wasabi, too little lettuce. Too much over-done tuna, too little crust. I'm done.\n\nIt was all right, not too impressive, but then again I'm not easily impressed by food in Nashville anyway. The price range at Jackson's is pretty average too, especially in the Hillsboro area. The salad I had felt a tad bit more expensive ($11). A couple of my friends also had tuna, but in a sandwich, and that was at least $3 less, including fries. \n\nOverall, I'd say Jackson's is average to good. Not stand out, but solid.\n\nAnd with that, I've written my first review!"], ["Great place to bring your dog and hang out on the patio.  Service was friendly and attentive. Food wasn't perfect."], ["Came in for just drinks. Mimosas and Sangrias. Mimosa was overpriced for the amount that you got. Sangria was filled to the very top and pretty good. Nice place with cool artwork for sale. Looks like a fun place to come with friends. Staff was nice."], ["Went to this place only because the line was ridiculous at Fido, which I love.  That was my first mistake.  The food took a long time to come out.  There is no organization, rhyme or reason to this place.  Servers walk around really fast, looking very busy but never seeming to get anything done.  My Tennessee omelette was a game of Find the Sausage but the joke was on me because there was hardly any in it.  It was tasteless as well.  They claimed the Buffalo Feathers were their version of Hot Chicken.. no they weren't.  Perhaps they've never seen Nashville Hot Chicken before but it's not pale white chicken not breaded and in an oily sauce.  Our server must have walked past our table about 10 times when we needed something and at no point did anyone ever ask us if everything was Ok. So since they didn't ask, I'm putting this review here to tell you I won't be back and to tell everybody else to not make the same mistake I made and just wait on the line for Fido."], ["Jacksons is synonymous with weekend brunches, happy times, great patios and a decent adult beverage selection. \n\nLet me expand on the patio a bit - there's nothing more fun on a Sunday morning than sitting and watching all of the beautiful people walk around Hillsboro Village. The neighborhood itself is just so awesome it's to die for - when the weather is right (typically 80% of the time) - so many great surrounding shops and places to walk... Hillsboro you absolutely have my heart. \n\nThe menu is rock solid. Buffalo chicken feathers is a great starter (keep in mind, it's crispy chicken) and I always find myself getting the wraps. Another good starter is Fried Green Tomatoes OR the Spinach Dip server with tortilla chips. Dang, why am I writing this review? I need to go to Jacksons now... ;-)\n\nOne more thing... the cookie dough egg roll is UNREAL. The kind of unreal that makes your spirit glow and takes you to another dimension. \n\nThe service - while not the fastest on the planet - tends to be good. If you're ok with sitting a little bit longer than most places, you'll be ok but it's worth it in my opinion.\n\nWhat are you waiting for, seriously? Go give this place a shot.\n\n\n***DOG FRIENDLY PATIO YA'LL***"], ["The quickest way to my heart is Jackson's on a Tuesday night. Ordering 2-for-1 bottles of Dos Perros makes me smile.\n\nGetting a table at Jackson's is hit or miss. Being first come/first serve, it depends a lot on the day and time you go. If I'm with one or two people, I usually just grab a seat at the bar (you can order food there, too). Besides, you'll probably get your order faster that way.\n\nMy one beef with Jackson's is that the waitstaff (on the off-chance you're not at the bar) tends to go MIA at any given moment. This is not the type of place you want to take too long in making up your mind. Or to frequent if you're in any type of hurry.\n\nOn the other hand, the relaxed atmosphere is what I love about it.\n\nThat and the interesting people you'll meet there.\n\nTry the Buffalo Chicken Feathers in bleu cheese dressing. And the spinach/feta omelet for brunch! The meatloaf is really good, too.\n\nAlso, check their Facebook and Twitter accounts; they post internet specials all the time!"], ["Great patio to bring your dog and an awesome menu, love the brunch especially!"], ["Horrible service, horrible bland food for the price points, I would never come here again for brunch. \n\nI love lunch and dinner here but that would be it. \n\nThey said it would take 15 minutes to wait, it took over 30 minutes, it took 10 minutes for our server to come and get us water, then our food took another 30 minutes and it was horrible. \n\nWe should have waited in the line at Fido. NEVER AGAIN"], ["Deep. Fried. Cookie Dough. Egg Rolls. Order these - I promise you will not be disappointed. \n\nWhen I was in college, I used to eat here with my friends and sit at a table, and the service was decent. Now when I am in town for business, I sit at the bar and I always have the same female bar tender with the short, trendy hair cut and immediately regret it every time. She acts as if I am inconveniencing her by placing an order and checks on me infrequently even if the restaurant is not busy. \n\nAs far as the food is concerned - I always order a torrado. They are basically just burritos with a different name. So if you like burritos, you will probably like these. I have never heard anyone complain about anything on the menu so the food gets two thumbs up from me."], ["Alright. Atmosphere reigns supreme at Jacksons. Chill on the patio and people watch, chat, whatever. The drinks come in a close second. A properly made cocktail makes up for many a shortcoming. Third is the food. Decent. If your looking for gourmet, go elsewhere. If you want a sandwich to soak some liquor or a burger to satisfy your bloodlust, they have what you're looking for. Service is completely hit or miss. Some servers are all over you like red on a baboon's ass while others couldn't spell service if they tried.\n\nGotta give it three stars cause it's one of the best hangout/drink/grab a bite places around the Vandy area. It's comfortable and it's not pretentious, but thats as far as it goes. Yippee."], ["Such wonderful brunch! Though this place does get busy, I feel like it's a hidden gem because I never hear anyone talking about it. You definitely have to check this place out. You can find something fantastic on all menus but the Reuben Hash and Fried Green Tomatoes are my favorite. Cookie Dough Eggrolls are a must have as well! Such a great spot and worth checking out if you're traveling and looking to avoid the hype or long waits of the other popular places surrounding it."], ["I haven't been on yelp in a while, but this was worth a post. I went to Jackson's for brunch at the suggestion of a friend a week or two ago. Our table on the patio was squeezed into a corner. No room to move at all. We spent most of our stay moving chairs in and out so people could pass. Everyone else on the patio was doing the same. Then, at the risk of sounding like a complete alcoholic, I was shocked at the price for a mimosa. $9 for what I'm positive couldn't have been more than 5 oz. of orange juice and champagne. It was so small I actually asked the server if they were seriously charging $9 for a drink that size. He shrugged and said \"That's just the way it is. Can I get you another?\". He seemed surprised when I asked for a glass of water. After that disappointment, the Monte Cristo sandwich I ordered was served. Lukewarm at best, no powdered sugar, no garnish, other than a tiny plastic container of syrup. So small, it was difficult to dip the sandwich.\n\nI can't imagine an occasion where I'd ever go back or recommend Jackson's to anyone. Very disappointing."], ["I like Jackson's for solid late night food.  I used to love their brunch, but they changed their menu a few months ago and ever since they did and started offering brunch all day, it's never as good anymore.  They also removed a lot of their super good menu items, like the Croque Madame, so that was really disappointing. But for late night eats and decent drinks, you can't really beat it.  Service can be spotty, especially on the patio, so flag someone down if you haven't been served and it's been a while.  I'd give it 3 stars but the gooey butter cake gets a star to itself."], ["Cam here during restaurant with my wife.  The Steak Frites was very nicely cooked and the fries also delivered tastiness as fries should.  The Tuna al Vino was slightly overcooked but was still pretty good for Nashville and the price.  The parmasen mashed were very tasty and helped to totally make the dish.    \n   We arrived pretty hungry and had to wait a little while to order even though we were throwing up signs.  Decent atmosphere and a decent place to watch sports.  With Sam's across the street, I'm sure you'd go there for sports though. \n   Would visit here again but most likely during happy hour or during a restaurant special such as restaurant week."], ["I went to Jackson's on Monday night around 7pm with a group of coworkers. I was excited to try the place based on recommendations from others. I ordered the BBQ meatloaf which came highly recommended from the waitress. It was just decent......nothing to rant and rave about. I ordered my wife a bacon cheeseburger and fries to go as I left. I requested it be cooked \"medium\", I got home and it was clearly well done and had no seasoning whatsoever. Her fries looked good, yet were hard and overcooked also. This place did not live up to the hype. I may try visiting during the daytime to see if that changes anything."], ["I was hesitant after some of the not so nice reviews, but they were one of the few dog friendly patios around town so we took a chance. I was not disappointed. Our waitress Ashley was so sweet and checked on us multiple times. She brought some water for our dogs. I ordered from the brunch menu and my husband got a spinach shrimp wrap. I stole a bite of his side salad and wrap and they were both great. My egg/sausage biscuits were great as well. But the best part was 2 for 1 Tuesday on drafts and wells. We enjoyed the whole patio to ourselves while sipping on our multiple drinks."], ["cool place... I got the french toast which is thick cut and \"double battered\". at jacksons that means that they really just take two pieces of bread stacked together and fried. it was delicious but you should know to expect the farthest thing from french toast when you order it at jacksons. still delicious"], ["the food is outrageously expensive here and there is not too much indoor seating. The drinks are average and for a place in such a coveted location it is pretty subpar. So expensive"], ["I liked this place.  As you may notice in reading some of my other reviews, I have a tendency to like most things.  I like food.  It's really hard for me to dissatisfied with food that has been put in front of me. \nIt was kind of expensive for bar grub, but what made the evening was the cookie dough egg rolls.  Yep, COOKIE DOUGH EGG ROLLS!  They were heaven on earth, and I am glad that I am in Illinois for the time being, or I'd be headed straight for a quadruple bypass."], ["Great service! Great food! Such a variety of items! Need to try the buffalo feathers! Friendly laid back environment makes for the perfect night out.  These bad reviews are all so wrong about the place. Could not have asked for a better evening."], ["Very disappointed in the breakfast I was served. Received a two egg omelette with minimal sausage(meat was not appetizing). Also got one piece of bread rather than toast and no home fries. Terrible breakfast overall."], ["Okay quick review as this was a lunch stop today.\nThey have an interesting menu-- apps, sandwiches, and bowls--- (whatever the item is, served in a bowl, could be salad or rice topped with whatever)..\nSo.\nI love the popularity of hot chicken in Nashville -- but not necessarily will I choose it every time because I'm not really into \"hot\"--- I'm more into mild.\nHowever. They have this thing they call \"buffalo feathers\" which is pulled chicken (instead of wings or thighs) and tossed in a green chile sauce instead of red. \nLove the concept of pulled chicken instead of legs and thighs and other pieces --- no one else in town does this--- and mine was on a Caesar salad -- I also asked for the sauce on the side --- \nVery delicious, only complaint is that if on top of a salad, I think the chicken should be a little less \"fried\" in consistency -- I would have enjoyed \"a little less crunch\" -- however as an appetizer and served with sauce, sure!! Give me the crunch!!"], ["Absolutely terrible service. They didn't seem to be understaffed at all but our waitress and the other waiters literally could not pull it together. Forgetting about our drink orders. And we walked back to the bathroom and saw our food just sat at the kitchen ready to go and wasn't picked up. Amazing menu items but that doesn't save the bad service. Fix this Jackson's. Your cookie dough egg rolls are unbelievable but you're making it not worth it anymore. Kthanskbye."], ["We met some friends while we were in town and they recommended this joint.\n\nIt is pretty cozy, which is a polite way of saying there is not a ton of room inside, but I didn't feel crammed inside either.  \n\nThe main reason I enjoyed this place was that it was different.  It wasn't just the same ole, same ole chain with the same ole food.  I had some pasta, which was easily some of the best pasta I have had in a while.  My wife had a burger and fries and I seriously thought about eating every last one of her fries.  That good.\n\nThe price wasn't bad, parking wasn't a challenge, and the service was on point (we had a big group as well)."], ["Points for the hostess being super friendly and our waiter trying to be friendly (though it seemed to be very difficult for him) and my entree was delicious. I had the lemon pepper shrimp, which was very tasty and very buttery, so I was bemoaning fate while I ate. \n\nAfter noticing all of the salads had romaine lettuce (seriously? why can't a sister get some arugula?!), I began getting the feeling that this place tries to do things cheaply. And when we tried the cookie dough egg roll, my suspicions were confirmed. I'll have to agree with Aaron and ask, \"If you thought this was good, what were you drinking? Because I think I need to have your kind of cocktail!\" Fake ice cream + fake chocolate sauce + fake pastry = ew, ew, ew. \n\nBut hey, the champagne vinaigrette was tasty. And the patio's nice...if you're not allergic to cigarette smoke. But that's another rant for another day!"], ["The bloody mary was excellent! I got mine dirty and my husband got his dirty and spicy. When they say spicy, they mean it. They also serve Four Roses whiskey, which warmed my heart.\n\nThe only food I tried were the crab cakes. They are made with real crab, and were basically the essence of what a crab cake should be. \n\nJackson's has a great outdoor patio where you can waste away an afternoon smoking cigarettes, sipping on drinks, and watching the hipster fashion show that parades by on the street at all hours. I could easily waste my life there. I consider that a good thing."], ["This place is FILTY! There was a layer of dust covering the chair legs and a thick coating of black dirt on the air ducts...that crap could fall in the food! The floors and wind sills were equally dirty. I was uncomfortable eating there...if the dining area is that dirty I can only imagine what condition the kitchen is in. \n\nThe food was bland, besides the bread that came from Provence there was nothing good about my chicken sandwich. It was dry, under seasoned, and poorly presented. The French fries didn't taste fresh, they looked like they were freshly pulled from the freezer and tasted that way too. It reminded me of what they serve in high school cafeterias."], ["First impression: A good place to drink BEER and people watch. I enjoyed the atmosphere and service at Jackson's but the food and bar beverages were poor... -- We ordered the Monday mojitos, verde dip, and cookie dough egg rolls. The mojitos were flat and boozy (vodka) but not in the way I expect from mojitos. The verde dip was creamy and had good flavor but it was way over-seasoned (salt).  The cookie dough egg rolls sounded like a great idea but the execution was off. The egg roll wrapper was tough instead of crispy. The egg rolls came swimming in a puddle of melted soft serve with ice cream on top. -- All that said the server was nice and contributed to good atmosphere. I'd go back. -- It was late. We had been traveling all day and didn't care to complain about bar food. I'm willing to try again because it was probably an off night in the kitchen."], ["I've walked by Jackson's several times and the patio has always been busy. My Foursquare app had some good tips, so my friend and I decided to try it out last night. Mind you, we had already been to the state fair which was underwhelming at best so we were looking forward to a good drink and some really tasty food. \n\nThe girl who seated us seemed less than impressed. She was less than friendly. We felt less than welcome.\n\nOur server was prompt. I had my drink choices narrowed down to two and he was very definite about which was the better choice. Score one point. On the Foursquare app menu, a pumpkin sangria was listed. It sounded delicious. I inquired, while also understanding that it might be a seasonal thing, whether it was available. It was not, as there was no pumpkin ale in the building. My friend ordered the same recommended drink that I did. \n\nHowever, halfway into our meal, our server returned saying, \"Guess whaaaaat???!?!?\" No, we didn't win a giant prize (which one would expect based on his level of excitement), but he did tell us that a pumpkin ale just came in. \"So we can have the sangria?\" \"Yes,\" he said in a yes-Captain-Obvious-that's-what-I-just-said tone. Two minutes later, \"Guess what? Sorry. We don't have any raspberry syrup and that would totally change the flavor.\" \"So..... we can't have the sangria?\" For Pete's sake, stop toying with our emotions!!!!! No sangria. Minus 10 points. \n\nI also had my meal narrowed down to two choices. When I asked if the fried-green-tomato BLT was better than the pimiento BLT, he replied, \"Why not have both?\" Genius idea. Score 5 points. Except that when my sandwich came, there was maybe a single teaspoon of pimiento cheese and when my bill came, that teaspoon cost a dollar extra. Minus 5 points. \n\nMy friend was given a choice of house salad or Caesar salad with her entree. Our server emphatically stated that the Caesar was far superior. It wasn't. I think Wendy's has a better Caesar salad. This one was just bland. \n\nAs for her beef stroganoff, just.... no. Every bite of beef had fat in it. The one bite I had was so gristly I had to spit it out. I can't even imagine anyone looking at that meat and thinking it was okay to cook and then serve to people. Yuck. \n\nOverall the food isn't terrible, but it's not special. The service isn't awful, but it is awkward. I don't know, I'd go again knowing not to expect anything orgasmic, but then again I'd rather spend my money on the orgasm."], ["So disappointed to have to write this - Jackson's was a fun place, pretty busy, one of the few places to sit outside in Hillsboro Village.  I went many, many times, including sitting at the bar for a nice lunch where I could read a bit and no one would find me (except by cell phone!).  The menu was interesting, food above expectation and the whole place felt funky and fun.  Now, I'm predicting that Jackson's will be the next Hillsboro Village restaurant to close.  Why?  There have been many changes over the last year or so - the menu has changed in concept to be much more limited and the wines by the glass provide virtually no choices.  Execution has fallen down in almost every way - yesterday I went for lunch with one thing in mind - the ahi tuna sandwich.  No tuna, despite ahi being a main component of 3-4 menu items.  The salmon on the salad I ordered instead was delicious, but the portion was tiny.  Salad greens were fresh, but the dressing was uninspired and low on flavor.  Worse than all of this?  It's a total ghost town vibe.  Few customers.  Fewer servers.  The place is clearly suffering.  I hope that they have someone with vision and toughness that can turn it around.  But I'm not going back until I see some evidence of that reversal in Yelp."], ["Ate here about 6 months ago and the food was so-so. I got a wrap with eggplant and it was very salty. \n\nThe atmosphere was nice though and the service fantastic. A bit limited on vegetarian options but the rest of the menu looked scrumptious."], ["Did this place get new management or some such thing? I used to LOVE Jacksons. The buffalo feathers! The milkshakes! Last couple times I went the food was really blah. Sadness."], ["Great neighborhood hangout with an awesome drink menu!\n\nWe had a large group (7ppl.) but had no problem finding a place to sit- it's first come first served...\n\nOur server was helpful and had answers to all our questions!\n\nWe started with the beer/cheese appetizer, yummy! \n\nI then had the Yazoo Fall Ale (Nashville's local brewery) and the Pimento BLT... the pimento is made with Cheddar Cheese which gave it a strong, cheesy flavor!\n\nMy friend had the pumpkin sangria- made with whiskey, pinot noir, and some type of beer, very good!\n\nDaily drink specials include a wine of the moment, whatever they are trying to get rid of, for $6 instead of $7.... and the shot of the day for $5, it was a bubblegum shot when I was there :-)\n\nI can't wait to return for BRUNCH!"], ["The flank steak sandwich w/ their homemade hot sauce is EXCELLENT.  The Rueben is VERY good.  Great patio & DOG FRIENDLY SERVICE.  We're coming back often."], ["Terrible service aside from the trainee who got us started - sucks that it was his first day, he should literally get out now. Open seating but waited over an hour and never even got our food. At that point we left and ended up just grabbing a bagel for brunch. Worst service ever had. Would have been way better to wait in the lines of the actual good places around like biscuit love or pancake pantry. DO NOT COME HERE AWFUL."], ["Let's start with the good. Location, location, location. It's in the thick of things in the HB hood. They've got a great patio with prime people watching. There's also parking! Unfortch, perhaps that's all that this resto/bar is counting on. \n\nI wasn't in the mood to eat, but with the lovely weather and a welcoming patio, the day called for a margarita. They featured a pomegranate margarita, and at $8.50, I thought it would be a stellar, finely crafted, high-quality marg. NO. Even when I asked our server if it had any artificial flavoring or sweeteners, she said no. \"Good,\" I thought. Well it came in a tiny, tiny glass - not even a margarita glass - and had no hint of lime, tequila or pomegranate. It looked and tasted like a vodka and watered down cranberry. For $8.50 - methinks not! \n\nService was okay, but it took a turn for the worst in the end. My tab was fine, so I won't get into that, but l'd expect a better handling of the sitch from management. I too, have worked in a restaurant."], ["We checked this place out because we wanted to grab a bite to eat before our movie at Belcourt Theater. It's just across the street so it was convenient. It was a cold rainy night but the inside was still busy. We were there on half price wine bottle night which was a nice surprise. They have drink specials throughout the week. We ordered the Patty Melt which was the best tasting Patty melt we've ever had! The meat was cooked perfectly and the bread choice was great paired with it. The half price wine & Patty Melt are the reason for the 4 stars alone. The sandwich was served with a small side salad accompanied by a rather tasteless and unenjoyable vinaigarette salad dressing. Our server was polite and when we told him we were in a bit of a hurry he made sure to get our food and drink out to us a bit more quickly than it appeared other people were being served so we appreciated that."], ["Here for restaurant week and my girlfriend and I had a great time. Jackson's has a great patio area with a great view. The staff was friendly and on top of their game. Overall the appetizer, entree and dessert were on point. Additionally, Jackson's has a great alcohol selection to pair with dinner."], ["I've been going to Jackson's for over a decade, and while I respect the folks who disdain all the tattooed servers and hipster patrons, I've always been very pleased. I've tried just about everything on the menu, and whether it's a salad, panini, or an entree dish, nothing disappoints and is reasonably priced.  They also serve strong drinks which can be hard to find these days.  \n\nThe service has always seemed not too attentive or too aloof, and generally pleasant.   I don't love the packed in tables and walkways like I used to, but I certainly don't feel uncomfortable and feel like they don't advertise to be roomy or upscale.  I wouldn't take my parents there, but I might take a cool aunt or uncle who likes to drink.  I also don't expect it to be some gourmet foray of hand crafted delicasies.  It just is what it is and is not pretentious.  \n\nAll that to say, if there is one restaurant in Hillsboro Village that captures the essence of the area, it is Jackson's, and none of the other places.  Is there a bunch of Vandy candy, check, tattoos, check, loudness, check.  \n\nThe brunch is also a real gem."], ["After living in Nashville's Hillsboro village neighborhood for the past two years I've frequented Jackson's a number of times for evening meals and drinks.  Today, following Easter service nearby, I debated my options for brunch in my home neighborhood - Fido & Pancake Cafe - everyone knows about these; good places in my experience.  Yet with the sun shining and a light breeze, Jackson's won out with its outdoor eating options and open windows.  Apparently my fellow Nashvillian's disagreed (those fools!) as I was seated immediately while the other destinations had lines out the door... this review is my attempt to fix that mistake.\n\nWhen I got the brunch menu full of tantalizing options I struggled again, which is unusual for me considering that I'm generally regarded as a breakfast eating professional.  However, the Double-dipped french toast won out since I'd never had it before and in a few minutes I was delightfully surprised.  I don't think I can adequately describe it, it was that unique... but also equally wonderful (imagine a light beignets flavor mixed with double thick toast - topped with shredded apple).  Add in a Mimosa from the full-service bar and you get the idea.\n\nJackson's comes highly recommended.  Great service and fantastic food at a reasonable price!  Go with confidence that you have selected the best breakfast place in the village - this is one instance where following the wisdom of the crowds  (at Pancake Cafe and Fido) will fail you."], ["We ate at Jackson's this morning because the wait at the other restaurants nearby was too long.  We were in a hurry and decided we didn't need a really great breakfast, just something decent.  haha.  What a mistake!  The food at Jackson's is hideous.  We ordered french toast and only ate one bite.  When we saw someone eating it at another table we actually thought it was fried chicken!  How do you make french toast look like fried chicken?  I guess you \"double dip\" it  It was both soggy and greasy on the inside, and hard and wart-like on the outside.  I have never seen anything quite like it.  My daughter said it reminded her of a funnel cake if it was soaked in 6 month old rancid oil.  The coffee was lukewarm.  The restaurant was filthy.  Stay away.  Can't imagine anyone would eat here twice.  (Our server was very nice but that couldn't make up for the disgusting food)."], ["Everything was \"eh\". Food was pretty bland and just Okay. It was extremely hot inside as well. service was just okay. not my favorite place in nashville."], ["Based on our meal here I'm not sure why this place wasn't as crowded as all the other brunch spots. Patty melt was really good. Service was good and everyone enjoyed everything. They sat us right away on the patio on a Saturday around 1130."], ["Honestly, we only came here for the fried cookie dough rolls, so my rating is based on that. They are amazing. If you are craving something chocolatey and sinful - order those! Its cookie dough, deep fried in a wonton wrapper, topped with soft serve and a drizzle of chocolate. SO GOOD."], ["I used to love this place but the last few times I've been here the food has been less than mediocre.  The chicken pasta literally tasted like plain boiled noodles and was dripping in water/oil.  And the cheeseburger tasted fast food at best.  Their patio is amazing so come here for drinks but the food isn't great."], ["Food is okay, but the absolute worst service... no one that works here has a clue what is going on. So terrible.. don't waste your time."], ["The only thing more disgusting than the waiter's scabbed up hands was the food. Everything was cold and the biscuits & gravy arguably tasted worse than dog food. On top of all of this, the bathrooms were so filthy they resemble an underground abortion clinic. Decent Bloody Marys though."], ["This is my place to go when I don't want to spend too much money but want a decent atmosphere with decent food and cocktail. I also know that I won't be interrupted too much with the staff stopping by too frequently to ask if everything's okay. It's a good casual place. I've visited for brunch, lunch and dinner and enjoyed myself on all occasions."], ["Don't waste your time or money. Especially if you are visiting nashville. SOOOO many other better options! Food is below average and service was fast but not worth it. Wait and go some where better!"], ["Listen, skip the hoopla and pancake house/fido lines; this was seriously good food and I had just enough to make me happy! I ordered sides: 2eggs o/med that came with AHHMAZING sourdough bread from across the street at Provence, French onion hashbrowns yes pls, and excellent coffee! I'm full I'm happy and I waited probably 15 total before food was in front of me (on a Saturday am, 10:45ish, during heartwalk weekend)! Thanks Jacksons for the wifi as well!"], ["Only come to Nashville a few times a year and can't leave without having the sunrise sliders regardless of time of day.  Make sure to get with sausage and apply the sweet/hot sauce.  Cookie dough egg rolls are great too. Rest of food looks good but never actually tried it."], ["Love is such a strong word.  Do I use it to describe my feelings for Jacksons?  I don't think it is.  I feel like I am more in like with this place than in love with it.  The food is good, in fact I think its very good.  The frustrating thing about Jacksons is getting there.  I stumbled upon it one day while waiting in line for the Pancake Pantry (review to follow).  Not wanting to wait for \"the cure\" I headed over here for something, anything to eat.  The burger I had was satisfying, prepared as asked and creative.  The drinks were generous and provided just that little hair of the dog that I needed to feel like a human being again.  On subsequent visits the food remained good, consistency is big with me and this place did not disappoint.  What is disappointing though is Hillsboro Village.  First of all, I don't think I am cool enough to spend any sizable amount of time there.  Second, parking is a nightmare.  I don't just mean difficult to park, I mean a nightmare.  When school is in session, forget about it.  I think that's the only reason I have to rate this place low.  The food is good, the atmosphere is great and as Marcia M. says, the people watching is fantastik.  Finding a way to get from your car to here though makes it a 3 star instead of 4...sorry Jackson's, it breaks my heart to say."], ["Jackson's is one of those places that you can get lost in the uniqueness. Local art hangs on the wall and people-watching is optimal. The waitstaff is very artsy and music orientated. The outdoor patio is fantastic! Food is good, service is too. I would recommend going there to hang out for lunch or during happy hour for a drink."], ["Great Hillsboro lunch spot. There is usually a wait on the weekends but no longer than any of the surrounding restaurants (aka pancake pantry and fido). Casual setting, typical American menu, nice outdoor seating area. They have a lunch, dinner and brunch menu as well which includes bloody mary's and mimosas (the most important part of brunch of course). Also serve beer and wine. Service is good, and food is relatively low priced for Nashville and surrounding area."], ["Drinks are good, food is good, service is half assed. Usually crowded and loud, but an ok place to grab a drink or snack when in Hillsboro"], ["We decided to take advantage of Restaurant Week 2015 and try Jackson's.   The staff was very friendly... even helping us find a handicap parking spot.   We ordered menu drinks  but twice our poor waiter had to tell us the bar was out of key ingredients.   Our appetizers were really tasty, loved the spinach /garlic dip!  The Beef Stroganoff was quite good  but my Shrimp & Grits were seasoned so badly,  so much garlic that I had to stop eating it because it was just painful.  Our waiter told us that particular dish lacked consistency.. That's a shame."], ["This isn't the fanciest restaurant in Nashville, but when I'm looking for something casual this place is perfect. I usually have good service and the prices are very reasonable. \nThe cookie dough eggrolls are always a must for my friends and I, even if we don't have any room for dessert. These eggrolls are fried and filled with warm gooey cookie dough and have a topping of ice cream. I think they are what keeps my friends and I coming back. \nThe food isn't too impressive, but like I already stated, its good for a casual lunch. My personal choice is the Baltimore BLT (crab cake) with a chopped salad. The atmosphere is little young since its so close to many of the local universities, but its never a party atmosphere. At times I feel like I'm not trendy enough for this place, but then again I don't exactly care..I just love how laid back everything is."], ["I've experienced Jackson's on a few different occasions and I must say I enjoyed my meal each and every time.\n\nThe cheesy egg breakfast panini was delicious and after a late night of dart throwing at The Villager, it was exactly what I needed. I ordered it with a small side salad with a champagne vinaigrette. Considering how late it was, everything was fresh and well prepared.\n\nI also took some out of town friends to Jackson's one day for lunch. One ordered the beef stroganoff and it was sensational. Rich, creamy and full of flavor. I ordered the classic club and it was delicious, as well.\n\nMy only complaint is that the service is a little slow, other than that I really have nothing but good things to say. The atmosphere and patio are great, the food is pretty delicious, they are open really late and it's in a prime and easily accessible location. \n\nI would definitely give this place a try if you are in the neighborhood and need some upscale late night eats."], ["I really enjoy dining at Jackson's.  The outdoor seating has a great view of people traveling around Hillsboro Village.  I see friend's passing all the time when I sit out there.  My favorite entree is the spinach wrap with a side caesar.  It's cheesy and delicious.\n\nThe drink menu at Jackson's is full of specialty treats.  Stay away from the Nashville Manhattan, but try the gummy worm martini if you're feeling frisky.  It's served with an actual gummy worm and brings together the twin joys of alcohol and childishness.\n\nA little secret about Jackson's is that Yazoo drafts are 2 for 1 with a student ID.  They don't like to do it and won't tell you about it, so you have to ask."], ["When we first walked in, I thought this place was really cute! We came here for lunch with a larger group of friends. The seating is a bit weird and we ended up at a larger table by the window. Unfortunately, it was also quite cold outside and there was a strong draft from outside...\nHowever, the food left something to be desired... I split the chicken and biscuits and the BLT with the fried green tomato with a friend. The biscuit was dry, as was the chicken. I put a bit of butter on the biscuit, but everything still tasted really dry. The BLT was fine. I thought that they were a bit skimpy on the fillings. Our server, though, was really patient with us, even though we came in a big group and kept changing our minds!"], ["Jackson's is another popular restaurant in the Hillsboro Village neighborhood, but not one of my personal favorites.  They're very small and because of this theres almost always a wait for a table.  It's hard to walk throughout the restaurant because the tables are placed so close together that free space is severely limited.  I always end up never wanting to go to the restroom when I'm there just so I don't have to deal with the claustrophobic walk.  \n\nTheir menu features mostly lighter fare like sandwiches and paninis but they do offer some pasta dishes and other entrees.  There's a distinct West coast flavor to their food, don't come here looking for comfort food items.  The food is pretty good, but nothing too outstanding. Their portions are on the small side and the prices are pretty high for a sandwich.  They serve brunch on Sundays, but its generally too crowded for me. \n\nThey've got a full bar that'll accommodate most of your beverage needs but their drink specials aren't really exciting.  The atmosphere is very laid back, and is enhanced by the artwork from local artists thats hanging on the walls.  \n\nThey have a small patio at the front of the building facing the street that can be nice, but 21st Avenue is generally so busy that the noise often detracts from the experience.  They have a very small parking lot, so you're generally going to have to find a spot somewhere on the street.  Not the best Hillsboro Village has to offer, I don't find myself coming here too often, but overall it's not a bad choice for your meal."], ["Oh you came here for the bar/hipster Nashville scene?  The great views from their glass front window?  Or the patio?  No, you came here for the lunch menu that serves up things like burgers and fish tacos then?  Or the 2 for 1 beer specials they offer during certain days of the week?  Silly You.\n\nWhat you need to come to Jackson's for is their dessert called Ooey Gooey Butter Cake.  This is really the only thing that matters.  It is a thick concoction of butter, sugar, crust, vanilla ice cream and Love.  Yes, it is clear this dessert is made with Love as something so divine can only come from Heaven.  You're Welcome."], ["Went here recently, Had a chicken salad, and the chicken was so hard. Also, it was supposed to have a buffalo sauce on it and it tasted like an asian type sauce. How can you mess up a chicken salad?"], ["I will say that I've been back since that bad experience and the service was great. It may have just been one of those random awful experiences, but the food is very good. The chicken biscuits with honey butter are to die for. Highly recommend"], ["Skip the Baltimore BLT. The crab cake was really gross so I ended up taking it off and just eating a bacon sandwich. However, I sampled my boyfriend's beef stroganoff and it was awesome. Rich and fabulous and made up for my poor choice. We sat outside which was really nice, but really loud. I think I'm just getting old and wasn't as drunk as the coworkers who started after they got off work."], ["We don't even have our food yet but since we are sitting here about to gnaw on the sweet and low packets I felt I could share that this place SUCKS.  Are you kidding me?  If you only have two in your party on Sunday don't plan on seeing open tables and think you will be seated.  You aren't four, go home.  Who cares if the food is good if they can't get it to you in a timely manner?  Key point, look at the floor in the kitchen areas.  Ordered biscuit sliders with sausage, got bacon but was so hungry did not want to send it back.  The waitress comp'd it.  Friend found a piece of ham in her omelet.  She is a vegetarian-fail.  Bathroom a mess but I'm surprised I could actually see anything in the darkness."], ["Great place in Hillsboro Village to grab dinner on a Sunday night OR brunch on a Sunday morning!!!\n\nThere is a tradition of offering half-price bottles of wine in Nashville on Sunday as it is illegal for liquor stores to sell it. Well, Jackson's has a great wine selection and a killer menu. Last night, $12 for a bottle of Muga Rosado from Spain (60% Garnacha, 30% Viura and 10% Tempranillo) and an off-the-menu fave of mine: Seared Ahi Tuna Reuben. Very affordable top-notch meal. Brought a friend to share the wine.\n\nPS GREAT outdoor seating and DOG FRIENDLY!!!"], ["Food was very mediocre. Grand omelette had minimal crab meat and goat cheese. Air conditioning was nonexistent. Redeeming item was the hash browns."], ["Great service if sitting at the bar. I've been here a few times when staying in the area, and only been pleasantly surprised. \n\nThe food is good, and on a weekday it is nice coming into a casual non-rowdy spot after having experienced sizzling Broadway."], ["Came here on a recommendation for the buffalo feathers and beer selection.  It was early on a Thursday, about 4:30pm. Well before the crowd.\n\nBoth the chicken feathers and beer selection were good, as was the service. Very good, friendly, attentive service.\nThe other food items we ordered were just ok (verde dip & grilled chicken sandwich). \nDecor of the place was interesting - dark gray throughout. The atmosphere definitely improved as the crowd picked up."], ["Jackson's is a gem of Hillsboro Village. Looking past the bare-bones decor and eclectic hipster crowd, the food here is absolutely delicious (!!!), fresh, and generally reasonably priced. My favorite is the Baltimore BLT ($10.00) which is really only a BLT sandwich with crab cakes (making it even more impressive when it comes out so tasty). Fresh salads, yummy french onion soup, and a selection of ten or so paninis to choose from make it the perfect lunch spot. \n\nI wouldn't recommend Jackson's for a \"nice\" dinner though--the entrees get very small and very pricey very quickly, and given that the decor doesn't suddenly become nicer or more polished, the change doesn't make much sense. If you're just looking for a nice, quick bite to eat though, it doesn't get much better, particularly that Jackson's seems to have a monopoly on mid-range meals in the area."], ["Great place to sit outside on the patio, good food, service is sometimes slow. A good option for Hillsboro Village"], ["Really enjoyed brunch with a party of 8. Corned beef hash and breakfast sliders were very good. Especially enjoyed the cookie dough egg roll for dessert!!!"], ["I can't believe this only has 3 stars right now!! This is one of my Nashville staples! It's always a safe bet when people come into town, especially for brunch. I've never had a bad experience here, and I've been plenty of times. Half priced wine on Sundays.... Plus- you can't lose with cookie dough egg rolls sooo...."], ["I'm conflicted about this one. The Rueben hash has potential to be a good dish, but there was quite a bit of oil on my plate. Bar tender didn't ask me how to cook the egg, I totally forgot, it came out over easy which personally I don't like. Bloody Mary I had was delicious though, and the atmosphere was nice. The monte cristo the couple next to me had looked delicious. Would have liked to see proper glass handling by the bar backs though, they should be holding glasses by the base, not by the rim where customers will be putting their mouth. Would try again, but maybe order something else."], ["I wish I could give Jackson's a review for Saturday/Sunday and then a different review for Monday-Friday - because it's literally two different worlds as far as food goes. \n\nSaturday and Sunday they offer a brunch menu and it is HEAVEN!! They have amazing mimosas and the brunch food is great! Our table had several different items and not a crumb was left! The wine special from 3-11 is worth going alone! However note that they stop serving brunch at 3pm - so if you want to eat off the brunch menu and enjoy the drink special - come a little before - order your brunch and there ya go.\n\nNow, the everyday menu is not as great in my opinion. Today I had was suppose to be a shredded ckn philly (no bun for me because I am allergic) - and it was literally a PILE of grease! I couldn't even eat my fries because they ended up soggy from SO MUCH grease in my plate from the philly :(  My fiance and friend both had some sort of egg sandwich and they two said it was just \"okay\".  I will say it was a busy lunch hour and the food came out fast! \n\nAnother thing I'd love to give 5 stars is they allow my dog to dine with me! Yay!\n\nAnother thing I'd give 2 stars to - parking. But that is just the area! Sometimes you get lucky - most the time you don't. \n\nAll in all - save it for a Saturday or Sunday - or if you go during the week save it for  just drinks!"], ["I was here during restaurant week and paid $20 for an entree and dessert. Pretty good deal I must say.\n\nThe steak frites and egg is what I got. Steak is juicy, tender, and tasty. The fries that go with it are oh so good too - skinny fries that are salted just enough. \n\nI got buttercake for dessert- not too over the top. It is so sweet but the ice cream kinda balances it out. \n\nOverall, I was extremely satisfied with the food here and would plan to come back."], ["Visited Jackson's tonight with a friend and I have to say that I was incredibly disappointed and sad that THEY TOOK THE CHOPPED SALAD OFF OF THE MENU.  How am I supposed to get my favorite Rio roll torrado and chopped salad when there is NO chopped salad to be had?  Minus one. :("], ["I've been a fan of Jackson's for many years. Good food. Good drinks. Reasonable prices. Friendly bartenders. Great location especially when you are going to or coming from a movie at the Belcourt. \n\nI'm adding this review because I ordered something new (to me) at brunch a few weeks ago - the Sunrise Sliders. Egg, cheese, your choice of sausage or bacon, all on a biscuit. Biscuit fan that I am, I had to try them. I ordered them with the Conecuh sausage. I don't know exactly what that is. All I know is that it was damn good. The sliders were served with a side of pepper jelly that took the whole dish from \"really good\" to \"oh my God\" sublime.   I've definitely got an addition to my Biscuit List."], ["I went to Jackson's based on a recommendation from my friend who goes to school at Belmont, and I'm very glad I did! The food was amazing, the service was friendly and helpful, and I left very satisfied! I had the Barros Lucos sandwich and it unreal! Sliced flank steak, really good sauce, avocado... incredible! And the fries were hot and crispy! I would REALLY recommend that sandwich! I also got the cookie dough egg roll (it comes with ice cream) and that was really good too! Just to reemphasize my tip, make sure you split it with someone. It's very rich. Go to Jackson's! Good stuff!"], ["Great food and even better drinks. When entertaining out-of-town guests who haven't been to pancake pantry, I will not hesitate to take them to Jackson's for brunch if the line looks too long. They are very creative with their entire menu - you'll probably spend a good amount of time deciding between all the fantastic food options. I had a breakfast scramble type of plate last time I went, and also some crabcakes - both were great. The one thing here I remember not being great was their version of a Caprese salad - instead of sliced fresh mozzarella, it was shredded mozzarella - come on man!\n\nBut despite my high praise for their food, the drinks are where Jackson's shines. Bloody mary's, mimosas, cocktails, or even just their draft beer selection - you really can't go wrong. I'm a real big fan of the Bourbon Alexander - if you like whiskey you'll probably love it. \n\nThe service has been decent every time I've gone - it's suffered at times when I've gone with a large (8+ people) group, but I think that's more my friends being idiots than a rap on Jackson's. If you're wondering what the best brunch places in Nashville are, after Loveless and Pancake Pantry, you NEED to go to Jackson's."], ["Overall, a solid dining experience.  The menu is full creative sandwiches and other fair, but I was underwhelmed.  The do make a good Bloody Mary and have some fun drink specials."], ["This was the first place I ate at when I moved to Nashville, been there a handful of times and always get the same thing - the Pimento BLT sandwich. And it's consistently delicious.\n\nThe outdoor seating is fantastic when the weather is nice. Servers are fun and chatty.\n\nOnly warning I have - don't be rude to your server. I have heard from a friend who worked there that they may or may not compromise the food of douchey customers.... just sayin."], ["Great menu choices.   Stay away if it's busy as the kitchen is small.  It took 45 minutes to get our food.    I made the mistake of ordering Shrimp and Grits....DON'T DO IT!  Shrimp and Grits tastes like oil and water. \n\nOmelets look amazing."], ["Me and five others ventured to Jackson's with a post-interview candidate and I sadly report that I've had better.\n\nWe were seated promptly and of course they had a great beer selection but it was the munchies that disappointed me. I ordered the small platter of turkey sliders (only two on the plate) that came with a dijon mustard. The buns were clearly stale and there were no fixings on the burgers. No lettuce, no cheese, and not even a pickle! Waste of $7!\n\nI also ordered a small shredded salad which I didn't find to be that bad. It was pretty much a vinegar Cole-slaw consistency with some slice purple onion and two slices of red bell pepper ($4). If it weren't for the Yazoo Dos Perros, I would have left hungry last night."], ["Love the late night hours and their vibe...tasty food, quick service, good beers. It's not my first choice in the boro, but once I'm there I find myself not wanting to leave!"], ["This place is successful because of its location in Hillsboro village within walking distance of Vanderbilt. Otherwise, the food is pretty good to mediocre. The mushroom spinach wrap and salad were decent, great for a business lunch or a casual late-night bite with drinks with friends, but not a place worth traveling across town to. There's an outdoor section, as well as a bar. Pretty standard American place."], ["good food, better drinks. great place to hang out and have fun in a relaxed vibe."], ["$20 for a bottle of champagne and a couple bucks for a tall glass of oj make for very cheap mimosas split amongst three friends.\n\ni ordered biscuits & gravy because, duh, it's the south. while they were good, i was certainly happy i ordered a side of the french-onion hash browns as they weren't filling in the slightest (before you judge me, check out my picture. would that honestly fill you up? twss). however, the swiss cheese melted on top of the hash browns stuck together in a clump, and i had to fight to separate it. i love onions with potatoes, but they were too sweet for my taste.\n\nsuper friendly server and relatively quick service..but definitely a place where hungover biddies go to sip coffee in their shades post a crazy night out on church street. we were also told the outside patio (where we sat) was heated, but it definitely did not appear to be so. i kept my down jacket on the entire time."], ["the food was okay, nothing special.  the service was fine -- they politely put the shrimp on the side of our dish, rather than inside the wrap for my vegetarian friend with whom i was sharing. \ni'd say the best part of the restaurant is the patio.  it was really nice to sit outside and people watch on a warm summer evening.  i'd try a different place next time."], ["Without a doubt, 100% sure this is my favorite place in Nashville.  I've probably been here about 50 times in the past couple years.  I love breakfast, lunch, dinner, late night snacks, and drinks.  It's basic American-style cuisine.  If you're a total foodie looking for something unique, this isn't the place.  But the food is great.  It's consistent.  The vibe is wonderful.  I go here on dates, with my friends, and with family.  LOVE LOVE LOVE."], ["I ended up at Jackson's based on a recommendation.  It was a crazy crowded night as I believe it was Fat Tuesday.  \n\nAtmosphere - crowded, dark, modern, bar/club/restaurant feel, tvs, corrugated metal, black paint, white oak, concrete, the trendy garage doors thing    \n  \nFood - As I was here for dinner, I perused their menu and opted for the Baltimore BLToff of the waitress's recommendation.  This sandwich consisted of crab cake, bacon, tomatoes, and romaine lettuce on a toasted sourdough with a side salad.  The sandwich was decent and the crab meat tasty for the price.  The side salad's raspberry dressing was just ok, not great.  The meal was decent and I would order it again, maybe w/ fries instead.\n\nService - The waitress was friendly and engaging despite it being a very busy night.\n\nPrice - Sandwich w/ side $10+tax and tip.\n\nOverall - It was a descent time and there were many a fried this and fried that in the dessert section that I would like to try on another visit.  What the heck is fried cookie dough?  I am sure it is good for you.  Right jack?"], ["Oh Jackson's still as good as the first day I met you. I give you 5 stars because well your food is always on point. The vibe is chill. The music is amaze balls. Yeah I said it. Sorry not sorry. Did I mention they're pet friendly? That's the cherry on top. Had shrimp and grits tonight. Taking an order of blackened ahi tuna bowl to go. I expect it to be nothing less than perfect. The manski is having the steak fries and eggs which I've had and it's delicious, let me tell you. Also some chicken feathers. Try them, they're awesome! The staff is great. Had this girl serve me on the patio with no heat. Thanks for being a trooper and bringing my dog water. Extra kudos to you. Come here you won't regret it."], ["Jackson's is awesome.   Its laid back, artsy, and has great drink specials.   All the haters are so annoying.  If you want AMAZING service go to Flemings.  If you want to have a laid back dinner and relax and laugh with friends go to Jacksons.  Get the chicken salad wrap.  Its awesome.   And, no, Jacksons is not a place for people that hate their life and love to criticize, honestly... the rest of us don't want you there either.   So, lets sit on the patio and have some sangria.  I'll see ya there."], ["Went here on a very cold Friday night in November. The atmosphere was great and the food was very flavorful (love the pebre sauce). The staff was attentive and offered helpful suggestions. I will definitely be back the next time I'm in town."], ["Always great service, food and drinks. Love sitting on the patio! A must stop anytime I am in the area"], ["This place is inconsistent and has poor customer service.\n\nI go to Jackson's last night (Thurs., April 19) at 8:50 pm. My partner and his friend planned to join me for drinks in just a little while. I go in and head straight for the bathroom, then go to the bar, asking what time they close, figuring they MAY say 10 or 11. They then tell me they're closing in ten minutes. I walk out, text my partner to decide on another place to meet, as I'd hate to keep them open later and was sure my people wouldn't get there for another twenty minutes. He doesn't respond. Meanwhile, something also just feels strange about the interaction inside about their hours, so I Google search their hours because I recall the days when Jackson's and SAMS were the ONLY places open past 9 in Hillsboro Village. Their website, the Google landing page AND their social media all say they close at 11 pm on Thursday nights. I return to the establishment and ask the server why, when everything online says they close at 11, are they closing at 9. She responds, \"Oh, where are you looking?\" I tell her everywhere and show her on my phone. She says, \"Well, these are our winter hours, so they must not be updated.\" Obviously noting my bemused facial expression at winter hours in April, she goes on to say, \"We are still running winter hours until it gets warmer.\" This is the most absurd thing I've ever heard, as it is 75\u00b0 one night in Nashville and then 45\u00b0 the next. Are they changing their hours every night according to external temperatures? I mean, it's an indoor location with an HVAC unit. I said, \"Well, why isn't any of this reflected on at least your social media?\" \"It's run by a girl in Birmingham,\" she says, as if that's an acceptable business response.\n\nSo I suggest she be sure to let their social media person know to update hours because it's confusing for customers, then I leave. Just to be sure of this, I also message their facebook page personally.\n\nAlready, this is a bad experience, and it makes no sense that they've had all winter to update \"winter hours\" but never did. So that's my first critique.\n\nShortly AFTER 9, my Patrick goes straight to Jackson's without checking his phone because that's where we agreed to meet. He gets there, and is told the kitchen is closed but that he's welcome to have a seat at the bar. Are you kidding me? Of course, my partner doesn't see me and so he then finally checks his phone to get my updates about where I am.\n\nFirst of all, I get it. When it is a slow night, it feels good to just close early. BUT your hours are until 11 pm, and you should honor your hours unless there's an extreme weather warning. Anyone could arrive within the next two hours and be disappointed. And if you ARE closing early, please be sure to treat all of your customers the same. Had the server told me the bar was open, I'd have said, \"Oh great! We'll just have drinks then.\" Not to mention, I technically still had ten minutes to order a snack if I wanted one. Are you a business? Do you want to make money? I'm so confused as to why you're turning customers away.\n\nIn addition to this already poor service, I'm a black woman, and my partner and his friend are white males. The fact that I even have to question or navigate the different ways in which we were treated makes my blood boil. That I even have to question how race consciously or subconsciously factored into the equation infuriates me. And I also cannot think of any other reason why that may have happened. I'll be reaching out to the manager and won't be visiting here again. I'll also be sure to tell my friends."], ["My fiance and I came here for happy hour with a couple of our friends. Drinks were good, happy hour was good and of course we ordered the much raved about cookie dough egg rolls. My fiance and I both agreed that they were good. They were not as amazing as they were talked up to being, and we would not order them again, but we didn't hate them. The service was ok."], ["Megan is a goddess. Ask her anything about Nashville. Food and beers are pretty good too."], ["Outdoor seating was good, but service was very slow. Also the food was not good at all. I will never be returning."], ["Our waiter was a doll so it was easy to enjoy our experience. The tomato soup with basil was excellent. I came home to Chicago wanting tomato soup and can't find anything that compares.\n\nThe fruit tea was also very good - something I had never had before. It that sounded kind of bad, but I decided to try it since 2 others I was lunching with were having it. YUM! The combo of tea and juice was delicious. Plus, free refills."], ["I have tried this place a couple times for their nice 2x1 Happy Hour. Their small plates are delicious. I would suggest getting the buffalo chicken feathers, they are to die for and they come with the option of blue cheese dressing and ranch. I have also had their brussels sprouts and these I was not impressed with. They were dry and hard to eat (literally). \n\nI honestly don't recommend them as a \"date\" venue or as a \"special occasion\" gathering place. They are more for the Happy Hour enthusiast who wishes to have a few drinks after work either inside or outside. Ohh! Also, their service is not very impressive. Even though, I must say, their staff is very friendly."], ["Came here for breakfast or brunch and the service was so poor.   We were seated outside immediately but the server ignored us completely, had to ask a busboy to find a server.  Finally someone came over, took order and then we waited.  And waited. About 25 min for 3 omelettes.  Nothing was that delicious.  I understand why the wait for pancake pantry is so long.  Overall disappointing."], ["I wanted to like the place. It was not busy at all for brunch. Food took over an hour to get out to us and it looked like it had been slopped together by a toddler. Also took awhile for a server to come to the table. The food itself wasn't bad, but honestly I could make it better. I would not recommend this place to friends or visitors from out of town. Very underwhelming. Poor service."], ["I love the patio at Jackson's! It's a great spot to people watch and it's comfortable! On Monday nights they have a special on mojitos, which were pretty tasty. \nI've tried a few meals here, I actually can't remember what they were, not super memorable. However, I can remember the desserts! Haha! I've had the gooey butter cake...fantastic! As well as the fried cookie dough...also fantastic!"], ["I'm new to Nashville but old to breakfast. I came here with a friend a week ago and had the best omelette EVER and got the stone mill grits that are OFF THE CHAIN. I'm craving that breakfast today."], ["I don't know anything about Nashville but I came across this place thanks to Yelp. My husband and I wanted a place we could take our little dog to (we are driving cross country) There is a great outdoor patio so it worked out perfect for our pup. I thought the food was very good but it was the dessert that really sold me. Don't pass up the fried egg rolls with cookie dough. AMAZING!"], ["I've been to Jackson's many, many times, mostly when I lived in HV, and while my heart wasn't happy to admit it, I cannot say how many egg rolls I may have consumed during those glory days of college.  \n\nI had my first Steamer (with caramel) here and I can't wait to go have another.  The Spanish omelette is quite tasty.  I typically love grits, but I did not enjoy these.  I heard from a co-eater that the Shrimp & Grits was very good.  \n\nBusy on normal peak & weekend hours, but as always, it's a great place to stop in & hang out at while catching up, people watching, or wondering what treasures you may find for your bookshelf in the \"free\" box across the street at Book Man/Woman!"], ["The Capri and Sonora are my favorites for lunch at Jackson's. It's a good, unpretentious place to meet up in Hillsboro Village. Not too expensive, decent drink selection, bathrooms aren't the worst ever. Parking can be tough so if you are pressed for time, good luck!"], ["I only come here for the patio and wine specials. It's great if you want to grab a quick drink before heading to the Belcourt to catch a movie. However, I wouldn't recommend most of the food. The menu is not very vegetarian friendly. Most of the times I've been to Jackson's have been to visit friends who work there, so my service is usually top notch. However, I do recall waiting about 30 minutes for my table's drinks to arrive when the restaurant was dead.\n\nThe patio, location, drink specials, and a few special servers (Krystal!) keep this place afloat."], ["There food is so gross. It's a fun place to go people watch but don't go hungry. You can bring your dog and watch hung over college kids pass by."], ["I like Jackson's because though it looks boring on the outside, it's actually kind of quirky on the inside. If you sit on their side patio you are bound to be amused by those trekking around Hillsboro Village, and if you stay inside you will undoubtedly be distracted by the paintings hanging on the walls (which I think are made by local artists). As for the food, it's pretty good. I have tried their Philly cheese steak, a wrap, and the shrimp pasta, all which have made my belly happy. I think Jackson's #1 deal breaker, however, is their ridiculously good cookie dough egg rolls, seriously, so good. If you feel like boozing it up, try their pomegranate margarita is also really tasty."], ["I got the bacon cheeseburger which was quite dry and overcooked. The cookie-dough eggrolls were decent but nothing too memorable. Consistent with what a lot of other reviewers are saying the food isn't great. But I loved the atmosphere and patio area."], ["This place was honestly awful. So bad it sparked me to right this review. There were 6 in our party and not one meal was good. To start it took about 15 minutes to even get a waiter over to take our drink order. When I stopped a waitress to ask if we could be waited on she was extremely sarcastic and rude about it. When we finally received our food about an hour after ordering it 5 out of 6 meals were way over cooked with a burnt flavor. We all took a couple bites and couldn't eat anymore. I will say the French toast was as bland as I've ever tasted and burnt batter on the outside. My wife had the egg scramble tacos and they were ice cold like they had been in the refrigerator. I would steer clear of this article place as there are far too many options in Nashville to eat somewhere this bad. Overall awful experience. This was a one and done."], ["Stumbled upon this little joint because the pancake place across the street had a long line. They were able to seat our large party right away which was a main reason we went in. The food was good and substitutions with the omelettes are allowed, which is helpful for picky eaters like myself. The upgrade to the cinnamon toast is definitely worth it! If you are hangry and in a long line across the street, definitely just walk over here instead."], ["It's ok.\n As a bar  it's better. The food is average and on my last 2 visits, so-so\nThe service is sub-par. \nFor food, I think that I'll walk a few steps to the many other eateries in the area."], ["My boyfriend and I ate here last week. The service was \"ok at best\" and the food was horrible. The fried green tomatoes were cold and needed salt. I ordered The chicken salad panini but promptly sent it back as it was dry and needed seasoning, I got the monte cristo. It tasted like old grease. My boyfriend had the Philly cheesesteak and he too said it lacked flavor composition. The atmosphere is the only pro I can definitively appreciate. Don't think we'll be back as there are plenty of other restaurants in the area that actually good. I almost forgot, the Caesar salad dressing was amazing. Though I don't know if they make it in house. *shrugs*"], ["My first time in Nashville. I originally planned to go to Pancake Pantry, but the line was very long. I saw Jackson's across the street, so I went there to eat. I got there and was confused because there wasn't a clear entrance. Once I sat down, I ordered thinking it would take around 20 minutes to come. I wanted the Hot damn eggs, but they didn't have pico or jalape\u00f1os. I settled for a different type of scrambled eggs and asked them to put sliced tomatoes.  After 20 minutes we asked the waitress how much longer and she said 30 minutes max. I hear other people getting up after their meal talking about how bad the food was. After another 30 minutes our food comes. The food isn't anything near what I ordered. My guest and I were very disappointed, so we told the waitress we don't like anything. We didn't eat any of the food and got the check. We ended up paying for the coffee and iced tea that we drank and had to pay for one of our meals. I do not recommend this place."], ["Decent brunch place with a nice patio in the Belmont area."], ["College place. Good food, service and prices. Highly recommend"], ["As an alternative to the popular Pancake Pantry across the street, I was pleasantly surprised with the aesthetic and quality of the food. The group I was with did not have to wait to be seated, which initiated the beginning of a pleasant experience. As a non local, the waiter was kind and helpful with suggestions for things to do around the area. Classic Southern Hospitality. I ordered the Big Ben Breakfast with a side of toast, and it mixed incredibly well. The eggs were well cooked, and the bacon added a great level of flavor to the dish. Adding to it was the fact that the brunch menu lasted until three, which is something I thought was more uncommon. The only detractor was that the menu was less wide than I anticipated, but regardless, the food was great and I was thoroughly impressed."], ["Very cool spot to brunch in Nashville. You seat yourself, so we were able to combine two tables for our large party with ease on a Saturday morning. Menu has a variety of items you wouldn't normally find on a brunch menu, but the flavors were slightly lacking. I ordered the grand omelette with the cinnamon toast upgrade. It was a good omelette, but there were very few pieces of crab, and it needed more salt. Our server was very nice, and he gave us recommendations for places to go in the city, which was great! \n\nOverall, it's a good place to go when the line for pancake pantry across the street is too long, but it's not a must-see type of place."], ["Jackson's is a place I would resoundingly deem as good but not great. If I go, I typically get the Rio roll, which is not particularly flavorful but is healthy and a good price. \n\nAs I'm sure many have mentioned, the reason to come here is the cookie dough egg rolls. If you're in the area it is a decent enough place to stop in, but nothing to write home about."], ["Let me start out by saying that Jackson's food is alright. Food alone would be 3.5 stars. I am leaving 2 stars, though, because I do not enjoy the atmosphere or the service here. It is so loud in Jackson's that you can barely hear the people you are with talking, even on the porch. Today I ate there and had some pretty bad service. I ordered coffee and my waitress brought it to me in a to-go cup. I thought it was weird because I was eating there, and I prefer a mug because I try to be a little environmentally conscious, but I let it slide. Then I got the check and was charged for a medium coffee. I certainly didn't ask for a medium. I just wanted coffee in a mug. But again, I let it slide. I paid with cash. I was supposed to get $2.33 back in change. I received $2. I'm familiar with change being a pain in the butt while serving, because I was a waitress for several years. If you round, though, you are supposed to do so in the customer's favor. I stayed for an additional hour chatting with a friend and we never heard from the waitress again. No check in to see if water or coffee needed refreshing. I left a 10% tip for the first time in my life. It would take a lot for me to visit there again. Even with OK food, today just left me with a bad taste in my mouth."], ["Loved breakfast here. Several of us enjoyed a spicy Bloody Mary and the 'Big Ben Breakfast\" that was made if scrambled eggs, potatoes, ham and cheese. It was perfect. Cool atmosphere and right across the street from the pancake pantry without the wait!"], ["Jackson's used to be great and their food was delicious -- ahi tacos and these wonton things filled with pork... all the good stuff has been taken off their menu. Now they focus on \"bowls\" and with \"seasonal vegetables.\" When I ordered a bowl, literally all it came with was a piece of severely overcooked ahi tuna and a huge heap of overcooked, under seasoned Brussels sprouts (cost around $14!). When I asked about this (since the menu said \"vegetables\"), they just looked confused and said they didn't realize the menu changed. They finally took the meal off my bill after I didn't eat most of it. It really was inedible, and service was terrible. Food took forever even though there were only 10 people there."], ["If you would like to see a restaurant where everyone appears to hate their jobs, then you've found the place. Their subprime elementary style isn't worth your time or money. My wife and I waited 45 minutes (not during peak hours) for sandwiches that tasted like they were made during the Great Depression."], ["Many Yelpers have raved about the cookie dough egg roll dish.\n\nSo with some time to fill before the start of a Blair piano concert, I walked in and asked if it would be OK if I just sat at the bar and ordered a dessert. \n\nThe hostess was remarkably friendly for Hillsboro Village. +1 star.\n\nThe bartender was even friendlier and more welcoming. +1 star.\n\nThe cookie dough egg roll unfortunately turned out to be a disgusting mess - unappealing dough fried inside a tough shell and topped with imitation ice cream and cheap chocolate sauce. And for this I paid $6+ ($9 altogether with tax and a generous tip to the sweet bartender).\n\nTo those who liked the cookie dough egg roll, I have to ask \"What were you thinking/drinking?\"\n\nThe saving graces that rescues this place from 1 star ignominy are the friendly hostess and especially the bartender who kept it surprisingly real. I'm not much of a drinker, but I could see going back and getting a beer. The barmaid said that Jackson's carries a custom Yazoo Pale Ale in addition to some Fat Tire and a Dogfish Pumpkin brew - though I presume that the pumpkin one at least is only available seasonally."], ["They 1/2 price bottles of wine on Sunday's have made this place a weekend must! My favorite choice is the proseco... For only $12! Love the outdoor patio and the fact that it's dog-friendly. \n\nMost of my experiences here have been good ones. My last visit I went earlier on in the evening than usual and the patio was pretty busy. The service was a bit slower than usual, but our waiter Andrew was very apologetic and even gave us a discount on our check! We definitely appreciated his kindness and will certainly be coming back. \n\nOn Sunday's, I recommend going after 8pm to bypass the dinner crowd. I also love going to see a movie at the Belcourt and then walking down for drinks afterwards."], ["Don't order the cough dough egg roll. Not worth the price or the calories. The gooey butter cake is seems to be decent."], ["One of my favorites in town. My boyfriend and I recently stopped in and had the tacos del mar (which he can't stop raving about, and he is from the west coast!) and the honey bourbon grilled chicken sandwich. The fries are always piping hot and fresh and nothing beats ending the meal with cookie dough egg rolls!"], ["Let me just start that I have been here plentiful of times in the past. What happened?! Is it new owners? The menu has been somewhat altered. My go to item is no longer on the menu (Sonora torrados) or any of the torrados, but that's okay. Gave me a reason to branch out. I got the veggie bowl which was curry saut\u00e9ed veggies over a choice of rice or quinoa. It actually was pretty tasty. Personally, I would've liked more curry sauce on it. My boyfriend ordered the blackened tuna bowl. It was good as well, but I feel like I could get this anywhere. \n\nWe got a couple drinks each. He got an old fashion and I got the sazerac. The sazerac was a bit too bitter for my taste. Both of our drinks were served at almost room temp. We were spooning out ice from our water to put in our drinks. Our waiter was nice...when he was around, but it took a while for him to come back by. It wasn't that busy either. We finally got a second round of drinks and went the safe route to ensure a cold drink. It wasn't a bad experience, but it definitely wasn't the same as before."], ["I think people go to Jackson's so they can sit outside and people watch. That's definitely one the reasons I go in the summer. I kind of forget Jackson's is there, for some reason. It seems like if I go out in the Village I'm going somewhere else. \n\nThat said, Jackson's is a perfectly fine bar to go and have a drink and some surprisingly delicious food. Decent salads and sandwiches. Not fine dining, but if you're with somebody and don't know where to go, this is a good choice. Nothing weird or objectionable -- people should be able to find something to suit them on the menu. Good selection of beers and an interesting selection of mixed drinks. What I have to recommend, though, is the cookie dough egg roll for dessert. Deep fried chocolate chip cookie dough so it gets nice and gooey inside with vanilla ice cream. One of the best desserts I've ever had. \n\nJackson's is one those places you like to have in your back pocket. Maybe not a destination, but good to have around."], ["I just moved to Nashville form Los Angeles, and this was the first restaurant I tried.  My mom and I stopped by for an early lunch while I was moving in.  While it had a nice crowd, there was no wait for one of the air conditioned inside seats (a must for me in this muggy summer heat!). \n\nThey serve an odd mixture of light and deep-fried fare.  I noticed deep-fried Twinkies and cookie-dough egg rolls (frozen cookie dough wrapped in an egg roll and deep-fried) on the menu, but didn't try either out.  Maybe another time when I have a major sugar craving!\n\nI took the server's suggestion of the Pacific Panini - Blackened Ahi Tuna with provolone and pico de gallo.  Mom got the Rio Roll Toronado - grilled chicken, guacamole, provolone & tomato lightly grilled in a spinach wrap.  Both came with a choice of chips or salad (ceasar or caprese).  The server recommended the ceasar, because they don't have fresh mozzarella for the caprese!  It makes me wonder why they offer it at all...  We both got the ceasar salad with our meals.\n\nThe ceasar was unremarkable.  I really liked my panini - I did wish it came with some more vegatables on it though.  It seemed a little like just two slices of bread and a thin serving of tuna.  The tuna was great though, and the flavor with the pico de gallo was amazing.  Mom's Rio Roll was really good too.  It came out piping hot, so she had to wait a few minutes to eat it.  I really enjoyed the flavor.  She told me afterwards, however, that she had never had a spinach wrap before, and she would have preferred a normal tortilla.  So be aware of what you're getting!\n\nAll in all, it's a nice place to have a light meal.  The food came out quickly, the service was great, and the atmosphere was nice."], ["I'm not one to post bad reviews but after sitting in 86 degree temperatures and enduring the terrible service, I had to say something. We asked about the the temperature and the server responded, yeah it's hot. The food was bland and slow to arrive."], ["Do you enjoy grease? What about slow service? If you said yes to both of these questions, this restaurant is the place for you!\n\nBreakfast restaurant checklist:\n\nCoffee - good\n\nEggs - grease. Yep. Grease. \n\nWeird waiter with a personal time zone separate from the rest of Nashville - definite yes. \n\nBon appetite."], ["Started off with waiter Steve ignoring us for 10 minutes and us having to request him to come to the table.  He was inattentive throughout the meal and I had to track him down to request additional syrup and the bill.  As for the food, the french toast was amazing.  Best I've had.  However, the bacon was not well prepared. Two pieces were barely cooked and then the other two were nice and crispy, but were all crumbled in pieces.  All in all, not what we expexted"], ["Food was good however service is seriously lacking. Waited at the door until I finally asked \"do I just sit anywhere?\" And told \"yes\". Other people walked in and no one helped them. The server took forever to cash me out."], ["The fact that this place is walking distance from my house gives it an extra star... and the outdoor seating gives it another star from there... and the brunch gives it another star.\n\nThe drinks are great and 1/2 priced wine on Sundays, high five! \n\nProbably my favorite time to go is for brunch on Saturday or Sunday. Be prepared to wait for a little while, but i honestly think it's worth it. The omelets are enormous (it says 3 eggs, seems more like 4 or 5) and there are lots of unique toppings. A friend and I split the 3 cheese grits and nearly licked the bowl. They're drier (just the way i like them) and very flavorful. \n\nIt's a small restaurant and seating is pretty sparse in the chilly months when it may not work to sit outside on the patio. (they close it off but... check before you sit out there. it can get a little cold sometimes.)"], ["Came here with my Mom, fianc\u00e9 and our two dogs while on vacation. If I could give stars for separate categories, I would give service 5 stars. Our waiter was fast and attentive and right gave our dogs their own bowl of water right away. They are very pet friendly (on the patio)!\n\nI had the grilled salmon entre\u00e9 and I was disappointed at how TINY the portion was. I work in the restaurant industry and understand portion control, but this was SMALL for $16. I would say the piece of salmon was only 3\" x 1-1.5\". I replaced the mashed potatoes with soup beforehand so, yes, all that was on the plate was the salmon, but it shows you the reality of the amount of food you're getting. I've seen salmon bigger on salads before. To be fair, the waiter did tell me that it's the same portion as the salmon caesar.\n\nThey did offer brunch/breakfast all day which is a nice touch."], ["My boyfriend and I came here for breakfast on a whim because everywhere else was packed. When we entered no one greeted us and we were trying to figure out if we sat ourselves or not. We finally sat down and had a great waitress. \n\nWe ordered the breakfast tacos. While waiting for our tacos, I had a view of the kitchen area. The gentlemen preparing the food both had long hair and a long beard and were not wearing hair nets. Also they were not wearing gloves when touching the food. While I am not a germaphobe, this is unsanitary. We did eat the food despite this, but were less than satisfied with the meal. It was bland and not worth the money. \n\nAlso, on our way out we saw the man who was preparing our food without gloves on smoking a cigarette out front. We will not be returning."], ["I hesitate in awarding a mere two stars to Jackson's as I've had a number of enjoyable experiences while dining there.  Unfortunately, the food has never been a contributing factor to said enjoyment.  I give credit to the place for featuring a diverse and relatively large selection of bottled beers and to the bartenders for mixing stellar cocktails (at least most of the time).  I also enjoy the energy of the space, though it can get tight at times.  Ultimately, however, I've found the food to be consistently lacking (dry chicken, lukewarm soups, uninspired & bland sandwiches - the list could go on) on more visits than not.  Don't get me wrong - not everything is bad - just mostly below average.  I suggest making Jackson's a pre or post-dinner stop.  You really can't go wrong with throwing back a couple of cold ones before or after meandering up the street or around the corner to a better dining destination."], ["Love J-son's. I've been here approximately 5 bajillion times but it's still on my list of go-to's for the following: \n\n-pre- or post- Belcourt dranks\n-dates (sitting outside and people watching can alleviate an awkward silence moment, same for the TV by the bar, same for the cocktails)\n-Mussels and Fries\n-PUMPKIN SANGRIA (What did she just say??? Pumpkin Sangria. YES. It is delicious and potent) and other seasonal bevs\n-Hipness \n-1/2 price wine Sundays\n-decent brunch\n-reasonable prices overall\n\nAlso - always pretty crowded but never much of a wait!"], ["Smaller bistro south of Vanderbilt.  French Onion soup was very nice, hot, cheese was perfectly melted.  Chicken quesadilla had smoky chicken-a plus!  Hash and eggs were perfect.  I like the hash a little crunchy and great flavor.\n\nCocktails-punch of the day had rosemary, ginger syrup and it was a lovely surprise.\n\nSteve was our server and he was attentive, helpful and so nice.  Rockstar!\n\nOne thing to remember is that their lot like every other one is a pay lot.  Get your ticket in the lot even if you only want to stay the \"free\" 1 1/2 hours."], ["I selfishly go to Jackson's to sit outside on the patio and people watch. They do have a good drink selection and an above average menu plus the wait staff and bartenders are very friendly. Maybe someday the Cool Springs/Franklin area have a place as people watching friendly as Jackson's. If you have time to kill and are in the mood to do some people watching then Jackson's is the place to go."], ["We have been here a couple of times, and this place has a great menu. The buffalo feathers were extra-special."], ["Meh, not impressed. Came here on a recommendation for lunch and got a panini and salad. Very blah. We also tried the buffalo feathers which were also just alright. I guess the breakfast/brunch is what you really need to get. I will say, the biscuits are good."], ["Upscale diner is how I would describe this bar.  You can get great diner food and have a drink with it.  The service is excellent.  There is patio seating but it was hot outside so we sat inside.\n\nThe BBQ meatloaf was spicy and delicious.  It came with parmesan mashed potatoes.  The cook knows how to season his food.  We will have to return to try the grits next time we are in the area."], ["Came here on a Sunday for brunch with my wife and friend. Got seated outside by the hostess. We sat there for 15 minutes, never received water or any wait service. We tried flagging down waiters multiple times, who made eye contact and just kept on moving. We got up and left. We never tried any of the food, as we never received any service."], ["I never post Yelp reviews, but after my experience just now I feel the need to share.  I lived here 5 years ago and Jackson's was my go-to spot.  Great food and beer place.  5 years later, I can hardly say the same.  The menu hasn't changed, which I was a bit surprised about, and the place was absolutely FILTHY.  I was sitting at the bar and noticed dust built up on rafters and air ducts to the point that they looked like stalactites.  This was over the grill, fryer, prep area, and main restaurant where people are eating and food is getting prepared.  GROSS, that was #1.  Then, I saw cobwebs hanging from the garage door track (cobwebs are old spider webs covered in dust), and finally, I took a closer look at the kitchen.  \n\nIt was, by far, the most disgusting kitchen I've ever seen, and I've worked at a number of restaurants, both low key and high end.  The fryer looked like it hadn't been cleaned in years, there was oil residue built up everywhere on neighboring appliances...even the fridge doors were full of crud.  If the customer facing appliances are so gross, I can only imagine that the insides are just as bad, if not worse.  This place needs a major overhaul before the health department shuts them down.  I can tell you that I will never come here ever again."], ["The blackened steak caesar salad is excellent!  Good beer variety and friendly staff."], ["With so many places to try in Nashville, there is no point in trying this again. The service was ridiculously slow, the portion size was so small it could be served on a saucer. The biscuits are the size of quarters, and there is about a spoonful of gravy  served on them. There's a reason why the place was empty."], ["I'm not a huge fan of their food, although I haven't had much of it. The bistro burger was a little dry tonight. \n\nBUT, I love this place after the sun goes down when the crowd thins out a bit. ESPECIALLY on Sunday's when they have half priced bottles of wine. We go almost every Sunday. The outdoor patio + a cheap bottle of prosecco and maybe an appetizer (the spinach dip is great) is a relaxing and very enjoyable night. \n\nOur waiter tonight, Andrew, was stretched a bit thin but took great care of us and we ended up getting our bottle of prosecco for free.\n\nAnd the cookie dough egg rolls are REALLY GOOD."], ["Quick service at the bar. Shared the rio roll- delicious spinach wrap however too much tortilla, not enough fillings and quite small for a wrap. Can't beat the price though... And the cheesy grits are good. I like mine a little cheesier but still quality. Great atmosphere."], ["Went here for lunch in Saturday when we discovered Bosco's had closed. Bad decision.\n\nService was generally poor. First thing I asked for was a particular local beer and of course they didn't have that one. We shared an appetizer of fried green tomatoes which were ok but nothing special. Then the fun began.\nAfter three attempts to actually cook a simple omelette my wife gave up and just ate the part cooked mess. The first attempt was so undercooked as to be dangerous. The second attempt (allegedly a completely new omelette) wasn't much better. They took the second one back and apparently showed it a lit match or something as it was still undercooked but now browned to appear cooked.\n\nThey took her food off the bill and offered free desserts. We declined. If you can't get an omelette right in 3 tries I don't want more of your fare thanks.\n\nWon't be returning.\n\nOh, one tip for you servers...have your girlfriends dine somewhere else. It is infuriating to be unable to get service while you are playing lovebirds at the next table while I am looking at undercooked food and trying in vain to attract the staffs attention."], ["We love this place. We have only tried brunch (twice), but would definitely come back for lunch.\nHubby got the omelette.  Pros: Very fluffy, nice size. Fresh ingredients. Cons: no sides are included.\nI got the quesadilla topped with scrambled eggs. Pros: On the smaller size. No sides.\nOverall pros: MOST meat is local. Good atmosphere. No line opposed to the Pantry next door. Yummy food.\nCons: Service can be lacking. Coffee is not served with fresh cream. No sides included with brunch. Beef is not local."], ["The shrimp and grit is too salty and the spring roll is too hard to bite. Don't know it happens only because of the restaurant week or it is always like this"], ["I had a great chicken sandwich and a few mojitos during happy hour! All around everything was great. Only complaint was the cheap lays chips. Just kind of seems like a place that would either have home-made or better chips for sandwiches. Either way, ill be back."], ["I'm so conflicted...because while I absolutely love a few of the menu items (Wasabi Ahi Caesar!), this is never my first choice.  Honestly, I don't know that I've ever said, \"Hey!  Let's go to Jackson's!\"; especially after they got rid of the Chorizo Corn Dogs and Carolina Rangoon.  Sigh.\n\nThe layout is a little funky.  Unless you are seated, it is near impossible to not feel in the way.  I absolutely hate that feeling.\n\nThat said, the service is usually decent and the bartenders are excellent at their job."], ["All you really need to know is that Jackson's has the best Sangria in town! It's everything you want in a sangria... sweet and tangy with the heavy red wine taste that rounds it all out. I dream of it at night sometimes... plus it's just so darn pretty. I've tried to recreate it at home, and somehow it's just never the same! The French martini is great as well, but anytime I stray from the sangria I wish I'd ordered it instead. It's just so good!! OK, I've got to talk about the food too. \n\nThe Verde Dip aka garlic and spinach dip is unlike any other spinach dip you've tried before. It's my favorite food item at Jacksons! For your meal, the Torrados are great and I haven't had a pasta here that I don't like. \n\nI've spent many a night on the patio with a sangria in hand having drunken philosophical talks with my friends and I wouldn't take a back a single sip or moment spent here!"], ["I used to live in Hillsboro Village and I loved going to Jackson's because it was a convenient neighborhood bar with good food. I moved from Nashville to Providence, RI two years ago and I've yet to find a good place in my town that has reasonable prices and good drinks.\n\nThe service at Jackson's isn't great, however.  I was just in town a few days ago and met an old friend there to catch up. As expected, the food and drinks we great and the service was a solid C+. I just thin the owners or managers of Jackson's should encourage their employees to lose their apathetic attitude."], ["I came out to Jackson's with some friends one Sunday evening and enjoyed a nice time on the patio.  I could imagine this place being extremely, extremely busy, but this being a Sunday night, it wasn't too bad.\n\nThey don't seem to have a huge range of beers, but they do have some nice choices.  I was pleased to find my love from the West, Fat Tire, on tap.  I had stole the \"chopped salad\" from one of my friends - it was good, but low on the salad, heavy on the beans.  Not sure what they consider a salad.  However, speaking of salads, the Caesar here is great... I had a bit of that, too.\n\nI had the andouille pups for my late night meal - three mini corn dogs with andouille sausage in place of the dog.  Good stuff.  I'd eat it three more times. :)\n\nOur waitress was friendly, but a little scattered.  I'm not sure if she was spread a little thin with it being a lower pace night or she was just scattered all the time.\n\nI wouldn't count on parking in the lot - it's small.  Like everything in the village - just plan on squeezing into a spot on the street and walking a bit.\n\nOh yeah - 2 for 1 on Sundays. :)"], ["This is a neat place with an interesting building. Good was pretty good. Overall really enjoyable!"], ["Nothing good to say about this place except that the wait staff was very nice. Coffee was bitter, bread on the Philly cheese steak was terrible, omelet was incredibly buttery, cinnamon toast barely had any cinnamon on it. Overall, underwhelming and would not recommend."], ["Best cheese grits ever. I'm not kidding; plenty agree with me. The menu is very broad and mid-priced; the service is usually quick and reasonably personable, attentive, or both. I've tried quite a few items on the menu; all were good. But the Three-Cheese Grits are the Best Evah.\n\nIt can be a little loud, but their outdoor patio with glass garage doors is a great idea for breezy afternoons when you don't want to Dine On Ice (i.e., freeze to icicles in over-air-conditioned inside dining -- they dont' have  problem with this, but plenty of places do). And there is almost always a line waiting to get in during busy times. I'm not the only one that likes this place."], ["Stumbled upon this place looking for a breakfast spot. Right across the street from the famous pancake house. Also across the street from the line that wrapped around the block to get unto the pancake house. There was no wait to get a seat outside. Started with a tennessee cocktail and a strawberry mimosa. We ate the loaded biscuits with bacon and an omelette with garlic, spinach, tomatoes, and cheese and split cheesy homefries. Waitstaff was super friendly and recommended some places to see in the area."], ["Jackson's has been a favorite spot since my college years. Here's what stands out:\n\n-Buffalo Feather Caesar Salad\n-Verde Dip\n-Chicken Caesar Torrado (with Buffalo Feather Sauce on the side)\n-Cookie Dough Egg Rolls\n-Sangria\n-Pomegranate Margarita\n-Gooey Butter Cake\n\nYou cannot go wrong with any of these menu items. I also love this spot for sitting outside on their patio in the warm months. Jackson's is a great spot for hanging with friends, grabbing a drink with a colleague, or having dinner with your date."], ["I had the fish tacos -- listed as an appetizer, but sufficient in my case for an entree.  Not spectacular, won't make me forget the fish tacos of San Diego, but a good choice in the neighborhood.  Jackson's isn't particularly distinctive, but it's a solid meeting place for friends."], ["Best patio in the neighborhood and very DOG FRIENDLY! Good food, great drinks, awesome service. Easily became a frequent customer after my first experience. Great location to people watch too. Patio open year round!"], ["Decided to try a new place so I decided on Jackson's since they have good reviews. I got their ahi tuna wasabi salad and Brussels sprouts on the side. Sound good? WRONG\nThe Brussels sprouts were soggy and not crispy at all they were like boiled. \nThen the \"salad\" was literally a piece of fish with no seasoning on some lettuce. Like that's it. The dressing was straight up wasabi and too strong to eat. The whole meal was such a letdown"], ["Food was...meh. I had a chicken wrap with chips, it was just okay.\n\nOn the plus-side, they serve the Madras Mojito, which I always loved at the now-closed Rumba...I just wish they would serve it in a larger glass- for Pete's Sake, that shit is expensive!\n\nAlso, I brought my Puggy along, and we sat on the patio without incident. They even brought him a bowl of water. Great place for drinks and dog-lovers!"], ["Jackson's is great! Like the service and the food- they have a nice selection of food and drinks- recommended"], ["Buffalo Feathers.  Sometimes I enjoy just getting a couple of those instead of an entree."], ["The best! Wish I had a cookie dough egg roll right now!"], ["The last time I was there the service was so poor that the manager gave me a $25 gift card. So I went back to spend the gift card and let me tell you what I experienced today.\nI went today during the daytime and really got a good  look around at how dirty and unkempt that place is. The  servers are greasy and dirty looking. I had called in the order to go and when I got there it was on the line ready to be served to a table.  I had to ask them to put it in a box. Then when I was eating I found a dead moth that had clearly been dead  for a while IN MY SALAD!!!!\nThe grill area was greasy and dirty. \nThey clearly just don't care. \nThis place used to be so good, what happened!"], ["Arrived in Nashville for a girls' weekend trip and we were hungry after traveling all morning. We initially were on a mission to go to Pancake Pantry but seeing that Jackson's patio was filled with people on a nice but humid day we took a different direction.\n\nPretty hip place - reminds me of Pittsburgh actually. Garage doors to open up the patio seating and the servers were hipster-esque. Felt like home.\n\nTo cool myself down I ordered an Abbey beer and the tuna wasabi salad. The beer was fantastic and I agree with Ash C. that Jackson was probably trying to save money but my salad was delicious. Romaine, a decent size of tuna and wasabi dressing were all great together. There was a lot of flavor though it was not overly spicy - my nose wasn't going on a seizure. My friend had the BLT and she scarfed that down.\n\nOur server was a no frills type of guy (got us seated, got us our meals and got us our checks with a smile here and maybe there), which was fine by me. If I were to return to Nashville I would return back to Jackson's though not after I do some more culinary exploring."], ["I tried Jackson's when I first moved to Nashville several years ago, and I really enjoyed it. But each time I've been back since, it's gotten worse.\n\nFor some reason, it seems that this has become a popular place for big groups to go, but I just don't understand it. There are a lot of space issues inside, and it's always tough to fit even a medium sized group at one table. And along with the big groups comes a lot of noise. There are some restaurants that I don't mind being loud, but the size of Jackson's makes it more unpleasant than most - you're really close to the loud tables nearby. Sitting on the patio when it's nice outside is better, but adjacency to Hillsboro is hardly a stellar spot to sit and enjoy your meal.\n\nAnd then there's the service, which is rarely good. Sure, you expect a bit of delay at a busy restaurant, but there's no excuse for a 20 minute wait for drink orders.\n\nBut of course, a restaurant should be judged by its food, right? On that level, Jackson's does well. The food's actually pretty good. It's not outstanding or anything, but I've never been disappointed. What's disappointing, though, is their prices. Nothing about their food is special enough to justify the money spent, especially when you have to wait so long for it.\n\nJackson's isn't a bad place by any means, but it's one that I no longer feel a desire to return to. There are other, better restaurants in the area."], ["The food is so bad it's almost amusing. I ordered the pimento cheese sandwich my first time coming here and it was so salty I had to send it back. I decided to give the place another chance with the buffalo chicken caesar and the chicken was so dry it literally could snap in half. Just no."], ["As I ate at this restaurant I felt as if I was in a broadway production, a comedy, where everyone was doing their best to do the absolute opposite of good service. It was actually really entertaining, eventually. \n\nToast was disgusting.\n\nOther food was good. Grits were really good."], ["One of my favorite aspects of Jackson's is sitting out on the patio on a fine spring or fall day, eating some fine food, and enjoying some of the best people watching in all of Nashville.  \n\nWhile there are certainly better choices for food, even withing two blocks, this is one of the few patios locations around.  \n\nI recommend it for lunch too, if it is a nice day outside, as the lunch menu is pretty affordable."], ["The staff was excellent! The food is typical and unique. Coming from out of town we treated with southern love. The BBQ meatloaf was delicious!"], ["Ended up here on a very rainy night in Nashville. We got a couple seats at the bar and ordered some drinks. The bartender was very friendly and talkative. We got to meet some locals who were great as well. We ordered the cookie dough egg rolls, which were good, but I felt they could be better. They were a little hard to cut to eat. \nBut our drinks and conversation and company was great."], ["Jackson's is top-notch.  I consider it my favorite place to grab a meal in Nashville.  I've dined friends, family, and coworkers -  it's perfect for any occasion.  \nI try something new just about every time I go.  I have yet to be disappointed.  \nTwo thumbs up to the food, the service, the atmosphere, the price, and the creative yet classic cuisine.  \nTry it, you won't be let down."], ["Stopped in here for Dinner. Place definitely has a good vibe to it and lots of open-air seating.\n\nI ended up getting a burger, which was pretty good. Nothing out-of-the-ordinary, but it was good.\n\nService was mediocre. Our waitress wasn't around much when we needed her, and my glass of (mostly ice) water sat empty on several drawn-out occasions."], ["The food is delicious, the location is great, the outdoor patio is spacious, and the service is excellent.  In fact, when I was there the other night one of the staffmembers saved a chocking guy's life!  True story."], ["We went here on a Tuesday night. You seat yourself and the waiter comes to you. Cosy, not too noisy, decent beer list. I had the crab cake blt and fries- and both were delicious. Good prices, would eat here again."], ["Went for breakfast.  Very slow to get food and forgot two items. Food was decent but the wait for some food items was a bit redic."], ["Man I use to love this place..My husband and I sitting on the patio enjoying some butter cake then a breeze would go by and I smell stanky dog ass in the air...the service is mediocre..and the food has went downhill..The fact I gotta smell dog when I'm trying to enjoy a meal isn't appetizing..food and dog ass don't mix. I don't think its a good idea dogs can dine with the customers but maybe it's just me..I give it 2 stars cause I still like the butter cake but to go"], ["I have had two very bad experiences here. Went with some friends a few months back. You have no idea if you are supposed to seat yourself, or if someone is going to seat you. Once seated, you see every waiter pass your table, but it takes forever to get service at your table. My first trip, we waited for almost 2 hours for our food. We got chicken biscuits, which were pretty good. \n\nFast forward a few months, and my girlfriend and me tried all the other Hillsboro Village breakfast spots only to find they were all packed (per usual). She said let's try Jackson's. I told her I wasn't a fan, but was down to try it again. Same poor service as last time. We both got omelettes and they were honestly disgusting. The flavors weren't the worst, but the texture was awful. \n\nOverall, poor service and food is not good."], ["Great bloody Mary's and awesome patio. I've eaten here at least 10 times and never had a good meal. I'm giving it three stars for the atmosphere - it's almost always packed on a nice day. So definitely grab beers here on a Saturday but I wouldn't recommend the food."], ["Cool vibe, quirky service, and an awesome patio to sit outside and people watch.  The food is above average bar food with a wide variety of paninis and more classic bistro fare like steak frites and croque monsieur (and madame with a fried egg).  Overall, can get a little pricy, depending on what you order.  Touted as a good hangover remedy, I'll have to look into that sometime....3.5 stars"], ["Wow that was gross. I had one of the rice bowls and the rice had no flavor whatsoever. Veggies were plains steamed then a sauce dumped on top. \n\nPerfect for college kids with no income and a less than discerning palate."], ["Someone needs to change $$ signs on this place.  $9 for an omelette that was flatter than a pancake and ..what no potatoes?   Also.. how about a choice of toast. Nope only white and while it was supposed to be toasted.. I did not see it.  I say go elsewhere."], ["Jackson's is always crowded, and as far as I can tell, it's only for one reason: the patio.  It's not really for the service.  Although I do admire the waiters and waitresses' sleeves and fixie-riding skills (and I mean that), there just isn't much to say about them.  They're not bad, not good, just...there.  It's not really for the food either.  I've had some good meals (the meatloaf and dessert egg rolls stand out), but I've had some bad ones too (the corned beef hash at brunch a) wasn't very hashy and b) was so salty that I felt like I had a bucket of seawater thrown on my face).   And it really can't be for the inside dining area.  It's pretty cramped in there, and the setup is less than optimal.  Watching the staff maneuver around each other is like watching someone navigate the Double Dare obstacle course (minus the giant nose).  So, I mean, it must be the patio.\n\nSo if you want to sit outside on a nice day, sip on a cold beverage, and people watch along 21st Ave, then Jackson's is a good choice.  Otherwise, you may want to head elsewhere."], ["I am a HUGE fan of Jackson's food and have been for about 10 years now. They are consistently GOOD.\n\nEveryone always rants and raves about the Cookie Dough Egg Roll which IS fantastic, but only if you are wanting yummy junk food. \n\nAll their TORRADOS are delicious-- lightly grilled spinach wraps filled with YUMMY goodness. Served with a salad or chips. I have had everyone and loved them all the same. \n\nI went to BRUNCH there last Saturday morning and there were not many people there (9:30 a.m.) compared with Pancake Pantry and Fido... I was confused as to why more people hadn't caught a similar drift and headed over to Jackson's. I got the... what do you think... Ma\u00f1ana Torrado!! It was reallly really good as well. \n\nEndless cups of coffee, too! \n\nI plan to make it a frequent brunch stop on my list. ;) You should too ;)"], ["Jackson's is great!  Nice interior.  Quick seat at the bar.  Great breakfast. Cool outdoor seating."], ["Have walked/driven by here more times than I'd dare guess.  Had it on my \"to try\" and finally got around to it last weekend after a movie at The Belcourt.  Oddly, it wasn't as crowded as it is typically.  Everything on the menu sounded great, it was really hard to choose.  I ended up with the Scottsdale BLT and a salad and it was a good choice.  Not great, but good.  Service was slow, but our server was also handling a really large table consisting of the most subdued bachelor party I've ever seen.  Hubby had the Rio panini and he enjoyed his too.  Drinks were OK, they were out of our first choices but we managed.  Don't know if I'd rush back but I wouldn't veto the choice either."], ["The French toast was amaze balls, great bloody Mary's and the grits were to die for!!!"], ["If you enjoy sanctimonious hipsters serving you overpriced boring food then you'll love Jackson's. \nSituated smack in the middle of hipster central, AKA In-between Belmont and Vandy, Jackson's is a staple for trust-fund babies, or people of \"new money\". \nThey have no idea what good food should taste like, but they'll spend $19 on a gross, flavorless sirloin that you could get at TGI Fridays for less.\nDon't dare order regular ranch dressing. You'll only get a snooty \"we only have fat-free...\"\nThe only saving grace is their happy hour. \nEven still, just skip it."], ["The atmosphere is not the greatest, because it's generally super loud and very busy. The food is pretty consistent. They have a tuna wasabi salad that is very good.\nI suggest brunch, but they can't really handle large groups.\nOn a slow night in warmer weather its nice to sit outside near the sidewalk and watch folks walking by. (if its busy the outdoor seating is just too loud)"], ["So, I quit my job this past Tuesday.  I just needed a change.  And where did I go for dinner Tuesday night?  To Jackson's of course!  Where they serve the life-changing chicken salad torrado sandwich!  Ha!  Now, that is my own nickname for the sandwich...life-changing.  But, it's really SO good.  I have tried to mimic it at home but just can't do it.  I have no idea what they put in that thing, but it's pure ADDICTION.  \n\nThe atmosphere is great too--different, eclectic--you could be seated in between a group of school teachers and some punk musicians with piercings all over...never know who will be there!  \n\nService is notoriously slow though...don't go if you are in a hurry.  Especially busy for Sunday brunch.  The brunch is great though, try the Big Ben Breakfast, or just get the flash-fried potatoes.  Sit out on the patio if the weather is nice--excellent people watching; you'll never want to get out of your seat!"], ["In Nashville for a girls weekend and instead of standing in line for the Pancake Pantry we walked across the street to Jackson's.   So glad we did!  Delicious!!"], ["I revisted Jacksons this weekend and have go to say that I truly miss porch season. I had the double dipped french toast and it was okay but for those calories, I should've gone with the monte cristo. The biscuits and gravy were fresh and the sausage was spicey. Nice. Try their extra spicy bloody mary. Yum! I wish they had horseradish for the bloody mary though. Still good. Always safe."], ["My wife and I are big fans of this place. The atmosphere is fun, and during the spring and summer refreshing. The patio is a great place to be on a cool evening or early afternoon in Nashville. \n\nThe food is great, they serve an all day brunch menu along with their regular menu. I'm personally a fan of the patty melt and anything on the brunch menu. The Mrs. loves the shrimp and grits. I'd stay away from The Tasty...a hangover inspired cheeseburger omelette with French fries. It's not so tasty- but I wasn't hungover either. So maybe if you're under the influence it's true to its name."], ["Meh to the Bloody Marys. Rare is it that I'm not compelled to order two, and here, I was not. \n\nAnd trust me, with the way I was feeling that day... it was bloody necessary. A bland Bloody Mary is a sin in New Orleans and I hold Bloody Marys up to my city's high standards.\n\nAs others mention, the front patio is all what this place is about. And truly, I'd probably give them three stars because I didn't eat and it's hard to judge a place on a single cocktail.\n\nBut... a Bloody Mary is a very important thing. Especially on a Saturday at 3pm."], ["1.5 hours after arriving...and still waiting for our meals. By far the worst service I've ever experienced here. Would not recommend for Sunday brunch/lunch regardless of how tasty the food may be when it finally arrives."], ["Tried brunch here today... we had a couple different dishes the shrimp and grits and the breakfast bowl . Breakfast bowl got two thumbs up! Shrimp and grits came out with some watered down sauce and no flavor? Not sure what happened there but sent it back and came back thicker but still not much on flavor. Jennifer was our bartender and can't say enough! Super Sweet and just this beautiful warm smile that made you smile back! Great little place was really doing a good business...nice outdoor seating too, maybe next time try out there. Food was pretty slow coming out but still got out in just over an hour on a very busy Sunday right at 1130."], ["Service was fine. People were polite and food came very fast. Biscuits and gravy were average. Nothing really special in my first experience here but would come back again to try's one of their other brunch items.  A bit pricey for average though..."], ["It's pretty much ok\n\nThe service on the patio is AWFUL.  I sat for over 1/2 an hour and never saw my waitress.  Had to ask for her, and she dumped off the check and went away.\n\nThe food's good.  The drinks are ok.  Their 'high gravity beer' is NOT worth the money, and the give it to you in a tiny glass.\n\nSo... it's ok."], ["I had lunch here with a friend from Atlanta and a friend that's a Nashville resident, and have almost no complaints. The food was delicious, the service was great (but I must disclose that my Nashville friend is good friends with the server we had), and I absolutely loved the sweet fruit ice tea. \nThe tables on the patio were set up kinda awkward, but I didn't get up much and we weren't really in a high traffic spot.  \nI did want more of a comfort food kinda menu, but I was starved when we were deciding on a place to eat so honestly, I would've eaten anywhere that I was taken."], ["My Grilled Chicken Caeser Salad was so-so but my dining companions each had one of their Philly Cheesesteaks which were huge and hot and delicious. Their cookie dough egg roll dessert was fun and a delicious end to dinner."], ["After roaming around Sunday late afternoon trying to decide on a place to eat, my boyfriend and I decided on Jackson's since neither of us had ever been there. We parked right in the back so that wasn't a problem. It was way too hot for the patio but that looked like it would have been fun to sit out there. We ended up sitting inside at the side bar because every other table was overly drenched in blaring sunlight. They perhaps need some blinds or something to filter some of that late afternoon sun. \n\nThe menu looked good and there were a few different things I wanted to try. We got the beer cheese dip and chips as an appetizer and it was super yummy and a very generous portion. I decided on the Pavo panini for dinner and honestly it was just ok. The bread was great, super crusty and perfect. But the sandwich lacked flavor. Perhaps yellow cheddar would give more flavor than the white cheddar they use? Perhaps mesquite or smoked turkey other than roasted? Maybe some spicy mayo? Idk. Just needed something. \n\nAfter reading through some reviews I'm seeing that bottles of wine are half off after 3pm on Sundays. Would have been nice if our waitress/bartender would have told us about the specials. We probably would have ordered a bottle. I was definitely interested in the cookie dough egg roll but decided to refrain since we ordered an appetizer. \n\nI would definitely like to come back and give this place another try, but next time I think we will wait until night time or at least when it's cooler outside so we can dine and relax on the patio."], ["Nice big patio that's great for a beer and french fries on a sunny day. There's a hospital a couple blocks away so expect sirens screaming in your ear the whole time."], ["There are some places you never tire of.  When you want a night out, you know of places you can go and get great food and service, without question.  This is how I feel about Jackson's.  \n\nI am partial to their paninis and wraps.  You can do no wrong with those.  They have amazing cocktails and have recently started serving locally-brewed Jackalope beer.  They are also open late, which as someone who very much enjoys late night dining at any opportunity, this is a plus for me.  I've come here for lunch on a weekend, for a sandwich and fries after a night of partying, and for the delicious spinach dip and chicken feathers (trust me, try these, they are incredible) after work with friends.  I've always had great service and have yet to have something off the menu I didn't like.  This is a perfect place for a date, a large party, a small get-together...its where my friends and I spend most birthdays and where my family wants to eat when they come into town.  \n\nI am obsessed with the pacific panini (get the tuna seared and get it with twi sides of wasabi mayo, it will blow your mond and clear your sinuses) and the rio roll (can't go wrong with chicken, avocado, and tomatos, I recommend getting ranch with this).  The chicken salad wrap with the additions of honey and bacon is another great choice.  When its nice, sit outside and watch Hillsboro village bustle around you.  This is a great place to be no matter the time of year or occasion.\n\nOh and two words...cookie-dough eggroll (or maybe that's three words, who cares, get this!!!)"], ["Went here for brunch on a Saturday and we went at noon and only had to wait about 15 minutes for our group of 5 which in Hillsboro Village is not bad at all! It was a great way to start a weekend! We all had mimosa's and they were good and not badly priced! \n\nI had the hash and it was excellent! I only wish it had a tad bit more potatoes but otherwise done nicely! I tasted the cheese grits and they were good and nice and smooth! I also sampled the french fried potatoes and they were quite tasty! I'm looking forward to going back!"], ["The new buffalo feathered caesar dressing is awful!  You need to switch back to the old dressing!"], ["Sunday brunch at 2pm. Good burger and shrimp & grits were delicious. The panini my friend had was not that great. \n\nDirty bloody Mary's were awesome. \n\nOverall great customer service. Patio seating was nice, people watching was excellent. Hillsboro is a super cute neighborhood."], ["I only knocked a star off because I sat without a beer for a little longer than I liked.  Other than that, I was pretty pleased with the place.  I had the croque madame, per the recommendation of the server when I was struggling to make a decision.  It was definitely way more delicious than I anticipated and even though you can't normally sub cheese grits in the evening, he hooked me up with some!  Service was top notch (outside of the one lapse in attentiveness), food was great.  All around good spot!  I want to go back for these egg rolls!"], ["Staff was incredibly rude. No one was working their front desk taking names. We waited 15 min with no one in front of us and everyone walked by us just asking us to move out of the way. They also made no effort to put tables together for our group. Was incredibly disappointed"], ["My boyfriend and I went there for Sunday \"brunch\" at about 3:00. The service was terrible. The guy had an attitude and actually slammed things down on the table.\n The food was bland and cooked improperly. I'm not sure how you manage to make the same egg dish runny & rubbery on the inside and burnt to a brown edge on the outside, but Jackson's managed to destroy these eggs with a level of personal vengeance normally reserved for cheating lovers or rival SEC football teams. You would need a forensic expert and dental records to identify that this was once a chicken egg with tons of tasty potential.\nWe also ordered a breakfast quesadilla and some breakfast eggroll things.  I have never in my life NOT finished a quesadilla... until this one. The cheese was runny, greasy, & gross. The breakfast egg rolls (by far the best of the lot) were chewy and tasted like fryer oil. We actually left food on the plates and went down the street to Noshville for a much better meal at half the price. \n\nThis is the second time I've been to Jackson's (once for dinner) and both times I've received the same, attitude-laden poor service and overpriced, poorly cooked, bland food. If you go there, stick to drinks. You'll be paying a premium price for your brews,  thanks to the location and the terrible art on the walls, but it's better than putting any of their horrible food in your stomach."], ["Awful service!! No one never waited on my groups table for 15 minutes. However, parties that arrived after us were waited on. I was to upset to complain. We just got up and went to Germantown Cafe."], ["Restaurant week menu was pretty good.\n\nAppetizer: The sloppy joe was NOT a sloppy joe. Growing up, I remember sloppy joe having sauce and as the name saids sloppy. Instead, it was basically ground beef (similar to in a Taco Bell taco) placed on a bun.\n\nEntree: The steak frites was good. Think the waiter screwed up the orders but we didn't realize it until half way through the meal. 1 was medium and 1 was medium rare. The waiter double checked himself at our table but the \"medium\" steak was bleeding all over its plate while the medium rare had no blood.\n\nDessert: Cookie dough egg rolls. WARNING: Good and rich. After having 3 Coke's with dinner, this dessert pushed me over the top. The egg rolls were hard to cut with the spoon and buried under the ice cream - hard to see. They had good cookie dough feeling that complemented ice cream well.\n\nAtmosphere: Sat on the covered patio. It is nice but logistically - this is ridiculous. I was asked to scoot up or move at least 3-4 times. I felt bad for the people next to us as they sat by the door and had people passing them the whole time."], ["This place was great.  I took two business partners here for dinner and we were extremely happy with the entire experience.\n\nThe Superb:\n\nA fun mix of foods.  Remixes of classics, such as the Alfredeux (chicken, pasta, etc. in a spicy cream sauce), were fantastic.  The buffalo feathers were delicious and quite spicy.  The desserts were also out of this world.  The deep-fried Twinkie is a must try, but the true standout was the gooey butter cake.  Finally, the server was simply fantastic.  He was funny, friendly, efficient and helpful.  Hooray!\n\nThe Average:\n\nA nice location, but nothing special about the decor.\n\nThe Horrid:\n\nThis was during the freakish hot weather at the end of September, but the amount of flies outside were out of control.\n\nI will definitely be back to Jackson's, and hopefully sooner than later!"], ["Went to Easter Brunch at Jackson's before visiting Vanderbilt University.\n\nWe were undecided on whether to go to Jackson's or the Pancake Pantry. We saw the line at the Pancake Pantry and decided Jackson's. That was a mistake. The Pancake Pantry had a line for a reason!\n\nWe were seated right away. The staff was a little uptight and the food was pricey for what it was. I ordered the Alpine Omelet. It came with one piece of toast.  I could of made better at home. I ordered a side of grits which were pretty good. \n\nSo my word of advice is: Go to the Pancake Pantry instead!"], ["Good food: We had the chicken fried steak and mashed potatoes as well as a favorite, the buffalo chicken feathers (with a little kick). \nService ok\nVery dirty restaurant from tables, chairs, windows, restroom, floors, etc. also a lot of flys and very warm inside when we visited.\nNot kid friendly but this was expected from a bar\nParking is limited"], ["We recently went to Jackson's for Saturday lunch and had a dreadful experience.  We waited 45 minutes for our food to arrive, and one of the waitstaff repeatedly dripped water on us as they carried clean glasses to the front of the restaurant.  Even after I asked our server to please have the person ensure they carried the tray of glasses away from the table, it happened a second time.  \n\nBottom line, the service was horrific and the food was highly mediocre.  There are way too many good choices of restaurant in Nashville to waste your time and money in Jackson's."], ["Jackson's was just OK for me, and I really wanted to like it.  Love the neighborhood and was expecting really good brunch because I had heard that about it.  Omelette was really average and the hash browns were almost flavorless.  Kinda bummed about it but their dinner etc may be better.  The Row and Noshville definitely have better brunch."], ["This place seems nice and has an interesting menu.  However, the execution and customer service leaves a bit to be desired.  We had brunch and while our server was nice, the omelette was incorrect twice.  The manager seemed more inconvenienced by our situation than anything."], ["We we're victimized by the  photos on the web page they looked appetizing. Then we proceeded to have worst lunch my husband & daughter could  remember having. \nPemento BLT  was a hot mess. Ahi tuna sandwich egually bad. Chicken salad bowl had rusty pieces mixed in. None of us finished our food. Just glad none of us got sick. BTW my husband said bathroom was filthy.\n1 star just to post a review. It's a ZERO"], ["You must try the Baltimore BLT with a Yazoo Dos perros or their dirty Mary! The pemiento panni was great but heavy. Even the little side salad was good! For dessert have a cookie dough egg roll."], ["We ate here for lunch on a Sunday as we were leaving town. It was packed, bug we only had to wait a few minutes for a table. The atmosphere was cool/trendy. Definitely a great place to hang out with friends.\n\nWe ordered the \"feathers\" with sesame BBQ sauce to start. They were an unusual appetizer but very tasty! I could have ate another order. My husband ordered the hamburger and requested they add a fried egg- no problem said the waitress:). I ordered the Rio Roll which had grilled chicken, avocado, tomato and cheese with a side salad that included chickapeas, cucumbers, and roasted peppers. I must say my wrap was just okay, not great. But overall, this restaurant will be a place I revisit if for nothing but drinks and an appetizer."], ["I don't understand the popularity of this place. My husband and I had lunch here on a Saturday afternoon. His burger was dry and cold. I ordered the fried green tomatoes and some French onion hash browns. The fried green tomatoes were okay -- they were hot and crisp, but the breading was bland. The hash browns were more like home fries, which is fine . . . but they were soggy and barely warm. They were topped with chunks of almost-raw onion and a slice of slightly melted swiss cheese.\n\nAlso, for a place with \"wine bar\" in its full name, they don't have much of a wine selection. I'll leave this place and its barely-mediocre grub to the college kids."], ["I've been in Houston since early 2008. I MISS the rio panini and their Long Island Iced Tea!"], ["I've passed by Jacksons numerous time but hadn't tried out the place until recently. I wish I could say that I had a better experience than I did. Maybe if I was one to partake of alcoholic beverages, the experience would have been more enlightening. \n\nThe patio seating (which we were assured was heated) isn't really made for winter time experience. I had to keep my coat on the entire meal, plus the tables and chairs are mostly metal which makes a cold room even colder. The room was also darker than I like for my dining experience, but once again probably ideal for someone drinking. Oh, and most of the time we were there, they would not give up on tuning the radio in, which resulted in about 30 minutes of flipping stations between music and static every few minutes. \n\nMy Mixto Panini was decent and full of flavor. The dessert was by far the best part of the entire experience. It seems that the Cookie-Dough Egg Rolls is all the rave, and I have to agree. \n\nI'd like to give Jackson's another try, but only during a time that I wouldn't be subjected to the patio seating experience."], ["Four Words - Buffalo Feathers Caesar Salad\nok, maybe three more - Gooey Butter Cake\n\nI'm in Nashville for the first time ever and stumbled upon this cute neighborhood while in search of The Belcourt Theatre.  Was hungry, looked across the way...and thought, \"Oh that place looks like it's happening, let's check it out\".  Glad we did, that's for sure!\n\nThe caesar dressing on their caesar salad is muy deliciouso!  There's a hint of horseradish that adds a little surprise kick.  But mixed with home made croutons and buffalo chicken \"feathers\"... C'mon now.  I was gagging at how delish.  \n\nCame back a second time with a bigger group and 2 out of 2 that ordered it agreed with me.  Yum!  And so came the yumminess of the \"Gooey Butter Cake\"... nuff said.\n\nMy last thoughts.... cake"], ["Service is great and restaurant vibe is fun and vibrant. Food is not good. It was really disappointing and was not seasoned. Probably wouldn't be back unless I was grabbing a beer and having a biscuit or something."], ["Used to ignore the typically slow service because I loved the buffalo feathers bowl so much - ordered yesterday and the caesar dressing has changed. Yuck. Switch back to the old dressing recipe!"], ["Waited 30 minutes to even get water, when we finally got service it was decent, but food was terrible. Portion sizes are a joke. Won't come back."], ["I have been to Jackson's before. If this was my first visit I would never return. Service was poor. The food was not particularly good. It seemed they tried to push us in order to turn the table. We visit for lunch on a Friday and ate outside."], ["Tried to eat brunch here last Sunday.  Unfortunately, after waiting 1.5 hours, we stopped waiting and went to Fido's instead, which was tasty and was much better at managing its operations.  If Jackson's had kept us better informed that the wait was going to be 1.5h, and if the hostess had actually called people's names instead of whispering them and then moving onto the next name, I could have given them two stars.  That being said, the 1.5h delay was apparently because the kitchen could not keep up with orders, which tells me that they don't know how to run a restaurant.  I'll go to Fido's again next time."], ["Phenomenal happy hour spot to meet up with friends and enjoy drinks and a cut above your average bar food.  Torrados all day every day."], ["Not sure what the hype is about Jackson's. I feel like the menu selection is scant. I've had it three times and two of the three times? Hair in my food. Typically slow service. I've heard great things about their chocolate chip cookie dough eggrolls but I honestly don't care enough to make it back. \n\nNice patio and good location."], ["I loved the food it was great! Ordered French toast, no where did it say it was deep fried and when it came I was a little shocked!  It was yummy but def fattening! \n\nThe Bloody Mary was perfectly spicy! \n\nWorst part of the place was how many dam flies were flying around! It was nasty!"], ["We decided to walk over to Jackson's after watching a movie at The Belcourt.  A friend raved about how great it was so we figured we'd try a post-movie brunch.  While one of us enjoyed (his favorite go-to) chicken and pasta dish, three of us ordered the Monte Cristo sandwich.  Mind you, I have fond memories of what a Monte Cristo sandwich can taste like from my experiences back east at Bennigans, so maybe EVERY Monte Cristo sandwich will pale in comparison.  This was bad, not just in comparison to Bennigans, but relative to any fantasy of what a Monte Cristo sandwich might be.  It was inedible.  Too hard, old tasting and greasy, and just gross.  NONE of us was happy.  A friend who REALLY likes their Monte Cristo's ordered a new one and, after they made new batter (?!) for it, they brought it out and he was happy.  I've been in Nashville for 13 years, work near Jackson's, go to the Belcourt all the time, but have never considered going there.  I won't be considering going back."], ["Sometimes you just gotta have a bloody mary. We stopped into Jackson for said bloody mary and a seat on their beautiful patio. We sunned and enjoyed a relatively mediocre Mary. We were also offered pumpkin Sangria which could either be terrible or delicious. Since they can't offer you a \"sample\" I'll never know. I'm not committing myself to a glass full of pumpkin sangria without some knowledge. \n\nWhen our coworkers showed up, we all decided to sit and have another bevvie. Sometimes I feel bad not warning folks that there's a table of Yelp community managers at their restaurant because maybe they'd behave differently. Then again, we want an authentic experience. \n\nAnd apparently here, when the server loses two twenties and we ask for the manager, that manager comes over and is rude, condescending and demanding. I've been a server, I get it. Stuff happens but when there are a table of six people, all of whom have paid their bills, it's very unlikely that one couple is trying to stiff you $10. Additionally, if you're a manager, don't insist on that $10 after someone at your establishment has caused said couple a $30 loss."], ["We were in town for a convention, needed to get out of the Gaylord and get into the \"real world\" for a couple hours.   We sat outside and had a terrific evening.The beer was cold and tasty and the food was casual and of high quality.  Our server was on the ball. We will be back on our next trip to Nashville."], ["Was going to brunch with my friend and this place had no wait so we decided to go here instead... guess that should have been our first clue. I ordered the chicken biscuits and my friend got an omelet. His omelet was alright, if not bland but the chicken on my chicken biscuits was so disgusting I didn't even eat one. It was over cooked and just did not taste good. Only plus was the sriracha honey butter. Will not be heading back here."], ["Had a really disappointing brunch experience here last weekend. I had been looking forward to trying this place for awhile. Last weekend we were looking for a end of weekend brunch with some girls. \n\nWe put her name in and were told 30 minutes. There was no system in place such as a buzzer  and there were lots of people standing around. We didn't hear our name but saw a large table sitting there for a long period of time. We went up to ask and were rudely told that yes it was our table . The rudeness did not stop there. Our waiter was fine but the staff that brought our food basically threw it at us and didn't explain which omelet was which and we had to figure out each persons order. No one was happy with their food. I ordered a scramble and it came out burnt. If we hadn't been waiting as long as we had I would have sent it ack. We were all excited by cinnamon toast on the menu. But when it came out it was bland and tasteless and very stale. My friend enjoyed banging it on the table trying to get it to break. Two of my friends got omelette s with different ingredients however were so tasteless that they tasted the same. The mimosas were good however I was charged for 3 when I only had 1. The second one I was charged for was due to our waiter mishearing my friends order for a Bloody Mary. When my friend said what she had ordered, the waiter asked if anyone at the table would want it. I said I would take it. I was also charged for a third drink which I never ordered or drank. That was taken off the bill after some huffs and puffs. I still ended up paying for the waiters mistake. I was looking forward to  Jackson's because as a Philly native I am always on the look out for decent cheesesteaks and have heard Jackson's  has one. However  after our brunch disaster I will not be back to try the cheesesteaks for awhile."], ["Colorado omelette- BOMB\nHashbrowns- more like fried potatoes n a slice of cheese, eh\nFrench toast- just short of amazing\nCheese grits- or nah\nSangria- MOUTHgasm \nPeach mimosa- DELICIOUS\nService....yea well....glad we didn't \"need\" anything \nOverall, I've always love Jacksons for the food and aesthetics-service has been hit or miss. But ask for Izzy!"], ["Small restaurant that seems like they can get pretty busy. Our waiter was very friendly and helped us navigate the menu and gave us some good recommendations. We ordered the spring roll quesadilla - definitely different, but the peanut sauce is super delicious. We wanted to just eat the peanut sauce. We both order ceasar salads and shared the chicken fried chicken - VERY good! Definitely worth stopping by at least once :)"], ["I'll be honest: I've never been a huge fan of the food here. I mean it's alright, but kind of pricey for what it is. That said, the drinks are decent, the staff is always friendly, and their patio is a lovely place to sit and drink on a pretty day. \n\nWhat I come here for though, what pops into my head any time someone mentions Jackson's, is the cookie dough eggrolls. Cookie dough in an eggroll wrapper, flash fried and covered in vanilla ice cream and chocolate syrup - sinfully delicious. That dish alone is completely worth a visit. Paired with a few glasses of wine, it makes for a delicious end to an evening!"], ["Got brunch here on a Sunday morning. Everything on the menu sounded great but what we ended up getting did not meet expectations at all. Food came out cold. This could be because of the extremely slow and inattentive service we got. The restaurant was dirty as well. A fly flew into my drink and I couldn't get a new one until I stood up to flag down the waiter to get one because he was no where to be found. Once we finally got our subpar food I noticed that my silverware was dirty as well. \n\nThe eggs, sausage, and biscuit I got were fine. Disappointed that the biscuit and sausage were not warm. It wasn't the worst experience I've had but definitely disappointed and I will not go back."], ["five stars for the deserts. the food is decent, and the vibe is not the sort of thing i'm into. but the desserts, holy mother fuck, the desserts. i've tried the deep fried snickers bars, the cookie dough egg rolls, and the mega butter cake. let's talk about this butter cake, shall we? all right:\n\nimagine, if you will, some butter. straight up butter, made with extra rich cream. throw some sugar in that, mix it up, and form it (carefully) into a brick. now, throw a bit of vanilla in the mix, and barely enough flour so it won't implode in the oven. re-form into a brick, heat it up, and throw a scoop of ice cream on that bitch. the first time i ordered this, i had NO idea what i was getting into. the second time, i ordered this with a glass of milk. everyone was looking at me like i was an idiot (as they all had drinks), but if they could understand what was going on concurrently in my mouth and stomach, they would have followed suit.\n\npeep the cake and enjoy the world for a a few minutes, it's not too often that you can these days, right?\n\neric b"], ["The food is great but the service can be hit-or-miss, especially when it gets busy and people are waiting in lines to get seated.  \n\nI've been here a few times and love the fact that the place can be considered indoor or outdoor anytime it gets cold or warm out.  The structure is built with a lot of windows and hatches that can be opened to have the restaurant open to the outdoors.  It's pretty cool to see, especially when a few other restaurants in Nashville have similar mechanisms to their windows or patio doors.  They have a full bar here which makes it a great spot to have a drink on the weekends or make a stop between bar hopping around the Village.  \n\nI give it 3 stars because I had horrible service during a busy day during lunch.  I ordered about 30 minutes before my friends and they received their food first, while about an hour later i never received my food.  And left the place, perturbed.  But alas, if you're patient enough to wait for your food, the food is good here.  But I'm not sure if I'll return here when it's that busy again."], ["I once said I wouldn't eat here and I've had to eat my words (sort of!).   I've eaten here several times now for breakfast with my beau :-) breakfast is great here and they have a nice sampling of breakfast cocktails too ;-)"], ["First time eating  here was fantastic. Unfortunately Sunday brunch left quite a bit to be desired. 1 hour wait time for food. People who came in after us were served before us. The food was no where as good as the day before. Our waiter ( Michael ) had the personality of wet cardboard. Very disappointed!"], ["I love this place. I'm a little confused to see the less than happy reviews. I guess I've just never had that experience here. \n\nI live in the Village and this is my go to brunch spot. The chicken biscuits are completely to die for good. They're one of my favorite things I've eaten ever, actually. They bread and fry a chicken breast, cut it in half and place it on two fluffy, amazing biscuits. The whole thing is served with honey butter, made with local honey. It's sooooo good. \n\nI also had some really tasty hand battered sausage \"corn dogs\", some wonderful cheese fries and their awesome desserts. The cookie dough egg roll was great, but the butter cake was really amazing too. Like wow I couldn't stop eating it. \n\nAnyway, I've always been seated quickly and served in a really timely manner. Their coffee is awesome and I love the seating area near the garage doors that open up to the outside. I would take friends there from out of town without hesitation."], ["Arrived in Nashville and found Jackson's.  I was with my friend that I had not seen in a long time. We sat at the breakfast bar, had bloody mary's and beers (so good!) and a few plates to share. We had the fried tomatoes, loaded fries and chicken feathers.  The feathers are a cool idea but a little dry and a bit like jerky, but tasty.  The food was ok, drinks great and service really personable and welcoming.  I would go back, early.  As we were leaving at 11'ish, there was a wait and it got really busy."], ["Had a wonderful dinner on the patio, where the staff was very solicitous of my little dog. Had a perfectly prepared Bombay sapphire martini, the grilled salmon with chunky parmesan mashed potatoes and a glass of Glass Loop sauvignon blanc. Yummy. I would mark off a half point because of the very low lighting but that would be quibbling."], ["In Nashville for a conference. My traveling companions range from picky eaters to epicureans. Everyone was pleased with their meal from Jackson's. The wrap that I had was flavorful without being overwhelming, and the fries were a hit. Service was prompt."], ["Well....I am sorry to say, but my experience here pulled me out of my yelp review retirement.  Yes, it was so terrible that I felt I owed it to my dining companions to be aware to avoid this establishment.  I don't really know where to begin, so I will just dive on in.  My husband, newborn and I decided to try this place for brunch.  Husband ordered a chicken sandwich.....I asked for the Savannah omelet add mushrooms....\"no problem.\"  After waiting an extensive amount of time for the meal (remember time is extremely precious with a newborn)....I look down to see the omelet has no mushrooms and no cheese....server said that they would take care of this.  After waiting for another extensive amount of time (at this point wished I hadn't said anything) it comes back.....without any mushrooms and cheese again.....on top of that the egg yolk wasn't even mixed in so was actually like a fried egg in an omelette.  We mentioned it to the server...she corrected it by bringing out raw mushrooms.  No apologies...even mentioned it to the host......nothing....on top of it, my husbands chicken sandwich was rubbery and cold.  Take home, stay away from Jacksons."], ["We were in Nashville for the weekend and looking for a place for dinner, so I fired up the ol' laptop and went surfing for a cool place with local flair (I can eat at Chili's in Atlanta). We came across Jackson's, looked at the menu, and decided this is where we were going to have dinner. I had the steak frites for dinner and gooey butter cake for dessert. The steak was good (not great), but the French fries were awesome. The salad has a champagne vinaigrette dressing which was quite tasty, too. I think what brought it home for me, however, was the dessert. The gooey butter cake is topped with soft-serve ice cream. I can describe the combination in one word- YUM! I will definitely be back the next time I'm in Nashvegas."], ["I stopped in for a quick bite of lunch and had the patty melt. Just average but the service was good and quick. I would recommend this place for a Saturday afternoon long lunch when the windows are open and you have time to chill, drink, shop and relax."], ["I recently visited some friends in Nashville and one of nights I was there we had dinner at Jackson's. The place was packed but we didn't wait that long for a table, and after being seated the service was prompt. They have a nice beer and wine list and a decent list of house drinks, and the menu is pub grub with a gourmet twist. I had the Moulle and Fries and was definitely impressed. My meal didn't take me back to Brussels (where I had the best mussels and fries EVER) but it was nice and the broth was very tasty. I wish I had saved room for dessert but didn't because there desserts (I was told) are killer!\n\nDefinitely a good time in the Hillsboro area of town! Will be back when I'm visiting again!!"], ["We headed to Jackson's to get out of the rain and enjoy brunch and bloodymary's... Then we realized it was Friday. Guess that is what vacation does to you.\n\nI got the burger and it was perfect. Just the right size and perfectly cooked. We still ordered bloodymary's and they were amazing! To top off the meal we had the choc chip cookie dough spring roll... one word - AMAZING! This is a must order."], ["I came to Jackson's for the first time today while entertaining some friends in town.  We wanted to go to Fido, but didn't feel like waiting in the forever long line only to hunt for a table and wait for our orders to arrive.  So Jackson's it was.   The restaurant was equally busy and seemed to be complete chaos, though we were seated rather quickly despite everything.  \n\nWe ordered Jackson's standard lunch fare of sandwiches and wraps, all of it fine, none of it great.  The service was the same.  I'd go back again if I needed to, but I won't be rushing back anytime soon."], ["Jackson's has always been a safe bet for me. When I lived in Hillsboro Village, I went nearly every week and was always satisfied with the great food and drinks. \n\nThe patio is INCREDIBLE in the warmer months, resembling a more European bistro and giving Hillsboro Village a prime people-watching spot!\n\nIt's hard to go wrong with any of the small plates. My current favorite is the Tacos del Mar-- Ahi tuna lightly seared with fresh pico de gallo. REALLY bright flavors! When it comes to entrees: I generally go for the yummy chicken salad torrado and fries, but if I feel like a bigger meal I almost always go with the Pasta Alfredeaux. It's a heavy, creamy pasta dish with a Cajun twist: the andouille sausage and peppers give it a great kick!\n\nDrinks are awesome. The French Martini was my favorite for years, and then I got turned on to their sangria. On a lazy summer afternoon, this drink certainly does the trick. There's also a great beer selection-- 2 for 1 Tuesdays are a no-brainer.\n\nLike other Yelpers, my only complaint is regarding the quality of service. They just don't seem to care much about it. Service is guaranteed to be spotty if you visit during busier hours, and sometimes it will be spotty on a normal, quiet night. It's always been this way, and I've simply come to accept it. Not a real deterrent for me. I will always go back!"], ["Went here for happy hour. Good atmosphere. Didn't try the food. I loved how the bottles and glasses of wine where all one price. Not sure if that was something special or an everyday thing. Will be back in the spring to use the patio!"], ["This is my favorite locale for a hang over cure.    Their Bloody Mary's are to die for (make sure you ask for Absolut Peppar) and their other drink specials ain't too bad either.  Their food is delicious.  Not quite gourmet but definitely crafted with care.  Maybe a little too heavy, but that is why it is great as hang over joint, you gotta soak up all that alcohol somehow.\n\nDefinitely a college kid favorite but it's always good to be around some young blood to rejuvenate these old veins."], ["Compared to my last visit, I was much more impressed the second time around at Jackson's. I went for drinks and dessert and the fried cookie dough egg rolls were out of this world. If you are in the mood for a sweet treat in Hillsboro Village, skip Sweet Cece's and come here for dessert."], ["Had a fine experience here one Wednesday night: two for one drinks, hangover omelette, buffalo feather caesar salad and cookie dough eggrolls. The food was okay, the drinks were appreciated, and the server may have been one of the most handsome men I have ever seen (seriously, like an Adonis that man). \n\nSeated promptly, service was okay if a little slow, although so, so pleasant -- seriously, he smiled all the time and made some recommendations I appreciated. No complaints. Would come back. \n\nOne quick thing though -- although the cookie dough eggrolls were good, I was not blown away. Too much eggroll, not enough dough, ultimately pleasing but not WOW. Just so you know. Still worth eating though, if you're feeling gluttonous."], ["Jackson's is open super late, which is key. It's the perfect spot to grab your drunken munchies to avoid that nasty hangover the next morning. The menu offers a variety of types of dishes and prices. I think the wasabi caesar salad with seared tuna is really good, and I love the Sonora wrap with shrimp. Some of the other items have let me down a bit, like the french onion soup which was all salt. The drinks are not cheap but not bad either. The atmosphere is laid back, and attracts an interesting crowd for the most part. I like this spot for an afternoon or late night meet-up with friends. It's not romantic, so take your date elsewhere unless you want to keep it casual! I look forward to some summer nights on the patio here."], ["Awesome brunch food and brunch cocktails.  Cool atmosphere.  Good service.  They don't have hashbrowns but \"flash-fried\" potatoes.  Their 'Monte Cristo' breakfast sandwich was fantastic.  Their potatoes weren't good but everything else was.  They had decent bloody mary's but don't give you a beer chaser - maybe thats a Wisconsin thing.\n\nThe outdoor dining area was great."], ["Jackson's is a nightmare at brunch and is brimming with half-drunken folks most summer weekend nights.  That said, it's one of the few patios in Hillsboro Village, and even though the furniture's plastic it's a nice place to spend a summer afternoon or night.  The waiters and cooks are usually fun, and the management doesn't punish them for being quirky and interesting with customers.  And no, I don't mean quirky as a euphemism for rude or belligerent.\n\nThe real gem at Jackson's is the back bar.  If you're the kind of person who likes to pick a nearby pub and hang out regularly, Jackson's is for you.  I spent a number of Sunday evenings at the back bar, reading the paper, studying, having a pint, watching some sports, and talking to the other folks.  You'll get to know the bartender and the other regulars, and the bar's set off in a corner of the restaurant so it can maintain its own laid-back vibe."], ["I've been to Jackson's for lunch before and been happy with the food and service. This weekend, I went for brunch with some girlfriends, and did not have a great experience. We expected to have to wait awhile to get in, but the long wait once we were seated was not expected. It took a long time to get drinks, then not all of them arrived. One was missing a straw, and it took forever for the waiter to bring one back, and he still didn't have the missing drink. Same thing happened when the food finally arrived, and all but one of us were served. Everything just seemed really disorganized. To top things off was the \"French toast\" I was served. It was deep fried! The menu does not indicate that they deep fry their French toast. I get that we are in the south, but do we really have to fry everything?  I was so hungry from the long wait, I ate it anyway. It tasted ok, but I had a stomach ache from all that grease for the rest of the day. I think we'll be taking our brunches elsewhere in the future."], ["Out of the multiple restaurants I visited during my vacation in Nashville, and this was probably the worst. The panini was two slices of burnt bread with thin cheese spread around. The price was ok, but really, Jackson's is an unappealing rubys. I say that because of the similarity of the two menus. The service was ok, and the reason I gave it 2 stars instead of one is because it has some pretty cool dec\u00f3r and a hanging fireplace that I loved. Maybe find another spot to eat!"], ["Brunch = yes\nBloody marys = double yes\nservice could be better sometimes, or I would give it 5 stars."], ["Wow! Where do I begin??? First off if this place actually got 100 on their health score, no one should ever eat anywhere in Nashville! This place is DIRTY!!! The server was on another planet. Service was very slow, food was slower. As we got up to leave after waiting over an hour for food, the tweaker girl delivering half of our order that had sat in the window for 20 minutes, said \"oh well, we tried\"..Excuse me??? Tried what??? This place was a horrible waste of my last morning in Nashville! No line at Jackson's for a reason! Go across the street and stand in the 100 person line at The Pancake Pantry. You'll get served faster! Avoid this dump!"], ["I really like this place. I think they should feature their pimento cheese burger because it's really phenomenal and it's hard to locate on the menu. \n\nFor whatever reason I also get Hendricks martinis here and they're delicious. \n\nIf the fries were better I could eat the burger every day. \n\nBuffalo feather salad and the tomato\nSoup are good as well."], ["I dig this place, not as much as my friends do, but I gotta say this place and me are on good terms.\n\nMay I suggest you try their Baptist Wedding Punch, which is a beverage consisting of Keke Lime Liquor and I believe Sprite but I may be mistaken.  It is astoundingly good and will probably lead you on a 7-store run to locate Keke Lime Liquor, but that might just be me (go to Froogle MacDoogles, they have it)\n\nAnother thing you should sample there is their take on a traditional Absinthe.  You probably aren't going to meet the Green Fairy off of two or three of these but chances are you're going to figure out how to hail a cab real quick.  It's not what we would consider real, but it's a good enough approximation of a traditional Absinthe.  Just remember, if you're in a conversation with the waitstaff and forget who you're talking to, stop.\n\nFor their food, as I recall they have 1 pasta dish and 1 panini dish that are veggie, they're ok, but not particularly special.  The special comes out in the deserts... like a flavor ninja, you are assaulted by taste but didn't see it coming.\n\nCookie dough egg rolls are awesome, I was about to go into a list of what is good on the desert menu but I'm pretty sure it's easier to just say all of it.\n\nPrices are not unreasonable for the area, but beware the tap beers range from ~$3.50 to $8, so you might want to check what you're drinking on a budget or you might want away with a bar tab of OMFGWTFBBQ!!!11eleventy\n\nParking is Hillsboro Parking... they have their own lot but that means 10 or so cars can fit there, so just plan to park on the street behind Sunset Grill or in the lot over there and you should be less aggravated getting there.\n\nRemember, if drinking here before going to the Belcourt, allow for an additional 3 minutes of walk time as the only time there's serious traffic is when you have to be there for a movie.  Traffic is peril sensitive, and will bunch up just to spite you.  You'll be wearing all black for some reason at night, be plastered, and unable to safely able across..."], ["So overrated I almost can't stand it. How they have 3.5 stars on yelp is a joke. I have been 3 times in the last year and I will never go back. \n\nThe service sucks every time I go. The waitstaff is awful. You have to beg to get a refill on your drink and when you do, it's like they are doing you a favor. \n\nThe food is pedestrian at best, and way overpriced. Their tuna is priced like fresh Ahi and tastes like packed catfood. \n\nIf they didn't have a patio and they were located anywhere else in Nashville, it would have closed down years ago. \n\nSave yourself the money and aggravation. I would seriously rather eat a McRib than go back there."], ["I don't usually leave bad reviews, but this experience warrants one. I normally go in to Jackson's for dinner and usually end the night with their creamy awesome milk shake. The other day I decide to walk in during lunch hour to grab a milkshake to go. When I sit at the bar, I ask the bartender if I could get one to go, and he just says, we don't serve Milkshakes. And I sit there with a puzzled look on my face, and he's like we don't serve Milkshakes, and I'm like, since when?! And he goes on to explain that their machine has been down for 6 months, which is totally not true as I was just there 2 weeks prior to this visit. In any case, as a good patron of the business, I inquired about when the machine will be fixed. And he rudely replies and says it's not coming back, it's not worth fixing, and they don't serve milkshakes, as if I didn't hear him the first time. \n\nWell, you can keep your rudeness to yourself! Because you've lost a customer for your terrible way of handling a fairly simple question and inquiry."], ["Great beer selection and knowledgeable server.  Tried a few of the high gravity beers and they were all delicious!  And you get the whole 12oz bottle, not 6 or 10oz like some other bars.  5 stars for the ooey cake, amazing!!!!"], ["I'm torn between 3 and 4 stars, but because I can't stop going back...4 stars.  Jackson's is pretty much hit or miss, your food can be awesome or it can just be so-so, so ehhh.  \nJackson's is a place where you can go mid-day, literally any day and find people sitting outside enjoying themselves over cocktails and beers.  The service is typically pretty slow but for the most part its worth the wait.  Thursdays if you bring your college ID you can get 2 for 1 beers, which is always nice.\nHighly recommend:\nCaesar salad with chicken strips(shit forget what they are called but they are soooooooo goooooood, GET THEM)\nTorrados, essentially warmed up wraps, the Rio one and the Tuna one are especially good, fries that come w them are worth it\nCookie.Dough.Egg.Roll.\nAlso a good place to come for brunch, or to nurse a hangover!"], ["I like Jackson's, but I feel like I like it for more of the feel of being in Hillsboro Village and sitting on the patio on a beautiful spring night rather than the food. The food is good, don't get me wrong. There are other places that definitely beat Jackson's. I tried several of their panini's and wraps, and they were all very tasty. However, its the atmosphere that makes me want to come back. \n\nI've been to Jackson's for half-off bottle of wine on Sunday, which is amazing. What a great way to spend the end to a weekend than with a group of friends and a cheap bottle of vino. Maybe add a little patio to the mix to make it absolutely perfect. This is why I like Jackson's.\n\nBUT, I must say. DO NOT, and I repeat, DO NOT leave this restaurant without trying the cookie dough egg roll. Now, you may feel as if you will die after downing this delectable dessert. It is probably one of the most amazing things that you will ever put in your mouth. Trust me on this one. And also share it with the table because it will most likely be too much for yourself. And that's all I have to say bout that."], ["We had an amazing Saturday morning brunch this weekend! We went about 10:30 and there was no wait but it was full when we left. The service was impeccable and the manager even stopped by. The bloody Mary's were outstanding. The food was delicious! The sausage gravy was the best I've ever had! We ordered the fries with gravy, chicken and biscuits, breakfast tacos, and an omelet. The only reason I'm not giving five stars was the tough flour tortillas and my husband kept being served lukewarm coffee. We would definitely go back!!"], ["Jackson's is borderline expensive, but delicious nonetheless. It is an interesting combination of fresh food and fried food, so there is something for every taste bud."], ["The food here is just average. Even if I was hung over can't say I could come back. Service slow and spotty. Not a lot of customers in here either. Wait in line for the pancake place across the street."], ["I won't eat at Jackson's but they do have some nice drink specials.  Great for people watching.  And the patio is nice in the summer.  And...they have Fox Barrel Pear Cider :)"], ["I've been trying to figure out why it is that I haven't reviewed Jackson's yet, despite the fact that it has one of my favorite dishes in Nashville (the Champagne Salmon Caesar). And what I've come to is this: It does a lot of things well, in fact it does them great. But a lot of things just really could be improved upon. And every time I've thought about writing a review, I didn't want to pin them down out of the ether. But I suppose today is the day. \n\nThe biggest thing I think Jackson's could do to improve its experience would be to get better tables and chairs for outside. They have such a great large patio area and that wonderful Tuesday happy hour, but every time we sit outside someone's legs or skirt ends up getting wet because of a bumped table and shaking drink. The waitstaff here is very hit or miss. Sometimes I get fabulous servers, but I've also been left at a table before for 20 minutes because they ended up switching tables on us and now no one knew whose section we were in. Same goes for checks. I can't count the number of times we've been unable to locate our server when we wanted to get our check and leave. \n\nAs far as the food, I've usually had good experiences. Brunch is great, as is the other food. I will say this: the Salmon BLT really needs to be reformulated. This was one of those sandwiches that you can't even attempt to bite into, it's so towering with the extremely thick bun and thick salmon fillet. Probably 5 inches high. I had to take it apart, cut the salmon in half, and eat it open face. Which I guess is fine, but if I'm ordering a sandwich, I expect to be able to bite into it. Last complaint: Tuesday happy hour, while a great value, would be better if they wouldn't bring you both drinks at the same time. It's fine if you have a friend who wants the same drink as you and you can each take one, but otherwise your second drink gets warm or watered down, especially if you're hanging with friends and enjoying the afternoon, wanting to take your time.\n\nAll of these things could easily be addressed, and I wish Jackson's would change them. If they did, I can guarantee I would be spending as much of my money there as I do at the Mellow Mushroom happy hour, which, let's face it, is half-price every day. They don't have the nice patio but they're way more consistent. Or Cabana with their $4 wine and fab martini specials. For now, I only go to Jackson's when the craving for the Salmon Caesar overwhelms me, but mostly I keep it in check."], ["Jackson's. I've been here 4 times now. There is just not a thing on the menu worth eating--maybe the ice cream? The only reason this place is still in business is because of the patio.  Which is hardly a patio--by most standards it's a garage.  People cite hipsters as part of the atmosphere. Hipsters know better than to eat here."], ["Would go 3 1/2 stars really.  Food's good.  Atmosphere is often more bar-like than restaurant, but that's ok with me in Nashville somehow.  For pure drinking bliss, go to Boscoe's and handle up on some Alt bier, but if you need grub with your suds, this is a slightly better bet."], ["Decent food, good location and ambience, but awful management and service."], ["Since Jackson's was part of Restaurant Week last week, my wife and I and some friends of ours decided to give it a try. My only complaint is the parking. I don't know if the difficulty in finding a parking place was the result of increased business for Restaurant Week or if it is normal for Friday night, but parking spaces were scarce.\n\nOnce inside, though, the atmosphere was pleasant if loud. It was difficult to hear what anyone at our table was saying, and it was equally difficult to hear what our server was telling us. \n\nI ordered the Memphis Pork Chop, and was very pleased. It was cooked to my liking and the cheese grits served on the side were very tasty. The Pimento Cheese and Crostini we ordered as a starter was also very good. The other three in our party ordered the Steak Frites, and they all said it was delicious.\n\nService was friendly and fast, despite the fact that the place was packed. The restaurant appeared clean as were the rest rooms."], ["When my friends and I can't decide on where to eat, I always suggest Jackson's.  Love the food. It's always flavorful (sometimes overly-so) but never bland and the dessert options are killer.\n\nFood:  The burgers are delicious--moist and juicy.  But, I always without fail order the Pacific (panini with blackened ahi-tuna, provolone, and pico de gallo) served with a side salad.  I always try to convince myself to try something new, but the Pacific is just too darn delicious for me to venture out into no-man's land.  You can also get salad or fries with your meal.  Desserts are cool too.  I'm a fan of the fried cookie-dough egg rolls served with vanilla ice cream.  It's a big hit for any lovers of the chocolate chip cookie dough ice cream flavor.\n\nFor the most part, their meats are cooked perfectly.  However, my latest visit ended up with both my tuna and my bf's burger being overcooked.  We were starving and ate it anyway, but the manager told us that the cook was new and was still learning.  He ended up giving us a complimentary dessert--and who can say no to those cookie dough egg rolls!  Of the twenty-some times I've come to the restaurant, I'd say that night was a fluke.\n\nAtmosphere:  It is quite loud and somewhat crowded.  Has that urban grunge feel.  Can get quite crowded at nights and late night.  Patio is prime parking for people-watching."], ["Only giving them 3 stars because bartender Amy was really great. Smiley and professional. However, I wasn't expecting Salisbury steak when I ordered the BBQ meatloaf. And the staff lingered around the corner of the bar where I was eating. They need to take their gossip and loud silverware rolling away from customers who are trying to eat."], ["I feel like it's my duty to warn others about the poor quality of the food here.  Overdone omelette with cold toast, french toast with a sour after taste that we had to throw out, weak/stale formosa drink, \"hashbrowns\" that are really just potato wedges with cheese on top, etc....  We were literally just trying to \"get through it\".  \n\nThe service was pretty good though:)"], ["People watching. \nSure, it may linger into stalker territory every now and then... but damn it's can make for a great time, no?\n\nJackson's always offers up some of the best of one of my favorite hobbies as the Hillsboro Village scene is always a melting pot of students, hipsters, celebs, homeless people full of pizazz, tourists, and industry folk. JACKPOT! \n\nI happen to know several of the endearing staff at Jackson's and know that the crew at this casual spot offer up spunk and drink specials like it's going out of style. The patio is THE place to be when you order up your drinks and bites. I am deducting one star due to the fact that there currently aren't any vegan friendly options which surprises me considering their location and clientele. However, prior to my animal lovin' days.... the Ahi Tuna sandwich with wasabi mayo and chopped salad was on my lunch agenda at least a couple of times a week. \n\nJackson's does offer up popular brunch menu and also an enticing late night menu to seduce you after you have inhaled several of their many brew offerings. I also enjoy their wine list which is updated fairly frequently.\n\nIf you are looking for a deal, pop by after 3pm on Sundays for 1/2 price bottles of wines until midnight.\n\nCan you get snockered during a business lunch or host an early happy hour? If so, take your client here from 11am-6pm for 2-for-1s on beers, well and call drinks. \nBet you can close that deal after a few of those....\n\nTIP: Super pup-friendly patio! Sometimes my little Chico gets his water before I do!"], ["I have been told this is a pretty popular spot and it came pretty highly recommended.  We came when it was fairly unbusy, so our server was pretty timely and attentive. What really pushed this up to 4 stars was the food.\n\nThe fruit tea (no regular sweet tea) was nothing fancy, but refreshing. For the meal I had the Baltimore BLT, which consisted of a crab cake (a pretty good one I might add), lettuce, tomato, bacon, and a super delicious wasabi sauce.  Now I admit I may be a little biased due to my love of wasabi, but it was a seriously frickin' awesome sandwich! While I've heard good things about many of the other menu items, it will take some serious will to order this next time I make it to Jackson's."], ["I met up with friend today and he suggested we eat here for lunch. Since it's 100 degrees outside, I wanted something light and refreshing. I ordered the fish tacos from their small plates menu. They were two nice sized tacos, plenty for lunch. \n\nLiving in San Francisco, I guess I've gotten spoiled with what a fish taco should taste like... I was expecting really fresh fish served with lettuce, tomato, and a slice of lime. Instead, it was served with a side of sour cream and guacamole. Hmm, ok. Overall, these were pretty ok. I've had better, but these were by no means bad. \n\nService was really good. I was greeted with friendly, smiling faces as soon as I walked in and they were really good about keeping our water glasses full."], ["Amazing new menu that is very friendly to those trying to eat a healthy diet!  Quinoa, brown rice, Brussels sprouts, veggies, its all there, and it's delicious!"], ["This once cool place is now an awful hole, the food is limited and doesn't match their menu...and they are so rude about it you need to take a Xanax to clam down enough to deal with the manager. This place deserves to go out of business and don't worry about the employees, they didn't really want a job in the first place...and it shows!"], ["Jackson's is a great bar that needs to be managed better.  They need better seating outdoors and more servers to accommodate the large crowds that they draw.  The food is average but their drinks are spot on.  Try the Baptist Wedding Punch - it will knock your socks off!!"], ["Well it's tuff to give any stars when you never get seated. We got there put our names on the list. Said 20 mins. Not bad we thought. Ate here before and it was good. 25 or so mins later we went in and asked how much longer. This was after we noticed a couple groups just walk in and sit at one of the multiple empty tables with out ever checking in. Hostess said there was still 8 groups ahead of us, there wasn't 8 groups waiting. She didn't have a clue who had been sat or not. When we asked about the people coming in and sitting she said \"like um some of our team members are like um not on board with like um the wait list\" what does that mean you ask. It means apparently you can just bypass the people waiting outside, walk in, find a seat and they will serve you. It was the most ridiculous thing I ever heard. So we just left. It's sad because this used to be a good place. Been here a couple times but whoever is managing it now needs replaced ASAP. Based on the other reviews I read I guess this a trend. Won't be Back. Won't recommend to friends."], ["Stopped in for some brunch on a busy Saturday- the brunch was delicious! The service was good for how busy it was, but we did spend a little time waiting for our check. We were kind of tucked in a corner that had little leg room, so if you're OK with the busy type but don't mind waiting for awesome food, then this is the place for you."], ["I love Jackson's. One of my favorite menu items in town is their pulled chicken pasta. Paired with their alcohol laced root beer float cocktail, and the cookie dough eggrolls, and I'm in heaven. I've had consistently good service from them for years. The reason for four stars instead of five? Well, they've changed the recipe for my beloved pulled chicken pasta (somethings off with the tomatoes-peppers-chicken ratio in the last couple of months). So the last time I was there I glanced at the menu and realized that nothing else really seemed appetizing. There should always be a plan b available, and Jackson's just doesn't, at least to me.\n\nBut seriously. Cookie dough egg rolls. Liquored root beer float. Yummmmm."], ["3.5 stars. \nWe came here for brunch and got seated right away. Considering the general hungover state of the party (please ref the ms. keli's review for clarification) and the huge waiting lines everywhere else, Jackson's won my heart immediately. The croque monsieur I ordered was tasty, but not out of this world. Others in my party ordered different items that all looked a little monochrome (yellow) and a little messy (all looked like hash even when it wasn't supposed to be). I hear the food was tasty though. The menu was varied and inexpensive. The waitress was great at refilling the essential diet cokes. And- my favorite thing in a brunch place! All sorts of coffee drinks to chose from. hm. mocha."], ["This was my favorite places in my brief visit to Nashville earlier this year. Super cute bistro/bar in a super cute neighborhood. I still have dreams of the Butter cake a la mode. I'm not even kidding- all of you Nashvillians better appreciate that delectable dessert. \n\nWhat I got:\nThe Rio Panini\nGoey Butter Cake\n\nWhat it was:\nDelightfu"], ["Jackson's is conveniently located by the Belcourt Theater. I hadn't been there in years, but it had always been a serviceable option for a quick drink and snack before a movie. On my recent visit, our server was extremely bubbly and helpful; the food, however, was quite poor. Chicken Feathers, which supposedly mimic Nashville Hot Chicken, are awash in Texas Pete-style hot sauce and bear no resemblance to the crisp, spicy original. The real offender, though, was the Ahi Tuna. When asked how I wanted my fish, I requested rare. What came out was well-done and completely white. The bubbly server was happy to take it back, but it's replacement was barely cooked at all and was still icy in the middle. Our server asked how it was, and I told her not good, but don't sweat it. At that point I just wanted out of there, but a manager returned with my first piece of fish for comparison...that's right, she pulled the fish out of the trash or wherever and stuck it back in front of me! I told her I didn't want to discuss further it and to please leave us alone. It was apparent that no one at Jackson's--not the cook, manager, or bubbly server--had any idea what Ahi Tuna was supposed to look like. So unless you're just looking for a quick drink, avoid. Two stars for exuberant service."], ["I must say my experience was pretty mixed at Jackson's.  \n\nFirst off, its very busy on a Friday Night.  There is technically parking available across the street, but if you park there for Jackson's you are expected to pay 6 dollars.  There are ways to game the system and likely get away with it if your visit is going to be less than two hours, but I don't endorse these.\n\nThe place itself is quite small for the crowd it generates, but overall the atmosphere is quite festive.  Or would have been, except we were the first people to arrive to get to enjoy the wonderful \"Indoor/outdoor\" seating option on the patio.  Now if it was Summer time, this would be a great choice.  But its 20 degrees outside, so even with the \"heat\" they claim this room receives, it was cold.  Someone came out to \"check\" the \"heat\" but I don't know if it was ever actually provided.\n\nThe real problem was the radio out on the patio was not tuned properly and we were treated to static intermixed with some occasional music, followed by more static.  I spoke with three different people about this, who's feelings about it ranged from disinterest, to pretend interest, to pretend enthusiastic interest.  Apparently though, they were obsessed with providing a musical accompaniment to our meal. It did finally get properly tuned, but only after our having to suffer through it for far too long.\n\nThe food was decent enough, but nothing special.  The French Fries were a bit over-salted and slightly over prepared, but the sandwich I ordered was good.\n\nThe entire experience would have been nothing more than 2 stars UNTIL the Chocolate Chip Cooke Dough Egg Roll arrived.  I was thinking about this thing an hour after I had finished dinner!  outstandingly delicious!\n\nOverall if I ever returned it would be more likely to sin again with this wonderful dessert. If I were to recommend it, it would be for that only."], ["I found myself at Jackson's on Sunday because I wanted to try something new other than Sam's across the street, but I wanted to be close to Sam's too so I could catch the race later in the evening.  Plus they had a patio and the weather was fabulous!\n\nSo we grabbed a table on the patio and checked the menu out while sipping a very good bloody mary.  Just the right pepper spice.  Our waiter was super friendly even if he was kind of slow overall.  The menu includes sandwiches, salads, burgers, entrees, drinks, etc.  Just a something for everyone type menu.  The vibe - yah, a little college, a little douchey, but overall I thought it was laid back.  Not too much of a party atmosphere despite it being Sunday Funday - I expected drunk people and drunk antics going on but it was tame.  Too tame for a holiday weekend in my opinion.\n\nSo we got an appetizer to start - the slice of jalapeno mac-n-cheese. I am a huge mac-n-cheese fan so I was excited.  This mac and cheese is baked with breadcrumbs on top and is served in a slice like a pie with a cup of pico on the side.  It was as dry as the desert, not creamy cheesy deliciousness.  And the jalapeno was not present or at least it didn't taste like it.  The pico was weird - why?  It didn't add anything to the taste and actually detracted from it.  This mac and cheese was a fail.  \n\nI had the crab cake BLT for my entree with fries.  This was better than the app thank goodness.  Crab cake included a lot of breading but it isn't a big deal since it is on a sandwich.  Bacon was good (when isn't it good?) and the slightly spicy sauce they served to go on it was delicious.  Definitely a decent sandwich, but something just wasn't AMAZING about it.  The fries, however, were slim and crunchy on the outside which is my favorite type of fries.  Definitely my favorite part of my lunch.  OH other than the Firefly vodka and water.  THAT was definitely my favorite part.\n\nSadly I didn't have room for dessert so I will have to make it back and try the cookie dough egg rolls.  Otherwise I just don't see going back to eat - maybe to drink and people watch but definitely not to just eat."], ["I love Jackson's Bar & Bistro and I love the fact that they allow dogs (kind of). But watching each person from the wait staff touch and pet the pup while serving turned my stomach. I didn't see my server touch the dog but the waiter who brought us our food had just finished petting he/she and the guy who brought us our condiments couldn't keep his hands to himself. They may have washed their hands but I didn't get that impression. The manager was somewhat apologetic but it didn't seem to phase her. \n\nThe food was okay, our server was nice, it took her forever to take our drink order and she questioned my boyfriend because his tip wasn't up to par. I understand that tipping is important and we generally tip well but the overall experience (okay food, okay service, dog drinking from the table and a very touchy wait staff)  was unsatisfactory. \n\nWe won't be back."], ["Ah, Jackson's.  You are a soul satisfaction but can rise and fall like the Philadelphia p-funkadelic scene. (If the reference above rings no bells, please look up Johnny Jackson and the Philadelphia soul scene.)  The vibe put off by this bistro in the heart of Hillsboro Village is downright groovy and like many a place in the Village, it is canine friendly on the patio.  My pups love hang out with dad while he chows down.  The staff is friendly, \"artsy,\" and always looking to tell you about the latest indie trends and things to do in town.\n\nAnyhow, the food at Jackson's is a complete toss-up.  Some of their dishes are delightful and delish.  Others are more hideous than an ugly fish. (Yeah, I rhymed... get over it.)  \n\nItems that I recommend:\nBistro burger was cooked well and had a nice flavor once I added some mushrooms, some bacon, and some cheddar cheese.  The cookie dough egg rolls are, um, cookie-dough-a-licious.  (It's a word, trust me...)  Most of their items on the menu that have to do with Ahi tuna are very well done also. \n\nItems that I don't recommend: most everything else.\n\nNot dining?  Just drinking?  Having a-go at the old \"liquid diet\"?  I'd recommend Jackson's for that in a heartbeat.  Live music:  check.  Hipsters:  check.  Local brew that's good on draft:  check.  Fantastically eclectic crowd from the indie going to the Belcout to the Vandy girls looking for a watering hole near enough to walk without using Commodore Cash for cab.  It's a delight."], ["Trying to catch up on all the yelp reviews & with yelp kindly reminding me of where i've checked into in the last few months, it certainly does assist in helping me get in gear and write a few thoughts down. \n\nJackson's.  Almost forgot Jackson's.  It was a recommendation from the Hutton Hotels' concierge.  On a drizzly Nashville morning, love & I just wanted a simple sit down brunch place to enjoy some eggs n things.  Mr. Concierge was pretty unwavering about this place Jackson's, a couple of miles away, in a cute little part of town.  We decided to give it a go.\n\nWhat an annoying place.\n\nCollege kids, post binging from the night before slamming mimosas by the bottle.  \n\nOf course there was a wait.\n\nHowever, we needed some quick as the blood sugar was crashing, and I pushed my way by through the little still hungover college kiddos and scanned the place for either a table I can snag without drawing attention from the young hostess who was huffing and puffing and dramatically trying to play circus keeper...emphasis on the dramatic.\n\nI saw 2 seats at the bar.  Beelined for it - mister was out parking the car.\n\nCounter was dirty, the poor girl was tending to what seemed like the entire restaurant by herself hence the rotten service and trying to spend as little time in there as possible, I ordered for both and hoped for the best.\n\nFood was below average, service was below average - not worth even mentioning...but hey, if you are still in college, or still behaving like you are in college, looking for a post party hangover brunch the next day, it's the place to be."], ["This place is really good. I love college towns, not just for the atmosphere but it's usually where you can find really good and inexpensive food. After I landed in Nashville my wonderful host/friend took me Jackson's for a quick bite to eat before a long night of drunkenness stupidity.\n\nThe hostess was really nice and attentive which was a really surprising since it was really packed that night.\n\nTo start we shared the silver dollar crab cakes which were really good. They weren't lying when they said \"lumps of crab meat\". The crab cakes were moist in the inside and wasn't loaded with mayo. For my entree, my friend recommended that I should order the Pacific panini which had, blackened ahi tuna with provolone cheese and salsa. I was a bit skeptical at first, being the picky eater I am, I'm not a real big fan of raw fish and with cheese and salsa?? Sounds like a trip to the emergency room waiting to happen. But I was wrong (rare occurrence)  it was soooo good. The fish was fresh and the salsa added another layer of flavor to the sandwich. DELICIOUS!\n\nEven though I was stuffed, we shared the cookie dough egg roll. YUM! A perfect way to end the meal. \n\nIf your looking for a fancy place with tons of forks and spoons you won't even touch then this isn't the place for you. But if your looking for a cool place to hangout with good friends and good food then look no further!"], ["Stopped in for a late lunch while visiting Nashville on Sat.  At first I was a bit skeptical but after looking at the menu I was all in.  I love me some pimento cheese and they have it in many of the options.  I was torn between the BLT with pimento cheese or the ASAP (As southern as possible) omelette which was an omelette filled with pimento cheese and bacon served with a fried green tomato and hot pepper jelly.  Oh my word was it ever delicious and the hot pepper jelly was the perfect touch.   When I complimented the jelly, they provided some for us to take home!  I don't like fried green tomatoes so I can't speak to that.   The server was good and efficient and the price was moderate.  I will definitely want to return."], ["I went out on an impromptu date night here for restaurant week. It wasn't too busy probably because it was during the week and it was raining. We ordered the spinach dip, shrimp and grits, and I ordered a BLT that wasn't on the special menu. I was a little disappointed with the food as a whole. The BLT was bland with barely any bacon. The shrimp and grits had no flavor. I will say that it was happy hour and you can't go wrong with a good happy hour. 2-4-1's and our server was prompt and took great care of us. \n\nI think this place would be great on a nice warm day when you are able to sit outside and watch the hustle and bustle of Hillsboro Village. Maybe with a cold glass of rose?"], ["A friend and I stopped in late one night for dessert, we had gooey butter cake( amazing!) and cookie dough egg roll ( definitely different but worth a try ). Service was not great, we waited quite a while before anyone noticed us. But there were three waiters standing at the bar looking at us on several occasions. I would be willing to give them another try, hopefully their day staff is more attentive."], ["Jacksons is a very average bar/grill... not much to say about it.  I like the outdoor seating.\n\nI got the fish tacos, which were fine, nothing great about them though.  My friends seemed to enjoy their dishes (more brunchy dishes, like omlets, etc) more than I did.\n\nThey also ordered some hash browns and grits for the table.  I tried the grits.  Most people loved them.  I thought they were average.  I've definitely had better grits, but they WERE tastier than your average Chicago place trying to do grits.  However, this is Nashville, so....I thought they'd be a bit more impressive.  Still, not bad though.\n\nAlso, many of my friends got Bloody Marys, which I tried (for the first time) and thought BLEGH, but... I don't think there's any bloody mary that i'd like.  They informed me it was actually QUITE good for a bloody mary.  So well done, Jacksons.\n\nThat's all I can say about it.  Peace."], ["I would give this restaurant a better review except for the fact that we waited an hour at the bar after putting in our food order before the bartender told us HE NEVER PUT OUR FOOD ORDER IN. Completely unacceptable so I can't give more than a star because of the god-awful service."], ["I'll keep this to the point:\n\nOK prices\nSlow service\nNot rude, but indifferent workers\nFood and drinks are meh/ok but nothing great or awful\n\nI'd never choose to go back but if someone wanted to go I want put up a fuss."], ["Excellent food in the heart of 21st Ave. They have great drink specials, I went there with a group of 4 girlfriends and had a great time. \nI would highly recommend their french fries, they are shoestring, thin, crisp, and tasty.  In the summer grab a seat outside and watch everyone going up and down 21st. \n\nIt is so difficult finding a place in Nashville that does good salads and my friend ordered the Caesar salad last night and it was crisp, well dressed, and came with plenty of real fresh Parmesan. Everyone sampled, I'm going to order my own next time.\n\nIt isn't as great if you want to go with a group of friends and chat, or bring your as it is loud, (unless you go during off hours) the crowd tends younger and more outgoing.\n\nThey have a secretly excellent selection of beer if your tastes are running in that direction and their bartenders & servers are well trained and very helpful.\n\nGreat place if you have time before catching a movie, or hanging after a show, and try sitting at the bar sometimes, their bartenders are way chill and friendly."], ["Went to Nashville for a friends bachelorette party and stopped at Jackson's for lunch. I really enjoyed the atmosphere and loved the patio. The food was delicious but our server made us feel like we were inconveniencing him by just being there, which was obnoxious. Everyone has their days but check the attitude at the door."], ["I'm not usually one to leave polarizingly negative reviews, but my experience at Jackson's was horrendous...\n\nThe restaurant was less than half full, and it took over an hour for my partner and I to receive our food. During that hour time frame, our server checked on us once.\n\nService aside the food was insanely underwhelming. I ordered the Chicken and Biscuits, because Nashville... The biscuits looked like they'd been sitting out for days, and I've seen crispier chicken at McDonalds. My partner and I each ordered mimosas, and the small wine glass was about one-quarter full.\n\nNashville is a foodie's paradise, but y'all should avoid Jackson's at all cost."], ["Great place for brunch! Bring your friends for some good food and a great patio with GREAT service.  The place was packed and still we received the best of service. Great area to shop too when you're done eating!"], ["I never ever give bad reviews. My friend and I waited over thirty minutes after being seated for our waitress to come to the table. First of all not even our own waiter asked us if we needed some water and I told him yes but we haven't seen our waitress in a long time. He found our waitress and let her know we were needing to order...  that made her avoid us completely.  Another 10 minutes goes by I asked someone to get the manager for us. Apparently our waitress was the manager and when she finally came over she asked if we even still wanted to eat there anymore?!? We said no and she was extremely unapologetic and proceeded to say she wasn't ignoring us."], ["I was really looking forward to my Easter brunch at Jackson's. My fiance and I searched tons of different menus and  were really interested in what we found on the menu here. \n\nWe got there around 12:30 and they told us it would be a 15 minute wait. We were seated under 10 minutes. Score. The vibe of the place is amazing. I loved the decor and they were playing amazing music. We were so excited. Our kind of place.\n\nIt's all down hill from there. They sat us at a little high top table right behind the bar which was very inconvenient because people were constantly walking by with food or drinks or congregating at the bar. There were a lot of \"excuse me's\" and close calls with something being spilled on my dress. \n\nOur waitress took forever to come get our order, forever to bring our drinks and didn't show up for the entire 30 minutes we were waiting for our food. We didn't order anything complicated. It was a corned beef hash and breakfast sliders both of which we were thoroughly disappointed in. The biscuits were burnt, the bacon was rock hard and it wasn't very warm. We ate it because we were hungry but then we left hungry because it wasn't much food. \n\nI don't know if it's a place I'd bother going back to. I think they have amazing potential and a crappy staff. Bad combo."], ["Having been here many, many times, I have to say this used to be my favorite Sunday evening hang out. But with one sentence from a doorknob of a server, I'm not sure if I'll return. That sentence was: \"We have a new rule that the Sunday half price bottles of wine are a 'dine-in' only special.\" (Which is not mentioned on the menu, and I was not told of until after I paid my check). Readers, we have a law in Nashville specifically designed to prevent over-consumption, and that law wisely allow diners to take home unfinished bottles of wine. (resealed, with a receipt, and in a closed bag). So now my options are: order only one glass of wine, or order an entire bottle and feel compelled to finish it. The former lowers the restaurant's revenue, and the latter puts them at risk for over-serving. Their new rule defies all logic. I'll miss the buffalo feathers, but there are several other nearby restaurants that offer not-so-shortsighted specials."], ["Jackson's brunch is FANTASTIC. The menu has everything you could possibly be craving. My favorite is the early riser. Its wonderful. The service can be slow sometimes and they seem to have issues with their AC, but honestly it's worth the heat."], ["Yes for Saturday People watching, Yes for French Onion Soup, Yes for Group Brunch, No for Parking.\n\nLocal industry peeps like to linger in the area. Slightly touristy but you don't see the cowboy hats and moon pies as would on Broadway."], ["Jackson's does brunch on Fridays, Saturdays, and Sundays and it is fabulous! It's right across from the famous Pancake joint.... so if you don't want to wait in line there, head over to Jackson's. \n\nThe bar is my favorite place to sit. Always great service and a friendly bartender. \n\nEverything on the menu is great! \n\nParking is free for the first 1.5 hours."], ["I just have to add my two cents. Jackson's is one of the best spots in Hillsboro Village! They have a great covered porch, great food, and wonderful service. I love their extensive drink menu. Just about any concoction of spirits you could want, they can make it for you! A great wine list, and the servers are knowledgeable. If you describe to them a wine you are looking for, or ask them to suggest a wine to go with your meal, they are in the know!\n\nI love meeting friends for dinner and drinks out on the porch. They have wonderful wrap sandwiches, fresh salads, and good pastas. There is something for everyone!"], ["Really good Bloody Mary and shrimp and grits. Don't mind the slow service and alternative wait staff. Don't order anything else. Would recommend on a rainy day when Pancake or Biscuit lines are out the door. Otherwise probably could do better."], ["What a disaster. \n\nI've been to Jackson's a handful of times now, and each visit has proved less impressive than the last. Our visit there today was handily the worst dining experience I've had in Nashville. Here are a handful of reasons why:\n\n1. No clear hostess station, no clear place to queue up for a table. When we finally identified the hostess, she assured us there were seats, but we had to wait a number of passes until it was \"safe\" for us to move out of the high traffic aisle where frenzied staff passed each other with dishes and drinks. The same aisle needs to be tackled if one desires to go to the bathroom. It's not a deal breaker, but take out a two top or bang out a wall and remodel already!\n\n2. Nasty, nasty bathrooms. Wet floors, wet seats, unflushed toilets, out of order hand-dryer. Again, not a deal breaker, but this was lunch not a 2AM drunken stop for food after bar-hopping. Just gross. \n\n3. Lousy service. Ordered at 1:10PM, received waters, did not see our server again for 45 minutes (seriously!!!) We were about to walk out when my husband checked with someone else about our food. We were assured it was on the way in, \"like, literally, under 30 seconds.\" So about seven minutes later when our server finally re-appeared with the food it was pretty clear the man my husband asked about our meal pushed the order through on the spot. I've been in slammed restaurants before. I get it. But this was ridiculous. \n\n4. Crap food. The guacamole in my spinach wrap had clearly been sitting out for too long (you know that nasty, sickly sweet smell avocados get when they start to turn?), my husbands potatoes tasted like raw garlic, and the rest of it was flavorless and poorly plated. \n\nI will give Jackson's some points for a pretty good happy hour, but beyond that it's a freaking mess. Close shop for a couple days, hire a contractor and give the space some flow. Get some computers so the staff isn't rushing to the grill with their paper tabs. Add some vegetables to the menu. Nashville has high standards  these days, time to get with the program."], ["Jackson's you are not good.  It makes me sad.  But you suck.\n\nI've been here twice both for a weekend late breakfast.  The service is surly at best and always painfully slow.  Hope you aren't too hungry.\n\nAnd the food is just not good.  Not good.  I had an omelet, which calling it an omelet required a stretch of the imagination.  What they really are is a very thin frittata folded over in half.  Therefore all the veggies, etc are in the egg parts and the middle is empty.  Oh did I mention the frittata was burned on the entire bottom so that when it's folded in half the middle of my omelet is entirely burned?  That and no sign of cheese anywhere makes me very unhappy.\n\nI want to like it because of it's location but sorry, not gonna happen."], ["Pros: Good location, good 2 for 1 happy hour, nice patio and nice waiter. \n\nCons: Awful food.\n\nOddly, our waiter made a big deal and asked us move after we were seated because he thought a 4 top table was too small for 3 regular sized people.  He moved us to a spot directly in the sun that was super hot. So we moved again and got stuck in a corner. Super weird.\n\nThe food wasn't good at all. I had a grilled cheese (for lack of vegetarian options) and it was a $9 plain sandwich bread kid's sandwich.  The fries weren't good either and not seasoned. My friend had a buffalo fingers salad and he wasn't impressed as well. Said it tasted like something from Wendys, all processed and cheap ingredients.  My husband had a burger, which he liked, hence the stars.  I wouldn't order food from here again. Bummer!"], ["This place is close to my work place. I have been there thrice. Very friendly place. Food is great and so are the drinks. Reasonable pricing. They have happy hours. They treat their customers very well. Like them on Facebook, usually you get to know of any deals they might have. If you are a loner or have no friends and want to make some or be in a natural social set up, this is the place for you. Very good place to spend couple of hours with friends or otherwise. I love cappuccino they have."], ["\"I'm going to Jackson's...you turn-a loose-a my coat!\"\n\nOk, sorry.  I have to sing that Cash song any time someone mentions Jackson's.  Jackson's is the West Side to an absolute tee.  It's right in the heart of the Village, so location is prime.  Other than that, the place smacks of dopey pseudo-hipsters nibbling on overpriced appetizers.\n\nThe food at Jackson's isn't bad, though it's a bit pricey and you can get better cuisine in the area for cheaper.  The gumbo, sandwiches and pasta all taste pretty good, and they allegedly have fried twinkies.  I don't know a damn thing about that and am fairly confident I don't want to, but the patio is decent and parking isn't too bad (except on weekends).  I like the staff a lot and am actually friends with a couple of the servers and bartenders, but those guys know as well as anyone that Jackson's is mostly about appearances.\n\nDrinks are plentiful but not especially cheap.  They have a kind of neat suspended fireplace dangling over one of the tables...very postmodern.  They put up local art, and the crowd is typically friendly, but I have to say...the place just doesn't do it for me.  If you want a drink in the Village, I say go to the Villager, Sam's or the Belcourt.  If you want food, Jackson's is probably near the top of the list, but it's nothing exceptional.  You should definitely try it at least once, but it certainly isn't one of my Nashville favorites."], ["Was I hungover from the night before...filled with honky tonkin at Cabana, Robert's, Bourbon Street Blues, Sky Lounge and Cadillac Ranch?? Yes...a bit. Haha...a lot a bit. \n\nJackson's helped me get over that. I had one of their paninis and tried a bite of Nate C's hangover cure plate. Everything was good from the food to the service to the outdoor patio. Some interesting Nashville food found on the menu...didn't try them. Maybe next time. Maybe not...they didn't sound too good. :p"], ["Very active place with lots of outdoor seating. The service was decent and the food was okay. I had a cheese burger it was pretty good. I don't know if this would be a place I would visit regularly as the burger was good but didn't blow me over. \n\nIt's worth a visit to check it out."]], 
            "review_rating": 3.07
        },
        {
            "business_id": "dD2p903p8lU0IgXT3OFluA", 
            "name": "Edgehill Cafe", 
            "address": "1201 Villa Pl", 
            "city": "Nashville", 
            "state": "TN", 
            "postal_code": "37212", 
            "latitude": 36.1429685, 
            "longitude": -86.7923549, 
            "stars": 3.5, 
            "review_count": 245, 
            "is_open": 0, 
            "categories": "Breakfast & Brunch, Restaurants, Food, Cafes, Coffee & Tea, American (Traditional), Sandwiches", 
            "hours": {"Monday": "9:0-15:0", "Tuesday": "7:0-15:0", "Wednesday": "7:0-15:0", "Thursday": "7:0-15:0", "Friday": "7:0-15:0", "Saturday": "7:0-15:0", "Sunday": "7:0-15:0"}, 
            "text": [["Ordered food at noon. Waited 55 minutes for two salads. Friend ordered House Salad, when it arrived it was spring mix, red onions, cucumbers. No cheese, bacon, tomatoes, pecans. When questioned, response was \"the chef changed it.\" Without asking the customer?? And to what....the only items we have prepped? Asked for the manager but was told she was in the kitchen.  Guess that sums it up. Obviously will never go back. \nOne day later UPDATE: A marketing team member reached out to apologize and offered complementary meal as his personal guests should we want to try again. Hope this is indicative of a team trying to right the ship. Stay tuned."], ["I had a meeting here on a weekday mid-morning.  Maybe not the best place for a business meeting (or for getting work done), as it was super loud (other patrons and music).  But a great place nonetheless!  A little pricey, but you pay for what you get.  My chai (with almond milk - yay!!) was very good.  And that gluten free peanut butter cookie was out of this world good - wouldn't have known it was GF if it hadn't been labeled as such.  The food looked good and I hope to have a chance to come back and try it!"], ["Love this place. Friendly staff, quick service, good music, great atmosphere to work OR hang. My personal go-to is the Fedora Frittata and an iced mocha :)"], ["Another stop in the desperately hip district of Edgehill.  Much like the other places of business in the area, Edgehill Studios pushes its post-modern architecture and ultra-trendy atmosphere on its customers.  However, because the sandwiches are affordable and because it's so conducive to laptopers, I had to give the place a star more than my gut wanted me to.\n\nThey make a decent cup of coffee, and prices and selection are similar to places like Portland Brew and Bongo Java.  Apparently they don't serve soup through the summer (a bit of a bummer since I am a year round soup junkie), but their selection is fairly diverse for such a small cafe.\n\nEdgehill Studios Cafe has more room than I expected, and it typically isn't too busy, so it's an alright spot to duck in and do some web surfing.  The staff is quick and friendly, and it's usually pretty quiet.  I haven't visited the actual studio or been on an evening with live music, but I imagine it is pretty par for a coffee shop/venue.  I deem Edgehill Cafe worthy of your business, but I just can't quite make it a regular stop.  I'll stick to Portland Brew."], ["Summer is here.. time to cool off!  \n\nMy barista friend turned me on to machiattos long ago, so when mine arrived in a 12 oz cup, I thought maybe this place is not the best for coffee.  It's a really good value, because made nice and strong, however was missing the artistic value found at crema, etc.  \n\nBefore I received the drink, I helped myself to some lemon ice water, and began to notice the natural oak wood, complete with knots and organic shapes.  There are  lots of tiny wooden countertops with flowers, some bartops with stools, a bench area, plenty of sitting chairs, and a long metal table with parson chairs. \n\nI ended up in the parson chair, and it was real comfy.. my derriere is in heaven right now.  The espresso I'm drinking, with a little foam on top, is not bitter and very strong, they probably make consistently good pulls for lattes and the like.  They offer teas and lemonades for the hot weather.\n\nSpeaking of which, this place is air conditioned and in a nice part of town, surrounded by cool little boutiques, an excellent spot for a relaxing summer afternoon."], ["Edgehill Cafe is located on Edgehill between Music a Row and 12 South, in a quaint little area called Edgehill Village. \n\nThey have a wide variety of hot and cold drinks that you order at the counter and receive at a separate window. I'm not sure how they get the order from the counter to the window, but I suspect they use either paper, digital transmission, or they turn around and tell the barista what to prepare and I've missed it every time, because I'm trying to figure out how much you're supposed to tip on a $2.48 coffee. \n\nTheir prices lean on the side of pretentious for a coffee shop, but I do like going there and it's very conveniently located between where I live and work. \n\nThe staff is nice. I can usually find a table. They have a really cool round table in the corner that people must camp out to get in the morning, because seriously there's always someone sitting there. It's always a girl like stressing out about a final she should have been more prepared for, too. \n\nI had breakfast there once. I found it to be worthy of them having a menu, whereas some coffee shops make the food more of an add on and less of a specialty. I enjoy their small plates, like the cucumber, goat cheese, and honey plate, because who can even get through the day without a healthy little treat like that. \n\nAnd that's what it boils down to. We all need a little treat sometime. When it's 3 PM and you know you can't lift another finger until you get a little treat in your system. You deserve it!"], ["We were looking forward to trying out this newly redone restaurant. The atmosphere is fresh and well done . We were there for breakfast. They now have table service. Things were great until the food came out. My pancakes tasted like stale bread.  My wife's eggs were cold. The potatoes were not cooked. They brought the wrong side dishes. For silverware, we were given  forks but no knives. It took a while to find a waiter to get the silverware we needed. We did speak to the manager. She offered a discount of $2.50  not that we were looking one, but why bother?). However, she did not remove the extra charge for the incorrect side dish we didn't order ($4.00).  She did apologize for the food verbally but somehow we were made to feel like she couldn't care less. I don't write many reviews unless I really love something or dislike something. This restaurant fits into the latter category. Sorry. A nice decor is not enough."], ["Definitely one of my favorite coffee shops to go to in the Nashville area!  It's such a cool atmosphere and it provides the perfect get away.  Whether you go there for a coffee date or just to get some homework done, they provide that relaxing and friendly environment.  The staff is wonderful and the coffee and food is even better!  They also have a great little reward system where you will receive a text that can be redeemable for a free coffee!  I would recommend you check them out at least once and who knows you might get hooked!"], ["Come for the latte and specialty drinks if you're around the neighborhood. They serve only breakfast and lunch. We came here for brunch and ordered: fisherman omelet, hangover hash, and sombrero frittata. They overcooked the eggs as we wanted over-easy for the hangover hash, but the spicy siracha mayo complemented the dish full of sausages and potatoes to add a little flavor. Sombrero frittata didn't amaze me since it has avocados mixed into it and a side of toast that was a like biscotti. The dish was pretty bland and I was expecting avocado slices. Fisherman omelet was a nice portioned meal but a little seasoning would be great my friend asked if it had came with toast, the waiter said yes, but none was served."], ["The old location was my favorite study spot. The new location is beautiful with the same great food and great customer service. The but: it feels strange sitting there for a few hours to do work since the new space has more of a restaurant feel and less of that nice coffee house vibe. But hey its probably better for business. I may now go there for brunch but not for studying."], ["This is one of my favorite places to get coffee so I finally decided to come for breakfast after hearing great reviews and I was not impressed. I got the open egg sandwich with avocado and after a long wait it finally came out barely warm. The avocado, which I paid extra for, was unripe and completely inedible. The breakfast potatoes were good, but overall it was definitely not worth what I paid for it and I definitely would not get it again."], ["Edgehill Cafe is a nicely designed coffee shop with lots of natural lighting and a cool, earthy vibe (Yes, this trendy place for ideal for hipsters). I really like how much room is available for seating and it is great that they also serve tasty, hot food (Hooray for sandwiches!) which they bring right to you when it is ready. They even have a loyalty program! I don't think there are really any other businesses like it in this area of town and it makes a awesome meeting space given its location in this neighborhood. My only peeve about it is parking. There is a small, one way lot outside but you can hardly ever find parking there. Your best bet is a paid lot next to the complex it is located in or street parking if you are lucky."], ["My amazing race try out partner and I had one of our regular lunches here on a sunny Saturday. This is a rather exciting place to have to lunch. Lots of nice comfortable couches with pop-art/earthy combo (yes I know it sounds strange - you have to see it to believe it). Ultimately, it makes it a really relaxing place to sit down and have a cat with friends. OR, if you are on a studio binge, you can go to the benches and get your study down with the Vandy and Belmont kids. \n\nFood wise its creative sandwichs (not just your typical bland stuff) with unique names. They are really well made with a unique flavor in it of itself and served in a very interesting dish. They are a bit pricey from what you expect of a sandwich place (a $12.50 for sandwich and chips).\n\nThe only thing that keeps me from giving it 5 stars is that parking can be a nightmare. You park up in this gravel lot that you pay 2 dollars for 2 hours. The parking vending machine is also rather annoying. You have been warned.\n\nOh and also...strangely, the bathroom is build into this old bank vault style entrance. I felt like I was in the movie Ocean's 11 (the original Frank Sinatra one) going to the bathroom..."], ["This place is the shit! Looove the food and the service is wonderful  Atmosphere and decor on point!!"], ["We were greeted by the hostess before we even entered the restaurant. The service was amazing and the food was great. We all loved it there. The coffee and atmosphere was to die for."], ["In a town with barely any coffee shops this place is a god send. I may be a little of a coffee snob but they did well and have a nice selection of Gluten free pastries and cookies! The decor is cute and the staff is friendly. What more does one need from a coffee shop?"], ["This used to be an excellent local flavor for college students and the like. Ever since the move next door, it has lost all of its character and has been transformed into one of the most pretentious places in Edgehill. Wait to be seated at a coffee shop? Are you kidding me?!"], ["We sat for 10 minutes, and were NEVER greeted. We ended up walking out after looking around and seeing the staff standing around and not coming bu the table. It was not busy, it was not during the rush and it was incredibly disappointing. We would never come back. We ended up going to Pomodoro East after, which we learned was owned by the same people. We were so glad we left and went there, the service was night and day. Do not eat here if you value good service, you will be very let down."], ["I really like this place.\n\nMy latte was excellent.  It had just the right amount of espresso \"bite\" without being harsh or too acidic.  The temp was spot-on as well - very nice.\n\nFood wise, I've only been here for breakfast, and it's very good.  I suggest you try \"The Lovely,\" which is a grits dish loaded up with unhealthy goodness - thick bacon, chunks of cheddar, and a fried-egg on top.  The grits themselves seem overcooked and a bit too creamy to me, but their menu does describe them as \"slow cooked,\" so I assume this finish is intentional.  I like my grits a bit, well, grittier.\n\nBeyond the grits, they have lots of other breakfast foods, including some good sandwiches with sausage, eggs, etc.\n\nIt's a big cafe, with plenty of tables, large and small.  The staff seems to support the fact that lots of people like to settle in and hang out a while.  This gives a good cafe a pub feel, and Edgehill has a good bit of this.\n\nIf you've not been here, check it out and let us all know what you think."], ["My favorite place we ate all weekend!!! Food was so fresh, just delicious!!  Those breakfast potatoes, I mean those were the best!  And the breakfast tacos hit the spot!"], ["So I go to this cafe a lot and I gotta say that lately I've been really disappointed with their kale salad. I usually get the same thing (pesto grilled cheese). It's a go-to for me. And I always get a side of the kale salad but the last 4 times, it's been prepared differently and it always looks like it should've been thrown out four days ago. The grilled cheese is always on point but I'm gonna have to switch to a different side because I'm convinced this kale salad is not being taken care of."], ["I really wanted to like this place, but after my second visit they did not convince me. The first time I went a few months ago the service was spotty, and their breakfast was bland to say the least (I had the apple oatmeal which needed heaping amounts of brown sugar to make it taste like anything), also their coffee seems to have a funny taste and always seems to come out cold. When I went more recently, I found a HAIR in my oatmeal. GROSS. Needless to say, I was planning on returning to try their pancakes, but after the hair experience, I think I'll make my own at home."], ["My experience at Edgehill is totally different than the earlier reviews from several years ago. I have a feeling a remodel happened or something or there's just some crankiness in the air. \n\nThe inside of this cafe is comfortable, kind of industrial looking, and a good place to get a latte and tap away on your laptop. I haven't tried them- but they do offer gluten free brownies, cookies, and muffins, which I appreciate.\n\nI like to sit outside in the afternoon, read the paper, and pretend that a certain fake-ass Mexican restaurant isn't mere meters away from me."], ["I really wish I was still in college because Edgehill Cafe would be my study spot!  With large tables, wifi and a calm atmosphere Edgehill makes a great location to get some work done or have a nice breakfast.  I've been in a few times, to work or eat.  \nI liked working at the previous location better because of the bar table along the windows made me feel like I was not taking up any room and could work as long as I wanted.  The new location has a long table in the middle but I felt bad taking up a spot when there was a wait to eat.  I go at off peak times when I want to work.  \nOverall- great food and drinks.  The staff is super nice and quick to get anything you need."], ["The burger with sweet potato fries are the best in town and the lattes are always picture worthy!!!"], ["I had the most wonderful experience today at Edgehill! The service was impeccable and the food delicious! I had the shrimp and grits. Cooked to perfection!"], ["We stayed at an Airbnb right down the road and it was such a pleasant walk to this cafe. Met the owner and she was super friendly. They accommodated some changes for me on my latte and had some super delicious muffins.\n\nVery spacious and nicely decorated on the inside with an extensive menu. Would be a nice place for a group or for a solo traveler to get some work done."], ["Thrilled with the menu change and new chef. Hitting the breakfast venues on the weekend, it was great to see a menu with lots of gluten free options. The spinach frittata was delish- gluten free toast one of the best ever. And the preserves were amazing. The order of buckwheat pancakes was substantial- again gluten free- and tasty!  Open egg sandwich had great flavor; the andouille sausage really stood out. If you are an andouille fan, this is clearly for you.\nGreat coffee- nice outdoor seating under a tree. Ok for doggies- enjoy!"], ["I don't know how to NOT make this review annoying.  You've been warned.\n\nHere's the thing:  I'm new to Nashville, and in the months leading up to our move (from Oklahoma no less, so pretty much anything with electricity AND running water impresses me) I fantasized about what Nashville would be to me.  Creative, diverse, full of energy, and mohawks, and skinny girls in scarves.  I could be someone better in Nashville.\n\nSo now I'm here, and I'm still completely boring, but everything else I idealized Nashville to be I found at Edgehill Cafe.  I was there midday on a Wednesday, and had a nonfat latte (see? BORING!).  The cafe was busy, but I still found a small table right away to set up.  The furniture is coffee house eclectic, and I was very excited to see a large wrap around couch in one area.  Someone occupied it the entire time I was there, and I bet she got a lot done--it is the kind of nook that just inspires creativity.\n\nI was able to sit and work for a few hours uninterrupted, and even went back to order an iced tea.  While I didn't  order food, I noticed that everyone who did looked quite pleased with themselves.  I will definitely be back for a meal and a glass of wine!  \n\nNext time, though, I'll bring headphones.  The cafe is clearly a hub for business meetings, job interviews, and retired musician reminiscing.  If you have a list to accomplish, and have an eavesdropping tendency, as I do, prepare to be distracted!"], ["Nice little coffee shop. Ended up here after trying to go to NOMzilla and discovering that it had closed. I got a tuna melt with chips and it was good. The others in my group enjoyed what they got as well. \n\nThere was a mix of people from hipsters reading, to professionals discussing work inside and outside at the small tables there enjoying the nice day.\n\nI didn't try to coffee or cookies, but they looked and smelled good."], ["Place has a great look and of course it's always wonderful to be able to get a table when other places have lines out the door, but that is the point, you will not find a line here.\n\nThe service was weak. Basic issues like not providing spoons for latte, having to ask for an additional packet or two of Splenda and the most significant no check up to see if food was ok-which it wasn't. The red velvet pancakes were crispy, brown and not velvety from being overcooked. The waffle was diminutive and underwhelming and the stuffed French toast were crispy on the outside and soggy on the inside. Also a few basic items 'we are out of'. The breakfast hash was the only thing that seemed to hit the mark.\n\nThe prices require good food and good service. Unfortunately, it didn't hit those marks. Sorry. So much potential unfilled. \n\nAt least the beverage manager was very attentive once we communicated this to him."], ["I was visiting my best friends sister on music row and she recommended Edgehill Cafe to us because we were looking to grab a quick bite to eat. I walked in around 10:30 and walked up to the counter and was told the kitchen was closed. Talk about feeling bummed out after looking over their tasty menu options. We were standing outside for about 10 minutes and got called back in because the kitchen was some how opening. I am not sure what happened, but I am sure glad I was able to order my Belgian waffle. I added bananas and chocolate chips for a .50 cent up charge and it took the waffle to the next level. The waffle is made with a cinnamon vanilla buckwheat batter and topped with walnuts and syrup. The waffle also comes with a side and I went with the bacon of course. It was nice thick and crispy. You can tell they only use the freshest of ingredients. The coffee mugs are a pretty decent size which allowed me to enjoy more of my peach white tea. \n\nWhat I thought made this cafe unique was that it served beer. This isn't your typical coffee shop. They have something for everyone. You also order at the counter and they will bring the food out to you when its ready. The interior was very modern chic. I loved the tufted benches and light fixture in the larger dining area. They also have a really neat patio and lots of tables inside. I would recommend this place if you are looking to grab a quick breakfast."], ["Edgehill Studios is definitely a technology-oriented cafe, and they seem to do a good job with that: a long, thin table with an outlet strip running down the middle makes for easy access to power, and there's even a fax machine by the door ($1/page local, $2 long distance).  The three flat screen TVs, each showing a different movie or news program, along with the lack or decorations, and the new, super clean feel contribute to the technology-centric feel I get from Edgehill.  There was some neat art for sale on the walls, a small stage in the corner, and some quiet rock music playing, which kept the cafe from feeling like a computer lab.  \n\nEdgehill Studios would be a good place to get some work done when your internet is out or when you're having trouble motivating yourself to study.  The customers seem to be mostly young professional types, and while there were a good ten or so people there, it wasn't crowded, and there were plenty of open tables.  They serve coffee, espresso, chai, soda, bagels, baked goods, soup, and basic sandwiches, all at lower prices than you'd find at most Nashville coffee shops."], ["Everything here is usually delicious. However I got the kale salad for the first time to try their salad period I would not recommend it. It is $14 with chicken on it. So very small salad and the chicken has no flavor. Everything else on the menu is delicious and reasonably priced . I just had it better expectations the cause the girl take him out holder said it was one of her favorites."], ["What a great little restaurant. You can order any item throughout the day, so don't have to get there any particular time. Really pleasant menu. I am doing wheat-free and there are plenty of options. Our server was so nice, and offered to find answers to any questions. The fare was lovely. I had the kelp salad, my husband, the McHenry, pimento cheese, bacon, tomato, sourdough sandwich. Both delicious. The fries accompanying the sandwich were delicious not greasy, great flavor without adding anything. Am looking forward to returning...eager to try a frittata!"], ["One of my favorite spots for lunch or coffee & my laptop.  The staff is friendly, the decor/environment is pleasant & interesting (coffee bag Queen Anne chairs, anyone)?  The food is delicious & fresh -- great place for a panini or salad."], ["Sure, I've diversified my coffee shop/pseudo office portfolio quite a bit since my days of practically living at Edgehill Cafe....\n\nYet, I am still charmed with the space, the staff especially Rachel the manager who is just an authentically dandy person, hummus sandwich, and of course my favorite caffeinated cup - The Hiyah!\n\nThis is just a great spot to plug your laptop up and tackle your workload or host meetings too."], ["Best coffee house in Nashville. Jack Egan is a champion amongst boys behind the espresso machine. Ask for an 'Iced Jackicano' and it will change your life. All the workers are super sweet and they make a mean chicken salad sandwich."], ["The bacon was as rubbery as Reed Richards. Tasted as if it had been \"cooked\" in an old microwave."], ["The cafe changed ownership and was renovated in July, and wow! what a different place!\n\nMy favorite thing so far is the breve's and the caprese salad,...YUM!"], ["Large place, great breakfast burrito, plenty of tasty drink options. Would recommend and go again."], ["Staying in Music Row, we walked over to this cute shopping area and saw this cafe. It was really hot and muggy even at 10am and we wandered in to the refreshingly cool air and friendly faces at the counter. The stars are mainly for the nice place to sit in and chat with friends. The sandwich I had was not revolutionary.\n\nBiscuit breakfast sandwich. Bacon was plenty and so was the egg and cheese. Biscuit was only alright - not the best I have had in Nashville. \n\nAmbience: love the decor, modern yet warm, very clean. Comfortable seating and bright ambience. People had laptops out and were working or chatting with friends over breakfast and/or coffee. Seemed like a good place for both! \n\nService: really friendly"], ["I didn't know about Edgehill Cafe until a few weeks ago and I'm so glad I know about it now!  Think of Bongo or Fido but with a more comfy, open, and varied seating area and a nice mix of people (students, business people, moms, friends, etc.), not just students studying and great overhead music.  The employees are very friendly and the (presumably) owner seems very personable and interested in the customers.  \n\nI ordered the Hummus & Veggie sandwich w/o onions (it's on whole wheat bread with sprouts, cucumber, tomato, spinach and red onion) and I swear I couldn't stop thinking about it for days.  SO GOOD!"], ["Coffee was delicious. Being from out of town and my first visit I had no idea that this was more \"self service\"."], ["Great breakfast served all day. Wife got the standard and a mocha and she was happy with her meal. I got the breakfast tacos and they were good. Not quite like the braised brisket tacos I had in Houston, but they were a good breakfast choice!\nDefinitely a hipster vibe, but as I walk around this area, I have come to realize that I am just smack dab in the middle of hipster Nashville. Not a bad thing, just worth pointing out!"], ["Best breakfast in Nashville   The granola the coffee was delicious   The place is super clean the people super nice and all the food was excellent"], ["I had a final paper to work on, so my friend suggested this place. Parking seems more difficult the closer you get to the shops, but we parked a block away with no problems. It's a lot more open than it looks when you first walk in. I had a salad, which was very good. Service is excellent; they're attentive without being overbearing.  This is a great place to study as seen by the number of other students who were also there with laptops.\n\nIf you need to use the bathroom, you'll get a neat look at the demolition of their old location. Also, the door leading to the bathrooms that looks like the door to a bank safe is pretty cool."], ["Hubby and I wanted to try a new place for lunch other than our regulars...it did not disappoint!! He got the bacon apple grilled cheese and I got the edgehill club...both delicious! I also got an iced 'always fall somewhere' that was better than some of our regular coffee joints! Friendly service and cool atmosphere--we sat outside to enjoy the sun! Will definitely be back!"], ["LOOOOVE this place!  Friendly staff, THE BEST GF peanut butter cookies (with chocolate chunks), the other baked goods (not GF) looked AMAZING fresh out of the oven, 'the Lovely' (a bowl of grits with sausage, spinach, tomatoes onions cheese and an egg)....soooooo good.  I went 2 days in a row because the on cookies and the latte was just that good and I was just visiting Nashville.  The lattes were absolutely delicious.  Perfect!  The ambience was really nice."], ["I use yelp all the time and I think this is my first review. My nine dollar kale salad was so disappointing that I felt a need to say something. The kale had bits of spoiled kale in it and was a little too mushy. The feta was scant and provided the only flavor in the salad. The dressing had no flavor. And for nine bucks it could have been a little heftier. Synopsis: soggy sub par kale, a few walnuts, approximately one tablespoon of feta, non descript dressing, and soggy cranberries. I'll be sticking to coffee from here on out. Pros: patio is nice and has plenty of shade."], ["I like the atmosphere here. Maybe a touch of a pretentious crowd, but the seating is nice and I feel comfortable there. It's a great place to go clear my head and hang out with my boyfriend or talk with clients about business without feeling like we're in a noisy restaurant. It feels the most like my favorite coffee shop back home where I'm from in Ohio. One of their baristas even looks so much like one of the baristas back home that I want to ask him if I can take his photo and send it to my friend haha. \n\nThe It's Always Fall Somewhere is my go-to latte. Fall is my favorite season and whether it's the cold of winter or the heat of summer, I think I would always enjoy sitting in their comfy chairs and sipping this drink. \n\nI've not ordered the cooked food there, but I've had a few pastries/cookies and they were always good. \n\nThey have a $5 latte flight, which I forget about every.single.time I go. I am going this weekend specifically to get it. I will report back. It sounds like such a fun concept. I just get in there and forget about it right away (even though they have it advertised right in front of my face) and get that fall drink because it's the best thing ever. Then as soon as I've paid I always remember I wanted to try the latte flight. Duumb. I will get it this weekend and let you guys know what I think.\n\nEdit-\nAlright guys. I tried the latte flight. It was amazing. For $5 you get generous small glasses of regular, chai, and mocha lattes. I have actually never had chai before so I was mildly reluctant to try it. Funny enough, it was my favorite of the three! The regular latte was great, but something I would have often anyhow. The mocha was nice and had a good, bitter dark chocolate flavor. The chai was so smooth and spiced though. It was really delicious and felt rich and special. I'm so glad I tried this because I wouldn't have just ordered a chai latte on my own. Now I know it's something I enjoy!"], ["I'm not sure why this place has any bad reviews. The food is really delicious (I recommend the Hangover Hash) and the coffee is great. The space has ample seating (rare for a cafe in Nashville!) both inside and outside and free WiFi. This has been my go-to spot for Sunday brunch and as a study spot."], ["Not sure how I missed the memo on Edgehill Cafe. I am so excited to have found this great lunch spot near Vanderbilt. I enjoyed the turkey pesto panini which was delicious but my kale salad on the side stole the show! Yumm!"], ["Where to start?? The staff is hard working but not stressed, they always seem to be in a great mood, they personally deliver food and drink orders to your seat, and for whatever reason, they're all very good looking! They are excellent conversation starters. \n\nThe coffee is up-to-par with most coffee shops around town, and I can't say I've ever had a bad cup here. They of course have a wide selection of espresso beverages; I have not tried them all, but I've sampled a few great ones. \n\nThey bring in fresh baked goods from a few other local businesses, and they have an excellent, full lunch menu. \n\nThey have a couple of cases of ready-to-drink items (Hatcher chocolate milk, bottled smoothies, juices, etc.). \n\nThe feel of the shop is very warm with hand crafted wood countertops, a variety of tables and chairs that fit together, chairs and pillows upholstered from burlap coffee bags, incandescent lighting, a descent music selection, and a couple of different bar stool sections. There's really not a bad seat in the house. \n\nGreat place to meet formal clients or casual friends, and works great for a place to study or work for awhile."], ["This local eatery and coffee shop is located in the heart of the historic Edgehill Village. It is one of my favorite spots in Nashville for brunch! The space offers up a modern yet welcoming vibe while serving a wide array of both hearty and healthy eats, all day breakfast, weekend brunch, and seasonal favorites. If you haven't yet, be sure to check out Edgehill Cafe! \n\nPROS & CONS:\n\nPros:\n- Open, modern, cozy atmosphere flooded with natural and soft lighting\n- Fantastic Food options\n- Decent coffee drinks\n\nCons:\n- Limited parking\n- Somewhat noisy depending on where you sit and time of day \n- Wait for food can be lengthy in comparison to wait for coffee drinks and depending on time of day \n\nPICTURED: \n\nLatte: 'Always Fall Somewhere' (House-made vanilla syrup, local honey, cinnamon)\n\nFood: 'Hangover Hash' (Breakfast potatoes topped with peppers, onions, bacon, fried egg, andouille sausage, pico de gallo, and sriracha mayo)"], ["Great coffee, friendly staff, delicious egg sandwich and gluten free pancakes!"], ["Go here if you want to wait an hour for a toasted bagel with a side of cream cheese, be dismissed when you ask if the order maybe got lost, and then freeze to death while waiting."], ["Checked out this place because of Yelp. We had the chai tea, always fall somwhere and an open salmon. \n\nThe Fall Somewhere smells like a fancy cookie. Omg! And it tastes like one too... like a cookie your grandmother made..prepared with love. Wow! \n\nThe open salmon is great! Loved the bread on it especially because I wasn't expecting it to be so good but the whole thing was great! \n\nDefinitely coming back!"], ["Stopped for lunch. I had a strawberry walnut salad and my husband had a Chicken Salad sandwich with a salad. We drank Unsweetened Tea, but they have specialty drinks, too. Just what we were looking for."], ["Might have secured the new top spot on my list of excellent places to write.  I love the eclectic industrial decor and mix of chairs and tables.  The 'it's fall somewhere' latte has been a delicious go-to.  The employees that I have worked with have been incredibly friendly and accommodating, and I'll dare to say that their crafted bevvies are a touch less expensive than other coffee houses in the area.  It's SO close to wear I work, also, so it makes it very, very convenient.  Parking is a bit of a bummer, though, (the lot is rumored to tow after a half hour!), so try to snag a spot on the street."], ["The coffees were slow and bland. My breakfast tacos came out after 30 mins and were wrong. This place is going down quickly. I would not recommend it. Nashville is full of great coffee shops and cafes. This is not one of them anymore."], ["Good neighborhood place with interesting menu and coffee drinks. We only had cappuccino but it was great, artisanal. Would go back to make a more complete judgment if I were staying or around this area again."], ["Turkey Brie Hot Sandwhich  great flavors and very filling. A little pricey, but worth it! awesome atmosphere."], ["I was visiting Nashville this weekend and stopped at the Edgehill Cafe for a late lunch around 3 pm on Saturday. Unfortunately, I left my credit card there. I called immediately after leaving yet there was no answer as the cafe closed early at 4pm. When I returned Sunday morning around 10am to retrieve it, I was informed by the staff that they shredded my card - they didn't even wait 24 hours. This extremely inconvenient and I'm disappointed with how they handled the situation."], ["Great breakfast of oatmeal with brown sugar, nuts and cranberries. Delicious breakfast burrito with sausage. Excellent coffee! Comfortable and smartly decorated inside and has outdoor seating area."], ["I had the most wonderful experience today at Edgehill! The service was impeccable and the food delicious! I had the shrimp and grits. Cooked to perfection!"], ["Nice and quiet environment to study or to catch up with friends. It has a hipster vibe- fancy coffee and kale items on the menu. I got the monte cristo sandwich. They put their own spin on it by replacing the usual deep fried egg batter toast with a sugar glazed biscuit!"], ["Renovated restaurant right in the heart of downtown Edgehill, this place was nice for a lunch date. Outdoor seating on a beautiful fall day helps take it all in. The Turkey Pesto Panini and Always fall creme br\u00fbl\u00e9e made for a full meal, both with plenty of flavor. Gotta come back to check out the rest of their well put-together menu!"], ["This is the kind of place where great novels are born.  Warm, eclectic ambience, good food, plentiful coffee, and spaceous - whether you want to perch up on the bar, sit at a table or curl up at the corner nook... a proverbial \"thinking space,\" something about the combination really pours great ideas into, well, at least MY, head.  Background is filled with chatters of renal physiology or western art history, a TRUE college town cafe.  Many, many hours were spent here doing work, reading, or just thinking about life.  It is a dangerously integral part of my routine.  Yes, there is wi-fi."], ["Very cool and hip-like trendy kind of place. Very quick and friendly service. Low key and mellow.  Remind me of Muddy Waters in Burlington, VT."], ["I have eaten her three times now. The food is pretty good! Love the oatmeals and enjoyed the kale salad today. Lattes have been on point.\n\nHowever the service is a bit of a mess. It's very unclear who your server is as everyone keeps coming over to do stuff, so then you never really know who to ask for something. I think four different people \"helped\" us today. \n\nOur waitress last visit took maybe 15 minutes to approach our table. At one point she said she would be coming back to take our order but ten minutes later and she still had not reappeared. When I went to the counter to ask for help, she was there and seemed irritated with me. Not exactly the attitude you want... Today it took forever to get an order placed and then when my credit card was taken to pay, it never came back to me. About 15 minutes later I went inside to the counter and the guy had clearly gotten busy ringing other people up. He seemed frazzled. It seems like maybe their system is just flawed... The lets all pitch in at each other's tables and at the counter strategy seems to be failing. I recommend the manager work on the server's attitudes and their method and encourage faster service. \n\nI'll be back because I like the food! But really hope they can work out these kinks."], ["I can't hide it...\n\nEdgehill Cafe is my Marcia Brady. All the other coffee shops just add up to Jan Status for me.\n\nA year later and I love everything from the tasty Hummus + Veg sandwich to the delish yet stomach gurgling Hi-yah! (My stomach responds to high doses of caffeine in an INTERESTING way)\n\nRachel the manager is always friendly and one of my favorite people. Seriously. She takes care of the customers and is a major asset to this business. I'm her Norm from Cheers... trust me.\n\nPlus, I just love the layout and comfy vibe here when I set meetings or need a work-day out of my home office. The playlist over the speakers never disappoints either.\n\nDon't forget happy hour specials too as they offer beer and wine!"], ["This place has an incredibly artistic atmosphere, without being distracting. It's great for studying, getting work done, business meetings, you name it. The social atmosphere is great, and I attribute that to the indoor space being well designed.\n\nI've always enjoyed the service here. The people working there are kind and helpful. Never have had a bad experience in that sense.\n\nI would say my favorite thing off the menu thus far is the Caprese Salad: baby spinach, tomatoes, mozzarella, basil, olive oil, and balsamic vinegar. Delicious! I've had a sandwich here in the past that I remember being OK, but I won't comment on that until I grab another sandwich.\n\nRandom: they have various board games and card games here. Haven't done that yet, but it might be fun to do one day :)"], ["Excellent.  The new ownership fixed the problem.  Coffee and food are 10's and the people working there are glad you are there.  Not too loud either.  If you were there before the redesign and new management, then you haven't been there yet.  Same name, completely different place and vibe."], ["Here's a little window into how my interaction went down with the two staff here today: \nI walk up with my dog so I'm restricted to the patio, pretty standard. I quickly see that every table is covered in dirty dishes and there is nowhere to sit. I decide I would bus a table and bring some dishes to the kitchen and ask them what to do, because last I checked this was a cafe, but instead of a kind response I get scoffed at and told \"WHY ARE YOU DOING THAT\". I was taken aback and apologized if I offended anyone but I had nowhere to sit otherwise. Secondly, having my pup with me I decide to try and bring the dog bowl that is strategically placed outside on the patio inside to fill up. Again I get scoffed at by the 2nd employee and told \"I DONT WANT THAT IN HERE, TAKE IT OUT, I'll BRING A BOTTLE OUT\". Good morning to you too, Edgehill! My $6.30 soy vanilla latte wasn't that good. I've been all over the developed world and that's the most expensive latte I've paid for. Not even in Melbourne or Gothenburg will you see a latte that expensive. I live around the corner on music row and now I know to go the extra half mile to Bongo Java... Never again Edgehill."], ["Great place that is clean, comfortable, and friendly! Hangover hash was fantastic, dirty chai looked lovely, and Melissa and Will took great care of me! The cheese grits is definitely more simple but still tasted good."], ["This used to be my Friday lunch spot, but I think I'm moving on. I order the Open Egg every time. The first time it came with a perfectly cooked over medium egg (as advertised), a full link of andouille sausage cooked perfectly and cut in half, on toast, seasoned potatoes, and this awesome aioli/southwest sauce on the side. Went about four more times, each time the quality getting a little bit worse. I took a break for a couple months to see if things would improve. Today the same thing has turned into a obviously un-seasoned scrambled egg, two slivers of andouille sausage (less than half as usual), on a piece of while bread, un-seasoned potoatoes that were underdone and probably had been sitting around a little while, and the awesome sauce has been switched to ketchup, KETCHUP. \n\nThe coffee has always been alright and the staff are never too excited to be there. (exhibited by the cooks smoking around the side of the building obviously not at all excited to be working, man bun barista guy excepted) If you're going to remodel and give your customers the impression you've improved and have some sort of attention to detail, it needs to be reflected in the service and consistency of the food. If I'm paying close to $20 for lunch it should at least be the same thing every time. \n\nIf this type of clean, bright cafe/coffee shop is your thing then go to Steadfast Coffee in Germantown or Crema downtown instead. The quality at these places is on a whole other level compared to Edgehill."], ["NOT WORTH IT. The coffee tastes like starbucks but is twice as expensive. The food is super basic, and every item is at least $8. I don't mind paying for food I can't or wouldn't want to make at home, but the quality just isn't there. The owner is also always huffing around. Hours aren't great either."], ["One of my favorite coffee shops in town. Great vibe, friendly servers/staff, good food. If you're reading this, don't come here, and while you're at it don't move to Nashville."], ["Nice place. Staff is very friendly and the setup is great. Lots of room and has never been too busy when I've been in, so you don't feel as cramped as you would in some of the other coffee shops in town. Good selection of both hot and cold drinks, too. I have enjoyed my experiences there and will continue to go.\n\nThe only frustration, for some, will be parking. There is a lot that lets up park free for 30 minutes. Beyond that, I think it's $3 for up to three hours. There is a lot of street parking in the area if you don't mind walking a little bit though. No worse than Hillsboro Village."], ["I read the reviews so I came to check it out.  I'm here the day after thanksgiving and it is delightfully quiet. I'm sure this place is packed normally, which would probably be a pain in the ass due to the small floor space but I'd highly recommend during off hours.\n\nI had the open egg sandwich and it rocked! Staff was polite, def check this place out if you get a second."], ["I pass this little coffeehouse every day in my way to work and oftentimes I end up stopping here to start my day.  I didn't realize they had a full menu as well as coffee and pastry selections.  I love that I can enjoy their delicious coffee with eggs, bacon, and a bagel.  It's busy in there every morning but even so the line moves along quickly and you're not waiting too long for your food.  They have a lot of advertisements near the door for local shows and events and they've started selling Edgehill Village-centric items which I adore.  This is a great place to sit and get work done too, though if recommend off hours as the mornings are wild in there.  Parking is limited as well, but there's plenty on the streets.  Prices here are completely reasonable.  I love this cafe!!"], ["I love this neighborhood cafe. It was actually one of the places that convinced me I wanted to live in this neighborhood. I like the vibe inside. The people who work there are friendly, as are the people in the cafe. The furniture has a nice arrangement to it, and a good assortment of options. There are high tables and low tables and bar seats and chairs and couches and even outdoor seating. It's the perfect spot for a hot or cold tea or coffee, or a bite to eat. I haven't had much of the food, and I don't think I'd recommend it for the food, but as a nice, chill spot for an afternoon, it's perfect. Oh, and since it's fall now, I am looking forward to trying the cider."], ["There is so, so much to love about Edgehill. When I first moved here, I believe they were under different ownership and it wasn't quite as sparkly wonderful, but after the renovation, the new interior and furniture is just incredible and much more comfortable. Not to mention they have excellent taste in music.\n\nThe coffee here is totally solid and the baristas are really friendly. I usually go with my standard soy latte (sometimes the chai, which is also excellent) and have never been disappointed. The baked goods are usually excellent and the sandwiches are also good. My default is the Bagel & Lox (and the Tuna Melt hasn't disappointed me), though with a latte and tip, I top out at about $13 so I rarely order it, much as I love it. (This might be the right time to confess that there was a period of about a month where I was completely addicted to the Bagel & Lox and they kept running out of lox and I would actually have to call ahead to check to see if they had it in stock that day. Ha, hm, erm...)\n\nOccasionally I've come for happy hour or wine and my one complaint is that the Sauvignon Blanc they offer (the Cupcake) is just not a good wine. \n\nTheir hours have changed a few times, and while I was very excited the first time they decided to stay open later, they decided to pull back so quickly that I haven't been back in for the later hours since they've resumed. I find it all a bit hard to keep up with when stores change their hours too frequently.\n\nDuring the week mid-day they tend to be packed with people having meetings from Music Row or the church organizations nearby, and conversations can be so loud  that I tend to avoid it. On Saturdays, though, it's a veritable haven which is why I tend to only go then, unless I've run out of coffee at home and need to make a quick run for their morning half-priced coffee happy hour (how great is that?!). I admit I've asked more than once if they have any plans to open on Sundays, because I would absolutely camp out there all weekend if I was able."], ["Friendly service and cute decor. The lattes are great and ordered side of cheese grits and scrambled eggs. The serving was surprisingly large for a decent price. The coffee a little too expensive in comparison. The grits were quite Amazing! A nice smokey flavor. Def great local spot :)"], ["This is ridiculous. I'm from this neighborhood, but now live in Portland OR. This place is the worst of both worlds. What do you get when you combine the soulless vapidity of wannabe hipster LA with the Kirkland brand authenticity of white Nashville? \n\nYou get a $12 crappy bowl of oatmeal with an ironically over-sized spoon and a cup of over-extracted acidic swill coffee. And plenty of attitude from the hipster d-bag wannabe customers. I can't wait to get back to Portland, where our hipsters are nice people who have and appreciate nice things. On the other hand, $12 is a pretty cheap price for learning that I can not trust Yelp in New Nashville. \n\nSkip this place in favor of a freakin' Charbucks."], ["I will start by saying the coffee here is amazing but I have had a lot of problems here. I usually try to get it on my lunch break which is only 30 minutes long. The first instance was when I ordered 2 coffees to go. I had been waiting for 10 minutes and noticed people that ordered after me had theirs already okay no biggie. I went up to the counter and ask how much longer it will be they said they were almost done, I had to remind them about my order 2 more times before it was made and by that point I had waited 30 minutes. So the second time I was disappointed I ordered a spinach salad. I clarified it more then once I wanted the spinach NOT the kale and yet low and behold when I went back to work it was a kale salad with maybe an ounce of dressing. Also the reason I ordered the spinach was because it didn't have any meat on it and the kale did. So I could not even power through it because it was covered with uncooked bacon."], ["Portions too small.\n\nOne time visitor and won't be back again. While all the food may not be as bad as the farmers omelette, I can tell that portions are small for nearly all options. Is affordable at like $6-12 but value is still weak as I paid $11 for potatoes and egg that probably cost about $2. \n\nFarmers omelette had nothing in it, very offputting to just eat a hunk of egg with little to no veggies. The space is great and carrot cake looked killer but the food was quite bad. Wanted to love this place but absolutely cannot."], ["Went for lunch this week and was totally impressed! As soon as I walked in the door, I got that lovely coffee shop atmosphere with the smells of coffee and their bakery items.\n\nAtmosphere: You order at the counter & they bring your food to you. Nice outdoor seating area & the interior is designed so nicely! Can't wait to return & eat inside.\n\nFood: Tasty! I got the pesto turkey sandwich & it was very hearty. Big portions size, flavorful, and delicious crispy sweet potato wedges. Also got a strawberry mint lemonade, which was nice and refreshing. They serve breakfast all day & seemed to have a few vegetarian & gluten free options.\n\nPrices: Pretty reasonable. Most everything seemed to be under $15. Big portions, so a lot of bang for your buck. (My sandwich could have served 2.)\n\nService: Great. Everyone was friendly & the food came out pretty quickly. Staff seemed happy to answer any questions.\n\nParking: They have a few spots in a small parking lot, $4 valet parking in Edgehill, limited street parking, and a paid community parking lot.\n\nOverall: I will be back! I can't wait to come try out some of the breakfast items. :)"], ["I've been coming here for years and watched owners and the menu/prices change over time.\n\nThe coffee is good, but doesn't stand out from any other shop in town.\n\nThe food was average but overpriced when this place was a counter-service coffee shop. It is now a sit-down restaurant with a larger menu, but many of the menu items are unchanged and at a higher price.\n\n$9.50 for a pile of kale with craisins, walnuts, and feta is ridiculous."], ["We have tried them three times for breakfast, but sadly given up. Food is below average and orders are wrong half the time. How do you mess up oatmeal? It has a weird grease flavor. Too many better options in this city."], ["What a horrible experience and I'm sorry to have to write that. No one even came over for the first 10-15 minutes, the food took a good 45 mins to an hour, arrived all at different times and to add insult to injury....was cold and not prepared right. I don't think I've had this bad of an experience at a restaurant in a while. The two stars is because the food was good tasting and they comped a meal because of how awful the service was......but still. I can't write enough how wrong it all went - I'd wait until they get their act together. There are a thousand and one places to eat breakfast in Nashville, you may want to try the others."], ["This place went back to being a coffee shop sometime ago. Thank you! They pretty much reinstated the old menu and everything. Wish they'd switch back to 8th and roast coffee though!"], ["My mom referred me to Edgehill Cafe. She said she really liked the ambiance. So I decided to check it out with a couple of friends when we had a business law study session. They had a small parking lot, which was full, so we parked a couple blocks away (it was cold out, so not an overly enjoyable walk). Like my mom said, the interior is pretty spacious for a coffee shop. All the tables were full (a good sign--they're busy), so we sat in a cute cushioned area until a table opened up. The drinks were decent (you get a fair amount of coffee). I enjoyed all the Christmas decorations very much. My friend also said that they sell sandwiches there. It's very likely that I'll be back!"], ["Great food, had the tuna salad and it was fantastic. The atmosphere is worth the trip!"], ["I had little interest in standing in line today. Yelp found this wonderful little place for me. The food was wonderful. Zippy, delicious, and perfect size. Coffee was good (I am a snob on this, others may enjoy it more). Staff super nice.\n\nBeautiful patrons, great food, wonderful staff. Only downside was 1 hour parking. Make a new line for this place, you won't regret it."], ["Wow, I give the vibe of Edgehill Cafe a full 10.  This is probably the best lay-out of any coffee shop in Nashville and it has many contenders.\n\nThere is so much ROOM!  Bring your laptop because they have free wifi.  I really love Amy's homemade baked goods like her gluten free blueberry muffin.  It is so yummy!!  \n\nThe coffee is outstanding.  I really love the It's Always Fall Somewhere coffee drink which includes vanilla and honey.  Very, very chill and very cool coffee house."], ["I really do like the Edgehill Cafe. Mainly, because the ambiance is perfect. People come here to study, chill, talk, read, group meetings, whatever. The decor is something like hobo chic/ DIY. Whatever it is called, I like really like it. It seems like the owner really put a personal touch in this place.\n\nThe staff is oh so friendly and relaxed. They will come to your table and deliver your order. I've sat there for 2 hours before, and the staff has even come up to me asked if I wanted another drink or some water or to take my trash! How kind! I've never had the food here, but I've had the coffee. It's like other coffees you can get at other coffee shops. I've also had the Chai Latte, I was not a fan of theirs. It was much too sweet and not enough milk for my taste. I could probably ask them too fix it too my taste, but I'm not.\n\nParking can be an issue. You either have to pay ~$5? to park in the gravel lot adjacent to the building, or park free on the street and walk, or park in the lot in front of the cafe; however, with the lot in front of the cafe, it has a 30 min limit (which I confess, I've never adhered to...). \n\nIt's priced like any other coffee place. It's a great place to bring friends and to talk or study."], ["Finally, a large coffee shop with great food portions!  The grits here will blow your mind; filled with bacon, cheese, and topped with an egg...yes, it's probably 1000 calories but dang, it's good.  And the coffee is excellent and its big enough to find a seat most mornings. I will gladly go here over most any place in Nashville."], ["Great atmosphere, good food, and a friendly staff.  The coffee is pretty darn good too.\n\nFound the place on Yelp looking to change up my breakfast routine.  I had the Trilby Fritata and thought it was very well prepared.   For me, that means the eggs weren't overcooked to a texture like Styrofoam. \n\nWe had to wait a bit longer than usual for pancake batter to be prepared.  The staff politely explained the delay, and gave my son a free cookie and me a free refill on my coffee.   Neither was necessary,  but appreciated.\n\nYou don't need to arrive early for a seat like some other places.  We left around 9 am and the crowd was just starting to come in.\n\nWhen we were leaving, my little boy said \"Daddy, I want to come here every weekend. \"  Three year olds give the unpolished truth, so there you have it."], ["I miss this place so much since I've moved!! BEST COFFEE PLACE. The update is so swanky but still incredibly cozy. I don't know what it is about this place but it feels so relaxing. The staff are so kind, they recognized me every day and were always happy and warm. The food... Delicious. Breakfast or brunch here is like insane. Always plenty of seating. Cool part of town. And pretty cheap considering its specialty drinks in downtime Nash. The ginger green tea with espresso was my go to. Heaven in a cup. Give this place your biz"], ["My first memory of Edgehill Cafe was about 3 years ago when they were hosting a writer's night that a friend of mine was in. Since that first time here, it was easy to see how cozy and welcoming the cafe is. \n\nRecently, I have been back to Edgehill for meetings. I often wonder why I haven't been back to this place more over the years. What a cool place! It's not your normal trendy Nashville coffee shop where you feel like you need tight pants and asymmetric side-swept bangs to sit and enjoy a cup of coffee. The staff is super friendly. Plus, it's right in the middle of Edgehill Village, which is such a convenient location and close to EVERYthing, including Belmont, Vandy, downtown, and music row. Also, they have awesome food that I've gotten to sample several times, but I have yet to return for a full meal. I imagine that it is fantastic. This is a place that I want to see myself become a regular at."], ["An adorable spot in Edgehill for coffee and great bites. Great ambiance and lovely service. The almond milk chai latte and grilled PB/chocolate/banana sandwich (I mean, what?!) are ridiculously good."], ["The staff is soooo nice and friendly and awesome!! If you go, you have to get the tuna melt and side of sweet potato fries. But if you're in a breakfast mood, the tacos are bomb.com \nBest coffee in Nash"], ["Not updating an opinion on Edgehill Cafe is just a crime.  It went from being the horrible place that the Vandy crowd went to anyway to a pretty decent place.  They changed up the decor: much needed and very nice.  The coffee was changed: from the bitter crap to Drew's Brews:   predictable and unadventurous, but not bad.  The service: hey, they treat you like a human being, not like the scum of the earth like that place on Hillsboro Rd.\n\nThe parking is difficult, still, but there's not much you can do with that.\n\nBut the place is definitely better.  A worthy rival to the J&J's, Bongo, and Casablanca nearby."], ["I can retire the Buck Owen's song because I have found Mocha...that I have been searching for...for so long!\n\n          \"Where, where, are you tonight?\n\n          Why did you leave me here all alone?\n\n          I searched the world over,\n\n          And thought I found true love.\n\n          You met another and\n\n          Phht! you were gone.\" \n\nBuck was singing about a girl. I was singing about Mocha. I first met Mocha in Galway City, Ireland. I think she is still there, but her twin has arrived in Nashville...at Edgehill Cafe.\n\nAs Americans, we love sugar and tend to make everything sweet to the point of ignoring the value of other flavors. Europeans, despite not having anymore children and handing their treasures off to people who don't value the treasures of the West...they still do \"sweet\" right by not over doing it by insisting that coffee is a drink and not a dessert.\n\nEdgehill Cafe not only affords a legitimate environment to work, relax, socialize, and enjoy life, but they get coffee. More importantly, they understand how coffee and chocolate can have a perfect marriage when united by leche to create a hot and wonderful experience. \n\nThe lack of a star preventing a perfect score (I rate based on genre and not Michelin stars) is due to the pricing. They can price the Mocha at any price...it's worth it because it's cheaper than a flight or boat to Galway, but the breakfast bagel was expensive. I really enjoyed the Everything Bagel with Egg and Bacon, but at $7 for just the sandwich it's just not worth it. The egg seemed to be legit as opposed to being poured from a carton and it was seasoned well, but still...$7 for what should be $3.50 is just way too much! The itemized receipt included fruit being served with the sandwich, but there was no fruit. Perhaps, maybe, if the plate included fruit...$7 would be an acceptable price for breakfast. Maybe. \n\nWell, who cares about a bagel? I found Mocha and I can't wait to visit again."], ["What a horrible experience and I'm sorry to have to write that. No one even came over for the first 10-15 minutes, the food took a good 45 mins to an hour, arrived all at different times and to add insult to injury....was cold and not prepared right. I don't think I've had this bad of an experience at a restaurant in a while. The two stars is because the food was good tasting and they comped a meal because of how awful the service was......but still. I can't write enough how wrong it all went - I'd wait until they get their act together. There are a thousand and one places to eat breakfast in Nashville, you may want to try the others. \n\nUPDATE as of 11/26....I will say that someone reached out to me from Edgehill apologizing for the experience (not my intention in writing this review!) Good on them - of course there are kinks to iron out during the first few months and it shows integrity when the restaurant takes note. I have been back since and really enjoy the place - lesson learned, let them settle in before rushing to the door."], ["I have heard murmurings that Edge Hill Cafe was recently purchased by new owners and that the business went through complete redesign. My last experience was several months ago and was left me indifferent. \n\nOn this visit, I was already swaying towards the impressed side when I walked in. I love the swap to a more lodge-like and comfy setting in lieu of the contrived contemporary vibe that was going on before. The furniture is absolutely beautiful! There are also many nooks to cozy up to with your laptop, book, meeting, or meal. I was instantly greeted and my Veggie + Hummus sandwich ($6) was served up within moments. The hummus is made in house daily and very evident because it was delicious! A large pickle slice and bag of chips were accompaniments. \n\nI was able to have a successful working lunch and thoroughly enjoyed my environment. This will be a new central option for the many meetings that I set weekly. I am pretty sure that I will also host an upcoming Yelp Office Hours here too!"], ["Super cute cafe inside and out. Has outdoor seating. Service was on point. Coffee and brunch was delicious! Parking is a bit tricky, had to do neighborhood parking about 4 blocks away- so not too bad."], ["Tasty coffee and great environment for anyone looking for a place to hang out for awhile, surfe the web, chat, or get some work done.\n\nI like to go here sometimes and use it for a mobile office.  It's very comfy and I always seem to get a lot done.  I also tend to see a lot of regulars doing the same which definitely says something about the place. \nOne of my favorite coffee shops in Nashville for sure.\n\nI lost my WiFi a couple times, but other than that no complaints.\nOh, and my laptop battery sucks so I love that there are outlets all over the place, which is definitely not the case at Fido's for instance, where they have great coffee, but impossible to get a decent seat with power in there."], ["Really good! In town for the weekend and midtown was pretty busy for a Sunday so we searched a little further and found this spot. Can't believe it's only got 3.5 stars. Very cute interior and the food and coffees looked and tasted great."], ["Treated so badly. First I ordered a caramel latte with my friend, when the drinks were delivered they told me they were out of caramel and gave me a vanilla latte instead, without asking. We then waited an hour for our food to find out the fryer broke and they wouldn't be able to make the meal. Had to get our money back. Awful experience here."], ["I really like Edgehill Cafe.  I have had their Hot Chai and the Abbe, really wonderful.  Flavors are unique and powerful. I haven't tried their food yet but I will try their bites as well as all of their lattes.  I have tried a lot of the cafes in Nashville and this is definitely one of the best. Parking is tough - just FYI!"], ["I hadn't been here since the remodel, and I love what they've done with the place! Came here for lunch with a friend and I love the spacious ambiance- tables, rugs, comfy chairs and even board games under the bench up front. I got the pomegranate green tea, which was delicious (very sweet though, not tangy like I thought it might be). I also ordered the smoked salmon sandwich and it was amazing. Cream cheese and salmon with sprouts, lettuce and wheat bread. With the Scoutmob, it was all for a very affordable price. Come here with a friend, to study, to drink, to eat, to play some games- so many possibilities. So comfy, it'll make you feel relaxed and happy. Fair warning, parking can be hard to find in the Edgehill area."], ["Edgehill is great.  The breakfast sandwich is solid.  Only warning would be about getting the grilled peanut butter and banana sandwich paired with the Fall somewhere Latte.  It will leave you searching desperately for a Gatorade.  There always seems to be plenty of space which is great as well. Enjoy!"], ["They just refurbished this location for a more contemporary look. I love the beautiful wood booths and streamlined modern tables, but the wifi was a bit unreliable. For a coffee shop, it is paramount that this is not an issue for smooth studying. I had the \"It's Always Fall Somewhere\" drink. Perfect amount of cinnamon, honey, and caffeine for the autumn season. It's a bit confusing walking into the space since no staff came to seat us or even talk to us. In fact, the woman at the counter being served seemed to just be talking with the server, not letting us even approach the register. A bit strange, but the rest of our experience at Edgehill was polite and quite fast."], ["This place used to be a fast food casual. It should go back to it.  We came around 10 am on weekday.  Sign said to wait for someone to seat you. Not really. We peaked around the corner and were finally seated.  Not an extensive menu but my husband came for Jenni cakes and I like eggs and toast.  I asked about fruit and the waiter (lousy) said there was an upcharge.  I said no and just bring the potatoes.  About 45 minutes later and after we continually asked where was the food, it arrived. Eggs were cold, toast was cold, jenni cakes tasted like cr&^.\nJelly was clear red water. It was awful.  Waiter never came back so we flagged yet another hapless soul.   Told her the problem and the manager came by.  No apology.  She took %10 percent off the bill.  No where in Nashville has ever taken 10 percent of an inedible meal. I asked where the potatoes were. The guy went back and threw some frozen square potatoes in the deep fryer and served. No seasoning.  Plus they charged $4 for the fruit I never ordered.\nThe place is lovely.  Will we back? Not ever. Dinner menu looked good but it should just go back to fast food casual as the people who ordered take out just zoomed in and out.  \nIf you come here, just get a cup of coffee and bring your own donut."], ["The Breakfast Taco was fresh and tasty.  I don't like scrambled eggs much, but the ones in the Taco I enjoyed very much.  The other 5 people were with thought their food was delicious. Our Server, Kevin was professional and friendly.  Definitely would eat there again."], ["Love their loose-leaf tea and coffee drinks. A favorite is the \"Always Fall Somewhere\" latte (vanilla, honey, and cinnamon)."], ["En super god morgenmadsrestaurant, gode l\u00e6kre r\u00e5vare, god betjening, god kaffe (men husk hvis du er fra Europa, skal du have et ekstra shot Expresso i din kaffe, ellers smager det som kogt vand, men det g\u00e6lder alle steder herovre), jeg fik en ham'n egg hvilket var et b\u00e5de stort nok, og l\u00e6kkert m\u00e5ltid... Jeg kom her flere morgener i tr\u00e6k, da stedet var ganske enkelt super godt!"], ["Love this place.... so cozy and staff so willing to please. Had the best soup and sandwich.  I had the Turkey Pesto on Ciabatta bread. It was wonderful. My latte was so good ....love the coffee here. Why go to Starbucks when you can come to such a great locally owned place without the attitude of the other coffee shops? Will definitely be going back next time I'm in the area."], ["Got the breakfast tacos. Super delicious! The reason I'm giving five stars though is because everybody who works here is seriously so nice. Will definitely be coming back!"], ["This was my favorite coffee shop in Nashville until the moved next door. The old corner building reminded me of San Francisco or Seattle. \n\nNew location is beautiful and artfully designed but it lost the coziness. \n\nAlso, they should update their hours on their website when they change them at random. Just spent 30 minutes parking and trekking through the rain to find this posted. So disappointing."], ["I AM A FAN. I have been here at least 10 times. The food is great the tea/coffee offerings varied. Coffee is everywhere however this place bustles with a wide swath of the public from business professionals to the most casual among us. I appreciate the way the staff is so pleasant and helpful. They don't grumble or growl.. They are always  considerate and answer the same questions a hundred times ... always with a smile. I enjoy spending time and money to support this business that understands customer \"Service\" and willingly satisfies every request. They are awesome. BARISTA Cafe in East Nashville on Gallatin could send their employees for some customer service pointers. \nGO TO EDGEHILL CAFE"], ["It was less than adequate. A $9 sandwich with a half an hour wait time turned out to be little more than a slice of cheddar (not melted) with egg and ham on toast. The cafe has a great ambience, just not the food or coffee drinks to match. Decent study space with free wifi, though it lacks outlets."], ["Being relatively new to the Nashville area, I've been kind of disappointed with different coffee shops that I've been trying out. Frothy Monkey in 12 South has a nice atmosphere but just OK food/coffee. Barista Parlor was too expensive and too pretentious. Lo and behold, I find Edgehill Cafe and it's exactly what I was looking for. Cozy, open space with lots of tables, big and small. Free wifi. No pretentiousness. Prices aren't cheap but fair, and the almond milk latte I got plus the Tuna & Swiss Melt sandwich I got was FANTASTIC. Seriously so good. And I'm not usually a fan of kale at all, but my sandwich came with a side salad of the stuff and I actually liked it. I sat in this coffee shop on a rainy day, plugged in my laptop, got my food, and was content here for hours doing work. I will be back for you, Edgehill Cafe. I will."], ["This place really surprised me. Apparently there is new management, so you can ignore the old reviews here. It has some of the coolest decor for a cafe in Nashville. The food is great (but they really need to update the cash register system for the new menu items - your receipt rarely lists what you actually ordered) and the staff are friendly. The salads and sandwiches are all tasty. I've eaten here for a casual drop in lunch with my wife and taken faculty visitors. It really accommodates a range of customers. I hope they stick around for a while!"], ["This is one of my favorite spots to eat when I come visit Nashville. Everything always tastes super fresh, the service has been great and the speed of food delivery to the table good.\n\nFood recommendations:\n       -Breakfast Hash: I recommend ordering this dish with over easy eggs. It's full of flavor and has just the right proportions of egg, potato, breakfast meats and sauce. The pico de gallo is amazing as well that's served on top.\n       -BLT: The fried green tomato turns this typical sandwich up a notch. The bread tastes like it came from a bakery and baked fresh that day. It's lite and airy. \n\nDrinks: I noticed on their menu board they had 2 for 1 mimosas I'm not sure if this is a regular thing or if it was something special for Easter weekend.\n\nEnvironment: It's a cozy environment. Good for a business meeting or brunch with a group of friends."], ["I had the bacon, egg and cheese biscuit and it was delicious! Seriously, one of the best biscuits I've ever had. It came with strawberry preserves that was also delicious. I also tried one of their specialty lattes. It is really good and they offer almond, oat, and coconut milk as non-dairy alternatives. I would definitely come here again to eat breakfast or to do some work."], ["Stayed just down the road at an Airbnb and noticed it was in walking distance. Great drink selections and a satisfyingly good breakfast menu!"], ["This wonderful little coffee house in Edgehill is the perfect place to come if you have any work you need to finish.  Open, bright, cozy, with delicious coffee and cheap eats and a small patio, it is a student haven for getting things accomplished.  I highly recommend the \"Hiyah\", a coffee with a double espresso shot and hazelnut flavoring.  It will turn you from a tired human being into a working machine.  As a Vandy grad student, this place is exactly what I need when I have to get something done.  Let's face it, there are way too many wonderful distractions in this town and hard to find a place to actually step out and work when you need to.  Everyone in this place is respectful and considerate.  I would recommend it to anyone needed a little peace and quiet or a good cup of coffee.  Also, their frittata is an incredible way to start your day.  Only downside is that they are closed Sunday, so go Saturday to get your work done so you can have Sunday off!"], ["Not best coffee I've had but not the worst. Cute space, a lot of seats. The younger one who made the drink seemed very nice, the 30 something girl who took my money could use a smile...or a drink...or two."], ["First time I came here I had the shrimp and grits, which was fantastic! So fantastic I begged my boyfriend to take me back... Second time was horrible. First off the service was bad, the waiter only came 3 times: to put water on the table, take our order, and give us the bill. The rest of the time we had to flag down anyone passing by. It took us SO LONG to get our food we had to pay to extend our parking (mind you we only got one thing) When our food finally came out a random waitress gave our food to a man sitting next to us (he ordered the chicken and waffles as well) and the man even told her we had been waiting a really long time, she should give us the food. She told us the other chicken and waffles was coming out right now...another 20 minutes went by, and we finally got it. We had to flag down another waitress to let us see a manager. We talked to him and he asked if we wanted anything. I asked could we get a slice of carrot cake which I had wanted in the first place. I NEVER EVEN GOT IT. But our meal did end up being free. The food is pretty good but the service was HORRENDOUS they need to do better."], ["Was worried about finding a decent breakfast/brunch place on a Sunday morning near the Vandy campus. Noticed the Edgehill Cafe was on Open Table and was pleased to see they had decent morning availability for our group of four.\n\nFound the place easily, nestled nicely in a neighborhood just east of campus. Parking was tight, but found a free street spot very close.\n\nThe front entrance might confuse when you walk in, as there's no dedicated host/hostess stand, but a sign clearly lets you know to wait to be seated. They indeed had our reservation and sat us quickly.\n\nWonderful after that: variety of coffee/tea drinks were excellent - you can tell the place has its roots in being a coffee shop. The brunch options were numerous and excellent: butcher omelette, hot chicken and waffles and French toast casserole were all ample and tasty. Grits breakfast called \"The Nap\" looked great on the menu and somehow tasted even better. Ordered a couple side biscuits and jam, which were dense and just what you'd expect in Nashville.\n\nThe place started really hopping just after 10 am, with people waiting outside after we left around 10:30. While we waited for our card to return to the table after payment, the owner popped by our table to check how it all went (and to start clearing the dishes); what a delightful guy.\n\nFrom starting at a point the day before where we had no idea where we could grab food on a busy Sunday to having the experience we did - pretty darn successful, I'd say.\n\nStrongly recommend."], ["This place... I love the idea of it - it's a wonderful thought of a restaurant/cafe. The original Edgehill Cafe was much different. It used to be a fully functioning cafe that looked and acted as a cafe should. Ever since they remodeled and moved next door they have morphed into the red headed step child of Nashville brunching locations. I want to love this place so bad, but it's like an abusive relationship, I just need to break up with them. Their coffee is awesome, their staff is friendly and smiling, but their food is way less than average with a few okay items on the menu, but mostly big misses. Their kitchen is clearly understaffed, they're just understaffed in general, but on a busy day get ready to hurry up and wait 30 minutes for eggs, bacon and toast. They can't figure out how to make biscuits, they literally just mix Bisquick with water, roll it into a ball, and bake it for 2 minutes longer than they should - more like biscuit bricks. Their sausage is the most dry and sorry excuse for sausage ever - it's an inch thick, formed like an oversized burger, and cooked until all of the moisture it's ever known is completely destroyed. For a while their bacon was so overcooked that it was a crime against humanity, but thank God they figured that one out. I just want to sit down with the chef and be like... don't you want your food to taste good? Stop making gross food! It's easy! Further more, if you want to add something to your meal after you receive your order, like a piece of toast, you may have to wait 20 minutes, or you may just never get what you ordered, as I have experienced both scenarios. Anyway, the staff is really nice, it has a decent atmosphere if you like feeling like you're eating in a library, BUT they desperately need to downsize their menu by 75%, revert back to being a coffee shop again, and either fire their chef or get him cooking lessons. On the upside their hot chicken and waffles are pretty damn good. Sorry Edgehill, we have to break up."], ["I constantly see our fearless leader, Marcia, checking in here, so I should have know that it was going to be great. Located in the Edgehill neighborhood, hence the name, it's a great spot to grab your morning pick me up, or fill your belly during lunch. \n\nI'm always on the prowl for great coffee shops, and I'm lucky to live in a city with quite a few. Edgehill is near the top of my list, because they have delicious coffee, filling sandwiches, and its all wrapped up in a cool atmosphere. \n\nThe first time I went here I ordered a latte and a chicken salad sandwich. Both of which were to my liking. If you're not into either of these options, I'm sure something else on their creative menu will catch your eye. \n\nThe staff is friendly and the offerings are spot on, so why not give them a shot?"], ["wait, as a nashville 'native', how have i never known about this place?! seriously, every time i go to nashville, the city surprises me. \n\ntucked in between the jcrew mens and the newest warby parker storefront in edgehill/nashville, this cute coffee shop has everything (except outlets) that i would love in a coffee shop. they have adequate choosings of drinks (aka coffee type drinks) for the non-black coffee drinker (dentist, im still doing great! no black coffee for me!) and also an adequate menu.\n\nthings i love:\n-the soft plushy velvety booth chairs lined up against the wall for your buttock comfort \n-high ceilings\n-tons of natural lighting for work (or IG photos)\n-cute decor\n-great food / drinks\n-friendly baristas\n\nminus 1 star for: dearth of outlet plugs along the velvet seats and the cafe. \n\ndont forget to hop across the street for some cool shopping and ice cream (legato gelato)! Parking is a challenge, but as it always is in developing nashville. it seems like this place has been newly renovated, so i can't speak to what it was like before, but i do love what it looks and feels like now! \n\nPROTIP: the parking in the little parking lot is 1 hour only, so make sure you park further down the street for unlimited free parking."], ["Someone knew what they were doing when they set out to decorate the trendy Edgehill Cafe. (arm chairs covered in burlap coffee sacks, farm tables, local concert bills) Industry folk meet and pitch their latest ideas. Decent parking options. Coffee is fantastic. Only complaint, they are seriously understaffed so brace to encounter disgruntled baristas."], ["Nice alternative place to have lunch off the beaten path in Nashville. We had the hummus & veggie sandwich and the club sandwich with kale salad which all was very good. Unfortunately they didn't warn us that they serve their apple cider hot, which we found pretty grose."], ["This can be a great place to people watch. Some dude from the Mavericks is in there all the time and once one of Josh Grayson's (of 20-minute American Idol  fame) staff was there saying not nice things about him. Ah, to be a fly on the wall. However, every time I leave the place after working on the laptop for a few hours I smell like a panini sandwich and have to change my clothes and shower. The coffee is ok, not great."], ["location is good, as is the general layout of the place, however the coffee always tastes burned and it kind of smells like wet animal in there."], ["A nice little cafe close to Belmont University to enjoy breakfast. I had the Farmer's Omelet and was surprised how delicious it was with cream cheese. I do not recommend the cheddar grits. It's regular grits sprinkled with cheddar cheese."], ["It's Always Fall Somewhere..oh how I wish I was constantly in that somewhere.  However, the coffee drink aptly named so at Edgehill Cafe will do in a pinch.  Not gonna lie, totally ordered this drink solely for the name, and took a gamble on what might reside inside that paper cup.  I mean, anything fall flavored is a winner in my book. This latte didn't disappoint.  Turns out it is a vanilla latte with cinnamon and honey.  Just the perfect amount of sweetness to match that rich brew they're cooking up.  And yes, I did long for a cool, crisp breeze while sipping that warm, liquidy goodness.  Next time I'm in town I'll have to order the Abbe Road.  The only thing better than tasting my favorite season in a cup would be if the Fab Four themselves reappeared magically. (I love you John!)  A girl can hope right? \n\nI spent the better part of my morning and afternoon in this eclectic coffee house with some work colleagues.  It's quite a cozy space.  My favorite part has to be the arm chairs that have been reupholstered in burlap coffee bags.  Sheer genius Edgehill.  *Insert applause here*  If you are looking to get some work done here, don't fret.  There are quite a few large tables with outlets to plug in laptops or spread your clutter about.  If you're more of the 'veg out' kinda guy/gal, there's a few cozy little seating vignettes along with a sweet little nook in back- perfect for conversing.\n\nIf I lived in Nashville, you can bet I'd be a regular in this space.  They've got hella good coffee and I noshed on a pretty kick ass turkey and pesto panini. The music in this joint is second only to my iPod mix.  I heard Johnny Cash AND Arcade Fire while I was here.  WIN!  It's very homey and the service was extremely accommodating.  So, until Nashville and Erica B. meet again, I'll continue to try and recreate that latte in my own kitchen here in Memphis."], ["Edgehill Cafe is perfect for when I want a quiet place to get work done, away from my office. I'll usually get an iced tea (half unsweet, half fruit flavor) and a muffin. I had salads and sandwiches before the menu changed, so I'm excited to update when I check out the new options.\n\nService is very friendly, and there is a comfortable atmosphere in the cafe. I like the idea of coffee happy hour in the mornings, but I haven't yet made it in for one of those. Outdoor seating is nice, when you can snag a seat. I feel good supporting a local spot that serves delicious coffee and takes an active role in the community."], ["The enivornment is great, but the food is ok. Potatoes where undercooked. Great place for coffee, but not for breakfast or brunch. Maybe the lunch menus better, but I won't find out since it is my last visit here."], ["Took 30 minutes to get a subpar waffle and under cooked bacon. The cold brew is super bitter too. This place is not what it used to be."], ["Here's why visiting the space itself is worth it: dramatic salvaged wood paneling, reclaimed wood tables, comfortable coffee sack reupholstered wing chairs, oversized pillows, cozy nooks, airy windows, and the list goes on. A DIY-er's design dream. This \"rustic elegant\" place is literally out of a magazine and more accessible than say, sitting at Bloomingdale's Home Store. \n\nThe coffee itself was acceptable, if you consider bland and boring acceptable. Also, my friend had an ice vanilla coffee and ended up drinking the syrup first, so I'll offer a fair warning and say stir well first. \n\nBut hey, the way I see it, you pay an entrance fee to sit and chill in an awesomely well decorated space and they even give you a cup of coffee! If that's the case, its seriously worth the three bucks."], ["I have ended up visiting this place twice in the last one week. It has an amazing decor. especially the passage to the restroom has a majestic vault door. Also the second time around I found their service to be really great. The attention to detail was impressive."], ["This place feels like being in a depressing hotel lobby. The old location had lots of character. The food and staff are still great, but I can't stand to be in the space for very long. Has potential, but won't be going back."], ["came for a saturday afternoon. edgehill cafe is a great place to sit down for a few hours and get some work done. pleased to see plenty of power sockets and places to plop down with a laptop!\n\nonly had an iced coffee (to herald in the warm months!), but it was balanced and very drinkable. will be coming back."], ["Relatively quiet compared to other cafe's, fresh food, great service, and I love the ample light and classy decor!\n\nI'd have to try the coffee before I give this place a 5 star rating.  The menu offers a variety of sandwiches and fare to fit your taste buds.  I ordered a tuna melt and I went in with low expectations, because I met the owner at church one day.  I do have to apologize to the owner for making a quick judgement.  A slightly frazzled elderly gentleman, made me thing it was an old mom and pop cafe.  \n\nTo my surprise, it was a classy, rustic, industrially decorated cafe located in the heart of Edgehill.  I found a seat, and loved that the food was served rather than having to pick it up at the counter.  Personal service adds a personal touch to a cafe and makes the customer feel at home.  Other cafes in the area are pretty dark and noisy, but this one is great because the Edgehill cafe is located with less car and walking traffic, and the large windows bordering the street bring in a great amount of natural light.  \n\nThe best kicker for me in this place is the great and consistent internet connection.  Many or most places in the area have horrible internet connections.  But this place has a pretty good connection.    \n\nEdgehill is a hidden treasure, nestled between the Belmont and Vanderbilt University campuses, that offers a great ambience, fresh fare, and a stable internet connection that won't disappoint any student or denizen of Nashville!"], ["I used to come here all the time before they moved into the new space. I miss the old edgehill cafe soooo much. Today I came in for lunch with two of my friends...I spent $17 on a kale salad with chicken and a cookie (the cookie is still delicious). The kale salad used to be soooooo good and they used to give you the option of getting turkey and they served delicious toast with it. The kale was totally dry and tasteless and the chicken was the same- it was all just gross and definitely not worth $17. They used to marinate the salad so perfectly and you no longer get the toast with it. There were fruit flies everywhere, and I had my food for literally ten minutes until my other friend got his food and then it was another 5 minutes until our other friend got his. Also the water cups are toddler size; we had to refill them several times. The only thing good about this place was the friendly staff and the peanut butter cookie. I'm so disappointed in the new spot and I will not be back."], ["I'm becoming a fan of the Edgehill Cafe. When it comes to coffee spaces.. I love Fido mostly because of the food. I love Crema because it's maybe the highest quality cup of coffee in Nashville. I love Roast because it's also the highest quality cup in Nashville. Barista Parlour was maybe too quality.. it gave me the jumpy jitters like I haven't experienced since I wasn't a regular coffee drinker.\n\nBut the warm drinks, food, and ambiance at Edgehill are winning me over, after all these years.  It's the perfect place to pop into for lunch, a snack, or a cuppa somethin'.  \n\nParking is a little crappy.. the lot is small. To park for free, you may be a few more cars down the street than you'd like to be. But hey, the neighborhood is nice, and it makes for a nice stroll."], ["The cinnamon/sugar toast. O.m.g.  It'll take you back to your childhood. It's so melt-in-your mouth delicious. \n\nI'm not sure what's with coffee shops and sub-par customer service, but the Edgehill was no better than the last, when it comes to treating the customer with a friendly greeting. \n\nWith that said... The cinnamon sugar toast... Mmm..."], ["This place has a nice atmosphere to it. The service is nice enough. If they get too busy, they'll forget a lot. They were very accommodating and friendly when my friend (who has a nut allergy) sent her waffles back because it had Nutella on the plate. My order of the grits bowl was just ok. The veggies and sausage on top were kind of cold, but it wasn't a bad dish overall. The Belgian Waffles are likely the best thing on the menu. I'd recommend them if you like sweet stuff. Overall, it's a good place for an affordable brunch."], ["Have gone a few times in the past month. Great spot to leave the office and work remotely. Fast internet and great coffee to compliment your work.\n\nI have tried select food items on the menu but the last time I got the club or BLT, and I couldn't eat it all, because of the food portion and brought it back to the office.\n\nI would highly recommend to go especially if you are around music row."], ["Love this place.... so cozy and staff so willing to please. Had the best soup and sandwich.  I had the Turkey Pesto on Ciabatta bread. It was wonderful. My latte was so good lovethe coffee here. Why go to Starbucks when you can come to such a great locally owned place without the attitude of the other coffee shops. Will definitely be going back next time I'm in the area."], ["We had the cortado and drink of the month-Windsor. Both drinks were amazing and the service was great. Good ambience to just relax during a busy day."], ["Really disappointed in this cafe. Menu falsely advertises ingredients and portion sizes are inconsistent. Manager is rude and abrasive. Will never be back."], ["This used to be such a great place. But since the move it has turned from a cool casual cafe with a great vibe into just another restaurant. Their menu used to be innovative and unusual but since the move and the ability to deep fry everything - its just the same as everyone else. Gone is the kale side (unless you want to pay an upcharge for it instead of fries) and the delicious hummous - in fact they have no vegetarian sandwich on the menu these days. They used to have a daily specials board that was always tempting but no more. The staff also don't seem as friendly - in the old cafe they were chatty and accommodating - but no more. I even got overcharged one day and the guy insisted he was right and I was wrong (and that I didn't know that they had put their coffee prices up). Low and behold the next day I was charged the usual amount. Such a shame. We now need a coffee shop in the music row neighbourhood to fill the void!"], ["This is seriously the best place in Nashville. It has amazing coffee, a great food menu, the best staff around and it is so conveniently located to anything I need to do. It's a great place to not only get something to go quickly, but to sit and stay a while, whether it's for breakfast, lunch, or dinner. \n\nAND they have fun drinks now! hi, mimosas!"], ["Edgehill Cafe is a great place to come to have a cup of coffee and use the internet to get some work done. The Cafe is located on Edgehill at the end of music row, and borders on Belmont University. They also have a recording studio but I have only been to the cafe.  The Cafe has a nice selection of pastries and coffees.  A good warm cup of coffee always helps fuel me along when I visit the cafe.  They have a great setup for working with your laptop.  They have several stations where you can plug in for power and ethernet. You will never have to scurry around the walls of the room to find a power outlet. \n\nEdgehill cafe never seems to be too crowded,  no matter what time I have visited I have always been able to find a good place to sit.  They have bands on the corner stage on certain evenings. The sound quality here is really pretty good, as you would expect since they also have a studio in the building. So, you can come down in the evening and still get some coffee, talk, and listen to good music."], ["Staying a few blocks down from the cafe in our Airbnb, we strolled down to the quite empty spot on an later Saturday morning. A little short-staffed but the food was excellent. Great hangry spot to bring turn the frown upside down and start the day off right.. just assuming you're gonna need it!"], ["Pros: cool vibe with lots of seating, amazing drinks if you get the right barista, and very tasty breakfast biscuit.\n\nCons: drinks are hit and miss. I've had the same drink prepared perfectly, and on other occasions, practically undrinkable. But biggest con is staff--they seem friendly enough with some patrons, but with others are downright surly. Yuck. I wouldn't come back if my study group didn't meet here!"], ["We went to the Christmas Eve brunch buffet. The food on the buffet seemed to have been sitting out for awhile and some was cold. The pancakes were tough. I got coffee, which I didn't like. It was really strong and tasted a little stale. They were open 9-2. We got there at 10. The service wasn't that great. I could tell the staff was trying, but there were no plates on the buffet and no syrup on the buffet. It would have helped to have sugar at the tables. We brought a toddler and had to do a bit of leg work asking for plates, syrup, water, cream, sugar, and they had filled my coffee to the brim before I put in cream and sugar. I wish they had asked us if we wanted water up front. We out to breakfast a lot and were surprised by the not great food and all the effort it took just to get our plates and drinks together and be able to sit down together."], ["Great breakfast spot! Nice that you order when you walk in & seat yourself & they bring the food to you. Breakfast potatoes are worth going for alone!!! So good! Breakfast hash was amazing & not to spicy."], ["Excellent. The food is always good.  Its not loud and for a meeting, its THE place.  The people that work there should get an award for being nice and never fake like they're just chatting you up. Love it."], ["I recently went to Edgehill for dinner for the first time and was welcomed with an updated, fresh, and welcoming atmosphere. The recent renovation made it feel very comfortable for a casual meal or dress up a bit for a nice dinner. The newly inspired dinner menu by a hot new Nashville chef in town did not disappoint! I had shark for the first time and it was cooked perfectly with a fabulous squash pur\u00e9e that had me wanting to lick my plate clean. Definitely opt for the side of brussel sprouts to share for the table. One of my favorites was the Kentucky Fall coffee drink at the end of my meal. I am eager to return for their updated brunch menu soon!"], ["Terrible service. My husband and I escaped an insane thunderstorm and decided to grab lunch here. They had very limited items (which was ok) and then when we sat down the staff approached us telling us they're going to close the restaurant and want us to take our food to-go and leave... into the torrential rain. It was awkward and terrible service. They didn't apologize or offer anything to make up for the major inconvenience. Right after he walks over to the window and closes the curtains while an entire family is sitting right beside that window. He was literally forcing everyone out. Very unwelcoming staff and very poor etiquette."], ["After much ado I tried this place out for lunch yesterday and ws extremely disappointed. I looked up the menu online before going and when I got there was made aware that it wasn't exactly the same. \n\nOn top of that we had the snottiest woman waiting on us. When my friend asked what sides they had she responded, \"I don't know, go look over there.\" We made several comments about how we hadn't been there before but she offered up no guidance. It was so rude. \n\nThe food wasn't bad, it's exactly what we ordered, but it took much longer than needed. I got the Turkey Panini, which comes with cheese, bacon, turkey on wheat bread. The bread itself was so hard it ripped up my mouth and I hurt for the rest of the day. I also think there was WAY too much turkey on it, or it wasn't cooked long enough because the outside was nice and warm and the inside was cold. \n\nNeedless to say, I won't be going back."], ["The atmosphere is modern and trendy but comfortable. The dining area is covered in modern furnature, but is still very functional. There are a variety of table sizes to meet multiple needs. Seems like a great place to meet friends for coffee, or bring a client to a neat lunch. \n\nMy sandwich (turkey pesto) was a perfect blend of flavors, however the kale salad was quite wilted. \n\nOverall, this is a place I would come again, and again, and again.."], ["Oh boy. It's become very apparent why the majority of Edgehills former regulars no longer frequent this place. Couldn't believe how the lady at the register spoke to each customer in line before me. Even the fellow employees behind her were shocked. I initially gave her sympathy as everyone has a rough day...until my buddy texted a group chat of industry friends and they all had a similar story to tell from a recent experience. \n\nAs an Edgehill Village resident I'm bummed to see what Edgehill Cafe has turned into. \n\nAs a result, go to The Jam Coffee shop instead."], ["We have done take out breakfast twice because they are so close, both times they got the order wrong. Food is average at best. Maybe lunch is better."], ["The food is alright, but the coffee is great. The problem is that, no matter how busy empty it is, it takes forever to get your food. It shouldn't take 30 minutes to make a couple of breakfast tacos."], ["The girl that works here looks like Jennifer Garner.  When I first came in I thought I was on some celebrity undercover show.  I'm serious.  After about 10 more trips to Edgehill I've come to accept that I'm not living in the Truman Show.  Even so, she's always been super nice and friendly, along with the rest of the staff.\n\nI usually order a tuna melt.  I'm a huge fan of the tuna melt and Edgehill is currently in my top 5 in the mini-city.  I also like that I get a pickle and chips with my order.  After making another failed attempt to order a vanilla italian soda, I'll usually end up with a soy chai latte. I keep hoping they will magically put it on their menu. So the soy chai latte has nice flavor and hits the spot.  My only qualm is I ended up spending like $13 on a sandwich and soy chai.  Ouchie.\n\nAs for the set-up I like EC a lot.  I can usually find a chair or table during lunch.  It's also never too busy or loud. I can read, enjoy the background music and unwind for 45 minutes.  It's definitely in my work lunchtime rotation."], ["Went into this cafe because of the \"good things\" I have heard. It's far from the truth. You go to a coffee shop for the experience. Anybody can make good coffee at home and I love going to a shop where the employees are friendly and the owners want to be there. This was not the case. The employees were very friendly however the manager on duty was very rude to both the employees and guests. She was dogging one employee in front of all the customers and her management style and skill if there is any was very lacking. As an industry manger and bar owner I want to sit down with this manager, I believe I heard people call her Sandy(?) her attitude makes me never want to step foot In that cafe again. DONT GO HERE. Employees were friendly but management was miserable and even gave us a dirty eye look like we were about to get talked down to"], ["I was looking forward to a nice breakfast at a local joint. What a disappointment at Edgehill Cafe. First, the menu on the website is not what you see on the chalkboard when you walk in. Only one omelet listed, and this was Sunday brunch. Secondly, you order and pay (and tip) before you even sit down. This is not your traditional server-based place. Food came out fast, probably because there were only about two tables seated in the entire place...not a good sign. Food was pretty good, but my sausage was colder than room temperature. Unfortunately, nobody came around to check how things were, nor offered to refill my coffee cup. Again, I guess it's not that kind of place.  My fault for hitting the 20% tip button as I ordered. I won't be back."], ["The area is very nice. Lots of places to sit inside with a couple tables outside as well. There is a nice variety of lattes, including a flight with three different flavors. Today, I only ordered a simple coffee but on my next visit I would like to try a latte. Also, they have an excellent turkey pesto sandwich which I would recommend without a doubt."], ["Easily one of my favorite places to catch up with a friend over coffee. \"The lovely\" is my idea of a wholesome, healthy breakfast (available all day)- a bowl of grits (carbs), veggies (spinach, tomato, red onions), protein (andouille sausage and an egg) and dairy (cheese)!"], ["I came here because they are so close, great location! I really like the concept of good food and good drinks (coffee, teas) plus the decoration makes you feel welcomed. However, there is something with the food that it doesn't make me completely love it. I ordered an egg white vegetable omelette and it had a lot of oil. They had Oolong, one of my favorite teas, that made them win a star."], ["I went on Saturday to check out the newly revamped Edgehill, and I loved it! I chose to have the Standard breakfast (eggs, toast, sausage or bacon, and haystack potatoes)...because who can beat a good plate full of those delicious things. I subbed the toast for a biscuit which was a little bit of an upcharge...but biscuits are my favorite. So naturally I had to check theirs out. When the plate came out, I stated \"holy cow!\" due to their portion sizes. My plate was huge. For $10 and delicious food, I was definitely not complaining. Looking around at other people's portions, I noticed that everything is pretty big. Again...a good thing to me! My friend had breakfast sandwich and hers was enjoyed as well. The staff was friendly and the booths were comfy. Business definitely started to pick up around 10:30 when there was a little bit of a wait, but I noticed tables were turned over quickly. Overall...a solid place for a lovely weekend brunch."], ["Liked the iced latte just fine. \n\nI'm not sure what's up with the mean girls behind the counter, though. Pretty sure there was a 3 against 1 something going on with them and it was really uncool. Also, except for the one that was getting pushed around, who was very nice to me and engaging while taking my order, the others were kinda lackadaisical and rolling their eyes at me. I KNOW I'M OLD AND UNCOOL NOW! I JUST WANT A COFFEE! Lord, you could cut the we're-cool-and-you're-not vibe with a knife. Look here you little snots, I was a young cool music biz college girl in Nashville too, once. Get over yourselves."], ["Edgehill (f.k.a. Edgehill Cafe) recently moved from the location now housing the J Crew men's store, a few doors down. We were bigger fans of the rustic/exposed brick/reclaimed barn wood look of the old location, but the new sleek contemporary look really is pretty nice. They've done a great job of activating a space that previously felt a little cave-like, and now have been able to expand into a full service establishment. It is busier (and louder) than ever!\n\nThe drinks have if anything improved, their latte is definitely one of the best in town. Also some of the special drinks are nice, try It's Always Fall Somewhere. \n\nThe only reason for four stars is that the food is pretty good but not outstanding. The shrimp and grits are a very good bet. The burger patty is not that great. The quinoa bowl is delicious, but the portion size seems a little small for the price."], ["Great coffee, delicious food, awesome service! It has quickly become one of our favorite places to go. The comfortable environment is great for work, studying, or just a good meal/hangout. Also, they have unsweetened almond milk which is somewhat rare in most of the local coffee shops in town. Overall, we highly recommend this quaint, locally owned cafe!"], ["If it weren't for the Frothy Monkey, this would be my favorite coffee spot in town. They have delicious food and exceptional coffee. A must go to place.\n\nYour first cup of coffee is free if you sign up on the iPad when you visit. They also send you texts redeemable for a free coffee every couple of weeks or so."], ["Love the food, love the atmosphere, love the staff!!  Best chicken salad in town, and my  all time favorite southern biscuit."], ["I've heard the food is great, but I haven't gotten to try it yet. I have had the coffee on multiple occasions, and it's good every time. The staff is really nice, and I love the atmosphere. It's a great place to get work done as well."], ["Loved the vibe here on a laid back sat about 10:30am and the food. Had the biscuit monte cristo n an earl grey latte - both were so tasty n loved the blueberry compote. Hubby had the waffle n said very good. Great neighborhood n a walk from our place. Came back sun am but they were closed. A bit of construction going on but u can't really tell from inside. Definitely on our goto list in Nashville future visits."], ["New manager could not be more rude. No wonder regulars have left and their old staff is gone."], ["They make a white-chocolate orange mocha that is to die for. Their regular brew coffee is just that - regular - and the food my friends and I have tried is the same. But the ambiance, the friendliness of the staff, and the delicious frou-frou coffee drinks makes it a great hangout and study spot."], ["Being a Nashville native I always find it hard to stray from my regular haunts. Thankfully I found Edgehill Cafe. I've been aquatinted with the establishment for some time now and I can honestly say I love their food. I usually get the breakfast biscuit add the swine but today it was lunchtime when I stopped by and I decided on the turkey and pesto panini. Delightful! Loved it but couldn't finish so I took the other half home. Just finished the other half and it was delicious cold! Took a test bite before the microwave annnnnnd it never made it to the microwave. The pesto soaked into the bread but it still crunched! Awesome. A tip of the hat to you all. You are definitely now on the list of haunts."], ["Ordered food at noon. Waited 55 minutes for two salads. Friend ordered House Salad, when it arrived it was spring mix, red onions, cucumbers. No cheese, bacon, tomatoes, pecans. When questioned, response was \"the chef changed it.\" Without asking the customer?? And to what....the only items we have prepped? Asked for the manager but was told she was in the kitchen.  Guess that sums it up. Obviously will never go back."], ["Let's be honest, there is not a huge difference in the coffee from one coffee shop to another.  Aside from the big chains almost all the local coffee shops in town offer a very good cup of joe.  So what makes a difference?  In my mind it is the setting.  A good coffee shop should be a place that you want to set up camp at and let a rainy day pass you by with a nice beverage and something to read.  \n\nThat is exactly what me and the wife did recently at Edgehill Cafe.  As soon as we entered we were very impressed.  The interior is a kind of rustic modern that is really inviting.  Great mix of steel, wood and concrete that really stands out.  The menu was fairly creative even though they were out of lox on the day we went so the wife had to go with her second choice quiche.  I got the Turkey, pear, brie sandwich.  Two large cups of coffee to wash it down.  Food came out quickly and the service was very good.  The coffee was really nice and balanced, good for both sipping and to match with food.  The food was not quite up to the same standard.  It was good, but nothing really stood out.  My wife was particularly disappointed with the quiche, which was completely overwhelmed by the turkey sausage and even though the crust was good was just kind of unsatisfying.  Overall probably a 2.5 for food, 3.5 for coffee.\n\nStill, even though the food did not knock our socks off the atmosphere more than made up for it.  The furniture is eclectic and genuinely beautiful.  In fact if you were to go over to the antique stores on 8th I imagine most of the furniture in Edgehill would go for more than a grand.  The vibe was relaxed and there is even a nice selection of photo and art books to enjoy.  We ended up getting refills and just watching the rain.  \n\nSo five star atmosphere with 3 star food and drink makes for a solid 4 stars.  I don't know if I will be back to eat, but Edgehill cafe is definitely on the shortlist for rainy day destinations."], ["There must be new management at Edgehill. Haven't been in a couple months and decided to work from there today. Not impressed with the new staff. Very loud and unprofessional. This place used to be busy and charming. I asked for\nAn americano with a splash of cream and she looked at me funny and said we don't do that. Hmmm. I won't be coming back. \u200d"], ["The place is very quaint and coffee is ok (could be better). Like the other yelpers says, the food and drinks are hit or miss, but we've been mostly lucky. Place is clean.\n\nIt's a nice quiet place in a quiet plaza to do your work and get stuffs done.\n\nAnd check out their complex' Door to the restroom. I love thick 5-inch metal doors :D"], ["I always go to Edgehill when I need to get work done. It has a very open seating area for a coffee shop and I am always able to find somewhere to sit which is nice. Parking is the only downside. Prices are pretty reasonable and when I'm not just getting coffee, I know I can always find something great on the menu!"], ["It's a nice dining area, but seriously understaffed on a Friday morning.  There were very few customers seated and perhaps ten people waiting in line with one barista/hostess/order taker.  We waited about 15 minutes to place an order.  Good food and ambience, but I need to find somewhere else to go."], ["Reading some of these reviews, we were a little hesitant to come here. I expected aloof staff, inability to find parking, poor wifi and a long wait for food.\n\nOur expectations were not met.  Visit ruined. \n\nI kid. \n\nIt was actually quite a pleasant visit. We were a little confused about how everything worked, so we didn't know you could sit down and a wait person would bring you menus. We ended up ordering our food at the counter and then sitting down in a booth. It all worked out. We got our food, and the counter guy even came by and checked on us to make sure everything worked out.  My husband got the chicken salad sandwich and I got the burger. Both were fresh, delicious and well presented. \n\nAfter our meal, we got coffee drinks (sweet ginger chai and cinnamon iced coffee). These were also delicious and well made. \n\nWe parked a bit away on the street. We didn't have to pay for parking. There was some construction in the building, but it didn't affect the quality of the food or coffee. I only mention it because I saw it on my way to the bathroom.\n\nI've been in some pretty pretentious coffee shops. This isn't one of them. All in all, a very enjoyable place to spend a few hours."], ["Overpriced and underwhelmed. I'm sure this is a common viewpoint, but ever since they moved, it's never been the same. customer service was questionable too. Biscuit was just okay...definitely not worth $3.50 with the liquid \"jam.\" Coffee was good. Best thing on the table. Breakfast burrito was lacking as well, could have used avocado or potatoes or something. All of this is consistent across all visits."], ["I have to do a quick update of Edgehill Cafe because after hosting several meetings here, this spot is definitely my favorite coffee shop/cafe in Nashville. Here's the Cliff Note's version:\n\nThe location is fairly central for most parties to meet\n\nI HEART the veggie & hummus sandwich ($6) which comes with a fairly large size bag of tater chips\n\nPrices are reasonable for coffee and other refreshments\n\nNot only is the interior spacious, but it offers up many nooks and a plethora of table/desk settings that can accommodate an afternoon of writing or host small or larger size meetings\n\nLove, love, love the furniture \n\nMusic playlist is a nice mixed bag of genres\n\nStaff has ALWAYS been sincerely nice and helpful\n\nIf I didn't call East Nashville my home, I would be that annoying girl who lives at the coffee house complete with loud phone conversations, laptop, and my Snuggie."], ["Meh. The place has a lot of potential. But the staff and food are lacking. \n\nThe hostess had no idea how long the wait would be. She finally found us a table and called us over before it was cleaned. She then cleaned it with a dirty rag.. and walked off. It was soaking wet -- then she placed our water cups rim-down onto the weird wet table... and left again. \n\nOur server replaced them eventually. He was really nice but seemed pretty busy. \n\nI had the chicken salad sandwich with a side kale salad. The chicken salad was tasteless. The bun was hard so I didn't eat it. The salad was actually pretty good but the kale could have been massaged a little more. \n\nWill we return? Probably not."], ["My favorite coffee shop in Nashville. Such nice people working there, great wifi, great coffee, great vibe. The only food I've had is the chocolate cherry gluten free muffin which was amazing.  Good for doing work, having meetings. Indoor and outdoor seating is good too. Highly recommend! \n\nParking is annoying, only 30 minutes in front, paid lot next door (which isn't cheap and I've had to run out to feed meters more than once), so try to find street parking, only please save a space for me :)"], ["We chose Edgehill because we had a large party, and in Nashville, places with reservations are rare. Should have had a clue when on a busy Friday night  there was no one else in the restaurant. The servers were all nice, but really not that good, it was almost like it was their first night in the job (maybe it was?). The menu was really limited--and very hipster-and pretty expensive, $27 for chicken and rice and we were told the chicken was a leg...  Anyway, ordered drinks, the moscato had turned, and they did not have another bottle, no diet soda, and they forgot to bring 2 of our drinks. We asked for the complete menu, which was basically breakfast food, and most of us ordered from there. The food was good, but mine and one others was cold when we got it. They completely missed one persons plate, so she shared with her husband. Needless to say, we won't be going back to Edgehill. Hopefully their breakfast is much better than their dinner, which must be where they get all the good reviews."], ["This is my third time at Edgehill Cafe. The first time was great, and I really enjoyed the hangover hash. The second time, We ordered three identical plates of food and one didn't come out until after the rest of us were finished. We were given no apology and they were visibly annoyed that we wanted it off our check. The third time, today, went smoothly- except for my hangover hash order. The hash did not contain the breakfast potatoes that I expected (maybe that was specified and I just overlooked it). However, the dish was pretty flavorless. The shredded potato was not pan fried at all- it was just warm shredded potato like you'd get out of a bag. Also, the amount of sausage and bacon was way less than the last couple of times I ordered it. I really want to like this place since it's really close to where I live, but the inconsistent food and subpar service make it hard."], ["I hate to downgrade a review but the new Edgehill cafe is struggling particularly in the service department. Even when they aren't full, it routinely takes 45 minutes or more to be served after ordering. Compare this to the much busier Fido, which almost always has food on the table in 15 minutes or less. The food remains tasty when it does arrive, but with a toddler in tow it becomes increasingly untenable to dine here...\n\n2018 Update: the lattes are great and relatedly, they sell the beans from Osa, acoffee roasters just around the corner.\n\n2019 Update: I have to say that their decline seems terminal. They've been closed for more than a month with no explanation - no sign on the door, no message on their webpage. It says on Yelp \"temporarily closed until February 19th\" but where does this info come from? One star until if and when they reopen at which point I'll reassess."], ["The quinoa bowl lacked flavor. I added chicken to it, which was quite dry. Great atmosphere and great service though."], ["Edge hill is a great place to go for brunch time except they have changed the menu so now they only have a breakfast buffet and only certain things you can order. This is like the third time they've changed their menu and atmosphere and I don't think it's helping them anymore. Coffee is really good here but a bit overpriced so be prepared for that. Also workers were not very kind once we first walked in which sets the whole tone of how the meal goes. All in all probably won't be coming back here."], ["I hate to downgrade a review but the new Edgehill cafe is struggling particularly in the service department. Even when they aren't full, it routinely takes 45 minutes or more to be served after ordering. Compare this to the much busier Fido, which almost always has food on the table in 15 minutes or less. The food remains tasty when it does arrive, but with a toddler in tow it becomes increasingly untenable to dine here..."], ["Wendy at Edgehill hosted a toy drive event yesterday for the Marines Toys For Tots charity. Two bands played and there were free gingerbread cookies and hot chocolate. Toys For Tots is a good annual Holiday toy charity drive where restaurants and other businesses can put a collection box out. It's good PR and it's good for kids in need. I enjoyed the music while dropping off a toy. Email Toys For Tots if you want a box next Christmas in your business. The kids will appreciate it."], ["The coffee tasted like Starbucks, and that is not a compliment.  I had just got out of a lunch downtown, and saw the place as I had passed by.  I'm an iced-coffee freak, so as I needed to find a place to hit the restroom pretty badly, I figured I'd stop there and grab a brew.\n\nThe coffee was very bitter.  Who wants that?  Two packets of splenda and one of Sweet & Low wasn't enough to overcome that.  \n\nThe layout was awkward, and the bathroom was very difficult to find, even with signs.  A Mac Mini was found, but when I asked about it, I was told they charged $7 per hour.  Yeah, that's a bargain.  It's not like the bandwidth isn't being used already.\n\nThe place might be a trendy place for the local gentry to see and be seen, but there's no reason to make the trip."], ["Arrived at 8:20am on Sunday September 18 and the doors were locked. No answer on the phone. Info on door, website, and phone all said \"open 7am, 7 days a week\". Major inconvenience."], ["I've never been here before, so can't say what this place used to be, but I really enjoyed the breakfast burrito they currently make. My fianc\u00e9's breakfast sandwich looked generic, but the burrito was very good and I would come back for it if I lived near by. It had a generous consistency that i believe people appreciate. \n\nWe were more impressed by the very well dressed customers that filled the restaurant. Not sure what that was about, maybe it's a southern thing, but everyone looked like they were dressed for church."], ["Trendy coffee shop located near Vanderbilt and Belmont. Great for business meetings!\n\nGood coffee options and decent breakfast variety. Parking is okay--street and a few spots in their private lot. I'm looking forward to going back for lunch, but I haven't made it just yet!"], ["So I always go to this cafe because it's so close to my work but I never get tired of it. There is always something new on the menu and today I got the Firebird. A grilled chicken sandwich with pepperjack cheese, bacon, Sriracha and spicy ranch. Holy moly. It's like my mind was blown! It makes me happy to know that I can continue to explore their menu and never be disappointed. My compliments to the chef. He knows what he's doing!"], ["Stopped in just to get a coffee to go, ordered the cold brew, I heard the cashier tell the barista to serve up a iced coffee, so I asked to make sure I was getting a cold brew, \"Is that a cold brew?\" And she said to me, \"What do you mean? They're the same thing - iced coffee and cold brew. It's the same,\" with a smug smirk and shrug. \n\nI'm surprised firstly they have coffee-serving employees that don't know the difference between iced coffee and cold brew and, secondly and more importantly, that they would tell me off for making sure I was getting the right order."], ["Superb off-the-beaten path brunch spot. No wait on the Sunday post NYE, a fabulous menu and super chill decor. I'm never a fan of the order-at-the-counter then sit with a number set-up but, alas, this is what you get here. C'est la vie. None the less, everything else is stellar. The food arrived promptly and was fantastic. I appreciated that they offered full bottles of chilled water to take to your table and that they artfully plated our meals (somehow good plating always makes delicious food taste even better). We didn't order coffee but the lattes we saw pass by looked superb too. We'll definitely be back."], ["I have been here quite a few times and have never been disappointed. I always have just gotten coffee until today. I finally ordered some food and I got the turkey pesto and a spinach salad. Talk about some flavor! For a coffee shop, this place is doing it right! Very please and well priced!"], ["Went here for breakfast on a Saturday; seemed to be a good mix of people eating breakfast or just drinking coffee and working. Decor was very cute and the space was clean and inviting.\n\nCoffee was good and hot; it seems like this is their specialty. Many people were stopping by for to-go coffee. \n\nThe food left a bit to be desired. I ordered the farmers omelet which was quite tasty. However I also ordered a side of house-made sausage; while the sausage had great taste, it came out cold. It seemed like it had been pulled out of the fridge and just barely seared on one side on the griddle. \n\nOverall our service was good, but I expect the server to come over soon after the food is delivered to ask how things are. By the time we flagged our server to the table it had been several minutes. He was gracious enough to put in a new order for sausage, but by the time it came out the omelet was cold. \n\nMy girlfriend ordered the standard with bacon. The bacon was extraordinarily salty and unevenly cooked. Additionally while I like the idea of the haystack potatoes, something a little more absorptive like hash browns or home fries would be better to pair with fried eggs in my opinion.\n\nIn summary, great place to get a coffee (or tea, I presume). The service was team-based and generally pretty good. Food preparation and execution needs significant improvement; I hope it comes because this location has a lot of potential."], ["Just have a great burger and really good coffee but the sweet potato fries were amazing. I'll be back."], ["Perfect little coffee shop/study space/hang-out for students, musicians, young professionals...anyone!  They have good items on the menu, though it's not very extensive.  I would be surprised if you couldn't find something you like because the variety is so great.  I had the turkey and pesto panini, and it was just the perfect lunch to hit the spot - and filling, which is sometimes hard when you're dealing with a small local shop like this.  \n\nFor coffee I had the 'black and tan' which was their take on a hazelnut coffee drink.  It was excellent.  I seem to be saying this a lot at coffees shops around Nashville, but Starbucks ain't got nothing on these drinks. \n\nAmbience is great:  good music (CD not live), though not too loud, and one table outside if the weather is good.  Not cramped inside, which is another thing that is hard to come by with coffee shops these days.  All in all, I HIGHLY RECOMMEND it."], ["This place is my jam. A great neighborhood cafe with tasty coffee specialty drinks, GREAT food and a cool, shabby chic vibe with mismatched furniture--how can you not love it? There are fresh baked goods available most of the day if you're just looking for a snack to go, but I highly recommend the sandwiches with a side of the spinach salad. SO good. Also, unlike other cafes that shut down Wi-Fi at certain times of day, Edgehill doesn't do that so you can always grab some Internet time here if you're looking to do a little work on the go. There's also outdoor seating for those pretty fall days."], ["Pros: great place to do work on the weekend; friendly staff; fairly accessible parking situation; the breakfast potatoes; the selection of hot and cold coffee and tea drinks\n\nCons: menu is being revamped, so no more of the red velvet pancakes; portions are small for what you pay; food is decidedly average; pretty sure one of my friends got food poisoning from her breakfast hash\n\nOverall: go, if only because it's one of the better cafes to camp out for hours at a time"], ["Dang. Good set of reviews on Yelp brought us here as our first stop in Nashville. It started off pretty decent -- a nice menu and semi-sentient young lady at the cash register. I often order iced coffee on hot days, and thus, as our six-block walk had generated a full-body glistening, iced coffee is what I ordered.\n\nThe problems began there as their iced coffee dispenser was empty. The young lady informed me she would bring me my drink as soon as they replaced the canister with a fresh one. \n\n15 minutes later, just as my companions were finishing their drinks, mine arrived. It's frustrating when something takes a long time, but if it's really good, it can often quell the annoyance. In this case, that did not happen.\n\nThe iced coffee was bitter to the point of tasting burnt. Not even a generous splashing of cream could cover the taste. Of the 16-ounce cup I would imagine 13 of those ounces found their way to a trash can.\n\nI'm not sure when my next visit to Nashville will be, but Edgehill Cafe won't be on the agenda."], ["So my dumbass showed up in yoga pants and a tank top because I didn't realize Edgehill had been completely remodeled and is now way fancy-pansy.  The food is still good...only place I actually enjoy a kale salad.  But I had to dock points because I miss the OLD Edgehill cafe and the ambiance of it being a hipster coffee shop.  Now they do serve alcohol, but there is a hostess and servers and hoopla.  Some things in Nashville should stay original"], ["This used to be one of my favorite places to visit when I come out to Nashville. I waited over 20 min for breakfast - poached eggs, turkey sausage, fruit and biscuit. The sausage was cold but was most concerning is the lack of care/service by most of the team. When I mentioned anything about the time for food the team seemed bothered by it. Which is why I did not mention anything else."], ["This place was gross. All of the tables were dirty, the floor was sticky, and I literally saw this employee pack up a customers leftover sandwich USING HER BARE HANDS. I couldn't believe my eyes. She was touching door handles, other items in the kitchen, used plates and cups, and so nonchalantly picked up the sandwich from this customers plate and put it in a to go box. I don't know what type of restaurant thinks this is ok. I would never in my life come back here."], ["Since the space has completely changed since my last review, I feel that it's only fair to write a new one!\n\nThe \"new\" Edgehill Cafe certainly has a different vibe.  Not necessarily bad, just different.  Whereas it used to be more of a coffee shop, now it's much more of a restaurant.  I'm not sure I would feel comfortable (or welcome) to hunker down with my laptop to do an hour of two or work.  That said, the menu is fantastic.  The food is tasty and not too overpriced.  Creative and yummy coffee and tea based drinks.  \n\nParking can still be an issue, but that's Nashville..."], ["Today....the \"Dirty Bird\" was my selection:  chicken breast, with pimento cheese and BBQ sauce!\n\nPlain and simple, this is a wonderful place to stop and relax, with a nice variety of sandwich selections and drinks.\n\nA comfortable atmosphere, too.\n\nI'll be back!!"], ["Bun-wearing counter dude: \"There's an upcharge for smoked salmon\"\nMe: Wait, doesn't lox mean smoked salmon?\nBWCD: Well, this is our interpretation of lox\nMe: You're kidding, right?\nBWCD: No. It's $3.00 extra\n\nOther counter dude: Okay, that's $17\nSteve: Can I order something?\nOCD: Sure!\nSteve: okay, I'd like (some breakfast thing) and an (boozy) Irish latte\nOCD: sure. Can I please see your ID?\n(Steve is grey, and very clearly over 50 years old)\nMe: Are you kidding?\nOCD: No, we check everybody - just to be sure.\n\nOn the upside, people seem to think this place is hip."], ["Very cool atmosphere and the espresso was tasting nice despite the fact it was 6 pm. Food was a little pricy but totally worth the cost. Delicious, especially the potato small plate with mush"], ["I hate to downgrade a review but the new Edgehill cafe is struggling particularly in the service department. Even when they aren't full, it routinely takes 45 minutes or more to be served after ordering. Compare this to the much busier Fido, which almost always has food on the table in 15 minutes or less. The food remains tasty when it does arrive, but with a toddler in tow it becomes increasingly untenable to dine here...\n\n2018 Update: the lattes are great and relatedly, they sell the beans from Osa, a new coffee roaster just around the corner."], ["Was a recommendation from a friend. Once inside it was extremely clean and the staff was amazing. Ordered the hangover hash, with a fresh brewed Latte... So amazing. Excellent experience and will totally be recommending this place to friends and family."], ["Edgehill randomly decides to be closed or close early, and it can be really frustrating given it's one of the only coffee shops in that area. Also it's too expensive for what you get."], ["3.5\n\nThere's a lot to like about Edgehill Cafe. The vibe here is extremely comfortable and fits the neighborhood to a T. Parking directly in front may be a challenge but there, typically, is decent enough parking nearby. The space is larger than it appears at first glance, with the dining room curving around to make an 'L' shape. There is plenty of seating, with long and short tables equally dotted throughout the space. The chairs vary in shape, size and feel as well. With fast wifi at the ready, EC is an easy and accessible place for surfing the internet or having a meeting with co-workers.\n\nBeing the (recovering?) fatty that I am, I couldn't resist the chocolate chip coffee cake. Ridiculous. Cinnamon. Chocolate. Light cake without being greasy. So wonderfully good. This a perfect coffee shop baked good. Delicious on its own, coupled with coffee, it's a home run. Where I erred was in my coffee selection. I didn't care for it. Unlike what I do with ethnic food (order my go-to to see how I enjoy the quality of the particular restaurant), I usually order the seasonal special at coffee shops. This time 'round, I got the leaf latte -- with bourbon & maple. True to its name, the beverage was entirely too woodsy for me. I didn't care for it at all and couldn't finish the drink. I like walking through the woods. Tasting it, not so much. My colleagues were smitten with their choices so the drink fail is entirely on me. I'd come back to get it right any time. But, upon my next visit, I'll stick with one of their classics."], ["Went for a business lunch while in Nashville and had a very good meal. Things have changed so much since I lived there and this is certainly one of the places I hope has staying power!"], ["This was my first time at Edgehill Cafe and I was there for a Yelp event.  I enjoyed the there and I will definitely come back when I'm in the area.  I really enjoyed the comfortable vibe and it's definitely a place to hangout!"], ["More of my income goes to coffee and food at Edgehill than goes to rent. That being said I spend enough time here I should probably just forgo the rent and move in to this great little cafe. \n\nThe cashiers are always friendly, everything from their baked good to their soup to the grilled cheese has been consistent and just downright good. There is a lot of seating, free wifi, and good people watching if you need a distraction from your work. It's a bit noisy so I wouldn't choose to come here if you're trying to get work done in a quiet space. \n\nMake sure to checkin on the iPad near the cashier and you can get free coffee, its like a virtual punch card. This place is pretty pricey in terms of coffee but the plain coffee is great and their specialty drinks are even better. \n\nI am lucky enough to be able to walk to Edgehill Cafe but I can imagine the parking would be a real pain in the rear otherwise. There is street parking if you can find it otherwise you have to park in a paid lot."], ["I think I prefer the previous decor to the recently renovated one. Food and drinks here are pretty solid. I usually will order a coffee and set up at a table to do some work for a few hours, and I appreciate the more quiet atmosphere. Service here is very attentive and friendly for the most part. I do feel like they don't want customers in the cafe for too long--I was constantly asked whether I wanted something or needed something, to the point where I kept ordering food just to appease them a bit. Made for a somewhat stressful environment. \n\nParking in front of the cafe is terrible--only a few spots and a very awkward angle for turning, so you're usually better off finding street parking on the nearby blocks. \n\nWith so many cafe options in Nashville, I'll need to keep looking for a reliable coffee/study place. So far, Frothy Monkey tops the list."], ["Man, Edgehill used to be the spot before J. Crew took their location. What happened to my turkey pesto panini?I'm so lost without it.\n\nJust had the Sunday brunch buffet. Both my lady and I are not impressed. As I sit here looking at my powdered eggs and thin bacon, the best part of this meal is the fruit and yogurt.\n\nEdgehill used to be spot on and now they're a hit or miss. Fido has taken its place. No longer will I be held down by the adventurous decision to \"switch it up\" with my damsel on a Sunday morning.\n\nWhere is my turkey pesto panini? You've changed, Edgehill. You've changed."], ["Amazing place great food. Super cool vibe! I will be going back to this place. There is a pretty wide variety of foods."], ["Went today for brunch with my wife. I had the Farmers Burrito, she had the grits, and both were excellent. Good prices, great food, and a great ambiance. An ideal combination of quality, value, and convenience in a hip yet comfortable space."], ["My friends and I came here to study for final exams on a Saturday morning. We came early enough that we didn't have to wait for seats but it definitely got busy around 10am. We were here 'til around 1pm and the staff was super friendly, always attentive to whether or not we needed anything and clearly patient with us. I ordered the breakfast tacos, which I absolutely loved! The stringed potatoes were super crunchy and tasted great too!"], ["I love coffee shops.  I'm addicted to coffee shops.  Not coffee, just the shops!  There's something wonderful about sitting amongst fellow coffee-lovers, watching people's eyes go from decaf to double shot in 3.0 seconds, and enjoying some indie music whilst pretending to do work.  I love the reclaimed wood, the exposed brick, the cool tables, the eclectic decor, and the coffee-snob vibe you get when you walk into one of these rockin' shops.\n\nEdgehill Cafe just does not disappoint.  Their decor is uber indie, their staff is super friendly and helpful, and their food is actually pretty darn tasty!  I love a good curry chicken salad, and I love it even more when you cut up grapes and throw it into the mix.  Oh, and the iced coffee??  Yes, please!\n\nI'm not terribly fond of the bread, which always looks just a little softer than it tastes.  Also, the noise does get a little out of hand sometimes, which can be frustrating when I actually AM doing work.  Not that I can complain - it's no secret that this place is great!  But if you're looking to grab a coffee and read a leisurely book, you can't go wrong here!"], ["Quite an excellent option for breakfast and brunch in the area. We came late Sunday morning and there wasn't really any wait. I got the breakfast hash and would definitely recommend it!"], ["Man oh man!! I am in love with Edgehill Cafe!\nIt beats anything Starbucks could think of and the atmosphere is SO cool:) I just had their Turkey Pesto and let me tell you what...it BLEW MY MIND!! Staff was spot on and the food complimented the great vibe! They have made a regular out of me!! Awesome place:)"], ["I used to really love Edgehill. I went here several times last year and enjoyed the atmosphere, food, and coffee. However, there must be new management or something. It has gone completely downhill. The staff was incredibly rude (a.k.a. closing 30 minutes early and basically running us out of the restaurant), the food took forever and was served in to go containers instead of actual plates, and it's very expensive for extremely sub par food. Service was incredibly disappointing. We were pressured to leave and it was just an overall horrible experience. If you're looking for a great brunch and coffee I would recommend The Jam and Red Bicycle."], ["Food was pretty good, but service was slow. Also, they were out of shrimp so I couldn't get shrimp and grits. Also out of butter. How does a breakfast place not have butter? Send an employee to the store to go get some!"], ["This is a review I wrote last Friday:\n\nSo it's Friday. One more link in a long, winding tail of penultimates. Today I'm at Edgehill Cafe. Normally I'm less inclined to come here because the little mall they're in just opened a pay lot, but I was lucky enough to find an open spot on the street.\n\nIt's louder than normal today. Lots of handshakes and first impressions and enthusiastic conversations. Used coffee stirrers strewn about on tables like little bloody swords. One guy is studying; there's a business meeting at my 2 o'clock. Dollars and words and hopes and caffeine all slosh together to the rhythm of the folksy tunes coming from the inconspicuous speakers on the walls.\n\nThe coffee is good. Nothing fancy, but rich and smooth enough to set it apart and make me get it again. There's a wide assortment of organic teas and drinks, as well as a decent sized food menu.\n\nThe crowd is split. Half have Macs, half have PCs. [I rest firmly and confidently with the former and our silent solidarity is utterly beautiful. Stand strong, my friends.]\n\nNo sitting area is the same. I love this. The decor and furniture are as eclectic as the clientele. I'm in an old patio-looking chair with aged, ruggedly chipped orange paint and a stained white cushion. There's an urban style wooden bar by the window with stools and lamps above. A long dining room table with ornate wood and leather chairs commands the middle of the room, balanced by a three-sided nook in the back corner with pillows and privacy. It's basically one big room, as inviting as it is boisterous and as simple as it is dynamic.\n\nBut what keeps me coming back is the atmosphere it fosters. It's not hyper cluttered or Manhattan-like busy like some shops, so I never feel rushed or like people are breathing down my neck to get up outta her' (except for the two hour street parking). That, to me, is much more important than the coffee. And the barista taught me how to properly say \"Au Lait\". What a sweetheart.\n\nIt's becoming one of my favorite coffee shops, and you should definitely check it out."], ["Let me rate this in portions.  I have been to Edgehill for a 5 star event and it was 5 stars minus the air conditioning.\n\nAdditionally I have been here at various other times and it was ok, but nothing super special.\n\nThe last time I was there I was pretty much stranded for 2 hours with a book and the internet on my phone.  I got a house coffee and a muffin and sat down in an uncrowded place, could barely connect to their router so 3g'd it (aww yeah) and tried to soak up the AC and watch the people who came in.\n\nMy plans were interrupted by removing a rather long hair from the muffin, or perhaps the muffin's saran-wrap wrapper, I was unsure where it came from exactly and although worth mentioning to look out form it's not worth mentioning to freak out about.  The coffee was pretty good, no hints of burning or staleness, basically it was exactly what a house coffee should have been.\n\nI became fascinated at the crowd that came in, it appeared as though everyone was walking off of a tv show, an odd put-together look that made me wonder I was on a hidden-camera bit.  In shorts and a t-shirt, recently shaven and with my hair combed reading a book I was the slovenliest looking person there.\n\nThe entire time I was there other than the people ordering I don't think I heard a peep from anyone. Saddened me a bit as it's always been my belief that a coffee shop should be thoroughly annoying in that aspect.\n\nThat visit was a 3 star visit.\n\nIt's definitely a place I'll head back to although I think I need to find the days and times when it's not a fresh-out-of-wardrobe day.  It was nice people watching, will give it that."], ["My new morning spot in Nashville!  Fun atmosphere, friendly staff and good food/coffee!!\n\nLooking forward to visiting their new location (a couple of doors down the street).  Hope the ambiance is a inviting as this one!\n\nGreat for study groups, 1:1 meetings and even a solo breakfast, as I had!  Standard breakfast meal was yummy and the biscuit was HUGE!  \n\nLooking forward to my next visit!"], ["Today on Edgehill's special board: raw biscuits with gravy. Also sent my niece's raw biscuit back 3 times and it was raw inside all 3 times. Not to mention it was extremely cold. None of us ate our breakfast and none of us got a refund or at the very least-an apology. I used to love it here but I don't love the chance of my 5 year old niece getting salmonella because they don't know how to make a biscuit at a breakfast cafe."], ["I'm still sort of new in town, so we're always looking for a good go-to spot for, well, pretty much everything. I had an errand up in Edgehill and was looking for a breakfast/brunch spot nearby. Thank you Yelp!!! This spot is practically next door to where I needed to be, and it hit the spot perfectly. \nI'm a brunch addict. I've been searching for an innovative yet traditional spot and the Edgehill Cafe is it. \nTraditional favorites take on recognizable twists at this funky, totally hipster spot. Order at the counter from the big chalkboard menu, get your number and find a spot. There's a few seats at the coffee bar, a large family-style table in the middle, a larger booths and several 2-tops that appear to be custom made for \"working\" meals (read: all were taken by Apple laptop users). \nLogistics: extremely limited free parking, paid parking nearby. Bathrooms in the offices out the back of the restaurant. \nVerdict: delicious food, quick service, loud environment, reasonable prices. I'll be back y'all."], ["Went in to try Edgehill Cafe.  Glad I did.  New menu, new chef , new atmosphere and delicious food !!\nI had the Lamb burger with Kale salad. Outstanding,  the burger was cooked perfect , nice flavor .  The salad was fresh and delicate,  glad I came in, I'll be back........"], ["This is the independent coffee shop/cafe Nashville has needed for a while. This is a great place to read, write, work, or catch up, not just pretend. The atmosphere makes it a great place to unwind during lunch or after a hard day. There's plenty of personal space and a bunch of places to plug in laptops, yet it feels cozy. The noise level is low enough that you won't feel compelled to crank up some headphones, but it's still alive inside.\n\nOh and the coffees are great local roasts and the sandwiches are tasty. I've had the turkey and the roast beef paninis. There are a few sandwich options nearby that come with  enough salt to give you kidney stones. None of that frozen then microwaved salty sauce stuff here. Although I haven't yet had one, the salads look amazing. Prices are competitive.\n\nThere's an always full parking in the front with an apparently unenforced 30 minute limit - I've never seen anyone actually leave the lot. You'll be better off parking in the street nearby. I've never had to park more than a block away, but your mileage may vary."], ["Why aren't there any coffee shops like this in NYC? Perhaps it's the issue with space limitations? Or the cost per square foot being so crazy, local mom 'n pop coffee shops need to turn cover after cover just to make a small profit? Whatever it is, sprawling wifi caf\u00e9s with a hip vibe and baristas who encourage you to open your laptop and stay awhile are rare birds where I live, so it was a nice change of pace to burn a few hours here. \n\nThe scene is friendly and inviting, there are several tables, couches, and arm chairs, many outlets to keep your battery strong, and a diversified menu of food and beverage options. Whether you favor veg or carnivorous eats, or you prefer tea to coffee (or vice versa), you'll find something for you.\n\nThey close pretty early, but it seems like most businesses have at least a couple days per week where they shut down shop midday. Maybe it's a southern thing? Either way, I'm a fan."], ["The space here is A-AMAZING. Huge long wooden tables, smaller tables for two or three, individual-sized tables for the study-aholics, comfy sofa-like chairs for lounging and curling up to a novel, bar seating--they've got every kind of seating imaginable.  And, I love that there is actually walking space between the seating--a design technique which most Nashville cafes have ignored. That means you can actually focus on what you are doing at your table and not be distracted by the next-door conversation. Tough concept, I know.\n\nService was friendly and quick, also.  But, I was super disappointed with the coffee I ordered. It was painful for me to finish drinking it. Slightly better than Starbucks--at least it wasn't burnt. But, really didn't taste like what I was hoping. Also, they only offer 1/2-and-1/2 at the self-serve counter.  I would have expected at least a skim milk option, if not a soy milk option as well. The selection of teas looked pretty promising though, so maybe I'll come back and try the tea or espresso options.  My taste buds were just not satisfied with the coffee at all.\n\nParking here also confuses me. The parking lot directly outside the cafe is for only 30 minutes. Who goes to a coffee shop for only 30 minutes? And the \"upper-level\" parking on a hill for two hours just didn't seem like a bright idea when I tried to turn up the gravel parking lot and some car was trying to back down it at the same time.  The parallel parking right across the street is also only for 2 hours which is a little annoying when I like to literally camp-out at cafes to get some studying done."], ["All I had was the Lovely grits and that combo of fresh spinach, tomatoes, cheese and PERFECTLY COOKED grits was terrific."], ["First of all, I was charged $2.75 for a glass of iced tea, and another $.91 for a refill. Who does that?! If that isn't enough, the food is just mediocre, at best. The first time I went I had a club sandwich with meat that seemed right out of the plastic container from the grocery store. This time I had breakfast for lunch. The eggs were very runny and the toast was cold, but the bacon was delicious. The breakfast potatoes had NO seasoning or flavor at all. Not impressed. Clearly Edgehill cafe does not respect their patrons if they are willing to charge  $2.75 for a small glass of tea and another $.91 for a refill, so I see no reason to ever return to this place."], ["I'm a freelancer with a home office. Every once in awhile, I'll be sitting at my computer typing away when it hits me...\n\nMUST HAVE COFFEE... with a hint of vanilla... a dash of cinnamon... swirled with honey.\n\nAnd then I lace up my shoes and am out the door with my laptop to work at Edgehill Cafe whilst drinking a fabulous beverage aptly titled It's Always Fall Somewhere.\n\nBLISS."], ["My husband and I just went in to kill time for a bit and got 2 americanos. They were as good as an americano can get. But what impressed me the most about this place is the ambiance. It's quite spacey, lots of tables, chairs, & couches. It's a place where you feel comfortable being in. There were a few people on laptops, others just chatting with friends. It's definitely a good place to get some work done or just hang out for a while. There's free wifi. Parking in front has a 30-minute limit. Next time I'd like to try their other drinks!"], ["Went there yesterday for a Yelp sponsored event, so not sure if it is a good representative of the actual experience. But nice kitchy-trendy atmosphere. Food and wine was good (though I think its just a coffee and sandwhich shop). Would be interested to go back as a regular customer to get a better feel for how they are."], ["Overall, I really love coming to Edgehill. The baristas are consistently so friendly and their customer service is fantastic. However, the person I believe to be the manager there in extremely abrasive and is constantly bullying the baristas in front of customers. It's really awkward and uncomfortable to watch and listen to. I've also heard her speak to customers in a very harsh, rude tone while ordering or for sitting a certain way on the furniture trying to make themselves comfortable while they're working. The days that she is there I feel like the energy is noticeably more negative and uncomfortable. It seems like the Cafe is going through a lot of changes and transitions so I'm hopeful once things are in a flow, that the energy will be better."]], 
            "review_rating": 3.61
        },
        {
            "business_id": "e86IBzGCsrnhJbD_wELj7w", 
            "name": "Herbie's Vintage 72", 
            "address": "405 N Euclid Ave", 
            "city": "Saint Louis", 
            "state": "MO", 
            "postal_code": "63108", 
            "latitude": 38.6488432, 
            "longitude": -90.2610791, 
            "stars": 3.5, 
            "review_count": 141, 
            "is_open": 0, 
            "categories": "Gluten-Free, French, Wine Bars, Restaurants, Nightlife, Bars, American (New)", 
            "hours": {"Monday": "16:0-1:0", "Tuesday": "16:0-1:0", "Wednesday": "16:0-1:0", "Thursday": "16:0-1:0", "Friday": "16:0-1:0", "Saturday": "17:0-1:0", "Sunday": "17:0-22:0"}, 
            "text": [["I really think Herbie's is more in the 3.5 stars range, and it could be bumped up to 4 after we try out their brunch (heard it's amazing!) or some of their cocktails that other reviewers raved about.\n\nNot sure if this place is ever crowded, but it certainly was fairly empty on a Wednesday night, so we were seated immediately.  I love sitting in the patio area with the view of Euclid.\n\nFood:\n1) Corn Chowder (special) - heard it was pretty good.\n2) Ligurian Shrimp Pasta - nice and fresh.  It def had a spicy kick to it, but not so much that someone like me who can't handle spiciness was able to enjoy a few bites.  Shrimp was cooked perfectly and were pretty large.\n3) Lobster Mac & Cheese (special) - pretty good.  Not swamped in cheese, though it lacked a little flavor (nothing some salt didn't fix).  Pretty big pieces of lobster."], ["What can I say, Herbie's has provided another wonderful Happy Hour for me and my friends. We had great food and wonderful service. Our waitress was attentive, knowledgable and gave wonderful advice on cocktails.I had the seasonal heirloom caprese salad and a taste of flatbread with chicken, spinach and jalapenos. They were both absolutely amazing. It is a bit pricey so if you want to go the budget route this place is not for you."], ["Excellent food and service. I had a Salmon and my friends a Burger. Sloan was our waitress and advised us from beers, wine all the way to our full meal. There was a two piece band that was a nice addition. This is a must for anyone. \nBonnie from San Diego"], ["After reading reviews we headed for Herbie's for brunch yesterday. 'Sorry to say it was a big disappointment. We waited  15 minutes to place a drink order and it took another 20 minutes for the drinks to arrive. They must have driven to the brewery to get that Bud Light. A Bloody Mary can't possibly take that long to make, can it? Our food was good but lukewarm.  Eggs Benedict just taste better when they are hot.  We won't be back."], ["Perhaps we'll visit again, perhaps the star count will rise.  The food was some of the best I've had in the city.  I requested a substitute on one dish and the server came back, saying the chef would prepare it but really advised against it since the flavors wouldn't meld well.  I appreciated that honesty and went for a chimichura steak special that was phenomenal with slow-roasted sweet potatoes and greens.  This is the stuff of dreams!  My husband enjoyed the tuna dish with a wasabi rissoto cake -- such unique flavors paired SO well together.  My tongue was on cloud nine (guess that's not entirely possible but you know what I mean).\nSo why the 3 stars?  Well, we showed up and were immediately seated in the patio bistro section when it seemed like there was seating inside where live music was playing.  This was our first visit so we weren't sure how it all \"worked\" and left figuring we were \"profiled\" for the more casual bistro since we were wearing jeans.  We would have preferred to sit inside and enjoy the live music but the host didn't bother asking us our preference."], ["The owner of this restaurant-- Aaron Teitelbaum-- essentially accused me of lying about whether a zuchinni-potato pancake had been included with my entree. It had not and I had no reason to lie about it. The four of us spent well over $300-- are you serious? Food was OK otherwise, but the owner embarrassed me and almost spoiled the night."], ["Excellent food and service.  Very romantic, vintage, sultry--and it feels like I've been swept away into a decade from a very long time ago.  Filet mignon and scallops are superb.  I've dined here 3 times and have had an excellent experience each time!"], ["Great experience here! It was a couple weeks ago so I actually can't remember what I ate (whoops), but I know at the time I really enjoyed it as well as the ambiance."], ["Herbie's reminds me of the old school way to do cocktails. The interior is moody and upscale but not unapproachable. Menu and cocktails are a tad pricey but worth it. Happy hour lasts until 6:30pm. Wine selection is very good and beer choices are decent. \n\nYou never know who you will run into at Herbie's on any given night. I like that it is located at the other end of the Euclid strip but it's still walking distance to hot spots like Sub Zero and Drunken Fish. It's an easy place to meet people for drinks and valet makes it appealing when parking is at a premium. Overall, I adore Herbie's and frequent it very often."], ["Best restaurant on the block, period!\nAmazing fresh oysters and fantastic daily specials. Drinks are reasonably priced too! Hospitality is second to none in the CWE."], ["Had dinner last night in the Bistro, started with the seasonal morel pasta-outstanding!!!!  Next, I had the field green salad, it was fresh and came out with just the right amount of dressing.  For my entree I chose the Osso Buco which was a pork shank that melted in my mouth.  Other choices from our group included the Duck special, Scallops, Bison Burger and the entree sized morel pasta.  We selected Frei Brothers Cabernet that was a bargain at $40.  For desert we had a chocolate mouse that was terrific.  Even though the Restaurant was very crowded because of a Graduation at a nearby College, our server was very attentive to our group of six.  Everyone  in our party were very impressed.  The chef stopped by our table to make sure our meal was as ordered and prepared to our liking.  Overall a terrific evening."], ["Food gets 5 stars! However, the service by our waiter was only a 3, and that's because we saw him only 3 times.  The busser was much more attentive to our needs, so we gave him a portion of the server's tip.  I will go back because the food was great!  It was a Saturday for brunch. Everyone at our table tried something different--drop biscuits (3) served with jam and gravy, skillet, veggie Benedict, and breakfast Reuben.  The Bloody Mary bar included just about every ingredient you could need."], ["Food was okay at best.\nWaiter was Missing most of the time.\nDessert was disgusting.\nBar/Drinks are fun and hopping."], ["Home run. Appetizers were great (esp pasta w walnut pesto), and main courses were perfection. Sea bass, lamb and lobster were great. Aaron Teitelbaum is the SHIZZLE. We'll be back...soon!"], ["My boyfriend and I had dinner here last night. We each called once before arriving and the hostesses we spoke to on the phone were both very polite and informative.\n\nWe arrived at 8:00 for a reservation in the bar area. The host seated us promptly and was very nice. HOWEVER, we were sat at the smallest, crappiest table in the bar. It was 8:00 and we had a reservation. The bar area was empty besides us. It would have been polite to give us a nice table. Slight damper on the dinner.\n\nOur waitress arrived promptly and was nice and knowledgeable. Her name was Tara, I believe. She was professional, prompt and checked on us just enough. Our glasses were never empty and we never had dirty plates on our table for long. ( Our bus person was very efficient as well.)  \n\nI had a glass of a red blend & several glasses of Rombauer Chardonnay. The glassware was nice and the pours were decent, both were delicious. \n\nMy boyfriend enjoyed the IPA on draft and it was perfect.\n\nAs appetizers, we shared the Carpaccio - so so yummy. The fennel salad was so perfect as a garnish! Also, the spinach and artichoke dip, yum! Could be served with a little more bread based on how much dip there was. ( Our wonderful server did off us more when she saw how much we had left but we took it home.) \n\nWe shared the french onion soup and it was pretty good.\n\nI ordered the filet with a mushroom risotto instead of mashed potatoes. The spinach was delicious, the risotto was cooked perfectly and was absolutely delicious! My filet was cooked perfectly and totally melt in your mouth, topped with the most delicious mushroom sauce.\n\nThe steak & frites was awesome as well. \n\nMy cucumber & lemonade martinis were PHENOMENAL! Good job, bartender! Even a garnish of a slice of cucumber.\n\nWe enjoyed a bread pudding & the chocolate fritters a la mode for dessert. Absolutely delicious!!! The chocolate fritters are seriously, heavenly. \n\nEspresso martini was pretty good.\n\nThe live music was a perfect touch. The cougars were slightly creepy but other than that it was a perfect evening.\n\nDon't go if you don't want to touch your wallet. Our check was $203 for the two of us. But, well worth it."], ["The main course was actually very tasty and the starters that we got were not bad.  My big issues were that the dessert was meh, and the service was indifferent at best.  The waiter never came to check on us when we got our meal, never noticed that one of the starters we ordered from him never arrived, and while we waited forever for the food and dessert to arrive, he never came over to check on us or give us a status update. However, all of that could have been forgiven if when ask, what the \"bread pudding cheesecake\" dessert was all about, he hadn't said, \"I have no idea\" and left it at that.  Not, I'll go check, or let me see, just \"you've got me.\"  Also, for those of you who want to dine here, skip the bread pudding cheesecake, it's very disappointing...bread pudding on Maraschino cherries with cream cheese drizzle on top, talk about a confused dessert."], ["Before this Saturdays showing of Buddy Holly at the Muny 3 friends and I had reservations at Herbies.  We went there last year and I don't remember anything special except it was a bit pricy.   This time my guest and I ordered a tomato pasta special they had.  I had water to drink and he had a coke.  The pasta was fine, something I'd make at home.  It did give me a bad case of heart burn though.  The description of that special wasn't quite right.  Our bill was $71, tip it was $90.  Two bowls of pasta, 1 coke, $90.  The waiting staff was great.  I won't be back though, that's ridiculous."], ["We went for Sunday brunch and were not disappointed. We tried the Herbie's burger (after seeing it served to a table next to us) and the smoked turkey reuben. The burger was one of the better that I have had in the St. Louis area and the reuben was a delicious twist on a classic. Their fries are excellent and the biscuits and gravy are also great. We will definitely go back again."], ["The food is very good and the service is great. It is a little pricey, but worth it for the upscale environment."], ["Sunday morning we were treated to a post wedding brunch at Herbie's.  We arrived right at 10 and were quickly ushered into the reserved room.\n\nThe first thing I noticed about Herbie's was the vibe of the interior.  Pretty cool old wrap around bar that looked pretty nice.  It looked like a pretty cool place to grab a drink and it looked like they had some good beers on tap...but I digress.\n\nThe area that was reserved was very nice and accommodated our group perfectly.  \n\nI went with the cast iron fritata which was great.  It was loaded with ham, onions, Cheddar cheese and roasted red peppers.  It also came with potatoes and toast.  It was a great dish.\n\nHowever, my better half got the morning flat bread and it was amazing.  Eggs, cheese, spinach and tomatoes covered the flatbread from edge to edge.  Really awesome.\n\nAll in all, it was a great experience.  They were a little light on the wait staff but not horrible."], ["Celebrated Father's Day here today. The service was VERY lackluster. Our server did very little to check on us during the course of our time there. When part of my order was missing & I asked him about it, he didn't make any apologies. He just kind of said \"oh\", walked away to get it and came back. I ordered the French Toast. Very disappointing! The menu indicates it's served with a House Topping. The topping is maple syrup. It is served on a cast iron skillet and is a single piece of Brioche bread. It was extremely hot for around 10 minutes meaning I was watching everyone else eat while I waited for mine to cool off. There was really no flavor to the meal. From the meal to the service, I can't find a reason to go back. And what sealed the deal walking out was the hostess who just stared at us go out the door saying nothing audible even after I told her to have a good rest of her day."], ["We dined here for Christmas Eve with friends. Admittedly, it was not our first choice but the menu looked inviting enough and we've only walked past Herbie's a dozen times over the years on the way into Dressels. Nevertheless, when popping over to Yelp that morning to confirm we made the right choice, I had my doubts. Happy to report they personally were unfounded.\n\nI cannot speak negatively for the clientele or service at the bar, seeing as it was flawless for us on this particular night. A handful of regulars and a very helpful bartender. The Tom Collins was poured right and I was even offered my choice of Gin (not common at your average low-end bar).\n\nWe were seated promptly under a dimly lit table and the server spat out a mouthful of specials (really, how do you guys do that?) We asked lots of questions and found our server attentive, helpful and funny to boot. I mean he was working on Xmas eve. Good service. We ordered a Malbec and the firecracker shrimp and Carpaccio. Yes, yes, the carpaccio is not out of this world but it was not inedible. Tasty even.  The raspberry duck, yellow-fin tuna and the special of the night, rabbit pasta completed the table. I felt guilty at first about that rabbit but let me tell you, it was as good as it was advertised. Very tender, excellent pasta and the duck was very well cooked. All in all the meal was well received.\n\nJudging by the reviews it seems that this is another place where your mileage may vary. If for the food only, give it another try. It wasn't the best meal on earth, or in town, but the staff and the cooks, at least on this night, did not disappoint."], ["Wow.... What a gem!! This place lured me in just from the wonderful ambiance! Not only did I fall in love with the atmosphere but Every single thing we had was amazing!! For apps, the sweet corn risotto was 1 of the best things I have ever had! Then the classic flatbread was sooo good!! French onion soup was very good! We also had lobster with the filet, the steak was actually better than the lobster! The lobster Mac n cheese was good, but just as a side.... U wouldn't want to do that as a meal. Can't wait to try more from this fabulous restaurant!"], ["Went for Sunday brunch, it took an hour and a half for them to bring us our food after we ordered. I had the stuffed french toast of the day, and it was probably the worst french toast I've ever had. There was no taste to it at all, and after a few bites the cream cheese stuffing made me feel sick and I couldn't eat anything else. Everyone else who tried the french toast agreed. Also I ordered poached eggs as a side, and they came in a ramekin basically drowned in vinegar. Really wanted to like the place but they were such a disappointment.. Not going there again. It was terrible!"], ["I got about 5 bites of meat and a sh*t load of mashed potatoes on the side. Nice atmosphere, kinda pricey, not a lot of food in my opinion for the price. Probably won't go back here. The food was delicious however. I had the baked chicken entree."], ["Bottom line: fantastic food and service.  We had a large group - almost 40 people and the service was excellent.  Food was delivered promptly and at the correct temperature. The tuna was phenomenal and was cooked to perfection. A couple people in our party were either gluten free or vegan.  The owner came out and spoke to each to determine their dietary requirements and made each of them a special meal that was not on the menu."], ["It's an interesting place and right in the middle of the Central West End. Decent food, although it always seems to fall a little below top notch, you always leave thinking that you almost had the most amazing meal of your life. Draws a little older of a crowd, tweed jackets and pearls abound on fancy mid 40s diners."], ["I have been to Herbie's now twice in the last two weeks... obviously because I really enjoy it!  The food is very good (try the Lobster Mac and Cheese... you will NOT be disappointed), the staff are very friendly and the prices are just right for an affordable but nice night out."], ["The food at Herbies is always magnificent -- whether you're dining in the bistro or the dining room. I recently threw a 30th birthday party here and made so many strange requests of the wait staff, I was sure they'd throw me out. Not only were they incredibly accommodating, they actually offered their assistance many times. (Long story short, I had plans to jump out of a person-sized cake that had to be assembled in the restaurant. The manager visited me in the wine cellar and offered his assistance in assembling the beast). \n\nThe atmosphere is always inviting at Herbies. The wait staff are great conversationalists and always have great recommendations from the menu. Bottom line, I always enjoy myself when I eat here. However, you should bring your big, fat wallet if you plan to eat here. A two person dinner with wine can easily venture toward triple digits in price. In the end, though, it's totally worth the spend."], ["Our first visit to Herbie's. I had seen where the French onion soup was voted best in StL. I had to try it. However, the pasta special sounded so tempting I ordered that instead. And I was not disappointed. Tasty and very generous portion. Have enough for a meal today!  My husband had a filet and said it was perfect. I will return for lunch sometime soon to get my French onion soup.  Oh, and our waiter was friendly and attentive. And OMG he recommended the chocolate fritters for dessert. If you are a dark chocolate fan, run don't walk to get them."], ["Best meal I've had in St. Louis. Had the filet and my fianc\u00e9 had the Wellington. The food and wine was pronominal as well as the service and ambiance. Recommend for a nice date night dinner."], ["So, to qualify the rating... the food was fine. Pretty good. I got the pain perdue and I enjoyed it. But the worst part was the service. We came here on a groupon and apparently it's extremely limited in terms of how it can be used. We were alloted 14 dollars for a meal from the group so we expected to be able to order some sides to bring it up to 14, because most of the entrees were at 9 or 10. But apparently not... according to our waiter. Another waiter said differently. Confusing... and apparently none of the drinks were under the 8 dollar limit except for 2. Alright, so we ordered, ate... our waiter let our water glasses sit empty, gave us our checks after we sat there without doing anything for half an hour, then put our check, with the cards and everything, in his apron-thing and carried it around 20 minutes while refilling the water glasses of people at other tables (not ours)! Ridiculous. If one of our party didn't feel bad about giving less than 15%, we would have left $10 on a $115 tab. Not worth coming back."], ["Ate there with a very large group and was very pleased with the service we received but my main course was a little lackluster. I ordered the scallops and though they were cooked perfectly the barley risotto was the disappointing part of the entree. It was not what i expected from a risotto and took away from the delicate and very well prepared scallops. \nAll in all excellent service (as per usual) but a less than inspired meal."], ["The word \"disgusting\" does not even describe how bad this place is.  This place caters to baby boomers (no offense to baby boomers but the majority of boomers seem to like crappy frozen Sysco food that is bland and over sauced with flavor-less sauce or gravy).  \nFor starters, the staff was very rude to anyone under the age of 40.  We ordered drinks at the bar 3 times and never got them.  I decided to make it easy on the Bartender by ordering a bottle of Laurent-Perrier Champagne.  Twice I went to talk to him and twice he put his hand in my face and told me to wait.  After waiting 45 minutes he finally came over and said, \"so did you finally decide?\"  I said, \"I decided a very long time ago.\"  And as soon as I told him I would take the Laurent-Perrier, his attitude changed in a flash, I gather because it was an 85 dollar bottle of wine instead of asking for a 5 dollar happy hour cocktail.  He became very nice from that point forward, but it was tooo late.  \nThe only reason we stayed and didn't leave after waiting for 45 minutes for a drink was because we had been invited for a special event.\nWe sat down to dinner at 7PM.  It took them 45 minutes to take our order, and 45 more minutes to get us our food.  Everyone kept coming by assuming we had eaten already.  We did not get appetizers, or dessert so they can't claim they were \"staggering\" our food.\nEverything we tasted was gross.  The Lobster Mac and Cheese was nothing more than flour water with bad noodles.  Oh, and I never found a piece of lobster, but it smelled like Truffle oil like you wouldn't believe.  \nThe bison burger was not edible because the tomatoes they put on the burger were clearly rancid and came out of a frozen pre-cut Sysco trey.  The meat was still frozen in the middle but cooked to well done on the outsides.  This was the ONE thing that they did not put sauce on.   It was dry as a bone, even though their description talked about an aioli being on the burger?  I asked for Yorkshire mayonnaise they had on the menu but I never got it.  They eventually brought out a mayonnaise but that was after the one bite of burger I had and I wasn't going to eat anymore after that.  The frites were not even hand made, they were burger king fries which equals Sysco fries.  \nHerbie's website looks awesome, but it is NOTHING like what you actually end up getting at the restaurant.  Avoid this place.  I can NOT believe that people call this fine dining.  This place is disgusting and people are rude."], ["Three cheers for Herbie's! \n\nI visited here a few months ago with a friend. The place itself is pretty nice; there's definitely a French theme going on there. \n\nOur server was initially a little standoffish and pretentious; I'm not going to lie. I was not a fan of the service at first. But something -- either the fact that I whipped out my DSLR and started snapping pictures or the fact that we weren't punk kids -- changed, and he became a lot friendlier as the evening went on. \n\nI started with their Sage N Stormy drink -- dark rum, apple spice ginger liquor, simple syrup, lime, and sage made up this delicious drink. I guzzled it down and had to go for a second. Yeah...it was that kind of night, y'all. \n\nFood-wise, I went with the lobster mac & cheese. I recommend going with the smaller portion, because I opted for the larger one (fatty, fatty, two-by-four...) and it was WAY too much food. \n\nOh, but it was so good. Rich, creamy, FULL of huge lobster chunks, topped with crispy breadcrumbs...it was heaven in a bowl. \n\nMy friend ordered the peppercorn & coriander encrusted yellowfin tuna. It was served with an edamame and shiitake mushroom risotto, tempura bok choy, and a wasabi soy sauce. I had a few bites and it was pretty good, although I enjoyed my mac & cheese more. \n\nFor dessert, I went with (what else?) their bread pudding. I honestly wasn't a fan of this; it was made of some sort of hard french croissant, which made eating it sort of challenging. The ice cream that accompanied it was almost bitter, and the stingy drizzle of chocolate sauce did nothing for the dish. Meh. \n\nThe waiter also brought out a chocolate fritter on the house for us to try. Again, I think this had more to do with the fact that I had a camera in my hand than anything else. But I'll take it! \n\nThis, my friends? This fritter was delicious. It was a crisp outer shell with the richest, most sinful dark chocolate inside. I could have eaten ten of these. Thank goodness he only gave us one. I have no self control.\n\nAll in all, it was a good experience. Would I come back to Herbie's? Sure. I'm in no rush to return, but the food was good, and once our server warmed up to us, the service wasn't too shabby either."], ["Friday night dinner: service was very good. House wines offered were way, way, way over priced. Seriously, $12.50 per glass of Steele Pinot Noir? Any wine you can buy at a local grocery store should never cost more than $6 glass.\n\nI had a French Onion soup and the Pork Chop off the Bistro menu. My date had a salad and an appetizer for her entr\u00e9e. I brought half my chop home as it was huge.\n\nOur server was delightful. The hostess was as well. \n\nAtmosphere very romantic with subdued lighting and a very interesting collection of clientele.\n\nThat wine thing though....gotta fix that."], ["I went here with a group of 8 for dinner.  The restaurant is a lovely space, and the hostess and servers were excellent.  We were seated near the staircase to the rest rooms, and there was definitely an odor, not necessarily from the rest rooms, but yet distinctly sewer-y, nonetheless.  Granted, we didn't ask to be reseated.  I was happy with the options provided by the vegetarian menu.  The mushroom crepe was wonderful, and the mushroom risotto was fine.  Bread pudding was good, although I prefer a classic pudding with hard sauce and no chocolate chips.   Friendly, helpful service made this an excellent experience even though the food left me a little wanting."], ["THE BEST BRUNCH I HAVE EVER HAD! I am a major breakfast fan - savory all the way. I ordered the vegetarian Benedict with chipotle hollandaise on top, came with potatoes. I have been drooling about it ever since. The sauce was great, vegetables seasoned perfectly. And don't get me started on the potatoes, they were golden, buttery, crispy and GOD SENT. I practically licked my plate clean I didn't want a single bite or flavor to go to waste.\n\nService was major busy - our waiter was very generous and very attentive, despite the chaotic morning. Has a slightly more formal dress code (my friends and I looked a bit underdressed in our tshirts and shorts). But nonetheless, cannot wait to come back and order the same plate!!"], ["One of my favorite restaurants in the CWE. Love them for brunch and dinner. Everything I've had here is delicious and presented well. I especially enjoy their tuna entree and eggs benedict with salmon. Their cocktails are creative and tasty too. Would eat here more often, but it's a little pricey. The last time I was here was with my parents and the server accidentally brought us all champagne to toast to their anniversary. It was not their anniversary, so this was a little surprising and we told the server. It was a mix up, but they let us keep the champagne, so props to them. Just hope whatever couple was celebrating their anniversary got some bubbly too!"], ["I think this is a great restaurant.  Good wine list, friendly, unpretentious servers, great food - vegetarian and gf choices if you lean that way.  I like the vibe in the bar and love sitting in the front bistro, which feels like sidewalk seating without the weather or bugs.\n\nAnother reviewer had some trouble with private event space, and I just wanted to say that I found their event planners to be an absolute delight.  Very helpful, very patient with all kinds of truly pesky requests and scheduling issues.  They were so nice I had to type a review to defend them!"], ["I rave often about how I love Herbie's... and then question myself about why I can't get here more often.  We had reservations for Saturday night for our anniversary and were given the rock star treatment.  Nice corner banquet table with view of the room, free champagne, oysters on the half shell with tangy mignonette.  I could go on and on.  It was a really great experience.  I had a just right size salad after the oysters and my hubs (who is in the midst of a Biggest Loser competition) really missed out on getting an app.  We each had scallops, which were fresh, sweet and perfectly prepared and he added on a lobster tail to his.  Bottle of really nice, minerally French Chablis rounded out our meal and dessert was a shared French toast cupcake, topped with maple buttercream and stuffed with a mascarpone filling.  Divine.  I love everything about this place from the ambiance - think old French litho posters and exposed brick, to the funky CWE vibe.  The menu is not huge, but is enough to make everyone happy.  My one wish would be for a more extensive wine menu ( miss you Balaban's), but most wine fans can find more than enough to stay happy.  LOVE you Herbies... and if you are here for lunch, don't miss the burger.  It's outstanding!   PS - valet parking is only 3 bucks... forget the garage!!!"], ["Just went to Herbies for the second time the other day for my birthday with some friends during happy hour. The bartender Amanda remembered us and was extremely friendly and helpful. We ordered the spinach and artichoke dip, shrimp dumplings, and the classic flatbread. Food and cocktails were amazing. Loved the atmosphere as well. Very reasonably priced for the incredible quality. Will be back soon!"], ["I had a gift card to Herbie's and so my husband and I decided to have grandma watch the baby for a night while we dined out in style. I made a reservation a few days in advance and they asked if it was a special occasion. It happened to be our 5 year wedding anniversary, so I shared that with them, not quite sure why. \n\nAs it turns out, once we arrived and were seated, we each got a glass of champagne, and later would get the banana's foster dessert at no charge. That right there bumped them up a star. GREAT service. \n\nI was surprised that it wasn't more crowded on a Friday night, but it seems like a pretty old fashioned restaurant in the heart of the CWE which is bustling with younger, hipper options. Perhaps it's more a brunch or early dinner location. In any case, the ambiance was romantic, and exactly what we wanted for our evening. \n\nWe each ordered a glass of wine and a salad and both were great. Sadly, I can't remember the salads, but I do remember it being tasty. \n\nFor my entree, I had the lobster mac n cheese. It was really rich, but very tasty. I read people complaining about the portion size, but there was plenty to eat that night and have a meal leftover! My husband had the short rib and he said it was good, but not amazing. \n\nThe service was prompt and attentive and again, we felt very taken care of with the extras on our special night. \n\nI do have to say, there wasn't anything super stand-out, food wise. Everything was good, but nothing really blew me away. I probably wouldn't return without having a gift card because honestly, I could get a meal just as good, if not better, for less money. It was a nice spot to celebrate an occasion and it was a fun, fancy, treat, but I probably won't go back."], ["I went to Herbie's recently for a Valentine's dinner with my boyfriend. It was a very charming atmosphere with rose pedals on each table and candles. I got the scallops with risotto and he got the filet and both were amazinggg. If you go here you MUST get the scallops!!!!! The best I have ever had. You could still taste the smokey flavor on the steak it was so good - highly recommend!!!"], ["Our waiter was a very tall guy, named Joshua. Very outgoing and provided wonderful customer service. He suggested an amazing glass of red wine (Chardonnay Merryvale 2008 from Napa Valley). Excellent choice.\n\nFOOD: Four of us split one plate of the Firecracker Shrimp and ended up ordering 2 more servings of it. It was delicious. I had the Atlantic Salmon as an entree. It was served on a bed of quinoa and topped with crispy leaks. I could have gone without the leaks though. The salmon was delicious and cook exactly how I wanted it. \n\nDESSERT: The four of us split the New York Cheesecake and I have to say that I was incredibly disappointed that it had NO graham cracker crust. That's the best part!!! The cheesecake itself was delicious although it could have been slightly cooler in temperature. It was served with a blueberry and lemon curd sauce on top. \n\nI would highly recommend this restaurant for a nice dinner...maybe not a first or second date, but definitely for a special occasion. The valet was quick and efficient and the ambience was cozy."], ["Ate here on a Saturday early evening.  Place has an old school classy vibe to it.  Service was impeccable - the waiters were practically hovering over us waiting for us to need something.  I mentioned when making the reservation that it was for our anniversary and Herbie's was very nice to go out of their way to wish us a happy anniversary along with a small dessert.  I had the strip frites bernaise which I'm sad to say was just average - the frites (fries) were great but the steak was mehhh.  It tasted good with a nice hint of charcoal flavour, however the cut of meat didn''t seem particularly juicy or tender or all that memorable to be honest (+I had high expectations for a $30 steak, which I left quite disappointed about).  The Mrs. had the scallops+lobster risotto.  The scallops are quite possibly the best scallops that either of us have ever tasted!  Absolutely perfect, cooked through but still \"melt in your mouth\" tender.  The place is expensive - expect a bill like you went to Ruth's Chris or similar but you can also expect excellent service to go along with it.  All in all we had a good experience and we will definitely be coming back, if anything for those scallops!"], ["I keep coming back to Herbie's and they keep knocking my socks off.  I'm never going to find them.  Saturday night was outstanding and if I could do a cartwheel, I would.  Remember they do have valet parking but there is also a parking lot (pay) down the street.  \n\nAmanda and Francesca were behind the bar this evening.  We had cocktails while we were deciding what to order.  This evening we decided against appetizers because we wanted to order a true meal.  Majordomo got the pasta special and I decided on the dover sole.  The pasta looked beautiful with shrimp, vegetables and wide noodles (pappardelle?) that was so tasty. Dover sole is a beautiful white fish that they will debone at your table is you wish to see a show.  Since we were sitting at the bar, I asked that they do that in the kitchen.  I remember having this several months ago and that it was delicious so I wanted to see if the experience could be recreated.  It could.  The fish is flaky and comes with melted brown butter to pour over the fish.  Side dishes were asparagus and fingerling potatoes.  These were both very good, however my fish stole the show.  So tasty that the gentleman sitting next to me (a stranger) was eyeing it. I had enough left over to take home for breakfast .  (It was just as good cold.)\n\nDessert?  Well we will listen to what you have.  Yadda, yadda red velvet ding dongs.  Wh...What?  The ding dongs were the icing on the cake.  I wish we would have ordered our own individual ones.\n\nWould I come back here.  Just look for me at the bar stuffing my face."], ["Went here for Valentines Day. The food was inventive and good, but not outstanding. (3.5) The wine list was excellent, and the mixed drinks were very good. (4.5) Unfortunately the seating arrangement really devalued the otherwise neat decor. Due to the close proximity of other tables, there was no privacy and it lessened the experience of the dinner. (2)"], ["To be honest, I was disappointed. My dining companion and I both felt the same: ho-hum food, nothing to write home about, and a little overpriced for what it is. I appreciate that they have allergy information on the menu, so I'll give them that, and the atmosphere isn't bad, but when it comes to the food, it's not a place I'd revisit. I had the salmon (which was overcooked and underwhelming), and my crony in eating crime had the pork chop, which was more fat than chop. Also, it's a serious understatement when they say \"wilted\" greens (they were dead)."], ["Great wine selection.  We had a knowledgable waitor that actually didn't recommend the most expensive bottle of cabernet (surprise) but the one he did recommend was a good one.  \n\nI had the tuna, which was prepared very nicely.  Corn chowder was excellent or a starter.  One of us got the lobster mac' n' cheese and wasn't all that impressed despite this being their specialty, but I did not personally try it.  Maybe I will next time. \n\nThe desserts were actually quite good, although I heard they had some better ones in the past.  They do rotate the menu frequently so if you have a craving for your favorite dessert from here then make sure to call and ask first.  One person in our party asked to see if they could make one of their old ones and they said they couldn't"], ["Poor service rarely sways a review for me, because as long as the food is good, I'm a happy man. We came in today for two specific items listed on the Sunday menu, but they had removed them and not updated the online menu. We were ignored and not handed menus, initially. Had he offered other suggestions, we might've stayed, we were already sat, but I guess they didn't want our money? The service was rude, which is understandable, I loathed serving tables on Sunday mornings, it's the worst, but don't be so surly and jerky. Bottom line, we paid for our drinks and left, and will not be returning."], ["Herbie's has everything anyone could ask for in a dining experience.  The menu is so diverse and caters to all palates and restrictions. The building is historic and charming. You choose whether you would like to sit in a lively bar atmosphere or at an intimate corner table. They have the space to host large parties and the friendliest of staff. You can enjoy live music, hand crafted cocktails, and exceptional food."], ["I went to Herbies to hear some music. I took a look at the menu and orders a \"classic flatbread' and washed it down with an Irish ale. Amanda was working the bar and her attention to service was excellent. The flatbread pizza was pretty tasty as well. It featured a light tasty crust, marinara sauce with a bit of a bite and had plenty of tasty toppings. For $10 is was a reasonably priced for the setting,\n\nI am pretty picky about service. Amanda didn't ever let my water get empty. I don't know how many restaurants I have been to where my water glass collected dust. It ranks as a pet peeve, regardless if I am drinking something else. \n\nI will go back to Herbies and try something else from their menu. In the meantime I need to sleep off eating the whole flatbread pizza thing."], ["Went here today for brunch and I must say I was quite...well, I simply was not impressed. Having it located at the central west end, I assumed it would be a bit better when it came to food quality but it was nothing to \"ooh\" and \"ahhh\" over. In fact, the food I ordered was the country friend chicken with scrambled eggs. Much to my surprise, it was presented to me in what looked like a cheap imitation of a \"gourmet\" meal. There was just too much potatoes to make up for the tiny portion of chicken. For my side I ordered the cheese covered grit. It was good but the grit was just too thick. I thought grit was supposed to be creamy instead of this thick chunk of cement. Anyways, I had gone during brunch hours - I hope it's much better other hours but from reading others' reviews it seems it fails just as much.\n\n**Edit** \n\nTo add a bit more review on their disappointing food. My friend got the waffle and my god it was like cutting through rubber. Also it was just a plain waffle - nothing so special about it and they charge you $7 for that thing that I could just get a box for the same amount and just use the toaster for it. Yeah, no - try again pl0x."], ["A farewell dinner for our visiting friends at Herbie's.  It did not disappoint. \n\nAppetizers were ordered. The duck crepe, cucumber bisque and French onion soup. I am definitely getting the duck crepe next time.  The cucumber bisque was refreshing and the French onion soup is a meal in itself. \n\nMy husband ordered the duo of beef and I ordered the tuna special.  Our entrees arrived and at some point I thought I saw my husband licking his plate.  He said it was very good. My tuna was delicious also with a white bean Jalepeno side.  Excellent. \n\nOf course we ordered dessert!  Butterscotch creme br\u00fbl\u00e9e and a sundae. The creme br\u00fbl\u00e9e was very good but did not have much of a butterscotch flavor. \n\nYes, we will be back."], ["Dined at Herbies on a Friday night. Sat in the front porch \"Bistro\" area.  Had a great time!! The atmosphere was great. Brandon was our server and he was excellant!!!  The food was amazing and the wine was decadent!! Would go back for sure!"], ["I love everything about this place and I'm very willing to spend all of my money there. The servers are polite without being the creepy kind of nice, the food is excellent, and the atmosphere is super classy. It's smaller than some other places, however."], ["We had Easter brunch today at Herbie's and it was SOOOO average the more I thought about it, it compelled me to write a review.\n\nFirst I will say everything aesthetically about Herbie's is awesome.  It is a beautiful place, eclectically decorated just has a great vibe from that perspective.\n\nI decided to take my daughter to brunch just the two of us.  We had a great table and our server was very good.  Where the misses start piling up is on the buffet.  It was overly simple and lacked any real creative selections and frankly was allot of cheap filler items like  Macaroni & Cheese..... for lack of a better word, it was a cheap effort - chicken picatta, eye of round...really how exciting thanks for providing a cut of meat no person would ever buy for themselves.   Yes they had some nice seafood items but it was the simple shrimp cocktail and packaged smoked salmon you can do on your own.  \n\nIn my mind this was just not much of an effort.  I would expect a restaurant with the history and tradition of Herbie's to perhaps smoke their own salmon or do something creative and that shows effort not just baking a cheap piece of meat and over cooking it at that.\n\nAlso as if that is not enough, they had 1 yes ONE dessert item...Bread pudding... on Easter at a Buffet ONE item......."], ["Went here for my boyfriends birthday on Saturday night. We arrived early for a 7:15 reservation and had a drink at the bar. Bartenders were nice and helpful, poured excellent drinks! Our server, I believe his name was Joshua, was fantastic! Personable, knowledgable, and not over bearing. My filet was cooked to perfection with just the right amount of seasoning and my boyfriend loved his beef Wellington. We ended with a complimentary glass of champagne and flourless chocolate cake. I highly recommend this restaurant! Can't wait to go back!"], ["Andy Warhol (Studio 54 provocateur) eat your heart out, HERBIE'S is here.\n\nBalabans -the legendary Central West End establishment has re-opened as Herbie's! (In homage to Herb Balaban's 70's-Era watering hole of the same name.)\n\nCWE residents have been eager for this infamous location to re-open and bring back some character and history to our great neighborhood. Herbie's delivers on this long waited promise.\n\nTonight was my second visit to Herbie's since it opened its doors 5 days ago.  The service has been impeccable, and the food delightful. The atmosphere is clean and a little more contemporary than the old Balaban's motif; if you're a Balaban's veteran you'll recognize the old place and probably like the upgrade.\n\nGo soon, and go often. There's an \"Anchor\" Restaurant on Euclid again, and his name is Herbie!"], ["My experience aat Herbie's was great.  We had dinner there before going to the Fox and they paced our dinner so that we were out of the restaurant on time.  I had short ribs, my husband had the fish special.  Everything was prepared as advertised.  The wait staff was very attentive and friendly.\n\nThe reason I did not give five stars is because the restaurant was not filled when we arrived and they kept wanting to put people next to us instead of giving everyone room.  By the time we left, the room was filled so if they wanted to put someone next to us it would have been fine but not when the restaurant is empty.\n\nI would definately go back because the food was great, service superb and atmosphere classy."], ["So I'm all dolled up in my Easter best, because of course it is Easter, and we head for our reservation at Herbie's for brunch.\nUpon arriving, I was immediately overwhelmed by the number of pastel-clad Easter folks scurring around the buffet.  I felt like I was in Driving Ms.Daisy, and some member of the clan was about to come out of the corner and serve me up some grits.\nThe buffet was a disaster by the time we got there.  Our reservation was for 1:30, and being the descent sort of church-going folk that we are (descent I mean, in that we go once a year... actually I hadn't been back since the last Easter...I guess that makes us descent and hypocrites at the same time) \nAnyway-- our reservation was late because we went to church to celebrate the resurrection, darn it.  I didn't expect to get punished later by a brutally torn apart compilation of a 'once was' breakfast smorgasboard.\nBy the time I got a warmed plate into my hands, the filet of salmon was barely recognizable as such, the salad was gone, the dressing was a smeared mess all over the table, hot pans of egg dishes were over steamed and miserable, and my dear, poor, stomach particularly unhappy.\nI did manage to down some cocktails, though.  Two grapefruit and vodkas and a glass of pinot grigio.  Our waiter was attentive but seemed stressed, which made my boyfriend stressed out too because he is a waiter and knows what it's like to be over-worked.\nI felt like the whole thing was just a little out of hand.  Perhaps they needed more staff, perhaps they should've made more food.  \nEither way-- it was a pretty under-par experience.\nI have been to Herbie's when it was really good-- and I'll probably go back again.  I certainly won't get suckered into one of their holiday buffets, though."], ["I met up with a few friends for happy hour at Herbie's last Friday and we had a good time. The beer selection on tap was decent and they had a pretty extensive wines by the glass list with some more reasonably priced options. We split the spinach artichoke dip which was VERY tasty and the popcorn was addicting. \n\nMy problem with Herbie's was the service. We had a very nice server but she kept disappearing. It seems every time we needed to order something else we had to get up and find someone to help us which got old after the first time that we had to do it. I'd be willing to go back here one more time to give Herbie's a chance to redeem the poor service since it may have just been an \"off\" day."], ["Atmosphere for brunch lively, food fabulous. Definitely going back!"], ["It's no secret that I like to drink in dim, moody places.  Not because I'm emo and rebelling against the world, but because I'm rebelling against the college bar.  Being so near to SLU, the CWE naturally abounds with college bars.  Herbie's is the antidote.  Classy and expensive, it's assuredly not a student hangout.  In fact...at 24, the next-youngest patron probably has 15 years on me.\n\nMy knowledge of haute cuisine isn't what it should be, so I found the menu fairly foreign and the service is nothing special.  But the atmosphere is superb, as is the location, and on balance, those are enough to keep me coming back."], ["Ugh Herbies... I can say I had the worst meal of my life there. I ordered beef carpaccio and I've had carpaccio all over the world and honestly some are simple and some are just amazing, well in Herbie's case it was one of the worst carpaccios I ever had! Who puts mustard and cabbage on it??? For dinner I ordered a Beef of Wellington and that just tasted like DOG FOOD! I wouldn't feed that to my dog. Service was awful, server didn't even ask us \"How is everything?\" I would not recommend this to anybody and would never go there again, I guess all the positive reviews come from STL kind of people and obviously they have no idea what good food even tastes like."], ["Came here for brunch with a couple of friends on Saturday around 11am. We had made reservations, so we were seated immediately when we got there. Though we probably would've been seated right away anyways since the place wasn't as busy as I thought.\n\nThe ambiance and d\u00e9cor is awesome. Loved the terrace space out front with all the huge windows, which is where we ended up sitting. We didn't get to see inside but from the pictures that I've seen on Yelp, it looks pretty fancy.\n\nI ended up ordering the Breakfast Rueben, and my wife ended up with the Huevos Rancheros.\nBreakfast Rueben with a side of fruit - Nothing special, with a $12 price tag I was expecting something that would wow me a little more. I went with the fruit for two reasons, because when I asked the waiter if the fries were handcut he said no, and I don't want to get too fat.\nHuevos Rancheros - I had a couple bites of my wife's dish, which I thought was far superior to mine. I really enjoyed the fried potatoes, that was probably my favorite part.\n\nAs for drinks, we didn't up ordering any, but our friends did. Herbie's have bloody maries for $10 each or you can pay $14 for unlimited bloody maries, which I feel like choosing the latter is a no brainer. They have a pretty sweet bloody mary bar as well. Tons of different hot sauces and bacon! (I stole a couple of pieces of bacon, shhh don't tell anyone). If I was a bloody mary drinker, this is the place I would go for a fix.\n\nService wasn't slow, but our food took awhile to come out. The waiter was very attentive in making sure our glasses of water were filled up at all times.\n\nI wasn't a huge fan of this place, but am really glad to be able to check it out. Maybe we'll be back for dinner."], ["So here's where all the cougars in the CWE go on the prowl. I always suspected they were at Sub Zero or the Drunken Fish. Or maybe this is where they take their prey? \n\nI've been here several times, usually just for drinks, but food has been had. \n\nThere's a good wine list and (at least in the past), knowledgeable and talented bartenders (I think all the ones I knew that worked there are now elsewhere). \n\nFor my only meal, I had a good (but unmemorable) salad and their shrimp and grits. It was definitely spicier than most renditions of shrimp and grits I've had, but it was maybe a bit heavy for what it was. Very oily. \n\nThe \"bistro\"/covered patio area is great for people-watching."], ["I love brunch at Herbies. One of my favorite things is getting my own personal little bottle of vodka to go with the awesome Bloody bar. The food rocks my socks too. The BLT is delectable and the fries mmmmm yummy! Treat yourself and head to Herbies!"], ["great spot for date night.  went there for a friends birthday dinner.   great menu. I went with the shortrob flat bread. staff is super friendly and helpful. was stuffed and didn't have time to sample the blood orange cheesecake."], ["We went here on a Wednesday night and really enjoyed ourselves. Good food great atmosphere, just a few small changes and I would have given it 5 stars. A little heavy on the peppercorn encrusting for the Ahi Tuna and the fried onions on the rabbit pasta was a little too much and overpowered the rest of the dish. Other than that, great service, good food, beautiful beautiful atmosphere."], ["This review is a little late in the making, but still deserves to be written. My husband made reservations for Herbie's in an attempt to dazzle me (and possibly himself). We read many great reviews about this place and were really excited to try it out as we were celebrating a long deserved night out away from our children.\n\nWe arrived 10 minutes before our reservation and were immediately seated.  After chatting with the hostess for a minute, she placed us in a private area so we could enjoy some time in a quieter area of the restaurant.  This pleased us very much.  So far, so good.\n\nWe were greeted by our waiter and gave our drink order.  After a while our drinks arrived and we were told the specials of the night.  The waitress was very knowledgeable of the meal choices and our orders were placed.  I chose the fish special and my husband a meat and potato combo.\n\nOur food took an exceptionally long time to arrive.  At times, we thought we were forgotten about and relied heavily on the bread to get us through.  Finally, when our meals arrived, my husbands already \"hangry\" demeanor was replaced with horror when he realized his steak was the size of his nose.  It was the smallest piece of steak known to man and you could see the beads of sweat forming on his brow.  However, knowing this was date night, he kindly accepted his plate and the waitress left.\n\nMy fish was wonderful, and I shared half of it with my husband due to his very small piece of steak.  There was some story about how the fish swims around a boat which gave it its name, but I can't remember what they called it. It was served on a bed of barley type risotto which was a little bland to my liking although the waitress did a great job of hyping it up.  Needless to say, we left hungry and ate a second dinner while watching Wicked at the Fox.\n\nLong story short, ambience was very nice, service nice, wait time too long, and portions too small for what was paid."], ["My boyfriend and I read in the February issue of St. Louis Magazine that Herbie's Vintage 72's Beef Wellington is one of the 30 best dishes in St. Louis.  We decided that we had to try it.  So for Valentine's Day, we decided to try the highly regarded restaurant.  It did not live up to all the hype.  \n\nWe ordered the Beef Wellington, Beef Short Ribs, the Duck Confit Crepe appetizer, Chocolate Fritters, and Chocolate Mint Creme Brulee.  The Duck Confit and the Chocolate fritters were our favorites.  While the food was not bad, we did not understand why it would be rated so highly. The food was mediocre and overpriced.  We will not go back.\n\nOn the upside, the service was excellent!  \n\nPerhaps it is just hard to find good restaurants in St. Louis.  We have noticed that the high end restaurants in St. Louis do not usually live up to their reputations. However, we will not give up.  We will continue on our search for good restaurants in St. Louis."], ["What can I say, Herbie's is one of our regular joints. The food is always fantastic and the waitstaff is attentive and informative. A best bet for beef fans is the Wellington of Beef, Filet Mignon of Beef or the Steak Frites. The duck is also a fantastic meal. They have a dining room for a more elegant evening and a bistro area with large windows that open onto the sidewalk for a more relaxed evenings."], ["Our brunch group picked up a pretty good Groupon for Herbie's  that we thought it was worth checking out.  The deal included any entree up to $14 and any cocktail up to $8. Sounded pretty good. \n\nOnce we got there, I ordered chicken fried steak with a poached egg. It was good, but the portions were small, so I was still a little hungry afterwards. All of the items were less than the $14 indicated on the groupon, but you could not add a side to get it to the $14 level. \n\nOverall, it was fairly decent. We were right by the door, so we felt like we were in the way a little bit.  I guess at the end of the day, the Groupon didn't make it a good deal, it just saved us the cost of the tip.  We're always up for an adventure, so worth a shot.\n\nI've been told dinner is much better, so definitely something to consider the next time we're looking to go out!"], ["It's gotten to the point that when I know I'm coming here, I start skipping.  I can't wait for their deliciousness to get in my belly.  We came here the other night with visiting folks from Maine.  It did not disappoint anyone in our party.  We were seated right away and our drink order taken.  Looking over the menu, one of the people from Maine noted that there was Live Maine Lobster on the menu.  He laughed and said he would rather have his cooked!!\n\nWe settled down and ordered appetizers.  I ordered a shrimp cocktail as did Majordomo.  Guests started with a Caesar  salad and French onion soup.  Both the salad and the soup looked wonderful and I made a mental note of ordering them the next time we came in.  I ordered the braised short rib.  It came with roasted sweet potato bites and red cabbage.  It just melted in your mouth.  Majordomo decided on one of the specials for the evening - blackened steak.  He said it was very good and that he would get that again.  It came with mashed potatoes and haricot verts (green beans).  Yummy.\n\nNo dessert this evening as we were tired from a long day. Would I come back here. I'm getting the Caesar salad and French onion soup."], ["I must say my experience was a good one! Enjoying roasted butternut squash ravioli in a perfectly balanced sage-brown butter sauce with slightly crisp fennel. I cannot complain. I didn't notice the patrons as being any different than the standard CWE crowd, so that was really nothing notable for me. \n\nThe waiter was knowledgeable and made many recommendations from wine selections to food. It's all about the experience and truthfully on this night Herbie's was on their A game. I read a few of the reviews, seems that that some Yelpers are not so thrilled, maybe a second chance will do you good."], ["We like Herbie's for brunch and sit in the bistro.  Herbie's has 3 sections:  The bar, which is very casual, the restaurant, which is formal dining, and the bistro, which is in between.  We prefer the bistro because we can dress up to go out, but not have to try too hard.  We also like the big windows.  Making a reservation is easy.  The host/hostess will take your jacket and hang it up if you'd like.  They're very nice and welcoming, as are the servers.  The food is delicious.  Our menu favorites are the Country Fried Steak and Eggs Madison Benedict.  While Herbie's is an expensive restaurant, brunch can be affordable and will fill you up for the whole day!"], ["Herbies is a great place for both a semi-casual or a fancy meal.  They have a fairly extensive gluten free menu, and they seem to know how to avoid cross-contamination.\n\nIf you are looking for cheap(er) options, then the flatbread is fantastic (and much cheaper than Pi across the street).  The Balaburger, house salad, and french onion soup are also excellent.  I love onions, and I never knew how good french onion soup can be.  I would come here just for the soup.  \n\nIf you are able to spend more money, the filet and scallops do not disappoint.  \n\nI do wish they had a gluten free complimentary bread or appetizer, as well as some dessert options."], ["I went here for dinner last night.  The food was well prepared and the service was standard.  It's unfortunate that most of the poor reviews for this place are for the bar area.  One may overlook this place due to it's lack of stars.  But, if you're looking for a nice dinner in a somewhat upscale atmosphere, this is a good place to go."], ["HORRIBLE SERVICE but food was very good even though it took us constantly asking for service. Appetizers entered into the computer but for some unexplained reason it didn't get submitted, press the send button maybe. Continually had to ask the server for drinks. Dinner took an hour to reach our table after it was ordered.  And to say the restaurant was busy it wasn't.  On top of that the one of the cancelled items we were charged for which made me furious.\nThe dinner entrees were outstanding from the perfectly prepared Sea Scallops,  Lobster Mac n Cheese, Yellowfin Tuna and Salmon.\nThe restaurant itself was inviting but extremely loud with a table if obnoxious diners playing a game that you couldn't carry on a conversation across the table."], ["My husband and I came to celebrate our 20th anniversary. We had an amazing dinner.  The service was outstanding and the attention to detail phenomenal. Chef Vumond gave us a treat of sous vide venison on butternut squash barley risotto, and plum gastrique. Amazing. The charcuterie plate paired with oysters on the half shell were delicious. The slightly smoked pork ribeye with a fennel and orange sauce was outstanding. The pan seared mahi mahi with fennel was perfect. We were treated again with Prosecco and gooey pumpkin butter cake and cinnamon ice cream.  We had a great evening and I will be back for that lobster my friends.  Thanks so much for great service and outstanding food."], ["Dinner there last night with colleagues.  The very polite and pretty cocktail waitress was just that.  Service was excellent, the food came quickly. The appetizer was lobster and mac'n'cheese.  By the time the plate got to me the small amount of lobster was gone, leaving a boring, rather dry macaroni.   I did not find my dish, shrimp and grits, very appealing.   First it has sausage, which I had to pick around.  Second the grits are quite liquidy and without any texture at all. Others might like it, but I found the dish too rich, too intense.\n\nWhy then, Seth, the four stars for a three-star experience!?  It was the soup.  The cucumber bisque."], ["I have been to Herbie's for lunch and dinner and everything I had was excellent.  Both times i sat in the front area and had great service.  This is one of my favorite restaurants!"], ["Someone once asked me why do I give five stars to some restaurants and lower stars to others.  The restaurant has to \"knock my socks off\".  And that is what Herbie's did last night. \n\nLast night was crowded but we were still able to find seats at the bar.  Dustin and Amanda took care of us. After sipping on our cocktail for awhile and munching on some popcorn, Mike decided to start with a shrimp cocktail and I went with a half dozen oysters on the half shell.   The tray that they came out on was impressive.  And the oysters were so delicious and fresh.  Burst in your mouth with that wonderful saltwater taste. Mike's shrimp got a big thumb's up also.  Nice and plump. \n\nWe moved on to our next course - one of the specials of the evening - rack of lamb. It was wonderful and cooked to perfection with mashed potatoes (how do they get mashed potatoes to taste so good?) with saut\u00e9ed peppers.  It was fantastic. \n\nAnd then on to dessert. Make your own s'mores. Get outta here. A little pot with fire. In house made marshmallows that were scrumdillyisious (and I don't really like marshmallows) with cinnamon graham crackers and three types of chocolate.  Is this heaven!!!  Oops, there went my socks. \n\nOf course I'll go back to Herbies. I have to find my socks."], ["I went to Herbie's this past weekend to use a Travelzoo dining certificate I bought a couple months ago. I've been wanting to go for weeks, and finally made it out!\n\nFirst, we were seated near the bar area at a tiny table. It was fine, and we could watch TV, but pretty much deserted (just us and the bartender). When the waiter came to pour us some water, he spilled it all over the aforementioned tiny table. While I don't blame him for making a human error, he didn't even bother to clean it up at all! So basically, our table was sopping wet the entire time. Strike 1.\n\nFor our drinks, I got a mimosa (meh, decent), and my BF got coffee. The coffee was lukewarm and when he added creamer, it clumped up something awful. They were really nice about it when we pointed it out, and happily exchanged it for a bloody mary (which was not bad). But honestly, a brunch place that can't make a passable cup of coffee? Strike 2 in my book.\n\nFor entrees/sides, I got the chicken fried steak with an egg over easy and the cheddar cheese grits. The BF got a classic eggs benedict and bacon. We had heard about how great the brunch was, and were willing to overlook previous travesties for a good meal. Alas, we were to be disappointed again. My chicken fried steak was so skimpy on the \"steak\" (which tasted more like hamburger mash) that I kept looking for more of it under the potatoes. It tasted mediocre, lacking much of the \"fried\", as well. The BF's eggs benedict had 1 lovely runny egg and another one that was pretty much hard boiled. It was awful. On top of that, his bacon was so badly burnt that it was practically black! It's appalling to me that the chef let that terrible bacon leave the kitchen, and speaks to the fact that the cooking was hasty, shoddy, and not worth even the discounted price. Strikes 3, 4, and 5. \n\nThe only good thing was the grits. I actually enjoyed those, although they were a little clumpier than i like my grits. I'll even knock off a strike for those.\n\nOverall, a pretty disappointing experience that I didn't think was even worth the 1/2 off Travelzoo price. I don't think we'll be going back."], ["MacHeadQuarters would like to thank the staff at Herbie's for making our annual company Christmas Party a huge success.\n\nI have to say this was the easiest private party I have ever setup. There weren't a bunch of rules and limitations that needed to be followed. Everything I requested was done without any resistance. We had almost 30 people and requested to be seated at one table and they made it happen. We chose to go with a limited menu rather than banquet style. When we got there, we noticed their Beef Wellington dish was not on the limited menu. They not only offered it to us without a fuss, but actually reprinted everyone's menu with our company logo at the top (which was not provided to them in advance). Wow.\n\nWe had the party in Herbie's wine cellar. This is an area that anyone can reserve for private parties. The wine cellar is decorated beautifully, as is the rest of the restaurant, but the wine cellar is separated on a lower level and provided a special atmosphere. Even the staircase entering the wine cellar is unique. It even has it's own private bathroom. I would highly recommend the space for private parties.\n\nStaff was great. They were friendly and fun. They kept up with all of the group's demands for drinks, etc. in a timely manner. We enjoyed interacting with them.\n\nFinally, the food was excellent. The Beef Wellington, the chicken, the fillet, the salmon, the Hor d'Oeuvres, the dessert, everything got great reviews from everyone. I thought the blackened tuna was amazing and I don't even like tuna!\n\nI wouldn't hesitate to recommend Herbie's to anyone for a private party. It went smooth, easy, tasted great and had an excellent, attentive staff. If you are thinking of having a private party, just stop by there and ask to see the room. I'm pretty sure that's all it will take. You and your guests will be impressed and have a great time."], ["I had another not-so-pleasant experience with Herbie's and I thought I would update my rating.  \n\nThis time it had nothing to do with the food or restaurant- this time it has more to do with the management and ownership. \n\nSo apparently Herbie's owns the old Monarch building in Maplewood.  Monarch closed a while back, but now the space is solely used as a place for private events.  I was looking for a venue for a private event for work about 2 months ago. I called Monarch and left three messages on their automated voicemail.  I also called Herbie's directly and I was told by the hostess that I needed to speak to the GM or the floor manager.  I left numerous voicemails and called the restaurant repeatedly during slow times and asked directly for both of them only having to leave messages with the staff.  No call back from either venue.  Really?  \n\nLet me get this right.  You have an empty, beautiful space that is devoted to private events but rarely utilized (I live up the road from Monarch).  Then you have someone basically begging you to take their business and you don't return a call?  If I were a business owner and GM, I would instantly think: easy money.\n\nWho runs this establishment?!"], ["I was right - having brunch here pushed the star count +1.  Brunch here was fantastic (kudos for having brunch on Saturdays AND Sundays) - some of us like brunch on Saturdays!  Also bonus points for serving brunch til 3PM for us lazy ones...\n\n1) Eggs Benedict - perfectly cooked eggs (I really hate when the egg yolk is solid!).  Comes with roasted potatoes...also yumm.\n\n2) Pain Perdu - french toast with a berry sauce and powder sugar...mmm (not too sweet!)\n\n3) Biscuits & Gravy - actually one of the best I've had in StL.\n\nThe mimosas were great and the service was polite and attentive.  Def will be back!!!"], ["Here are the reasons why I give Herbies five stars: (oh and FYI I'm only basing this review on Sunday brunch!)\n1. MIMOSAS.  Unlimited, fruity, delicious mimosas! You pay around 14 bucks for all you can drink! They have several different flavors (regular, peach, berry, etc!) which is awesome. They bring you a new glass of whichever flavor you want when you want :)\n2. FOOD. wow, the brunch food was absolutely to die for! I had skillet French toast with berries and we split the biscuits and gravy! All of the people in my party loved their entrees and we want to go back! \n3.  AMBIANCE. This place is so sweet and cute. It is a great date place or place for friends!\n\nI recommend Herbies to anyone who loves brunch and mimosas :) enjoy!!"], ["RIP Herbies in CWE. Hopefully Clayton will do you right.\n\nHerbies is a great date spot, even with an interior that looks like it belongs in a different decade. It's a little pricey but the cocktails are good and the food is pretty good. (As an aside, a great man once said Herbies was the place to take a date in the '80s if you wanted to get laid)\n\nIt's one of the few places with a \"romantic\" atmosphere that offers good sea food in St. Louis, too. The lobster mac is good, though a little soupy, the oysters taste fresh enough for the midwest, and the salmon is cooked perfectly.  While I've never had a burger there, a guy in my party was quite disappointed with the Herbie's Burger - apparently it was cooked poorly to the point he couldn't finish it. But that's the only complaint of that level I've heard about from the location. \n\nThey have a great wine selection, as mentioned above, the cocktails are great. I haven't had to ask for suggestions from the staff but the ones I've ordered from the menu were great."], ["I love the building and style of architecture straight off - even if the posters are a bit overkill. The burger was awesome - with an overloaded goat cheese spread and crunchy bacon. Def. will go back, to try the dinner menu."], ["Brunch today was disappointing. I had the special which was crepes stuffed with scrambled eggs & spinach. The crepes were cold and the spinach was stems, potatoes tasteless & bacon over cooked. My friends order the steak & eggs which they seemed to feel was ok. Ordered the chocolate fritters, which were cold, which I found to be the biggest disappointment. We ate on the patio which could use some work as the edging around the windows were pealing and missing a lot of trim,. This place is certainly not being kept up and the food lacking in flavor. Just doesn't feel like the Herbie's I remembered."], ["Went there for some apps. and cocktails the other night.  Sat at the bar and everything was great.  Service was tip top the atmosphere was cool and I was happy to see the nice crowd on a Sunday night.  The highlight was by far the Carpaccio of Beef Tenderloin...Outstanding!"], ["Tonight we celebrated my husband's graduation at Herbie's! It was my job to pick the restaurant and my father-in-law treated us all, so I needed this place to make him happy! Lucky enough for me, it did! We were a party of eight and at 5:30p on a Friday night, they were able to seat us in the second dining room, which we had to ourselves throughout most of the meal. This kept things quiet and allowed the conversation to flow! We had good service - they did a great job of being attentive, but also allowing us space to talk.\n\nMost everyone seemed happy with everything they ordered. My mom's salmon salad came in one of the most enormous bowls I have ever seen! And so did my friend's pasta. So these were pretty decent portions (except for my mother-in-law's scallops, which was a smaller plate). One of our friends ordered the Bison burger and it looked amazing! I got to try one of the fries and it was definitely on point.\n\nMy husband, my father-in-law and I ordered the special: Veal T-bone with sweet potato and bacon gratin and brussel sprouts. The brussel sprouts weren't roasted quite enough to my liking (my husband and I like them practically burnt), but they were seasoned quite nicely. I've never had veal, so I had no expectations going in. It was cooked perfectly and the seasoning was nice. But I have to say that my personal favorite is still filet mignon. However, I'm glad I had the opportunity to try this in a place that did it right. My favorite part of my entree was definitely the gratin! As far as I'm concerned, you can't wrong with sweet potatoes and bacon, especially when you cover them with PLENTY of gooey cheese!\n\nI have to say that dessert was my favorite part of the meal! My father-in-law immediately pointed out the Chocolate Fritters to me - he knows my sweet tooth so well. While other desserts sounded like safe bets, I've never found chocolate fritters anywhere else, so I knew that's what I needed to try. They took balls of Bailey's chocolate, covered them in funnel cake dough and fried them. While I have no idea how one can eat these balls of magic without dripping melted chocolate all over your face, hands and the table, I didn't really care, because I was in chocolate heaven.  Also, the fritters paired perfect with a scoop of Cinnamon ice cream (Bailey's Cinnamon ice cream). \n\nMy mother loved her Butterscotch Creme Br\u00fbl\u00e9e and my friend loved her flourless chocolate cake. Although I think the latter definitely came in second as far as chocolate options went.\n\nHowever, I would have to warn against brunch based on a prior experience. It was more strange than anything....I ordered the skillet and the ingredients that were listed on the menu, were not the ingredients that arrived on my plate. The brussels sprouts, onions, eggs and cheddar were there. But the sweet potatoes had been replaced by regular potatoes and the red peppers were replaced by tomatoes. Doubly disappointing to me considering my extreme love of sweet potatoes and then my distaste for tomatoes mixed with eggs. I was also disappointed because there were only three chunks of potatoes in my huge skillet and I'm not sure that there was any bacon at all.\n\nThis makes me so very torn as far as a rating goes!! But I think that for now I will give them the benefit of the doubt and give them a 4/5 based on an awesome dinner. I'll try another day for lunch and dinner and hopefully they will convince me of their awesomeness!"], ["One of my favorite restaurants in St. Louis!  The food is excellent and the menu has enough variety to make almost anyone happy. The staff is wonderful and they remember what you like. They also make great wine recommendations, and they've never made one we didn't like. This is also a great place to get oysters. They almost always have blue points, and they are sweeter and fresher than what is served in other restaurants in the area."], ["I love the late night happy hour and 1/2 priced appetizers that are YUM, but I was in for lunch recently and was disappointed with the food.  I had the cucumber bisque and the fish tacos.  The soup was a bit rich, but it was tasty.  The tacos were breaded with a tasteless, hard-to-bite-through corn coating and a rich sauce, and the fish was dry.  It was really bad.  \n\nMost of the group were disappointed with their lunch, except for those who ordered burgers.  Those who ordered burgers loved them.  I'll stick to happy hour..."], ["Was really looking forward to having dinner at this place on Saturday evening. Unfortunately the food just wasn't prepared with the love that I've experienced at other places in the St. Louis area. Had the shrimp puff appetizers. They ok. Nothing real special. Our table order the special, amberjack. They could not eat it. Sent it back. Our scallops were not cooked properly. Raw in the center. Salad was good. The only reason for giving 3 stars, the service. With the amout of new restaurant in this area, I think I'll skip Herbies and try some of the others next time."], ["TERRIBLE - TERRIBLE SERVICE. a friend of mine asked the waiter if she should order the filet or tuna .. He said \"The tuna is healthier.\"  I wish I was joking! The waiter was rude and did not pay attention to our table. It's unfortunate because the food was delicious!"], ["I went with my girlfriend on my bday for brunch, although the brunch was good, I probably wouldn't return for brunch but definitely want to try there dinner.  The ambiance is very relaxing and beautiful.  The brunch menu just wasn't selective enough for me as I am extremely indecisive."], ["My husband and I went here for our anniversary. They took wonderful care of us and were even kind enough to put the champagne and dessert on the house. My filet mignon was amazing. Melted in my mouth!! I highly recommend this place."], ["I have spent many an evening at the Herbie's bar for live music and even their entertaining updated version of the gong show. This was my first visit for brunch, though, and I was thrilled.  We went to celebrate my father's birthday, and our server and many other helpful attendants gave us VIP treatment all the way.  Mimosas all around, and it was good champagne with fresh-squeezed juice.  Very high quality coffee as well, perfectly brewed.  I have seen even some higher end establishments cut corners with their coffee service, but not here.\n\nI had eggs madison, which is a version of benedict with salmon and capers.  Absolutely delicious!  The hit of the brunch was what my mom and BF got, the morning flatbread.  A very crispy crust topped with eggs, cheese, bacon, and veggies- prepped pizza style so there was a lot and it was easy to share.  I thought my mom was going to kill my dad for ordering the very rich and I'm sure unhealthy country fried steak with bacon lyonnaise potatoes, but it was his birthday, and the dish was decadent and fabulous.  I also tried the pain perdu, cinnamon french toast that was tasty, even though I go for savory over sweet any day, even for breakfast.  \n\nThe chef stopped by the table to wish my father a happy birthday, and brought out a turtle cheesecake with ganache...wow!  My dad was very touched, and the dessert was fantastic.  \n\nYou get what you pay for at Herbie's, but it is on the pricey side.  This is a brunch spot that will be reserved for special occasions as it is a little more expensive than a typical brunch.  Well worth the birthday splurge, though!"], ["I went here last Saturday and the food was phenomenal! The group I was with had a variety of food. I personally had the lobster mac and cheese and it was delicious. The portions are perfect! Also we had josh as our server and he was one of the best servers I have ever had. One thing that he did was after he put in our order he asked us if we had somewhere to be. I thought that was very considerate because our food was out in a timely manner. We only had an hour and a half before the money and we were out of there in plenty of time. I would go back to this place and would recommend it to anyone!"], ["What a HUGE disappointment. I have been to this restaurant for a few functions and found it adequate. But this time we came for dinner with another couple and we were totally disappointed. \nService=atrocious, meal=atrocious\nFour meals and 2 of the meals were sub par..filet under-cooked and tough as a $5 steak. Flat bread way over cooked. other meals were a let down as well. WAY OVERPRICED!\nNever will go back, not even for a function. Will cross the street and have a better meal."], ["Herbie's has been outstanding on several occasions.  Herbie's worked well for my group of girlfriends for dinner. Herbie's provided my husband and I a nice romantic dinner.  And Herbie's scored rave reviews with my boss's business guests from Seattle and Chicago.  Herbie's is a restaurant that you can count on for great food, great service and a great experience."], ["We were celebrating our 25th Wedding Anniversary and I won a gift certificate to a 4-course meal at Herbie's Vintage 72.  It was on a Sunday evening.  Although we had reservations, at this date and time it was not necessary.\n\nOur table was in a romantic corner where we sat close to each other on a lounge seat.  We were asked if we had any dietary restrictions and off they went.  With each course came a glass of wine and a brief description of what we were eating or drinking.\n\nFresh bread and creamy butter was also included along with large and wonderful vintage artwork throughout the dining room.  The food was served in small portions with each bite adding a delight with the appropriate wine of variety and taste.\n\nWe had a wonderful time."], ["I came for brunch on Sunday and absolutely loved it.  The Madison eggs Benedict was terrific. I also think the sausage gravy with the cheddar drop biscuits was absolutely to die for! Great atmosphere, friendly staff, superb food, reasonably priced for the quality you get. I would go back in a heart beat and heartily recommend it!"], ["I heard Herbie's was moving so I wanted to catch it one last time in its old place.  While the ambiance and service are still wonderful, unfortunately the food has not held up as well. Their staple beef Wellington was rather bland. Their layer of mushrooms was sparse and the sauce didn't do it for me. \n\nWe also had the filet, which was wonderful but the sides where terrible. I appreciate crisp green beans but these were raw. And the mash potatoes were swimming in butter making them more a soup of potatoes vs mash.   Oh and we got the lobster tail with the filet. It was $10 and I figured why not. Well at $10 I think I paid too much. It was so rubbery I thought I could bounce it off the table."], ["We are big fans of Hell's Kitchen so we searched online for a place to go in St. Louis to get Beef Wellington and Herbie's came up. It did not disappoint! Herbie's is excellent. We did our own version of a surf-and-turf by ordering a beef wellington and a scallop entrees and split them between us. Outstanding!"], ["A couple of my girlfriends' and I came here to try their \"famous\" weekend brunch.  Honestly, I don't understand the hype...umm, at all.  \n\nWe arrived around 10:30 AM. and the place was basically empty.  I see a lady seated at the bar and there was another table with 4 people.  We ask the hostess for a table for 3 and she asked us if we had a reservation.  When we said no, she looked at us like walk-ins were forbidden. Which whatever that would be completely fine if reservations were required, ONLY if she didn't glare and say it in a tone like: \"duh...don't you know you need a reservation 'here' especially considering today is the first day of the Groupon and we anticipate being too busy to seat you in this empty restaurant at 10:30 AM?!\"  Obviously, lol, we did not know this, but she was able to \"squeeze us in.\"  All you had to do was explain it, lady.\n\nI ended up going with the three cheese omelet.  I got mine filled with sausage, bacon, and veggies.  It came with roasted potatoes and I selected a bagel and cream cheese as my toast option.  I just had coffee to drink.  \n\nNothing fabulous or memorable about the food. I'd say the best part of my meal was the roasted potatoes because they were crispy and probably the most flavorful part of my plate. The omelet was aight, but it was teeny tiny.\n\nOkay- So you know when the food can just be \"ok,\" but the service is so over-the-top excellent that it will literally bring you back in?  Maybe that's just me, but customer service makes the World go around! haha.  \n\nWell that's how this place could have been...the atmosphere was cool, I love the CWE, and the food wasn't bad at all.  But GOOD GOLLY the service!!!  I understand we chose a bad morning for the fact that it was the first day the public could use their Groupons here.  But c'mon, who serves you black coffee and hurriedly disappears for 15 minutes without give you a chance to ask for cream and sugar.  And when you get the cream and sugar not bring a spoon?  Or who gets stopped for a side of ketchup without seeing if the rest of the table needs something else before frantically disappearing for another 10 minutes only to bring back a single scoop serving of ketchup to have to go back in the back to get more ketchup because the other two people at the table needed some too, but you literally sprinted away before we could ask.  \n\nThe table that was seated next to us waited on their Mimosas for, I swear, at least 20 minutes.  By the time we left, they didn't even have waters- they had to get up and go to the bar and tell a manager.  \n\nI mean....it's the little stuff, I guess? lol\n\nIt's disappointing because I have ONLY heard amazing things.  Anywho...maybe I need to try their dinner.  2 out of 5."], ["I loved the brunch here! The new items were so yummy. I tried the cheddar drop biscuits with gravy and they more then satisfied my appetite."], ["I love going to new restaurants...even if it's the 4th or 5th time it's been 'new.'  I must say, that my first couple trips to Herbie's were experienced with Yelp on the mind. \n\nFood:\nI wanted to try every dish that my group had, and I tried to order my food with great variety in mind.  Another point, I should add, is that I consider myself to be a connoisseur of French Onion Soup.  I have scoured the world in search of the best offerings.  Quite honestly, Saint Louis has little to offer in the ways of French Onion, that is until now!  Herbie's french onion soup was delicious!  I can't wait to have it again. (if it changes, I'll let you know) I also had the carpaccio, and it was well complemented with capers, fennel, onion, and a delicious horseradish dressing.  For dinner, I ordered the amazing peppercorn tuna, which the chef recommended med-rare, but it actually tasted a little better medium.  The duck was well cooked, and not overwhelmed with dressings and glaze so that the natural flavor came through.  The chicken was succulent and paired with excellent whipped potatoes and vegetables.  All in all the food was delicious this last time around.  I really think Herbie's is starting to hit stride, as when I went the first time a couple weeks ago, it would be described as dismal.\n\nAs for the service, it was impeccable.  The chef gave us 2 complimentary dishes in between courses, and the manager, Tim, came by our table to introduce himself and ask us in a non-intrusive and sincere way how our dinner was going.  The wait staff was extremely attentive, and the food and drinks came out quickly without ever feeling rushed.\n\nI took off one star, as the beef wellington was (for lack of a better word) inedible.  I couldn't even finish it.  If Herbie's becomes more consistent with all of their dishes, I'll be happy to revise my review. All in all, a great new place to eat, and I'm glad the doors have been re-opened! Highly recommended!"], ["Another wine & food filled night at Herbie's last night!\n\nThe atmosphere is still pretty killer for me, and an obnoxiously large group of us took up on of the corner bar tables in the front room. Our server was MIA most of the time which was a little frustrating, but you could tell she was swamped. The chardonnay by the glass I had last night was just okay... okay enough to have three glasses of it, but I digress. \n\nTried some new dishes last night!\n\n-Lobster mac'n'cheese (lobster tail meat, corn, four cheese mornay, truffle oil & asiago gratin) - I don't even like lobster, but this was GOOD! Really rich though. Order the entree size because even that one isn't that big.\n-Vegetable Lasagna (ribbons of squash & eggplant, mozzarella cheese & marinara) - I can't wait to order this one again. It was huge and people kept begging me for bites! Big flavor and filling even sans meat.\n-Florentine Flatbread (spinach, artichokes, mozzarella & jalapenos) - I didn't get to try this one 'cause it was at the other end of the table, but it was gone faster than I could believe.\n\nI really do love the food at Herbie's... the service needs an upgrade, but it's still worth the occasional intimate dinner or cocktail with friends!"], ["Went back again for my birthday and still delish!  Started with mussels and pinot grigio and i had scallops for dinner....Amazing!!!  The restaurant part was not that busy, but the bar area was hopping...LOVE this place:)"], ["Server was good but raw chicken puts a bad taste in your mouth. Manager apologized but only offered 1/2 off entree. Poor move."], ["Recently, my husband and I decided we were overdue for a date night. It was decided that we would head to the CWE, but where? After deliberation, we opted to try the \"newest\" \"old\" restaurant in the neighborhood...Herbies: Vintage 72.  As a nod to the beloved CWE haunt created by the late Mr. Balaban and respectivley encased in his vision, this restaurant definitely embodies the \"old-St.Louis\" charm that I have come to appreciate.  I had been to the old Balaban's a number of times so I was looking forward to trying out the new spin on an old classic.  We arrived an hour before our reservation time and happily valeted our car for $3 (what a steal).  We found seats at the bar, which looked impossible from first glance.  The bartenders were very knowledgable as well as helpful allowing me to taste a couple different wines before making my selection.  There we sat, me with my wine and my husband with his super hoppy beer just taking in the scene!  \n\nAn hour later we were escorted to our table, which was a perfectly positioned window seat table looking out onto Euclid Ave.  It took about 10 minutes for our server to approach our table, she was pretty slammed with a large group seated next to us.  We didn't really care, there was plenty to keep our minds occupied and gave us time to weigh out our menu options.   After carefully selecting the escargot as an appetizer and the lobster mac n' cheese and duck for entrees we were ready to eat.  The escargot was excellent...the best part was dipping the bread in the leftover buttery goodness, yum!  As for the entrees, I would happily take down another plate of the lobster mac anytime, but might pass on the duck. It was pretty dry and the wild rice that accompanied the dish wasn't cooked enough for my liking.  An extra-dirty martini capped off our experience, who needs dessert when you can have a perfect dirty martini with blue cheese olives;)   \n\nOverall, it was a great night, good crowd and pretty good food!  We will return..."], ["Loved the atmosphere! They were relaxed that we wanted to have a drink at the bar before dinner and held our table.  our server was AMAZING. my husband had mentioned in passing he didn't eat cheese, and the server automatically requested the dairy ingredients off of our carpaccio appetizer without us even asking. The food was a tiny bit bland but overall we had an awesome time and will definitely be back."], ["Before I was invited to dine at Herbie's last spring, I'd never heard of it although I lived in St. Louis my entire life before college and was a huge fan of the Central West End.  The name struck me as much less refined than the restaurant actually is - but it was a very pleasant surprise.\n\nA reservation, especially on the weekend is \"strongly encouraged\" (ie: you don't make one, you won't get seated in the dining room, only the bar area if you're lucky).  My date was aware of this though (apparently the above scenario had happened to him in the past) and we were seated promptly after we arrived.\n\nThe restaurant is very nicely appointed - it oozes old school charm with dark wood, parquet flooring and low lighting.  Our waiter, however, was a little sketchy.  He just didn't seem like he'd been at the job very long - a little awkward is really the best way to describe him.  I'll say I wouldn't have chosen him first to be the \"customer-facing\" side of the restaurant - but oh well, not a big deal.\n\nWe ordered a good bottle of red wine and a cheese plate to start.  The cheese plate came out on a plank with three different types of cheese, dried fruit and NO bread or crackers!  Huh?  How are we supposed to eat the cheese - especially the soft brie, without something to put it on?!  So we had to awkwardly ask for bread, which was brought out - but really - we had to ask!  Not so great, Herbie's.\n\nThe rest of dinner was very good though - I ordered an excellently prepared salmon that came on a bed of zucchini, quinoa and leeks, and my date had the lobster mac n cheese - which was quite possibly, the richest mac and cheese I've ever seen.  It even comes in two sizes depending on the level of your hunger - I would recommend the smaller portion, personally - even that was generous.  We were quite full at the end and didn't have room for any of the excellent desserts available.\n\nSo!  Except for our slightly creepy waiter and the appetizer incident (I'm sure that was just a kitchen oversight), it was a great experience.  If you're looking to impress on a first date or really put on the dog for the in-laws, Herbie's is a good choice."], ["We stopped in for a drink and desert one night last week. It was my first visit and as a frequent fixture in the CWE, I am not sure why I have never been. Anyway, the Summer cocktail was amazing. The chocolate bread pudding came highly recommended at it did not disappoint. It is one of those deserts that I would go out of my way to get. Lucky for me, I live close by. I am only giving this place 3 stars because I am BIG on service and our server was cold and aloof. I am not looking for a long term friendship, but a smile would be nice. \n\nI will definitely be back for that dessert..."], ["I mourned Balaban's closing to the point that I resolved myself to never walk through Herbie's doors out of respect for what once was.  Good thing I rarely hold true to my resolutions!\n\nHerbie's was excellent.  We sat in the bistro section next to the open windows on a beautiful evening.  The service was wonderful from start to finish even though it was a very busy night.  \n\nBIG props for having a gluten free menu.  It's always great to have a knowledgeable chef when it comes to gluten free but it's a real bonus when they actually print out a G.F. menu that spells everything out for you.\n\nMy filet was cooked perfect medium rare.  Spinach could have used a tad more seasoning but that was easily taken care of.  Potatoes had a great garlic taste without being overpowering.  Also had their play on a mint julep--think it was called a Kentucky Sweet.  YUM.  Also had their, I believe it was the house, salad.  Delicious.  Tons of bacon, avocado, and the best ranch dressing I've had in years.\n\nOverall, an excellent way to spend an evening in the Central West End."], ["Can't remember his name, Steph maybe, but wow.  We had a great experience and we're talking about it the whole way home.  Thanks dude.  Be back soon"], ["Between the excellent service and tasty food, my out of town clients were thrilled.   The duck confit was awesome and plates were virtually licked clean...awesome experience...thank you"], ["If I was writing a review about dinner at Herbie's it would be 4 stars edging towards 5.  This review, though, it just for brunch.  We went to brunch with a group of 6 and while there wasn't anything glaringly wrong...there wasn't anything fantastic either.  \n\nI had the three cheese omelette with sausage and veggies added.  It came with roasted potatoes and choice of bread.  The omelette tasted great and the filling was delicious but it was seriously the tiniest omelette I've ever seen at a restaurant.  The roasted potatoes were actually just french fries.  I was literally hungry within an hour of finishing brunch.  They were able to accomodate a gluten free diet but not with very many choices.  Herbie's caters so well to gluten free for dinner that we were very disappointed with what felt like neglect on the brunch menu.  While Ryan did enjoy his food (eggs benedict with salmon and capers), it was nothing spectacular.  \n\nOur group had a coupon that included cocktails but without that, I would call Herbie's brunch unnecessarily pricey.  I enjoy spending money on good food but for the portions, this was just flatout overpriced.\n\nI'll be back to Herbie's but it will definitely be during dinner hours."], ["I've been a fan of Herbie's for a while but a recent Friday night spent in the dimly lit bar area with champagne cocktails and good friends won me over completely...\n\nWhen I say dimly lit, that's exactly what I mean. It's almost TOO dim, but it's not, so it's perfect for an intimate evening with friends or a significant other. The dark wood, fancy cocktails, and sophisticated menu all come together for the perfect atmosphere.\n\nI've tried a number of cocktails here, and I recommend any of the champagne mixers as well as any of the martinis. They have a really extensive wine list ranging from $8/9 glasses to hundreds of bucks for a bottle. If you're sitting at the bar, just tell the bartenders what you typically like and let them craft something up for you. They know what they're doing for sure.\n\nI'm usually here for drinks & light food, and I love the spinach artichoke dip appetizer as well as the BBQ chicken pizza. The dip comes with big pieces of crusty bread, and the pizza is topped with homemade BBQ, fontina cheese, red onion & chives. DELICIOUS. I've also had the vegetable pot-pie which was good, but it took almost 40 minutes to cool down to where I could eat it. If you're wanting something a little more filling, go for the roasted butternut squash ravioli. Sweet, salty, satisfies everything.\n\nHerbie's = classy and sophisticated with top-notch food and drinks. Stay there all night drinking fine wines, or get boozed up and head across the street to Club Viva! Whatever you prefer."], ["Herbie's (Balabans replacement) is located on the corner of McPherson on Euclid. It's not quite as populated as Maryland and Euclid, but with galleries, cafes, antique shoppes and bookstores, it's still a great people watching corner in the Central West End. \n\nI never caught on to the old Balaban's craze, as it was always a bit upwardly crusty for me. High prices, expensive purses, fake boobs.... you get my drift. While Herbie's still captures some of this group and the prices are still slightly high, I do think it's an improved version of the old Balaban's with edgier decor, and clientele. \n\nWhat I like most about Herbie's is their late night happy hour (weeknights at 10:30 pm). I stopped in with a large group of friends after a local event on a Tuesday night. I missed dinner and was starving. \n\nHerbie's has a bistro menu in the bar and at 10:30 all appetizers are 1/2 off. We ordered the mother load (escargot ($4, calamari $4.50, Carpaccio of Beef Tenderloin $5, seafood crepe $4.50, Smoked Missouri Trout salad on mini corn pancake $4.50, and Shrimp Ceylon $5). All of the food was excellent, and the drinks were on special too, \n\nWhile Herbie's is a little pricey for my regular taste, I will be back for the late night happy hour. Especially if I'm hungry. I hear the brunch is good too."], ["The quality of the food i just 'ok'. I like to come to Herbies for the Justin Cabernet and the beautiful decor (aka black wall paper- my favorite) in the bar area. I've never had an amazing meal here. \nThis is place you go to get a pre- dinner drink and then head over to Pi across the street or anywhere else in the CWE for a meal."], ["Been here  a number of times over the course of 25 years. Can be hit or miss as the new Herbies. Last night was great. French onion soup, Cesar salad, escargots, shrimp/grits, scallop and steak frites. Service started weak and ended strong. Great vibe on bar-side on Sunday/ live music night."], ["What's great about Herbie's is that it's a great restaurant AND a great bar. Some nights I go just for dinner, some nights I go just for drinks. The bar staff is great and the cocktails are fantastic. Sometimes I go for happy hour drinks and end up spending all night there...\n\n The food is enjoyable as well, and the menu has great variety. Lots of fine dining choices, but you can also get a hamburger. Service is always good."], ["Yum. Yum. Yummy. Another visit to Herbie's tonight.  Wednesday is oyster special night and I was looking forward to that. \n\nWe sat at the bar as usual (you can always find us sitting at the bar).  Wayne took care of us and brought us our drinks. He makes a great margarita in a rocks glass.  We decided to share the appetizer of fried oysters.  I was a little disappointed that there were only three oysters.  They were delicious and came with a dipping sauce - maybe a vamped up thousand island dressing. \n\nMike ordered the Bison Burger for dinner.  There was some discussion as to how it should be cooked.  Apparently if it is over cooked it can get a little tough. I believe he settled on medium rare.  I decided on the classic flatbread.  Flatbread (pizza) with sausage, pepperoni and three cheeses.  Both our meals were very tasty and we left as happy people. \n\nThank you Herbie's for another great meal."], ["A week or so ago there was a Groupon for brunch at Herbie's. I'd never been there before and I wanted to try them for dinner (didn't even know they had brunch) but decided to go with brunch anyway. The Groupon was $20 and you could only get two drinks ($8 each) and two entrees ($14 each.) \n\nWe had to make reservations because when I called in at 12:00, there wasn't anything open until 1:30pm. So I recommend making reservations even for brunch, which ends at 3pm btw, that wasn't anywhere on their website or Groupon, so I had to call and ask.\n\nWe ended up getting stuck parking in the lot with the attendant except there was no attendant at all and there was a sign saying to put a coin in the meter box but it was Sunday and lack of attendant made us think parking was free. Bad assumption, but you can read about that at the end of this review.\n\nWalked inside Herbie's. Neat looking old building, and I love the antique cash register with the copper drawers. It smelled....weird, though. Not an appetizing smell. Sean told me he used to valet for them a few odd years back and it smelled the same as it did then. Ick. \n\nI ordered two glasses of OJ. They were $3.50 each which ended up being $7. I don't know why I didn't think to just get a mimosa. There was no cocktail menu to be found and the server didn't offer any. It didn't specify what type of drink so maybe alcoholic drinks were okay. But maybe not. I don't know. The mimosa might have cost $8.50 for all I know just so that it couldn't be used for the deal. My entree (Eggs Benedict classic) cost $10 and Sean's pancakes cost $7. Yeah. Not exactly $14 each. And this was supposed to be brunch for two. He wanted a side of potatoes which the server charged us $2 extra for even though our entrees were most definitely under $14. Uhhhh. Weird. I dunno if this is Groupon's fault or the restaurant's. But whatever. Mildly annoying.\n\nThe server, btw, was one of the most awkward human beings I have ever encountered in my life. He kind of mumbled and talked really languidly as if he was high on some kind of drugs or maybe just didn't sleep for a week. Either way it made for a really awkward experience. We didn't really feel welcome and I was counting down the minutes until they took our plates so we could pay and leave.\n\nThe food was only \"okay.\" Oddly enough Sean's pancakes were MUCH better than my Eggs Benedict, and I didn't think I'd end up saying that! My dish seemed really under-cooked, in terms of the eggs. They were poached as quickly/lightly as possible so that when I went to cut them, the yolk literally squirted out like if you were to pierce a water balloon. Ew. It gushed and gushed...and it was also hard to use the English muffin to absorb some of the yolk since they weren't too absorbent. The Hollandaise sauce looked like the time I attempted to make my own using a packet of powder from the grocery store. There were little orangey lumps in it which suggested to me that they did not whisk it sufficiently. Yeeeah.\n\nAltogether our meal was about $26 or so with tax. We ended up saving only $4 with the Groupon and then we had to tip, of course, and I did leave a decent tip even though the server was a total space cadet, at least the food came out within a reasonable timeframe.\n\nBut the real icing on the cake was that the parking lot attendant somehow conned us into paying $5 for an hour's worth of parking. What a freaking joke. \n\nI am not sure if I'd go back....maybe for dinner, because Steph's chocolate fritter review sounds prettyyy good. But I am not in any hurry especially due to parking situation & the overall awkward service. It's crazy how good service makes a world of difference. I also feel bad knowing that the restaurant probably didn't make squat off of the Groupon. The more I learn about Groupon the more I want to stop using it."], ["When I come home from LA I come here. I have a history with Herb and Adelaide and I grew up in their places. Now they are gone to other lands, and the guys and gals who took over have a large reputation to fill. Its not the same but terrific. Its not the old daze but what is. Its still terrific food, and I am pleased to come in remembrance. Great seafood, and meat dishes. All good. Some traditional Balaban's items. You gotta love that."], ["I went here about two years ago for the first time and ordered the lobster mac and cheese and thought it was just the best thing ever and told people it was the most expensive mac and cheese I have ever had ($30) ... and well worth it.  It was nice to find on this trip that it was just as good as the first time with plenty of lobster chunks.  I'll probably get it every time I go.  I also ordered the house salad which was pretty decent, the shrimp and grits, good but still spicy for me, and the scallops which were excellent.  We had a small issue with a previous credit my date had with her but the manager to his credit handled it very well.  Also, not always a fan of small tables to have dinner on but Herbie's I do believe is meant to be more on the romantic side of places so I'm okay with it.  \n\nAs we sat fairly close to the front entrance we would get drafts of cold being a winter night but they also handled it reasonably well given the double door entrance and use of curtains.  \n\nHerbie's retains a good imagine in my mind and I would easily go back again."], ["First review ever for me..   Went there on a Sat night. Sat in the bar which was dead, which is fine..  Took 15 min for the waitress to come by and she did when my gf was in the restroom and proceeded to take my order before she even had a chance to see the drink menu.\n\nLeft us drink menu s and vanished for 15 min( 10 people in the bar). She finally came back to take the drink order and then took ten more minutes to get the drinks because the space cadet bartender was taking to her friends at the bar!!  The whole time the owner is socializing with a small group at the bar oblivious to the rest of his restaurant.  Then a busboy finally brought our drinks.  OK. Food was good service was terrible I can't keep typing but you get the drift and it's making me mad anyway sad to see the place going down.  Btw... The ONLY employee in the restaurant with a good attitude was the busboy who brought our drinks. He got the vast majority of my sizable tip!!"], ["Ive lived right near here for 2 years and never heard too much about Herbies. Though I was very impressed and surprised more events and dinners aren't held here. Great vibe in there with tons of large groups. And it's safe to say it has the best shrimp and grits in St. Louis!! I wish I could say anything about the other dishes but the shrimp and grits are too good"], ["I had a fantastic night here.  Our waitress was super friendly and helpful.  We started with a risotto ball type thing that was amazing, can't remember the name.  I got the mushroom crepe for dinner and it was pretty good.  The Cesar salad was ok.  My date got a steak I think, and enjoyed it.  Great wine list."], ["Love, Love, LOVE! I use to live around the corner from Herbies and frequent this place often. They have a great happy hour! It's very upscale but not snooty. \n\nReuben is the best bartender in the place! Tony's alright too ;)\n\nThe dinner menu is a bit pricy but it is great food in a romantic atmosphere. We have moved farther away so now we go to Herbies for a special occasion or to visit Reuben (he really is that great). \n\nLater at night people tend to stay after dinner or come in and it turns into more of a swanky lounge/bar. Great for ages 25-50 at night, it's a very diverse crowd. \n\nLastly, on Sundays they have a fabulous brunch."], ["Had only been once before in this space's incarnation as Herbie's and due to Balaban's legacy I gave it the benefit of the doubt. \n\nSo, on a whim we tried it for Saturday brunch. \n\nThe all-over stickiness of the table top should have tipped us off. Maybe we should have figured out something was wrong when the flat soda arrived. Twice.  We certainly should have gotten the picture when the burnt waffle arrived for our toddler on a scalding plate. But, no. We stuck around for the tomato soup masquerading as gazpacho and the saddest salmon plate and the grease soaked burger and fries.\n\nAnd out server, while very sweet and very polite, seemed to lack the necessary training, experience or both.\n\nThe upside? From our table we could see two better restaurants."], ["Sentimentality forces me to write this review, and in the interest of full disclosure, I am somewhat biased. I was a server at this location for ten years. This was when it was Balaban's, a classic STL establishment and a great place to work. The food was world class and the service standards very high. I dine at Herbies once a month or so, and struggle to refrain from making comparisons to the Balaban's Days. However, I want to say that I think that Herbie's stands on it's own as one of STL's better eateries. The service is consistent and while the food falls a little short of what was served in the \"glory days\", I have almost never been dissatisfied with my meal. The exception- the Lagorian (sp?) Pasta is a dish I crave and last time I had it, the pasta was overcooked and had absorbed too much water, far from al dente. I have no doubt that if I had made a peep about it, it would have been promptly replaced or substituted. The service and management, front and back of house, is top-notch. I always have a good time at Herbies. So if there are a few of you who pine for the good old days of Balaban's, give Herbie's Vintage 72 a chance."], ["Have been to Herbie's a handful of times and had decent food. Went back last night for dinner and had the scallops...during the course of the dinner my front tooth was chipped on a shell from the scallops, which, obviously we're not prepared properly...I stayed calmed and collected, which obviously was a mistake, our server Josh, was great...the manager Sean, however was not... I went to the restrooms to look in the mirror and snap a pic of it...as I came out, I was approached by Sean, who try to tell me he don't see how I could have lost part of my tooth from the scallop....we exchanged phone numbers...when the bill came I was still charged for my meal!! When I approached the manager again, he said, well I thought everything was ok...I said, so, I guess I have to cause a scene for anything to be done about this?!?  Won't ever be back, fair warning, management doesn't give a crap!!"], ["Solid food and service.  It does not look very fancy from the outside, however food is solid American with a gourmet touch that makes for a memorable experience.  Great for a hearty meal or for drinks and apps in a classy setting."], ["Went here for our anniversary a few days ago.  It was quite good, and I'll go over the various elements. \n\nSo breaking it down:\n\nFood: Food was very good in most cases.  We had the shrimp dumpling appetizer which was extremely flavorful and my husband that normally does not like shrimp even enjoyed it.  For our main entree I ordered the Wellington of Beef and he got the Pork Chop.  The pork was slightly overcooked but still tasted well enough and my husband doesn't like to make complaints.  The Wellington of Beef was extremely mushy and lacked flavor.  However - the manager was swift to offer me another option - the filet.  The filet was great, certainly one of the best I've had - top five for sure.  I have to say the highlight for me was the desserts.  My husband had the cheesecake with chocolate sea salt and I had the Butterscotch Creme Brulee.  Both were a huge highlight for us.\n\nAtmosphere: The general decor and building is pretty, but it is obvious it's an older building that would benefit greatly from some small repairs.  In many cases small dings gave it a presence but there were areas where the old fashioned tile was so broken up that it subtracted instead of added to the overall theme. \n\nService: - The service was exceptional.  The waiters were attentive, the manager was quick to address issues (detailed above) and they were even so kind as to give us a free dessert after learning that it was our anniversary - I thought that was quite classy of them.\n\nOverall:  I feel they are a solid four.  Given they weren't perfect but certainly still very good.  It was a good place for a special occasion but certainly too pricy for a more casual meal.  Worth trying at least once I'd say."], ["The Blackened Tuna was amazing. Oatmeal chocolate chip cookie dessert was completely incredible. Be sure to get the Zassafras if you're a rye whiskey fan! Oh, and the wine flights are fantastic."], ["I took my wife for a fine dinner on Valentine's Day along with some friends. She ordered the Filet and her friend got the Beef Wellington. She took one bite and told me to try it. It cost $28.00 for the filet. The filet and the beef wellington had no flavor. The salmon,sea bass, and oysters were fine. I could have went to Longhorn and had 2 steaks that tasted better because I had just ate ther less than 30 days ago."], ["My friends and I came here for brunch today because we heard about the $14 bottomless mimosas and delicious drop biscuits. The restaurant wasn't super busy so we would've probably been fine without a reservation. We were seated promptly, I ordered the unlimited mimosas, and within 2 minutes our server came back with our drinks. I would like to give a shout-out to our server Francesca because she made sure that I always had a full champagne flute of mimosa in front of me. 5/5 star service!\n\nUnfortunately I can only give Herbie's 3 stars because we waited very, very long for our food. The drop biscuits looked a little burnt and were cold by the time they arrived at our table. The biscuits were still savory and you could really taste the cheddar and chive, but I was really looking forward to a soft, warm biscuit. I also ordered the French pancake du jour (blackberry compote), which is basically a pancake on steroids. It was super thick and served on a hot skillet. The pancake was a bit sweet for my liking and I struggled to eat more than half of the dish. I expected the pancake to be fluffier but it ended up being pretty dense. \n\nI am not going to rule out future brunch dates at Herbie's because of one mediocre/bad experience. I would like to come back and order different brunch items or try dinner here. Hopefully it won't take forever for us to get our food next time."], ["We traveled to the Restaurant Formerly Known as Balaban's last night for drinks. The wait at the new Pi across the street was at least an hour and the bar was super crowded so we figured it best to try Herbie's across the street while we waited. It was a very interesting experience to say the least!\n\nAlthough the restaurant is very beautiful, the patrons are kinda gross. Definitely a great place to spot a cougar in action... For the most part, these people are so NOT a big deal, but act like they are. Ick. \n\nAnd our cocktail waitress was pretty terrible. She obviously didn't care about getting us our drinks quickly and pretty much expected a good tip. One of my friends left her a $7 tip (because he got tired of waiting for her to come back with a beer and just left a $10 on the table and went back to Pi) and she didn't even say \"thank you\" to us or try to find him to say thanks. \n\nGranted, I didn't eat here and maybe the food is better. But if you are looking for a cool hangout with nice, down-to-earth people, Herbie's is NOT the place!"], ["We Have been going to Herbie's for years and when people come into town it's always the favorite choice. We had company come into town tuesday night and again went to Herbie's for what we thought would be a excellent meal. We were so disappointed with the specials that night and one of the regulars on the menu...the crispy duck which wasn't crispy at all but fatty and somewhat roasted. It was served on tasteless spaghetti squash and wild rice that barely teased you with a taste of cranberry. I found two cranberries by the way...duck is already rich enough and if it doesn't have a complamentry accompanied with it it can really be not good. The mustard encrusted steak was just so so. To say the least, my guest will probably not want to return again which is too bad because Herbie's for the most part is always consistent...especially the service."], ["We were wandering about Euclid in search of a welcoming dinner place. Herbie's menu seemed a bit out of price range of a casual dinner for family of three (toddler and all), but we were getting hungry, and everything else seemed to be a bar and smelled like cigarettes, so in we went.\n\nWe ended up having a very nice dinner, apps, main courses, and a delicious beer. Kid was perfectly content with a thin crust cheese pizza, and hubby and I enjoyed shrimp and grits, and a strip steak with fixings.\n\nWe ordered a spinach/artichoke dip, which came with nicely browned long croutons, and was non-greasy, and non-cheesy, which we both noticed and thoroughly appreciated.\n\nMy shrimp and grits had very nice BBQ sauce in them, excellent flavor, and beautifully presented. The only downside here - TOO much sauce, everything was swimming in it, so I had to \"salvage\" delicious bits and eat my way around the sauce paddles.\n\nHubby enjoyed his strip steak, which also had some of the same sauce, mashed potatoes were nice and creamy.\n\nWe skipped the dessert.\n\nThe interior is beautiful, old school art nouveau / art deco type from 1910-1920, with some french posters, brick walls, and beautiful woodwork ceilings. I liked it. It was quiet, well lit and felt clean.\n\nService was well timed, attentive and non annoying.\n\nI'd definitely recommend this place for a nice date dinner, with a bit more than casual atmosphere and great food."], ["I enjoyed having brunch here this past weekend. The ambiance is great; I love the French decor and the feel of sitting in the terrace space with all the windows and light. The inside dining rooms looked pretty upscale and chic. \n\nI had the huevos rancheros benedict, which was really tasty. There was just the right amount of egg and sauce and bread. There was supposed to be smoked pork on it, too, according to the menu that I just looked up, but somehow I didn't notice it yesterday. Hmm, weird, but I guess it was so delicious that I overlooked it, so oh well. It also came with fried potatoes which were crispy and a nice surprise that I wasn't expecting. \n\nThe service seemed a bit on the slow side, considering it was less than half full. Our food took a while to come out; our server was apologetic, though. At least he knew it wasn't supposed to take that long. It was a good thing our friends had ordered the unlimited bloody marys to make at their bloody mary bar, so it didn't seem too too long of a wait for our food. \n\nI give them 3/5 stars for decent food (if a tad pricey) and charming ambiance, but slower service. I'm not sure I would go out of my way to come again when there are still so many brunch places I want to try out, but I wouldn't be opposed to it."], ["Really good food, but maybe a little overpriced. Service is always good. Surprisingly great brunch (breakfast flat bread!). Big chichi 35+ bar scene at night."], ["Came in late on a Monday.  Hungry after shopping.  Desperate for food.  Wow.  Unreal.  The pasta was perfect.  Bolognaise was perfect.  Thank you."], ["as i pass by herbie's on my bike to work every day, i say to myself: i really need to try that place. and i thought my boyfriend's birthday would be a great opportunity to try it. so i did. and i must say i'm happy i did. upon walking into the place, i found the ambience quite romantic...dimly lit, yet comfy...not pretentious. upon being seated in the dining room in a corner booth, i began taking in the room. nice decor...not overstated. however, i did find the music choice of 80's rock to be a little odd.\n\nback to the most important part: the menu. being a pescatarian, it was so nice to be given an entire vegetarian menu in addition to the regular menu that had a great seafood selection as well. and when i talk about vegetarian menu, i'm talking about a full vegetarian menu with more than 2 options of apps, entrees and salads. well hello!!! after much debate, my boyfriend and i made our selections. i started with the chilled cucumber soup...a beautifully smooth, satisfying soup with just a little kick to it. next, i tackled the roasted tomato & goat cheese bruschetta, sprinkled with a wonderful balsamic glaze, which was served with a small strawberry salad. so far, so yummy! my boyfriend chose the shrimp dumplings, which were just okay. he also had the carpaccio, which was served with capers and a fennel salad. since it had beef on it, i didn't try it. so i'll take his word on it that it was quite tasty. on to the entrees: i had the scallops with pureed cauliflower and brussel sprouts (it came with pancetta, which the chef happily left off, thank you very much). the scallops were slightly seared...perfect. the cauliflower puree...oh my. i wanted to lick my plate. add the brussel sprouts and i'm in food heaven! i tasted my boyfriend's tuna with tempura bok choy and an edamame corn cake. the tuna was fabulous, as was the bok choy. however, the edamame corn cake was a little dry and dense. and since it was his birthday we HAD to order dessert. we were stuffed to the gills, so we got it to go: chocolate chip bread pudding and gooey butter cake. we ate it 3 or 4 hours later, so my opinion may have been different had we eaten it fresh. first, the bread pudding. i have to say i LOVE bread pudding and tend to be a little bit of a harsh critic. and since we weren't eating it \"fresh\", i was prepared to be disappointed. but i was not disappointed...i was quite impressed. in fact, i wish i would have ordered two of them instead of the gooey butter cake, which i found dry and heavier than most gooey butter cakes. and i'm a fan of gooey butter cake.\n\none last note: the service. i found most of the wait staff to be attentive and engaging with exception to our waiter. we tried making conversation with him, but he seemed more interested in the rest of the dining room. at one point, my boyfriend finished his beer and was ready for another. he put his glass at the edge of the table and we timed how long it would take for our waiter to notice. 10 minutes! yep, 10 minutes later, he finally asked if he needed another drink. luckily, the kitchen staff asked if we needed anything else when they brought out our apps, and obliged with his drink. given the amount of money spent on our meal, i expected service equivalent to that of sidney street. expected, but not received.\n\ngreat, great food! nice atmosphere. we would definitely return, making sure we had a different waiter. now when i ride by herbie's, my tastebuds will be smiling!"], ["We were in town for a wedding and had some friends who live in St. Louis, so they were kind enough to meet us for dinner. They chose this place, which is located in a super cute area with patio tables outside on the sidewalk and string lights. When we walked in, it reminded me of an old school steakhouse.\n\nFood: To start, we ordered the short rib flat bread and shrimp dumplings to share. The flat bread was pretty good, but then again, who doesn't like short ribs on pizza? The shrimp dumplings were okay. They had a very thick outer layer that I wasn't a big fan of. I ordered the roasted chicken breast and my bf ordered the steak frites with the red wine demi sauce. My chicken was pretty good, nice and moist. It came with mashed potatoes and veggies. It reminded me of a steakhouse because everything was quite buttery. Not a bad thing, but also not a good thing when a girl has to fit into a dress the next day. My bf's steak was solid, but the frites were probably my favorite part (I have a soft spot for fried potatoes in any form).\n\nAmbiance: Classy and old school.\n\nService: Our waiter was very attentive. There also weren't very many people in the restaurant to begin with, though.\n\nDrinks: They have quite and extensive wine list, but I didn't partake in any. Their cocktails are pretty good.\n\nWould I return? Nothing WOW'd me and I'm always looking for a new place to check out, so maybe not anytime soon."]], 
            "review_rating": 3.7
        },
        {
            "business_id": "GOSVLhjUT6TnrPhkkmDOpw", 
            "name": "Vineyards Cafe", 
            "address": "847 N 16th St", 
            "city": "Philadelphia", 
            "state": "PA", 
            "postal_code": "19130", 
            "latitude": 39.969939, 
            "longitude": -75.163026, 
            "stars": 4.5, 
            "review_count": 192, 
            "is_open": 1, 
            "categories": "Coffee & Tea, Cafes, Food, Creperies, Internet Cafes, Restaurants, Breakfast & Brunch", 
            "hours": {"Monday": "0:0-0:0", "Tuesday": "7:0-15:0", "Wednesday": "7:0-15:0", "Thursday": "7:0-15:0", "Friday": "7:0-15:0", "Saturday": "8:0-15:0", "Sunday": "8:0-15:0"}, 
            "text": [["I honestly didn't know this place existed until my friend suggested it for brunch over the weekend. I can't believe I live four blocks away and haven't been here before! I ordered the honeybee crepe and an almond croissant. I'm one to typically bring leftovers home but the food was so delicious there was nothing left to take much to the surprise of my friends. There is a small seating area downstairs and some window seating on the first floor. I'd recommend getting there on the earlier side if you're with a group and want to sit. I'd also recommend this for smaller groups. Will definitely be going back."], ["All the crepes I've tried are fantastic. The coffee is very good, though I wish they had larger sizes available. Looks tiny from the outside there is comfortable seating in the basement."], ["I never knew this place was here.  \nA comfortable, clean environment with seating downstairs.\nI always prefer savory vs sweet so I ordered the Norwegian Crepe and it was so good and filling.  I would love to go back there and try all their other options... and maybe share a sweet one for dessert"], ["Amazing new find! Small cute cafe with VERY reasonable prices for delicious food. I tried the egg on Gouda crepe with bacon which was delicious and well stuffed. I just wish the Gouda taste was a bit stronger and that there was some type of sauce to go with it. The caramel ricotta crepe was DELICIOUS and very well prepared. I'll definitely be coming back to try the rest of their menu!"], ["This place is a favourite of mine in the Fairmount/Francisville/Temple area. Got the turkey goat cheese baguette sandwich and the lady had the Philly baguette sandwich (lox and cream cheese w/ tomato). Food was delicious. Iced tea and iced chai latte were both amazing as well. Cute outdoor seating. Everything was super clean and tidy and the staff was super friendly. Highly recommended for a late breakfast or light lunch"], ["I love to explore local small businesses and this one was a great find. It's a very nice small cozy and super clean neighborhood coffee and crepe restaurant. Staff is very friendly and their crepes are amazing. I tried the Honey bee which was good with mochachino. The prices are pretty affordable. It wasn't super busy on a Saturday morning."], ["Nice, small breakfast place run by a husband and wife who make tasty crepes for affordable prices. Pretty small menu but the crepes are worth a trip there."], ["Again I can't say enough about this place. Just split the phili (salmon, cram cheese and spinich) and honeybee. And the mochacino. Food is so good here and staff are great as well. Can't wait to visit again."], ["Crepes were fabulous! The location is slightly odd, but I guess that is the nature of Philly. Caramel Latte was delicious and a very good bang for your buck. They also serve juices from Rijuice which were very refreshing. I would recommend this to any Philly new comer."], ["I love the atmosphere and set up, it is very modern and calming. I also thought the omelet was good value, large quantity and good quality."], ["I don't know how it took me so long to visit this place. It's right in my neighborhood and it's AMAZING. I HIGHLY recommend to crepe lovers or newbies. They have so many options and everything we tried was delicious. I've been craving it since our last visit. And it's very affordable for a very large and filling crepe. Also they are great with customizing so really you can have whatever you want and it's delicious. Even if you're not in the area I would go! Heads up that there is seating downstairs but not a ton, so may not be great for large groups."], ["My wife and I drive all the way from Germantown here. It's our favorite coffee spot in the city.  Coffee is good and the food is always great. (Honeybee is my favorite).  The staff is also welcoming and efficient."], ["This place is amazing. Food is amazing. Decorations are amazing. Staff is very friendly.\nI ordered the Americano omelet and Nutella crepe. Both were crazy good."], ["Came with a friend to do some studying on a Saturday morning. We ordered two chai lattes and sat right by the large window at the front, which lets in a lot of natural sunlight. There's seating at the front and also more downstairs so it's a great spot to bring a laptop and do some work (plus the staff were very sweet as well). \n\nThe latte was made from the purple Oregon liquid chai mix (which a ton of people use). It's a little too sweet for me so next time I'll probably just go with a tea."], ["Amazing crepes!! Very thin so I wasn't expecting it to be filling but it was! The atmosphere is very casual, more like a coffee shop than a restaurant. You can see people studying on the bottom floor. I would recommend this place to everyone!!"], ["Best coffee in the city! The staff is super friendly, the food is amazing! Great prices and relax environment!"], ["Delicious food & coffee!!! Awesome selection. We had the Honey Bee Crepe & the Goat Bacon crepe to eat. I'd highly recommend both of them. I also got the Mochacchino (hot) and it did not disappoint.\n\nWe will definitely be back!"], ["Pretty good breakfast/brunch place.  Honeybee Crepe was a great, balanced, sweet-savory treat -- if maybe a little too carb-y (crepe was pretty thick).  I also would have liked a side salad with that.  I stole my partner's and it was fresh and good.  I ordered a cortado and received something more similar to a latte -- espresso-milk ratio was too milk-heavy.  The space is nice, but was very smoky both upstairs and downstairs.  Don't come here if you have asthma?\n\nOverall, a friendly, cozy place with good food.  Crepes (and omelettes) are pretty massive, so if i come back i'll likely get something to split."], ["I live around the corner from here and it has become my go to place for myself and guests.  I have had many of the items on the menu (both sweet and savory) and have not been disappointed.  The staff is friendly and the service is efficient.  The coffee is hot and specialty drinks are well made.  There is limited seating on the first floor and outside, and also seating upstairs.  I will continue to come here!"], ["Delicious coffee and crepes for breakfast, brunch or lunch. I had the bacon goat cheese and tomato crepe and it was great. It's a nice quiet off the beaten path spot. Limited seating inside with a couple of tables outside. I Would definitely recommend."], ["This place is the BEST coffee I've ever had (and it's so cheap!). They use La Colombe, a local Philly favorite. The experience is only heightened by the absolute adorable decor, spacious and welcoming downstairs, and beyond kind owners. The couple is so sincere and continually ask customers what they could do to improve. In my eyes, NOTHING! The coffee, the huge egg sandwiches, the crepes, everything.. pure perfection. Worth going to once and continually going to!"], ["The best Macadamia nut latte I've ever had!!!  The cap on savory crepe is da bomb! Mushrooms, avocado, and spinach"], ["Nice little cafe in an area that absolutely needed one. I had a honey ham sandwich on a bagette which came with a generous salad on the side. The iced coffee comes with a shot of espresso in it since the owner thinks iced coffee doesn't have enough flavor. Not gonna argue with more caffeine. Lunch came to about 10 bucks which was more than reasonable for what I got. The staff was friendly as well. Will be back for crepes next time."], ["Good coffee, great atmosphere, excellent service, this place is a hidden gem. Found my new go to coffee shop."], ["I almost hesitated to review this because I don't want it to become mainstream. Fortunately, it's out of the way enough so that it probably won't be.\n\nThis place is beautiful. Amazing coffee, really sweet owners, scandinavian aesthetic, small, quiet, and sort of an oasis in an otherwise coffee desert. Everything is super well-priced. A savory crepe and a massive cup of coffee and a nice place to read a book on a Saturday morning costs me about $10.\n\nI've gotten the honeybee crepe (mozzarella, spinach, egg, honey drizzled on top) and the goat bacon (goat cheese, bacon, mushrooms, tomato) and both were delicious and very fresh. Thanks for existing, guys."], ["The barista accidentally poisoned me by putting milk instead of soy in my latte, but I've forgiven them. Really enjoyed my goat bacon crepe and my husband's omelet. Parking is easy. Will return (but won't order a latte)."], ["The front of the business is barely noticeable, but it is worth finding. The iced coffee and giant chocolate chip cookie I got were amazing! The prices are very reasonable, and they take cards!\n\nThe basement has a very large seating area. It is easy to relax without feeling cramped like most cafes. The menu seems to have a good selection of sandwiches, cramped, and other items I hope to try soon!"], ["The closest to a traditional French crepe I've had do far in Philly. We went there for brunch and ordered the Egg On crepe and Salmon crepe. The Egg On crepe was delicious. The salmon one on the other hand was a bit too heavy on the spinach, which made the crepe soggy. Their coffee is good if you like it strong and a bit bitter. The place is very cute. There's few extra sitting in the basement, if you want to dine in."], ["What an amazing place.  The crepes are amazing and as was said by many reviewers, the honeybee crepe is something you must try.  The atmosphere is nice and relaxing with friendly staff.\nThis place is pretty hidden away and in a really random spot, but it's worth it no matter your travel.  If you're eating in be sure to check the downstairs to ensure there's room, it's small but very cozy.  I couldn't recommend this place more."], ["I'm so happy I found this cafe near my new job. The coffee is always fresh and delicious, the crepes are just amazing, and the service is fast and friendly. I'm quickly becoming a regular. Iced hazelnut latte all day every day!"], ["Very cute place. 3.5. Nice variety of sweet and savory crepes. If you eat in, you order upstairs and they bring you your food to your table at a more spacious downstairs eating area."], ["I had the Nutella crepe with Strawberries and a Mochachinno. Both were fantastic! I will definitely come back next time I'm in Philly."], ["A few weeks ago, I walked over to meet my wife at the school where she works for an after school event.  I walked past Vineyards Cafe and did a double-take at the inviting, Nordic-like interior.  But I was running late and did not get to try it.  Then, the holidays came and I had to file Vineyards Cafe away...until yesterday.\n\nThe interior is clean and beautifully lit.  It makes for an inviting space to enjoy breakfast.  The owners are welcoming and friendly.  The menu small but more than sufficient.  The coffee (La Coloumbe) was excellent, crisp and fresh.  I ordered an egg sandwich with cheese and opted for the French Baguette (you can have it on a bagel as well).\n\nMy breakfast was a fantastic start to 2016, particularly on this first, cold day of work of the year.  The bread was excellent.  My eggs were cooked to perfection.  The cheese was melty and plentiful (perhaps a little too much cheese but I'll never really utter those words again).  There is a water station that looked thirst-quenching and extremely well-kept.\n\nIf I could, I'd park myself in the beautiful downstairs every day to work and eat.  Thanks, Vineyards Cafe for making my day and getting my 2016 off to a smooth start.  Buen provecho, Yelpers."], ["Everything here was perfect. The crepes were to die for and the iced latte was some of the best coffee I have had. Great seating area downstairs and extremely cozy. Will be coming back next time I am in Philadelphia."], ["Visiting Philly with my daughter last week. Met her friend and family here for brunch. Delicious, fast, and cool ambience. Very reasonably priced for Philly too."], ["I am a HUGE fan of this place.  Orest and his wife (the owners) are genuinely nice people and the other employees are fantastic. They accommodate any menu tweaks i've asked for and they do everything in their power to make sure you are satisfied. All of the food I have had is well worth the cost (fairly average prices in my opinion)- they serve very generous portions!  The location is great since there is not many other spots like this in the area and the layout and design of the cafe is awesome. I recommend this place for anyone looking for a new breakfast/brunch/coffee go-to!"], ["Legendary crepes and quick service. I just wish there was a bit more seating and space, especially outdoors. My friends and I came for Sunday brunch and we huddled around a tiny table outside."], ["Excellent mochaccino and cutest design! Peaceful here and great for a breakfast or beginning to your weekend morning! Great service as well- would definitely come back!"], ["Love the food here, everything seems fresh and clean. Service is polite and friendly. Just everything you want in a little breakfast place."], ["This place is very good - 4.5 stars if I could. The crepes are delicious and affordable and the shop is designed a way that just makes you want to spend time there. If you're in the neighborhood or are just craving some crepes, this is the place to go!"], ["Best coffee and crepes in the area. I will often take a visiting friend here for breakfast, or come by myself on the weekends. Crepes are awesome, love the norwegian crepe. Also a fan of a baguette with jam and butter, they usually have a few jam selections that are interesting. Staff is really friendly, owner is usually there and he's nice. Also a highlight - they have a constant tap of infused water for customers!! Cute."], ["Was looking for a place to grab breakfast and I knew this place was the one. Coming into the shop it was very clean and such a cute comfy spot! I ordered a latte and an American cheese omelette with spinach which came with a salad and a side of balsamic vinegar. I was super content with the whole plate. The omelette was well made and big and the salad was a very good portion. The latte was stronger than other lattes I usually have, but it was good! Overall I had a really experience here and left with a happy fully stomach!"], ["A sweet little spot for brunch. Small but super clean. The seated area is downstairs. \n\nDelightful crepes.  Goat cheese and figs: one of my fav combinations. My husband loved his ham on a baguette. Hot chocolate  was JUST sweet enough, not sickeningly sweet. \n\nEfficient, friendly service. \n\nWe will be back!"], ["Vineyards Cafe is a cute little place for breakfast or brunch.  There are seats downstairs to relax and hang out.  And very clean.  I ordered two crepes for myself to try a savory and sweet crepe.  The Norwegian crepe had a decent amount of salmon, avocado and goat cheese filling.  And was a good portion.  I would like to have it again.  The Au Sucre crepe was like my dessert.  Plain but pleasant as I got a good sense for the batter they use.  This dish would be good for the kids.  And the perfect price for what I ordered.  I would like to come again and try something new."], ["Fantastic little cafe hidden in an upcoming neighborhood nice outdoor seating reminds me of a cafe on Montmartre in Paris a must visit there coffees are amazing and food just delicious"], ["What an awesome place close to home friendly staff very comfortable the food was great 5 stars all the way."], ["So happy I visited and I cannot wait to get back. Beautiful building inside and out, pleasant and kind staff, and delicious savory crepes! I can't recommend Vineyards highly enough."], ["One of the best chai lattes (hot or iced). Innovative and basic crepes. Ninja fast service. Relaxing neighborhood atmosphere."], ["Came up to Philly for the weekend and we wanted something quick to put in our bellies before the Sunday morning drive...also we love crepes. \n\nThis is a cute little unassuming place. (I would have missed it completely if it wasn't for the \"open\" sign.) When you enter, whether you want your meal to stay or go, you must order and pay upstairs. I went with the Norwegian (goat cheese, salmon and avocado) while my fianc\u00e9 went with the Goat Turkey (goat cheese, turkey, fig spread). I also ordered the blood orange pear tea and he got the lime mint wellness. The prices were quite reasonable, even with 15% tip everything came up to~$25. \nYou have to wait upstairs for your tea as they will bring the food to where you are seated but not the tea. We waited then took our cups downstairs. \n\nThere aren't a ton of tables downstairs (or upstairs). About 2-3 two person tables and maybe 2 four person tables...were also 2 armchairs near a low table. It is quite intimate and closed in. There were a lot of what looked to be Temple college students and the place did seem to have that chill atmosphere that students would gravitate toward.  \n\nWe didn't have to wait too long for our crepes. They were QUITE filling, you only need one at a time! The Norwegian was ok, there was way too much goat cheese for me and it seemed to overpower everything. The Goat turkey was amazing, loved the fig spread, it added some balance. The herbal teas were also enjoyable (I recommend adding a sugar cube to the blood orange pear to really bring out the blood orange flavor). \n\nI enjoyed the nice touches like the lemon-cucumber ice water stations (one upstairs and one downstairs). Very refreshing. \nThere was single gender neutral, differently abled friendly bathroom upstairs. The staff was extremely friendly and helpful. I would definitely like to come back to try the sweet crepes."], ["Cute find. Def a local spot the pricing is amazing ! The food is fresh and not processed. It looks kinda small from the front but go downstairs and there is room to accommodate a good sized group. This would also be a nice place to study or just stop and grab a coffee or smoothie"], ["Wow I never knew crepes could taste sooo good! LOVE this place! new favorite!! The strawberry au sucre was absolutely on point. It melted in my mouth lol. Their savory crepes taste amazing and are quite filling as well."], ["Delicious HUGE lattes, which is perfect if you're here to write a paper like I was. I had the Egg On crepe, which was delicious (add fig spread, just  FYI!) and fruit infused water. I noticed previous comments mentioned a lack of outlets, but there seem to be more now...some by the soft  chairs and some underneath the bench seating by the tables. I will definitely come here often!"], ["Vineyards is my go-to cafe around N Broad/Fairmount. The owners are great people; kind and friendly. The food is excellent, especially the crepes.\n\nI also recommend the omelettes. They are HUGE, and come with greens on the side, a nice touch. The crepes are also stuffed with goodness.\n\nThe coffee's great too, as are the bagels. Their speciality drinks are also good. If it's a nice day the outdoor seating provides great views of the Center City skyline. It's affordable too! What's not to love?"], ["Great little spot for coffee and breakfast. Bright and roomy, with a quaint feel. Bright pine everywhere, and a very welcoming downstairs seating area. The Americano Omlette was delicious and the owners are very friendly. Come in for coffee to go or food downstairs, but you'll enjoy it. \n\nThere are plenty of outlets downstairs with large tables to get your work done as well."], ["This place has most delicious crepes in Philly!!! Love there Philly crepe, Caramel Ricotta crepe and La Colombe coffee!! Love love love!!!"], ["Such a great, simple and delicious place! Definitely give this place a try, you won't be disappointed. La Colombe coffee and great food is a winning combination!"], ["Unforgettable flavor combinations! Have visited at least 5 times so far and have tried the Honeybee and Nutella crepes as well. However, the GOAT BACON is king. I wasn't thrilled when my wife ordered a savory crepe (as I had previously associated crepes with dessert). One bite and my eyes were opened. Delicious thick cuts of bacon tossed with mushrooms, balanced with acidic grilled cherry tomatoes, melded with goat cheese. Not your average crepe ingredients, but this menu item has brought us back repeatedly. As a matter of fact, I could go for one right now..."], ["What a pleasant treat! I picked my daughter up from Temple and took her here for brunch on a Sunday. Great menu for meat lovers like myself and vegetarians like my daughter. Would definitely go back here again and highly recommend."], ["Terrific, cozy neighborhood cafe that looks very unassuming but has much to offer. The coffee is from la Colombe, so you know it's good, and the food is desirable as well. The menu is rather expansive for the size of the shop and they manage to do everything well from the sandwiches to the crepes. I highly recommend checking it out. Don't forget to check out the extra seating in the basement, but the outdoor seating is just perfect for the season!"], ["Vineyard is by far our favorite caf\u00e9! My boyfriend and I go every single weekend. The staff is welcoming and friendly and the food is always great. Love love love the coffee as well. Our normal order is: the Americano omelette (goat cheese instead of Gouda and add avocado) and we get the omelette on an everything bagel... plus the Caramel Ricotta crepe with apples (or bananas). Splitting both gives us savory and sweet perfection. The best!!!"], ["My husband and I LOVE going to Vineyards for breakfast or a quick coffee date. Anytime we have family in town, we take them here too. The couple that runs the cafe is wonderful and the coffee and food is phenomenal!!! Super relaxed atmosphere and prefect location!! So excited they're in our up and coming area!!!"], ["Crepes!!! That's all i need to say but i'll say more. Nice little place. There is a down stairs so dont worry if you see that there might not be any room for you and your friends. The downstairs is really nice actually. Comfortable chairs and charming little set up. I had the Americano crepe. Gouda, eggs and bacon. Perfect! With some pellegrino to wash it down. Great breakfast for only $10! You can get a crepe for as low as $3:50! So if you're on a budget and want a nice meal. No question, Vineyards is the spot!"], ["Excellent coffee, hot chocolates, and bagels!! Love this spot. The owners are so nice!! I can't wait to try their crepes!"], ["This place is the best! Wonderful service, delicious food that's reasonably priced, great coffee and tea, and a lovely ambience (particularly relaxing music). These guys always think of the tiny details (cold fruit water, proper coffee cups instead of takeout, fresh decor and a warm welcome), and it makes lunch at the Vineyards a pleasure every time. Highly recommended."], ["Good coffee and nice staff! The seating area for doing work is great."], ["Vineyard caf\u00e9 such a cute hole in the wall! We almost missed it driving by. We walked in and all the women behind the counter were very kind and welcoming. I ordered the maple ham which was delicious and the coffee (latte) on point  I'm not a fan of salad but I had a taste and it was so flavorful. There is a bar and stools entering the Caf\u00e9 with seating downstairs. Such a cute and soothing vibe it gives. This would definitely be my spot if I lived in the area."], ["This place is great. The coffee is great, the crepes with a large variety of savory and sweet are delicious and the service is sensational. The shop is very inviting; Orest and his wife (shop owners) are super friendly. We were very surprised to learn that there was additional seating in the basement area which was very comfortable and nicely decorated.  If you're in neighborhood stop by and if you live a distance away it is with the trip!"], ["great coffee, great food, and a great staff. I usually get their lattes or cappucinos. Everything Bagel was also very good and huge!"], ["Outstanding! where do I start..\nmochacino is tge best I ever had anywhere. the honeybee crepe was fantastic.one of the best I have ever had no kiding.  veggie omelet was fresh and tasty. next time I might switch the goat cheese with mozzarella or ricotta. strawberry nutella was also good, but honeybee was just anazing.  best of all price was very reasonable and service was excellent."], ["Everyone one the menu is beautiful and delicious. The atmosphere of the cafe is wonderful. The earthy tones in the lower section is a hidden gem. Perfect place to relax and enjoy your meal. It's hard to leave once you get comfortable."], ["A delightful place to eat lunch. The food and the hospitality were wonderful! Thank you Yelp for finding us a perfect place. =)"], ["The crepes here are the best!!! The service however sucks!! I live down the block from the cafe and order here quite often. 4 out of 5 times the lady who answers the phone always picks up and hangs up on you. Once I didn't have a menu so asked what the bacon crepes were and she hung up on me mid order.\nA friend wanted to build her own crepe with \"Nutella and bacon\" and the lady at the counter looked at her like she had 2 heads."], ["The crepes are amazing! Very fluffy and flavorful. They have really great iced coffee as well."], ["Charming bright place, wonderful & attentive staff, & fabulous crepes & eggs. Great espresso drinks too! Excellent breakfast choice. So happy!"], ["What a secret gem! Go here if you love crepes! I ordered two of them and ate both without regret :)"], ["Dang yo this place is Poppin they have delicious treats and slamming coffee, do yourself a favor and go here"], ["This place was the cutest find and the perfect way to start my day trip in Philly. The atmosphere is so cozy and inviting, and the staff was very friendly and helpful. Myself and one other person shared 2 crepes, an iced coffee, and a side of bacon, all DELICIOUS. We had the honeybee and the apricot comfiture. While I'm not a fan of cheese or eggs, the honeybee seemed to be such unique mix of tastes so we decided to try it, and I was pleasantly surprised. The apricot was also a delicious choice, and the mix of one savory and one sweet flavor were a nice blend. They also offer fruit infused water as a courtesy, which was a very sweet touch. Overall I was glad I found this gem, and I would certainly recommend it."], ["Excellent food, atmosphere, and service.  The omelette on a baguette was AMAZING"], ["Coffee and food were delicious. Pesto crepe and veg omelette were both awesome! A unique breakfast menu and a great little corner spot with friendly staff. Nicely decorated with indoor and outdoor seating. Walked a mile to get here after I saw the Yelp reviews- well worth it!"], ["A great neighborhood cafe! I especially love the outdoor seating so I can hangout with my dog."], ["Best cafe just opened up in the area. Crepes are the best of the best,  they have water filled with strawberry with mints inside which makes it really tasty for this hot summer. Downstairs sitting for those that need wifi to do business. Orest the owner with the stuff behind the kitchen are very accommodating on how u want ur crepes and coffee done. Try it this place you will not be disappointing. Highly recommend it."], ["Went here today for a quick lunch. Place is bright with nice woodwork, service was friendly. I felt I had to get a crepe and glad I did. I had the Honeybee and it was delicious! Light and fluffy and not too sweet. Also had a latte that was tasty and oversized which I like. I highly recommend this place and hope to se more places pop up in Francisville."], ["Great cafe in the growing Francisville neighborhood! Delicious food and coffees! The crepes are savory and sweet; in our two visits thus far, we have had the goat bacon, goat turkey, and strudel crepes. The honey ham sandwich and salad was a huge serving and leftovers  taken home for another meal.  The downstairs seating offers a comfortable, cozy environment. Staff are friendly. Glad to support a local, small business!"], ["This place is AWESOME!  Pioneers in a developing neighborhood, I first went there to check it out and help support a new neighborhood business.  To my surprise, they are serving La Colombe coffee and are making Crapes and Bagel Sandwiches!  All the food I have tried has been great and the owners live in the neighborhood and really care about their customers.  I usually get a Crape on the weekend, when I have time to enjoy their downstairs dining area.  During the week I usually grab a Cappuccino and their \"Philly\" on a bagel.  I am there a few times a week."], ["A pretty great cafe in the Francisville area.  Upon arrival I was a little bit wary because it looked pretty tiny with only one table and some high top seating. I was pleasantly surprised to find out there's a floor downstairs with some extra tables and even couches! The aesthetic does what it can to be hip/trendy. It is also very clean and bright which I love. \n\nVineyards seems to be known for their crepes, but I didn't get to try one during my first trip here. I got a hot latte. It was $6!!! That is v expensive for a cup of coffee and if I'm being honest it was not that good. That got me a bit turned off. My friend got a mocha chino which was just as expensive and a chocolate chip cookie.\n\nI don't wanna hate on a local small business, so even though I do think that this place is overpriced, I'm gonna back it.  I'll definitely be back to give a crepe a try and recommend it if you need a cup of coffee or a place to get some work done."], ["Vineyards is AMAZING! Would highly recommend eating here. The food is amazing and the service is great!"], ["This is my go-to spot for coffee. Great staff, great atmosphere, delicious coffee and AWESOME food. What are you waiting for? Get here!"], ["Great coffee, and best cr\u00eapes in town!!!\nBeautiful interior, and owners and staffs are friendly.\nYou have to visit at least once, c'est magnifique!!!"], ["REALLY wanted to love their crepes - but alas, it does not compare to other crepe places I've frequented. The little cafe is situated in a weird (but up and coming) neighborhood - super close to my boyfriend's house. I was so excited to try!\n\nTheir sandwiches are good. Their crepes (we ordered take-out) got soggy after the 4 minute walk home! It seems like they make their crepes a little watered down, so I noticed a lot of air bubbles when taking a bite of the crepe. It wasn't anything special and the ingredients were a little lacking. \n\nTheir drinks menu could be a little more creative, but for a small place like this, I think it's pretty good. I enjoy their iced lattes and their quiet and quaint little study area."], ["Probably the best crepes I've ever had! Both sweet and savory are amazing, I cannot wait to try all the others! The staff is super sweet and friendly, which makes this place that much better. Wonderful spot for a quick visit or for a couple of hours to work/study."], ["My Husband and I have been frequenting this wonderful, quaint little Cafe since we moved to the neighborhood 8 months ago. We have ordered the food and picked it up (the Crepes were delicious, hot, and not soggy), we have eaten in the Cafe, and we have simply ordered some beverages. Their coffee is the best tasting coffee my Husband and I have ever had, the Iced Soy Latte I get is out of this world (the craftsmanship that the Owner uses is fantastic), the atmosphere is warm and inviting and it is very visually appealing. They always have a dispenser of water with fresh berries or citrus which I love, and all of their pastries, pressed drinks and other foods are local. Overall the Owner knows his stuff, is very friendly, and his Wife is a lovely lady always smiling when someone new comes in. I highly recommend this place!"], ["This place is so good the crepes aren't the cheap kind it's nice decent food their sandwiches are great and the bagels are really good the people are very nice and the place is clean"], ["I don't yelp often these days but this little spot deserved more than just a click of the 5 star rating. This cozy spot is run by a pair of wonderful people, who each worked to make our crepe birthday breakfast something to remember. We'd read good things, so we ventured far from our usual haunts to give this delightful place a try. You should too."], ["This is a tiny coffee shop that serves excellent crepes and nice breakfast . I had the vegetarian omelet in a baguette. My friend had a crepe which looked amazing. Ice coffee was outstanding as well as the hot coffee. The service is efficient and the place is pretty in an up and coming neighborhood. Worth the trip. Could use more inside tables ."], ["Came here for a late breakfast. Everything was great. Tried the savory crepe with goat cheese, avocado and salmon, it was delicious. Also tasted the bacon and mushroom omelet on Baguette. Portions were huge and very satisfying. Had a drip coffee which I believe was La Colomb, it was brewed strong and I thought it was very good. I would definitely eat here again and try different variations of savory crepes. This cafe is kind of in a weird location, little hard to find as they are doing lots of construction in the area. Most seating is indoors with two small tables out front."], ["Yes yes yes! What a gem this place is. It was so good, I came here 2 days in a row. First time I got a savory crepe with spinach, cheese and mushrooms. Second time around I got the sweet Nutella banana crepe. Not to mention, the cappuccino is amazing. I'll definitely be back for more!"], ["The best creperie / cafe I have ever been to! I got the goat cheese & turkey crepe and it was beyond perfection! \n\nAnd their iced chai latte is to die for as well!"], ["this place is so hipster! i ordered crepes which were delicious and also a smoothies which was also delicious. price wasn't too bad and the store was so cute. they also have a downstairs that you can eat and study there. it's super chill and laid back and the staff is very friendly and welcoming. love love love this place"], ["Been here many times and absolutely LOVE this place. The omelettes are awesome, the sandwiches are awesome, the coffee is awesome! Everything is awesome! Please support the amazing couple that has this cafe. Great ambiance, friendly service and perfect for studying, or evening getting breakfast with friends!"], ["You'd be hard pressed to find a better breakfast place in all of philly, great food, great atmosphere, quaint quiet with undertones of a French bistro. Serene does not even scratch the surface. There is something deeply divine about this place. From the music, to the delectable crepes (goat cheese mushroom bacon is to die for) and the down stairs seating area is cozy with tables whilst also having a couple lounge chairs, long story short go here, I guarantee you'll fall in love with it like I did."], ["They gave us great service- such friendly and professional people. I love the atmosphere; it was very clean, comfortable, and charming. The food is delicious."], ["This place is awesome! Everything we've have had from their menu is delicious... And my girlfriend is a very picky eater. Personal favorites are the Goat Turkey Crepe and the Honey Bee Crepe. They have great coffee, tea, sandwiches, baguettes and bagels as well. \n\nBoth the main floor and the basement seating are clean, well decorated and well lit. And I love that they have outdoor seating in warm weather. \n\nThe owners (a young couple) and their staff are all extremely friendly. You can tell they put some serious money, time and effort into this place. This is EXACTLY what Francisville needed, and they did it the right way!!"], ["Quality food at great prices. Try their Crepes, they are awesome. They also serve La Columbe coffee which is my favorite."], ["This is hands down my favorite spot in town, and it's hard to stop me from eating there at least once a week! The service is always a wonderful experience, and the food and coffee are amazing.\n\nAll of their sweet crepes are delicious, but I would recommend caramel ricotta, au sucre with strawberries, or apricot jam. Their savory crepes are lovely as well, however there are not many vegetarian options. However, their honeybee crepe is lovely! It's also worth noting that there are no vegan crepe options called out on the menu."], ["What a gem of a place in the francisville neighborhood! I had a skim chai latte and a sucre crepe. The staff was very friendly and the downstairs dining area was very welcoming. We will be back."], ["Good bagel and coffee.. but went at 11am on a Sunday morning and they didn't have eggs?? What kind of breakfast cafe doesn't have eggs when it's over half their menu? There was only one other customer in there and three people standing around \"working\"... send someone to the store?? Service wasn't overly welcoming."], ["A cute little place on 16th street, nice and cozy! A group of us went here for breakfast and the food/service was delicious. I got the honey bee and my girlfriend got a sweet crepe and they were both awesome. The iced coffee was awesome too. I would come back here for sure, very awesome low key spot."], ["Very very cute cafe! I think their crepes and teas are good. Not quite I-NEED-THIS-A-FEW-TIMES-A-WEEK good, but I'd-be-happy-to-come-back kinda good. My friend and I split a honey bee and the nutella strawberry one."], ["Good price for good crepes. I had the savory Philly crepe. Came with smoked salmon, cream cheese, and spinach. Generous amount of smoked salmon evenly spread out in the crepe. Well worth the $9."], ["I go to this place every time I'm in town (which is not enough). My favorite dish is the pesto sandwich. It's pesto, mozzarella, tomatoes, and avocado on a perfectly toasted baguette. It's served with a side salad drizzled with a balsamic vinaigrette that pairs so well with the sandwich. Reminds me of Italy!"], ["This is the best pancake place in a city. Cozy atmosphere and incredibly friendly staff."], ["This is my favorite caf\u00e9 to go to whenever I'm in town. It's the perfect spot to grab a coffee and do some work in their downstairs lounge area. They have plenty of outlets, free WiFi, and a comfortable atmosphere. Definitely, worth a trip for a quick lunch as well!"], ["This place was surprisingly good.  It's a mishmash of Italian and French inspired sandwiches and crepes.  The crepes were great -- not too sweet, which seems to be a common pitfall of American made crepes.  \n\nThe pesto sandwich with mozzarella was good as well."], ["Such good iced coffee. Tastes like hot coffee tastes but actually is iced coffee. Some iced coffees are more bitter or not enough bitter but this one is the nice amount of bitter. And good ice to coffee ratio. Love the Halloween decorations too. Lovely."], ["We came on a rainy morning not long after the cafe opened, and the cafe was understandably empty. Boyfriend and I grabbed the lone table upstairs. There were window bar seats though and a downstairs I didn't get a chance to check out. I ordered a caramel ricotta crepe and boyfriend got a smoked salmon avocado one. Service was super friendly and fast. My crepe came out larger than I'd anticipated, but I still managed to finish it; it was drizzled with diluted caramel syrup (so not overly sweet) and dusted with powdered sugar. I usually dislike smoked salmon and avocado, but I tried the Boyfriend's crepe, and I surprisingly really liked it. I liked it just as much as the crepe I ordered. This is a cafe I'd revisit if I were in the area again just to try their other creations."], ["The food is delicious and for a very affordable price. The people are really nice and the place itself is very clean and well decorated. Had the eggs on bacon and the Nutella + strawberries crepes."], ["Been dying to try and finally made it today! Amazing!! Crepes were perfect the sweat and the meaty ones! Goat turkey on the baguette was also amazing.. ice lattes on point! After 3 years I finally found my neighborhood spot 6 stars"], ["I am a HUGE fan of Vineyards Cafe! The staff is all super friendly, and I am a big fan of how they do iced coffee (essentially a red eye, which is DELICIOUS!) And honestly, their pesto sandwich is one of my top favorite sandwiches. I love that they're right down the street from me, and I appreciate that they were able to open up again to do takeout service during the pandemic. Definitely check them out!!!"], ["They're kind, hardworking people. The breakfast selection is large considering and the owner is so sweet. The coffee is very strong and you can tell it comes from a good source! An A+ place to grab a coffee, though, I wouldn't suggest eating in, its rather small."], ["Great little breakfast spot! It's super quick and the basement eating area is cute without looking like a basement at all."], ["Love this place! I live just right up the street on poplar. I come here at least 2-3 times a week for my morning coffee. Their customer service is great btw! I advise anyone who is in the area or even just visiting the city to take a visit. You won't be disappointed with their menu. Btw their lounge is a huge plus! Great place to study when trying to escape the noise of the city."], ["Caramel ricotta crepe was amazing and so was my mochaccino but the Norwegian crepe was sadly not for me at all. I normally love goat cheese but this crepe was totally overpowered by the goat cheese which was slathered on very thick. Also I just felt like the goat cheese, avocado, and salmon were all way too similar with slimy texture. I would not recommend that crepe but their other stuff looked and tasted good. I want to come back and try other things."], ["I'm late posting this Yelp review. I stayed for the weekend in Philly nearby this gem. Stopped in on a Sunday AM looking for a cup of good coffee and maybe just a quick bite. The menu is pretty varied (who knew there were so many choices for crepes?). I decided on the goat bacon and was not disappointed. \nThere was a small wait, but the ingredients are fresh, and made as ordered. Grabbed a great cup of coffee, sat down for a bit and took in the sights. It is located in a neighborhood that is undergoing a resonance. \nThe crepe was just scrumptious! Great way to start my day. \nHighly recommend."], ["There aren't a lot of destination dining spots in Francisville...yet, but Vineyards is certainly an exception.  The owners took a bit of a gamble by opening this fantastic european style corner cafe at 16th and Ogden amidst a ton of residential development.  After watching the place fill up to the brim today, I think they made a smart move by fulfilling a need here in the Francisville community.  \n\nThe space is bright, clean and feels comfortable with all the reclaimed wood.  The upstairs doesn't have much space, but surprisingly, there's a cozy garden level seating area below.  The menu consists of savory and sweet crepes, sandwiches, salads and a few omelets.  The drink menu is diverse, and while we don't drink coffee, everyone else seemed to be enjoying it.  \n\nWe loved the ham, gouda and walnut with maple syrup crepe.  (It was a little bit better than the crepes we had in Paris.)  The Norwegian crepe was loaded with goat cheese, smoked salmon and avocado, and the ricotta/caramel variety had just the right amount of sweetness.  \n\nWe'll be back for sure and we wish them the best of luck as a cornerstone eatery in the neighborhood.  As the density continues to fill in, I'm certain they will be in good company."], ["Absolutely the best crepes I have ever tasted. This place is a must go when you visit Philly. Btw, the crepes are HUGE. They also have delicious coffee and tea options. Highly recommend"], ["The space looks small but downstairs says otherwise! Got some crepes to start off my morning."], ["I really enjoyed my Sunday brunch at Vineyards cafe. A friend and I met for coffee and crepes and I really enjoyed myself. I ordered the \"American\" crepe and added spinach, and a hot latte. Our food and coffees were ready within minutes, and everything was very tasty. The seating inside is a bit limited, but there were tables outside. I also really liked the complimentary water with lemon and lime slices - very refreshing. I will definitely return!"], ["Amazing breakfast!! Crepes are great!!!  Coffee is tasty!!! The atmosphere is beautiful!!!"], ["I love this place!  Kinda off the beaten path on the eastern end of rapidly gentrifying Francisville, it is a beautiful space with the best crepes in town, period.  The Norwegian is my fave - goat cheese, lox, avocado, in perfectly done buckwheat crele. And La Colombe coffee."], ["Read on Yelp about these amazing crepes, and they did not disappoint!  We sampled the Pesto and many savory ones including Strudel and Nutella.  All were made fresh to order and were fantastic.  Service was super friendly and quick. Seating is on short supply so we took them to go. We'll be back again and will try more flavors."], ["Coffee is delicious! I ordered a pesto sandwich and it was very tasty, actually delicious. Bread was fresh and the other ingredients very good as well. They have a very cozy sitting area underground and very relaxing ambience. Place is very clean. And the girls are lovely. I am so glad I found it!"], ["Amazing place!!! Cozy atmosphere!!!\nSuch a friendly stuff!!! Sooo delicious food and COFFEE"], ["This coffee shop makes me so happy to have moved to the neighborhood. The staff are always very friendly, the crepes are out of this world (salmon, goat cheese, and avocado), and coffee is always tasty. The atmosphere is warm and welcoming. The perfect spot for lunch or a coffee date."], ["Im glad I found this place because there is a lack of good coffee in the area and this place is good.\n\nI like the room downstairs because it's comfortable and a good layout.  They play chill music.\n\nGood Place."], ["Truly the best coffee shop in Francisville. So happy they are able to be open during COVID through the mini window. My go to here is iced chi & their Maple Ham crepe  (best crepe EVER). I come here for a morning work drink or after a long night where I KNOW I need my crepe. Staff is so friendly, highly recommend if you are in the area!"], ["Would go here all the time if I lived in Philly. Fresh and delicious flavors! I had the goat cheese, ham and fig sandwich and it was delicious!"], ["I can not say enough about the Norwegian and Honey Bee crepes. The only thing better would be the cappuccino, easily one of the best I've ever enjoyed. \n\nThe staff is very friendly and though they said our food would take 15 to 20 minutes it seemed closer to 5. \n\nDefinitely on the short list for a return!"], ["Such a cute little neighborhood cafe, I met with clients here and their basement space is perfect for a meeting or just a quiet breakfast/lunch. It makes you feel you are in your own leaving room.\n\nTea and coffee are very good and their crepes are delicious, although I am giving 4 stars because I ordered a Nutella crepe but it was not fully Nutella, it was more of a mix between Nutella and chocolate syrup, I was expecting pure Nutella filling (as the name says) and not a mix of chocolates so that was a bit disappointing."], ["This little hidden cafe has AMAZING bagels. I think it's French owned. Their bagels are soft and tasty! They're pretty affordable too! I am putting them on my list of favorite cafe/coffee shops in Philly."], ["Wow I never knew crepes could taste sooo good! LOVE this place! new favorite!! The strawberry au sucre was absolutely on point. It melted in my mouth lol. Their savory crepes taste amazing and are quite filling as well."], ["We went to Vineyards Cafe for breakfast after reading about how delicious their crepes are. The inside is pretty small, but has a very warm and inviting atmosphere.  There's also more room downstairs but we never got a chance to check it out. Both servers were very friendly. This place really does feel like your neighborhood cafe, just like their sign says!\n\nI ordered the Norwegian crepe. These were really packed with salmon and avocado.  I never had this combination of foodstuffs together before, but it somehow works. Even my girlfriend who admittedly doesn't like goat cheese or avocados commented on how much she liked the dish. \n\nI was also able to try a bite or two of her caramel ricotta crepe. Also very delicious and not too sweet. Would be interested in coming back here to try more of their crepes and some of their coffee."], ["Delicious crepes! Highly recommend the Philly--salmon cooked perfectly. Make sure you check out the super cozy downstairs seating area. Great place to work/study/have a meeting."], ["Vineyards cafe is one of the coolest coffee shops I have visited in the US. Welcoming atmosphere, coffee and food are very delicious. The prices are great either, spend 10-12$ for the best in the city savory crepe(it tastes incredible) and cup of freshly brewed coffee. If you have some spare time, grab a good book and enjoy yourself in a cozy and comfortable setting. \nA truly great coffee shop has to feel special, THIS ONE DOES."], ["This place lives up to the reviews. Wonderful coffee (my favortite latte place), nice music, friendly staff, cozy atmosphere to chat or study/work, fast internet, reasonable prices. What's not to like?  I'll be a regular here from here on out."], ["Excellent place to start your day! The place was extremely clean and the employees were very polite.\n\nHighly recommended!"], ["Best. Crepes. Ever. This is a little pricey but you really can't beat it. The employees were great too"], ["This place is super cute. I came here for breakfast before work and ate in. I had a savory crepe, the Americano I believe, and a macchiato. It was ready pretty quickly, and was very good. The crepe is on the larger side; I managed to eat most of it but probably shouldn't have. The space is well-lit because of the windows, and on the smaller side. I'm not sure if there's another floor with more seating."], ["Thank you for amazing spot in Philly. Cozy atmosphere, food is delicious, service is so good. All flavors of syrups for coffee that you ever wanted (thanks for the amazing pumpkin spice). Highly recommended! Unbelievably low prices!"], ["This review is long overdue. Vineyards Cafe has swiftly become my home away from home. Perfect for studying or just enjoying a nice morning by myself. Super dog friendly, which I love because I can get my dogs out of the house while enjoying some perfectly crafted coffee. Interestingly, my fianc\u00e9e and I frequent this place, so much so that they allowed me to host our engagement party there. Great staff, great food, and most importantly great coffee."], ["I've given this place so many chances. The crepes are not good and they've messed up my order multiple times. They are also out of everything all the time and they take a very long time to get orders ready. The bagels are subpar as well and they are always either burnt or under toasted."], ["Great little cafe. I had a goat cheese turkey and dog jam crepe and it was delicious. Good prices and good service."], ["It almost hurts me to write this, but I think my days of patronizing this business have come to an end. Today my friend called me to tell me about his experience here with the young lady at the counter speaking rudely to him. Ironically, a few months ago I had a negative experience with this same young lady as well. I had ordered a Vanilla Iced Chai and was handed a warm chai (in the middle of the summer). When I told her that I wanted ice in it she told me that I didn't ask for ice. I know for sure that i asked for ice, I wouldn't drink a hot drink on a hot summer day. Anyhow, I assured her that I did ask for it and perhaps she did not hear me. She insisted that I did not ask for ice, I sensed her attitude and decided not to go any further because I did not feel like arguing about a drink. Today, he saw a notice that they were not serving eggs and asked her about it, she responded in a rude tone \"We just don't?\" It was unnecessary and unprofessional for her to give him attitude for asking a simple question. Well, this prompted us to find out on our own. Come to find out they were in violation of code and had to cease cooking eggs immediately. That was no big deal for me, but when I read that there was no backflow prevention on the sink water supply lines, that made the decision for me. I would think that a business who's been cited with various violations would be more humble when dealing with customers. It was a nice run while it lasted and it's sad to remove them from my list of favs but with the violations and the attitude, I'm good love, enjoy!"], ["Yoooooo this place is scary as hell. You wanna feel uncomfortable??? Just make your way to Vineyards Cafe and make sure you are specifically non-caucasian!\nI am writing this review on behalf of a friend who felt so uncomfortable at this establishment. \nThe coffee she had was not made well at all. It tasted like soap. \nThe workers were unfriendly and felt hassled by my friend and even annoyed when she wanted to stay in the cafe to do her work like everyone else and have her nasty ass drink. They were unwelcoming."], ["It's a deceptively small when you first walk in but there's more seating downstairs. Very chill and friendly environment. Super cute and aesthetic. Coffee is very authentic and staff is so helpful and attentive."], ["Whenever my friends ask to meet up mid-afternoon for a snack, this spot comes to mind. The atmosphere is clean and calm so if you want a place to study with free WiFi, stop by! \n\nI'm partial to their sweet crepes. Personally I like the simplicity of their confiture crepe which offers your choice of jam and powdered sugar. I like the blackberry jam the best. Their savory crepes are good too, but if you're not a fan of cheese that is on the stronger side, you might not like their gouda crepes. I like them a lot, but I had one friend who didn't like it at all. It's up to your tastebuds I guess!"], ["DAYUM that's a good crepe. I've had some good crepes in my day, but DAYUM. Got the Goat Bacon, amazing decision. Menu has savory crepes, sweet crepes, sandwiches and omlettes. The folks running the joint had a french accent which inspired great confidence in their crepe making ability and it lived up to the billing.\n\nThe crepe was huge and the goat cheese/mushroom/bacon filling was plentiful. Mark this on your GPS as a go-to spot in Philly."], ["It's perfect for the neighborhood. It's very cute and quaint, the owners are nice and I love the simple yet contemporary decor. The basement lounge area is really cool and not too tight. The food is pretty good, I'm a fan of the tarts and the fresh squeezed orange juice is awesome. I had the vegetarian omelette and it comes with a side salad that is pretty tasty. My friend seems to love the Hazelnut latte. I am looking forward to trying a crepe and enjoying the pleasant service again very soon."], ["This is a very cozy place and has really good coffee. The coffee here was so perfect, the bitterness of the coffee was not overpowred by the flavoring."], ["Omg so good ! I got the Norwegian with smoked salmon goat cheese and aVocado .... sooo good I could eat another one ! Parking is a little rough , coffee is strong . I highly recommend !"], ["This is my first review on Yelp. Vineyards cafe is such an amazing addition to my neighborhood. The food is delicious!!! The staff and atmosphere make eating here even more enjoyable. Another bonus is they are super kid friendly!!!!!"], ["what a cafe should be by definition!!!\nAwsome food, great coffee prepared right, friendly service!"], ["Edit: The owner (I think) responded, he explained they do not have direct contact with Postmates so the menu was not up-to-date; hence, items not being available. They also shared they typically do not recommend crepes for delivery, as they should be eaten within a few minutes of being prepared. All that said, I respect him reaching out and respectfully adding context. Kudos for good customer service. \n\nWe ordered delivery this morning, we are so so so disappointed. First, we found out they were out of 3 of the 6 items we ordered - blackberry jam for a crepe, fresh OJ, and one of the other crepes. In the end, we picked the sucre crepe, Norwegian crepe, crepe with apricot jam, everything bagel with fig jam, and an iced coffee drink. The only thing that was good was the bagel and coffee. I don't understand all the reviews praising these crepes as special. I know this will sound super pretentious, but I have had crepes in France and at many places in CA - none of them have tasted as poorly as these. All 3 were lacking flavor and the consistency/style of crepe was  not appetizing, plain, not crispy, more brown colored, and lacking. The Norwegian has salmon, goat cheese, and avocado - the salmon was overpowering, while a good quantity of protein is usually welcome, this was super fishy and with a lack of flavor/spices, it was as if rating straight salmon, not a crepe with other ingredients. The plain with apricot jam was like soaking up apricot syrup with a plain piece of bread and the sucre one didn't even taste of sugar, I couldn't even see the sugar inside.I dislike giving low reviews, but I am confused why this has high reviews which misled us and was why we ordered here. We all have different taste buds and preferences, this was our experience, hopefully others enjoy this place."], ["Had lunch here with a friend. The crepe, potatoes, and coffee were perfect. The atmosphere is so elegant- I love their plants! I'll definitely come back."], ["It's a cozy place with more room in the basement. \nTheir crepes menu is perfect, has sweet and savory options. Plus serve La Colombe Coffee. \n\nIs a great morning breakfast cafe. And the workers are also very nice and very helpful. \nComing back for sure!"], ["Love it here. The crepes are absolutely perfect. I have the Philadelphia sandwich (lox) close to once a week. And they serve la colombe coffee.  Great space with outdoor seating and a dining area in the basement. Such a good spot."], ["Great customer service the girls were really nice! the downstairs is the cutest seating ever. I got the honeybee crepe and my bf got the honey ham sandwich and both were amazing"], ["I was in Philadelphia for a weekend with friends and after we toured the Eastern State Penitentiary I left it up to them to find a nearby lunch spot. I was pleasantly surprised at the variety of menu choices and quality of food - had the salmon/avocado/goat cheese crepe and an iced latte, and probably would have eaten there every day if we stayed in the area (the cafe is sort of hidden).\n\nNote: they have a nicely decorated lower level that offers more dining space."], ["Phenomenal crepes, great coffee and an even greater ambiance to work or hangout in. The staff has always been nothing but friendly and accommodating. Glad they are a staple in this neighborhood!"], ["I love this neighborhood cafe! The coffee is great and their crepes are delicious and hearty! I normally get the one with egg ham and cheese, and I've tried one with bacon that was tasty as well. I especially love the downstairs area; it is a great place to relax and read a book when there are not many customers. The staff is always friendly and the decor is beautiful, but I wish there were more vents because it can get smokey in there sometimes."], ["This place has great coffee and great crepes! they are always a special mid-day treat. It is just a walk-up window, so do not plan on sitting down. Additionally, you can call and order ahead for pick-up."], ["It's a deceptively small when you first walk in but there's more seating downstairs. Very chill and friendly environment. Super cute and aesthetic. Coffee is very authentic and staff is so helpful and attentive."], ["Good crepes. GOOD coffee. Great atmosphere. The kind of place I'd spend an afternoon sipping coffee and getting some work done. 10:30am on a Sunday I was worried about getting a seat but it wasn't a problem at all. For sure my new spot. I can only say I wish they had MORE crepe options so I can try them all."], ["Dessert crepe was great! The salty crepe had no sauce and was a pretty bland but the ingredients were very fresh"], ["This will be my new breakfast spot! Just moved down the street and went to breakfast here! It is such a chill atmosphere and the crepes are delicious! Especially the caramel ricotta one!!! Delish!"], ["Orist and Zoriana are sweet and hospitable owners. Their friendliness puts this place over-the-top for me. I was happy with the coffee and the service otherwise, and impressed with the hard work they've done to make their cafe beautifully lit and warm. Recommended. My favorite coffee shop in Francisville."], ["Delicious Crepes! I got the Norwegian which had goat cheese avocado and Salmon. It was soft and delish. I wish they brought syrup out. Didn't see it on the counter until after.\n\nMy wife got the Strudel Crepe with apples and cinnamon. It was pretty basic.\n\nWould go back again. What a hidden gem!"], ["The nicest and friendliest owners. Great food and great selections of cafe beverages."], ["Was studying here with a friend a few weekends back. The caf\u00e9 is a cozy little space located in a rapidly developing niche in Fairmount.\nI'm big on studying in caf\u00e9s so ambience matters to me a lot. I wasn't a big fan of the interior space, it was rather lackluster, though it let in a lot of sunlight. There was seating out front and downstairs but the main area itself (which is where we were situated) was rather small and had one outlet on the other end of the room. If you're going to come here to work, I advise grabbing the one seat by the outlet or bringing a fully-charged laptop. \nThere's free wifi and it's pw-protected, which is great.\nVineyards offers lots of different beverages, baked goods, and sweet and savory crepes. My friend and I only ordered two chai lattes, which tasted like your typical coffeeshop chai latte, so nothing really mind-blowing. The owners were very polite, which was nice. Overall, a pretty ordinary caf\u00e9 with crepes and nice people. I'd come here again, but mainly because my friend lives in the area and we'd most likely be doing our work here."], ["I was very pleased with the menu. The crepes are delicious and the coffee is amazing. There is free WiFi too and it's a great place to study."], ["Solid little cafe serving crepes and coffee \n\nCrepes were huge, with fresh fillings and a great batter. \n\nThe coffees looked great though I didn't have one."], ["Only has coffee here, can't comment on the food! \n\nCoffee was very watery and not that flavourful"], ["Cute little spot in francisville for delicious crepes! just a note though, there are some photos on this yelp page from a previous menu - they do not serve any eggs anymore. I love the nutella crepe, the philly crepe, and I've also had a few sandwiches that were good as well. \n\nMy favorite drink here is an iced mochaccino- it will keep you up to get work done. I wish they had oat milk as a non-dairy option though. \n\nPre-covid they were also pet friendly in the upstairs portion!"], ["This place is a quaint breakfast place with a basement lounge perfect for any hipster. The one time I went they ran out of bagels, and I went at a normal breakfast time, but to be fair, you go for the crepes. These are BOMB. They have a lot of unique combinations but they also let you tweak them. This is a great local breakfast stop to pickup or to grab a bite and hang out."], ["This place is very cute. The people who work here are always so nice. They have the best iced lattes with almond milk!"], ["The crepes are always spot on. I normally get the Nutella crepe w/ strawberries & bananas, but last time I switched it up and got the Philly crepe. It was amazing!! This place is a gem!"], ["I've been dying to try this place and am so glad I did. I pass by Vineyards Cafe during my commute to work in the morning. It's usually not open yet since I get in so early, but one day, I was running late and thought f*** it, I'm getting myself a cappuccino! \n\nSmall, quaint, and cozy, this little neighborhood cafe is such a treat. I'll definitely be back to try a crepe next time."], ["Yelp suggested this cafe for me. So decided to try it! It was located on this cute little corner midst a residential area. The cafe has seating downstairs too. Though it looks super tiny, it can seat a lot of people.\n\nThe menu was huge- it was all squeezed onto a blackboard but surprisingly legible! They offered savory and sweet crepes, sandwiches and freshly baked choco-chip and oatmeal raisin cookies (which were not made in house).  They were ginormous and oh so soft!! \n\nCoffee was given to you plain, and you can walk up to the little coffee maker corner and add whatever you please.\n\nWe ordered-\nMaple Ham crepe: pretty large size, over-drizzled with syrup. It was pretty tasty if you like all sweet things. But half way in, it was a little too much of the same taste.\n\nPesto Sandwich: has pesto, mozzarella, tomatoes and avocado. The baguette was a little too hard for my taste. Was difficult to actually bite it.\n\nMaybe we just had bad selection of food this time, but it looked like a pretty busy little cafe on a saturday.  I would definitely return to give it another chance! But the cookies- yum yum for sure! I'd probably go back at least for one of those!"], ["It's in the neighborhood and very easy to access even during COVID. I think they are opened from 8 am-1 pm but their window is opened and you can order, grab, and go. Contactless, of course."], ["Chai tea latte had good flavor at first but very watery\nCinnamon raisin bagel has good flavor but it isn't a good bagel at all it's so thin and dense \nI like the location though and will try other things"], ["Sunday brunch in the city... I find it almost impossible to find a place without a wait. Thank god for Vineyard!! \nWhen you enter it looks like a small coffee joint, but they have seating downstairs. I love the vibe that this place has. \nChai latte: being Indian, I'm picky about my chai. And this beats EVERYONES chai latte (even Starbucks). \nEggs, bacon, gouda on a baguette. Light savory dish , just enough to fill you up without that heavy brunch feeling. And the baguette is soft, so you're not tearing it apart like most places! \nNutella, strawberry crepe: one of the best crepes I've had in this city. \nThe owner even came down to check if everything was okay. The food is delicious, The place is clean And the staff is friendly. What a wonderful place in Philly to grab a bite!"], ["Cute cafe in the Francisville/Fairmount area that provided an awesome place for me to hole up for several hours and have lunch, take a couple meetings, and get some work done. Seating is outside or downstairs, and on a Monday afternoon, I had my choice of tables as there was only one gentleman in the entire place (nice to meet you, Andre!). \n\nMy caf\u00e9 au lait was perfect, and I love the help-yourself water station with large glasses. I was excited to see cr\u00eapes on the menu and went for the goat bacon with goat cheese, bacon, mushrooms, and tomatoes. The cr\u00eape was good but I would have enjoyed it a lot more if the bacon inside was crunchy. My dining companion's pesto sandwich looked incredible and I had a bit of lunch envy. I'm definitely going to try a sandwich or omelet next time. \n\nThe staff was really friendly and the wifi was complimentary. Definitely adding Vineyards to my rotation of spots to get some work done, and looking forward to trying more from the menu."], ["Best creperie I've come across in Philly. It's a small cafe, located on the ground floor in a new development. My first observations were that it's very clean, and that it has a neat wood decor.\n\nThey feature a tantalizing variety of savory and sweet crepes. I opted for the Honeybee\n(mozzarella, scrambled egg, and spinach - finished with a honey drizzle) and then took home a Nutella/banana for dessert. Both crepes were super appetizing, well portioned, and priced appropriately.\n\nI'll also mention the service was very friendly (two women behind the counter). And they offer free wifi!"], ["Love this little neighborhood spot!  Food is great (good quality and prices), their outdoor area is so cute, and the staff are always extremely friendly.  Lucky to have them in the 'hood!"], ["Worst coffee I ever tasted. The coffee tasted like dirt and she had an attitude and the inside is closed because of covid."], ["Excellent coffee. The pastries are terrific and the owner is a joy to deal with. A truly neighborhood type of place. \n\nDid I mention the coffee was great! I'll be back. No pretense here."], ["Terrific, cozy neighborhood cafe that looks very unassuming but has much to offer. The coffee is from la Colombe, so you know it's good, and the food is desirable as well. The menu is rather expansive for the size of the shop and they manage to do everything well from the sandwiches to the crepes. I highly recommend checking it out. Don't forget to check out the extra seating in the basement, but the outdoor seating is just perfect for the season!"], ["The girls who work there started cleaning up well before the closing time turning chairs upside down on tables to be unwelcoming. We came in about 15-20 mins before closing and they declined us. Why? Because they already cleaned up. \nIt's bad business practice to clean up before the store is closed. To be open but appear completely closed. The owner should really reconsider who he hires."]], 
            "review_rating": 4.64
        },
        {
            "business_id": "1skzWN0fxGgZNRE53Y_3gw", 
            "name": "Perennial Artisan Ales", 
            "address": "8125 Michigan Ave, Ste 101", 
            "city": "Saint Louis", 
            "state": "MO", 
            "postal_code": "63111", 
            "latitude": 38.545541, 
            "longitude": -90.2653434, 
            "stars": 4.0, 
            "review_count": 125, 
            "is_open": 1, 
            "categories": "Breweries, Food", 
            "hours": {"Wednesday": "15:0-20:0", "Thursday": "15:0-20:0", "Friday": "15:0-20:0", "Saturday": "12:0-20:0", "Sunday": "12:0-17:0"}, 
            "text": [["Good beer. Much better than most beer made in STL. Sweet. If you love sweet. \n\nAmbiance is sterile. No vibe. Looks like an office building. destination spot."], ["I've been wanting to try this place for some time, but can never seem to get far enough south to swing by. My man-friend and I made the trek this past Saturday to get some of their recent release - 17.\n\nThe atmosphere is minimal and inviting. The bar is covered with a nice copper coating and has ample room for seating. The space itself is very open and offers plenty of sitting for more high volume times. The tap room features board games and darts - not a typical sight at a brewery. The bartenders were friendly and efficient. \n\nI had the Bailey's Chocolate Oatmeal Stout - delicious! Has a great subtle bitterness, which I assume comes from the chocolate. The oatmeal rounds out the mouthfeel of this beer making it super palatable.\n\nMy man-friend had the 17 - an Imperial Stout with Chocolate & Mint. This beer is a home run! I rated it a 5 on UnTappd. Job well done!! Can't wait to cellar one of the 750 ml we took home for a bit and explore this brew again.\n\nI'll definitely be back. The food looked great and hoping to come sample some of their fare next time I visit."], ["We took a tour at 2 pm and it was a great way to start, the brew place is interesting on how they make all the manic happen with their amazing brews.  I generally love the saisons but the sumo stout and abraxas stout were top notch and would drink more If didn't have to drive.  Stouts were so smooth, flavorful!  Love this place"], ["Finally made the trip to the unsuspecting spot where Perennial resides. What a gem!  Based in the bottom of a refurbished Coke factory that now houses loft apartments, this place is awesome. As soon as we walked in, the bartenders gave us a friendly greeting and asked if it was our first time - indeed it was!  She then went through the menu and all the beer options available that day.  My husband and I both opted for a flight of beer to find out which one we liked best. My winner was Midnight Rambler, a dark full-bodied Belgian Stout. Mmmmm, mmmmm, good.\n\nTo pair with our beers we ordered the charcuterie plate and the pumpkin humus. Both were spectacular but the pumpkin humus blew my mind! I am a fan of all things pumpkin and it makes so much sense to use it in humus. It also came sprinkled with pomegranate seeds on top which gave each bite a tart, acidity to it. I am drooling right now just thinking about it. \n\nOur experience at Perennial could not have been any better. The beer, the food, the service all five star worthy. Oh and we got to chatting with a group of home brewers who traveled up from Memphis to try the place, very cool.   Got some great tips to use for our future home brews.  This place is a winner and we can't wait to go back to try and get our hands on some of their famous Abraxas beer next month!!"], ["I have only been to the brewery to pick up beer for releases. Today was my first time sitting down and grabbing a beer. The brewery makes some outstanding beers and are always looking to make an imprint on the craft beer scene in St. Louis. During the warmer, they have a great patio to sit drink and play games. \n\nIt's one of the great breweries in St. Louis so if you are around, check it out."], ["Awesome staff, yummy food, great beer. Releases of beer every Thursday at 6pm. Has some board and card games, seats and couches, outside pet friendly patio."], ["When we checked out Perennial, it was not at full functionality. They were only rolling with 3 beers, some Billy Goat chips and cheese curds. \n\nThe beer was tasty and so were the staff. I am looking forward to returning in the future when they are running at an optimal level. Very cool space."], ["My beer-drinking friends really enjoyed the Heart Of Gold beer.\n\nI am a soda-drinker, and have lived in St. Louis for 16 years, and Perennial makes THE BEST SODA I HAVE EVER HAD IN ST. LOUIS.  It was made from Missouri apples. \n\nThe decor in this place is sparse, making you focus on your drink.  They have a short menu with some nice food.  Note that there is no table service, you need to go to the bar to order whatever you want to eat or drink."], ["I called ahead for a small (around 13 people) going away party for my sister.  The staff at Perennial were very accommodating and allowed me to order special appetizers ahead of time for the party.  They provided us our own table and had everything ready for us at the time of the party.  The appetizers were delicious and everyone enjoyed sampling the beers and thought they were amazing.  I'm not much of a beer drinker myself but greatly enjoyed the locally brewed Pluot soda.  Everyone had a great, laid back time.   I will definitely try to hold another social gathering there."], ["Love this bar!  If you haven't been in a while, they have added new tables/seating near the front entrance.  There is a huge patio out front of the building with plenty of picnic tables.  If you happen to sit at a table instead of at the bar, remember you have to place your beer/food order at the bar.  Bartenders are always friendly.\n\nOn this occasion, I tried the Anniversaria 2015 and Regalia.  I would definitely buy a bottle of the Anniversaria to take home ($20).  The Regalia was by far my favorite (and my husband kept trying to steal it!).\n\nDuring the winter, on Wednesdays, they have $3 pours of all beers (except Abraxas)."], ["We tried all the available beers in sample form. My husband really enjoyed the Saison de Lis farmhouse ale. My fave was the blood orange suburban beverage....also loved the flavor of mint in the Imperial stout. Definitely worth a trip. Also got some great swag...love the hoodies and t-shirts!"], ["I love this place! I mean if I could make a brewery this would be it. First the location is a little weird but they have a great outdoor space that can't be beat. Plenty of parking available as well. They had about 8 beers to either get a taste of or a larger pour. Between my husband and I we pretty much tried everything and it was all tasty. The beers are unique and full of flavor. They had a good mix of light beer, lagers, and porter type beers. Also it's super nice that they offer food. Their menu had a couple different options and we got the pretzels and cheese curds. The amount of pretzel sticks were insane! The mustard was delicious that it was served with. The cheese curds were also really yummy. We ordered the savant blanc to go which was beer aged in wine barrels and it was great! Maybe my favorite. We also got a couple other bottles to go. This place is really awesome and I cannot wait to return!"], ["This place is pretty awesome. They have a great patio and great beer. The staff is extremely friendly and attentive. The only thing it has going against them is MAYBE the area it's in. Some people might be \"intimidated\" by the drive. But trust me. There's nothing to worry about. They also offer 20% off to American Homebrewers Association members! Party on, Garth!"], ["We got a growler here and the lady charged us the full price but only filled it halfway. Will not come back as they short pour the glasses as well."], ["The beer here gets 5-Stars easy.  Perennial's abraxases are their best, and their saisons are phenomenal.  Honestly, all of their beers are worth a try but those two types are where they shine.  Also, they started selling bottles of their rarer beers for on-site consumption, which is cool. \n\nI'm not a fan of the brewery/bar's location.  Sort of run down.  The inside of the bar is nice, but it never feels comfortable or even like you're inside a brewery (apart from the wonderful smell).  \n\nThe food tastes great though the selection is limited and a little pricey.  The meat platter is great buzzed food to compliment their saisons."], ["Cute place off the beaten path. Worth the stop if you are in town and interested in trying a new beer."], ["If you like good beer, vibes and people, visit here. If not, stay away. Awesome beer and friendly staff"], ["Excellent beer and a perfect atmosphere.  I love this place and make trips their often with friends and family!"], ["A new found gem for me! Wide range of beer selection. Stouts are my favorites by far. Can't wait to continue to see what they come up with next."], ["Sometimes you walk into a place and it feels like a natural extension of yourself. The music that gently tickles your ears are as pleasant as the aromas that float into your nostrils. The. The beer hits your lips and all is right in the world. \n\nPerennial executes their award winning brews in such a high level that you get excited to wait in line for the chance to acquire a bottle(s) to take home. Between the tremendous brewers and friendly servers Perennial is easily my favorite local spot.\n\nLet's not forget about the food. They Have a constantly rotating menu that pairs great food with great beer for the current season. Well worth the drive if you are not close and you should be ashamed if you live close and haven't visited. \n\nStop by on a Thursday and you will certainly be in for a treat as they put something new and exciting on every Thursday at 6p. Enjoy your free sample and stick around for a pint or two with your new friends because once you sip it's hard not to talk about it with the person next to you.\n\nCheers"], ["Have you ever been to a brewpub with concrete floors, plain but tasteful wooden chairs and tables, a bar for tasting and maybe some shelves along the wall for t-shirts and such?  \n\nHuh? What, all of them fit this description?!?  Hmmm, I guess you're right, now that I think about it. \n\nAn overwhelming feeling of boring deja vu is not a great way to kick off a visit to a place that's supposed to be fun, but we forged ahead anyway.  We were just stopping in for a couple of beers after dinner.  The bartender was super friendly and quick with a taste, which alone is a big plus at a brewpub.   Unfortunately, though,  we tried three beers; one was not too good (lager), one was pretty bad (a mint/chocolate/burnt toast abomination), the third was very good (dunkel).  \n\nThere's not much to make us want to come back, except it's the closest brewpup to home.   If you're out to go visit a lot of brewpubs, you can check this one out but I can't recommend putting it high on your list."], ["The directions take you to the rear of the building, got to wind down River Desperes Pkwy to get here. Perfect spot for teach a Friend to Homebrew Day. Beers could be higher proof. The Hommel would be perfect at around 8%. Nice space once you find it. Good bourbon and Scotch offerings, three bottles total, but well chosen. Beautiful copper bar top. Wine available. Pricey beers. Darts!  Stop in. Much more of a garage beer feel then Schalfly or Rogue type set ups."], ["I love that Perennial is housed in an old warehouse of the beaten path. It felt like a club where the wonderful beer was a secret shared amidst friends. I tried the Southside Blonde and La Boheme, both excellent. They have a great selection on tap and the staff is super helpful in breaking down the beers for newcomers. I felt very welcome. I look forward to my next visit."], ["Great brewery. Lots of great beer options. They have beers (mostly bottles) that you can only get there. We got several (bottles and drafts), all were good.  The bartenders are great & know a lot about beer. We had the pretzels & cheese curds. Cheese curds aren't fried & we loved them. The pretzels were really good.  Feel free to bring your babies too!"], ["Well-made, balanced, and delicious beers. The only ones I wasn't crazy about were the mint imperial stout (17) which had too strong of a mint flavor and the gose (Suburban Beverage) which was a bit too beachy (salty) for me. \n\nGiven that they are such an exceptional brewery, I was surprised that they had so many innovative small plates. Also, after moving from Virginia, I was happy to find a place in St. Louis that serves the caviar of the south. Get the meat and cheese board, which rotates regularly. When I went, it had delicious items like terrine, country sausage, and breaded and deep fried head cheese. Seriously some of the most well-made, creative, and delicious food I have tried in Saint Louis since moving to the city 3 months ago."], ["We stopped in STL for a night and after perusing the interwebs we saw that Perennial had great reviews and just so happened to be debuting a new offering that very evening. \n\nThe entire front wall of the bar rolls up like a garage door (the weather was outstanding) and we grabbed a seat at a bar that seemed too nice to be serving something as humble as beer. \n\nThe bartender gave me an interesting look as we sat down and I asked him what was good here. He asked me what I liked and I said I like most things, just bring me something YOU like. He gave me a blank stare and said that he wouldn't be able to recommend anything without getting an idea of what I like. After a bit of a struggle we agreed upon a beer and it was indeed phenomenal. \n\nI say all of this to describe the general feel of this bar - clinical and indifferent. Maybe it was me or maybe this guy was just having a bad night, but when I go to a place serving artisan brews I want the care, attentiveness, and passion to shine through not only in the finished product but in the atmosphere and the attitude of the employees."], ["Great atmosphere with the indoor and outdoor table set up.  The beer was delicious.  They  had good sessions.  The food items were over priced and not that great.  our chips were cold and stale, and the pretzels were warm but overly salted.  I'd say stick to the drinks here and grab some bar bites else where. We're from out of town, so we were stoked they had stickers of local DC breweries.  Representing Right Proper and Port city!  There was a lot of space in the brewery for kids to play games, and for strollers."], ["Its a hipster place. Im not saying that is a bas thing but that is the vibe. It seems to have its regulars, but staff was still courteous and semi welcoming to strangers/tourists. The beer is great. Had decent prices. I didn't try any food. All around not a bad place to go for a few beers."], ["If you love craft beer then you've probably heard of their famous stout called Abraxas.  It's only released once a year but fortunately they had a couple of bottles from 2015.  Needless to say, it was very good.\n\nIt's a little bit of a drive from downtown STL, but worth it.  All of the beers were good and the service was friendly and helpful."], ["I love me a good local brew and I love supporting new businesses in the area.  A friend highly recommended Perennial Artisan Ales, so we gave it a try this weekend.\n\nGood Points:\nFriendly Staff\nSuper yummy food - I had the Grilled Cheese with Carmelized Onion & Thyme Jam and the hubby had a BLT.  We both said they may have been the best we've ever eaten.\nClean\n\nBad Points:\nThe beer is just so-so.  They're not bad, they're just not great.  They tend to flavor their beer a little too much.   \n\nWill we go back?  Yeah, maybe."], ["Why have I never been here before? This is a great microbrewery in South County with an ale for every taste. Currently enjoying a Saison De Lis while my husband sips a heavier Midnight Rambler. Make a trip here and you will be pleasantly surprised!"], ["This place is in such a random area, I'm not even sure what part of the city it's considered to be located. I was visiting some friends and they said I had to check this place out. You can either get a tasting for $2 or $5, depending on the beer or a pour for $5-$10. The tastings are a good portion. I really enjoyed their dark beers, especially the 17 which was a minty chocolately beer. Food was a bit pricey but good. We got a cheese platter, deviled eggs, pretzels and cheese curds. Cheese curds were decent but not Wisconsin cheese curds. The other food was fantastic. \nOverall a great place that is kinda out of the way but worth a visit if you're looking for good beer and chill place to hang out with your friends while playing board games."], ["I am a lover of craft beer and I came to Perennial for the first time during a Yoga Buzz event actually where we had a private yoga class in their tasting room then were treated to a beer tasting afterwards. They have a small tasting room with several tables and lots of board games that would make for a great weekend afternoon with friends. They also have a lot of bar space to sit and have a beer and geek out with the bartenders. Before our tasting we were educated in the different varietals they had on tap including their ingredients and tasting notes. I tried both of their saisons they had on tap which were pretty flavorful but not my favorite. I loved their darkness chocolate orange stout which was right on line with some of my favorite stouts. Their beer is more pricey than the other local breweries in town but they also brew it in smaller batches. Will definitely be back!"], ["This place has, easily, some of the best beers I've had especially in St. Louis. Staff is knowledgeable and hospitable. If you like saisons you need to check this place out. The food menu is also delicious and perfect for a taproom. I highly recommend!"], ["just had the pleasure of our first visit here. i had tried Perennial's beers around town - they were a featured brewer at Cicero's beer school, Cicero's also had the black walnut on tap once upon a time, Crow's Nest has had the Hommel on draft, and i've picked up a 750 ml of the Saison de Lis here and there... \n\nbut i wanted to try the stuff at the source. we ventured out to Perennial's tasting room, which is a destination all its own, unless perhaps you're dropping in for a brew after a session at the Fight Club next door ... ? the place is comfortable enough inside. very simple painted drywall  with a bar lining the wall and some communal tables in the back. reminded us of the simple facade of some wineries in Augusta. fittingly, the tasting really is the feature of this place. the menu consists of about 8 brews, all available in 5 oz or 11-13 oz pours. i suppose you might want an 11 oz Southside Blonde, but the 5 oz tasting pours basically means you can design your own flight for the night. many of these beers are perfect for a taste but not something you need a whole glass of. they also have a brief but selective food menu with suggestions for pairing.\n\ni enjoyed the Saison de Lis (solid. citrusy and flavorful.), Heart of Gold wheat wine (surprisingly hoppy with a nice head), Vermilion barleywine (a friend said he would like it on pancakes), and the stunning Abraxas. really stunning. chocolate, chili, and malt. thick, rich, yum. tasted my husband's, tasted more of his, and ordered my own 5 oz pour. which was the perfect amount. we timed it well to arrive just after the seasonal release of Abraxas. in a couple weeks they release the bourbon barrel-aged Abraxas and you can bet your bottom dollar i'll be back for it. \n\nbeautiful beers. Perennial was actually one of my favorites from beer school, among such competition as Stone, Bell's, Arcadia, Left Hand, and Sierra Nevada. (ok i can't lie Left Hand was amazing). they craft some thoughtful and remarkable  beers, and i look forward to the brews to come."], ["Great beer. Great atmosphere. Great staff. We ordered half pours, cheese curd, and deviled eggs. All were great! We chatted with the bartender for awhile and got some great recommendations for other breweries and food. We even received a free drink for going to camp (ask about that!) and some stickers. We will definitely go back when we are in the area again!"], ["Great place...out of the way for sure, it's a bit like an expedition down to Carondelet for it.  But, the beer was very good, as was the food.  Actually, the food was great, don't miss that."], ["Perennial is a delightful visit any day, any time. Visiting on a Saturday afternoon, we had a tour of the brewery operation with beers in hand, so interesting! Every Thursday at 6pm they release a new brew which sounds like a great time too. If you like Belgian style ales and artisan craft, this is a great place for you."], ["If you haven't checked this place out yet then scrap your weekend plans and check it out. All their beers are super smooth, I loved the brew crew, the food was small appetizers but they were all amazing."], ["Stopped in to their tasting room after it was recommended to me by multiple people before a trip to Saint Louis. \n\nThe service was AMAZING.  There were two bartenders and they were both so nice.  You can order tasting sizes of any beer on tap. It was a girls weekend and we'd enjoyed a night out the night before so we just wanted to try some offerings before purchasing some bottles. All four beers we tried were delicious. Abraxas (which was basically our reason for going), Black Walnut Dunkel, Saison De Lis, and IPA #5 were our choices.  And the IPA and Abraxas, in particular were very good. Both were extremely complex and tasty.  My friend (\"The Bride\") described the Abraxas in this way, \"Wow that's really good. It's quite a ride.\"...haha. \n\nLike I said, we only stopped in to buy some bottles after trying some beer so we didn't stay long but we did order some bruschetta and it was also delicious. They sell glassware and T-shirts as well.  We bought a fair amount of bottles and they just gave us a case to carry them all in. \n\n\nGreat beer, great service, they use local products....great experience all around, was glad we got the chance to stop by!"], ["Always fun to come here and create (healthy-pours) flights for yourself. They do fun flavors and have chill inside and outside spaces."], ["Love this place! Just note that the entrance is next to their giant parking lot, not on Michigan. \n\nReally like that they have sample pours (5oz) for $2 (!!!) and they have most of their own brews on draft. Chill place, good for groups, a fire pit is in the front. Friendly folks, cheap and delightful beers. As a frugal person, I love that."], ["I really like this place, but it can definitely improve. \n\nReasons why I like this place:\n- it's a few blocks from the Des Peres bike trail\n- it's a very cool space\n- they carry other's beers, not just their own\n- their objective to brew belgian-american hybrid brews\n- they will carry @Salume Beddu (@Yelp, you really need to add referencing functionality. it's so 2007, which makes yelp 2006...no bueno) -- so damn exciting\n- the copper bar top\n- the dart board\n- they use a gravity brew system\n\nNeed to improve\n- their beer. sadly, it's not 'there' yet. it's not bad, but not great, yet. i believe they can get there, hence the 4.\n- the leaves painted on the wall\n- cash only"], ["Thank God my buddy drove, 'cuz I don't thik I would've found this place on my own.  However, now that I've been there, I think I have dropped enough breadcrumbs to find my way back.  And find my way back I will.\n\nWhat a cool little brewery hidden away in South County.  Apparently the building is an old Coke syrup factory that was sitting vacant for a decade or so until some folks started moving into it.  It looks good.  It feels Bohemian..and I don't even know what that means...\n\nThe interior is still pretty sparse, but it didn't stop it from being busy on a Saturday afternoon.  The beers are good and they have a small menu with a few sandwiches and cheese plate offerings.  I had the grilled cheese with bacon, and it was tasty.  The service was good, and their payment system is hi-tech and interesting (I was sent a text message with my receipt).\n\nThey offer tours once a week at 2pm, and it's a nice, informal walk-around of their brewery.  Do the tour.  It makes you appreciate just how hard this place is working to get a quality product out there.  It's not run by machines mass-producing and capping bottles; it's folks using their hands to bottle beers, apply the labels, and press down the bottlecaps.\n\nSupport your local breweries!\n...and get a good grilled cheese along the way."], ["This place is tucked away off the highway.  If you don't come looking for it you won't find it.  But when you do its worth it.  \n\nFor the most part, this isn't the bar for you if you're looking for traditional pale ales, hefeweizens, etc.  I like that.  Perennial saw a need in the beer community and moved to focus on styles that breweries won't paying enough mind to. \n\nYou may not love everything here but that is part of the craft brew experience and renaissance we're experiencing.  The people at perennial are pushing the limits well beyond the norm which means that everything may not fall in your realm of preference.  \n\nThat said, the staff are knowledgable and the beers you do enjoy will be among the best you can sample in the STL.\n\nI'm not wild about the lighting by the darts but that's a small thing."], ["I've always been a fan of their Hommel so i knew thats what i'd be ordering. I asked for a taste of their Peach Berlinerweiss and i did like it except it wasn't peachy enough for me. They have a great space but the patio seems lacking. Maybe they just have too much space for the amount of tables and fire rings that they have. Either way, they seem to keep doing a great job so i'll plan on being back."], ["Best microbrewery in Saint Louis. they do a great job, seasonal selections are great.  We didnt eat however."], ["Great relaxed environment in the tasting room - open, clean, but comfy too. They have board games available to play while you sip, and awesome sharable munchies. I liked the Saison de Lis and the pretzels... Highly recommend both!"], ["St. Louis is a beer town.  In addition to the city's largest brewery, Anheuser-Busch (Budweiser), there are some 40+ breweries in town.  These are microbreweries and are generally pretty good.  However, there is one that stands above the rest: Perennial.\n\nPerennial is the best brewery in St. Louis, and I have to imagine its probably one of the best in the country.  I have never had a beer from them I dont like.  If you go there, you will see their menu, which has around 10 different beers on it.  Most are on tap, but I think some are in bottles.  You can also buy a bottle of some of their brews.  They change up their lineup fairly frequently, so if you go several times, you will have the chance to try different beers.  They also serve some food, mainly snacks/appetizers and a few sandwiches.  I've only gotten one of the food items once (chips and dip) and I received a generous portion of chips and a tub of dip that did not match the chips in terms of quantity.  Regardless, it was good.  \n\nBack to the beers, I think the best thing I can say about Perennial, other than that they rock, is just about every time I go there, in listening to the other people at the bar, there is always someone there from out of town.  It seems like beer aficionados come from all over the country to go to Perennial.  I dont know if these people come to St. Louis specifically to go to Perennial, but it sure seems to be on their hit list when they do make it to town.  If you go here and they have it, try the Abraxas - it's one of the best beers I've ever had.  Overall, if you want to go to a brewery for drinks, go here.  You can't go wrong."], ["As a homebrewer and a fanatic of all things beer, I welcome as many craft breweries that want to open in St. Louis.  That being said, this place is just not my style.  I'd rather drink a solid rye pale ale and eat a pastrami sandwich than sip a poorly executed Strawberry Rhubarb Belgian Wit and over-priced deconstructed vegetarian pot pie.  All beers, and all places, have their fans so please give the place a chance and decide for yourself.  Just because it is not my style doesn't mean you won't like or love it."], ["As many times as I've been to St. Louis over the years, I can't believe I just now made it to Perennial. It may be my new favorite spot.\n\nI guess it's understandable why I haven't been here, as it isn't exactly close to major attractions. It's in an industrial, blue-collar area south of downtown near the river. Yet it feels like you've wandered into some lovely little Belgian farmhouse brewery when you arrive at the tap room.\n\nIt's not a big place, but it's a cool spot to hang out. It was a little too chilly for the patio outside, but I can't wait to come back and sit and sip there sometime (you can bring dogs, too).\n\nOnto the beer, which is the most important thing. This brewery specializes in saisons, Belgians, ciders and the like. I was told that the draft list was a little more boring than usual when I was there, but I still found it to be pretty amazing. I particularly enjoyed the Hommel, their well-known Belgian pale ale. You can get full pours or 5 oz tasters, the latter of which is very reasonably priced at $2-3 and allows you to try many different ones.\n\nI was there on a slow night, but the bartenders were extremely friendly. They even comped me a beer when they found out I was a beer nerd from out of town. Later, another bartender opened a bottle of the Foeder Saison and poured me a glass on the house. It was a spectacular saison, one of the best I've ever had. I ended up buying a bottle to take home. \n\nThere are also some small bites on the menu. I got the pretzels and beer mustard. Loved the tanginess of the mustard, and while the plate is meant for sharing, I devoured the whole thing myself.\n\nThere are some amazing things happening with small breweries in Anheuser-Busch's hometown, and Perennial is my new favorite one."], ["Stopped in for a few beers when we were in town. I had heard of perennial but only had it one time. (They don't distribute much to California) Inside was a little tasting room with a bar and some tables. We ordered a few small pours. Abraxas was absolutely fantastic! A great roasty stout with sweet cinnamon notes. So glad I could try it from the source. \n\nThe vibe was pretty chill and mellow and we were able to sip on some tasty beer and relax. Can't wait to go back"], ["Phenomenal beer, food and service.\n\nGreat all around place.  Being from Denver, one of the Meccas of the craft brewery movement, it's great to see places like this in St. Louis, especially because it's right in AB InBev's lair.\n\nKeep on making awesome, high quality brews!"], ["Just when I thought all breweries in the lou were going to be 5 stars for me---I had to go and visit Perennial today.  I appreciate the fact that they have high alcohol content beer and found that I really enjoyed the black walnut brew.  However the atmosphere is lacking....it is too large for that much grey/white/ colored wall with the open ceilings showing the duct work.  They really could do a lot with just minimal effort to enhance the atmosphere and make it inviting.  The food offerings left a lot to be desired.  I was hungry but was not willing to pay 9.00 for a grilled cheese we opted for the 6.00 pretzels and sorry you only get some stone ground mustard to choke those back with....some cheese sauce would have been wonderful.....What really knocked a star off for me was the server couldn't wait to remove our pretzel wood board from in front of us and we were clearly still eating and enjoying our time.....for some reason she was dead set on getting that little wooden board out of the way....this pissed me and the hubby off because it wasn't busy so it wasn't like they were running out of these things...and we just thought it was uncalled for....I would buy this brewery's beer if I saw it at the store but not sold on going back to the place it is brewed when so many other spectacular options are available.."], ["We love this place so much, great beers, great staff, wonderful time! We always make a point of stopping in once, twice, maybe 4/5 times when we visit for a day or two... haha. If you're a newbie to perennial, you should definitely go to camp ;) just ask your friendly bartender, they'll walk you through it! Go go go! Enjoy epic beer, and make sure to visit when they release the greatest Mexican chocolate stout I've ever had, (and I'm not usually a stout guy) Abraxxas... omg"], ["My husband and I went for the abraxas release. I normally don't like heavy beers but the abraxas is smooth and the hints of vanilla and cinnamon are delicious."], ["Honestly, I love that this place is tucked back in a neighborhood, where you wouldn't normally catch me wandering about at night... but this place is really neat. I don't usually eat at breweries. I go to them for the industrial atmospheres that I love. \n\nFirst and foremost, they have a selection of beers that are virtually amazing...\n\nGet the Abraxis... you won't find it in bottles or really anywhere else at all. \nHome Front. Anything Saison. There is another one, that I love, that they have on tap at Flying Saucer, and what seems like nowhere else --- in the Fall, also amazing.\n\nThe Hommel is delicious. People who like hearty wheat ales with an orange peel will find copious options here for just that palette. The environment here is intimate and if you ever get the opportunity to do the tour and tasting and see the behind the scenes production - do it. \n\nTry Perennial, you will not be disappointed, in the least, with the beers --- you will then find yourself gravitating towards choosing Perennial ales while out at various establishments."], ["Dear Perennial,\nWe need to talk.\nSee, I want to love you. I want to give this review five glowing shiny stars. Your beer is some of the best in St. Louis. Fleur de Lis is inspired, and your imperial stouts (Abraxas, Fantastic Voyage, etc.) are simply divine. You're doing things with beer that no one else is doing just for the heck of it, and the results are creative and delicious. You have a new beer release every WEEK! That's awesome. \nBut... right now you're a also a restaurant. And as much as it pains me to say this, your restaurant could use some serious work.\nThe last couple of times I've been there, you've been out of at least one major menu item, usually the most interesting sounding thing on the menu. Service has been very, very slow (though always friendly), to the point that I've had to check to make sure our food wasn't forgotten. And when we've gotten it, the food has been very hit-or-miss. Some of it (a brisket sandwich comes to mind) has been superbly tasty and worth the long wait. Others, not so much. The cheese plate is embarrassingly overpriced, and the blt fell apart after one bites (and wasn't anything special). \nThe problem is, the menu changes every week. It's a really cool idea, but the fact is you just don't have the infrastructure to maintain that frequency of change. It's getting increasingly hard to convince myself to drive that far out of the city for a highly unpredictable meal. I wish it weren't, but it is.\nPerennial, don't get me wrong. I'm still going to tell every beer nerd I know to try you out. Your beers are fantastic and deserve all kinds of praise. But as long as the dining experience remains so wonky, you're going to fall short of the five stars your beers really deserve."], ["I really should have read the reviews for this beforehand, as I hope you are doing now dear reader.  Please note that, as others have mentioned, the entrance is behind the building.  Let me repeat:\n\nTHE ENTRANCE IS BEHIND THE BUILDING!\n\n My husband and I came to St Louis to visit friends for the weekend and convinced our friends to spend the day visiting local breweries.  As you may or may not know, Indianapolis has had a local beer renaissance in the last five years, and it seems that the same thing is now happening in St Louis!  This was the third brewery we visited on our trip, and I think they are doing some great things here, particularly for such a young brewery.  We got the sample board so we could try everything, and though I spent the whole day drinking beer, I specifically remember the Saison de Lis (brewed with chamomile), the Black Walnut Dunkel Weiss, and the Abraxas, a chocolate stout brewed with ancho chilies.  All three of those were really, really excellent.  The tasting room also has a clean, casual vibe and is the kind of place you could hang out all afternoon.  Our server was also very nice, and happily chatted with us about the beer (we were perhaps a bit chattier than normal, with this being the third brewery...).  \n\nConsidering they are producing beers this good having been open for just a few months, I look forward to seeing what they develop in the years to come.  This was definitely worth the drive south."], ["Beer is some of the best in Stl, food is creative and good.  A must visit on the STL beer circuit."], ["I went to Perennial on a Wednesday night to try it for the first time. I was after some Abraxas since I missed it when it was sold in Chicago. To my pleasant surprise, they had the Coffee Abraxas!...but only in a bomber to be consumed on sight by my lonesome. Do I do it? Do I do it? Yes, i did it. I couldn't try other beers because it wouldn't be safe.\n\nThe bartenders were great. One gave me a high five and said 'no judgement' because of what I ordered. Once I had a sip of that wonderful ambrosia, I drifted off into the clouds and happy feelings overcame my body. I didn't know beer could do that. I think I saw a unicorn, too.\n\nIn my good mood, I bought 2 bottles of regular Abraxas to go and 2 other beers. I wrapped them nicely in my baggage and they made it home, even though TSA checked my bag.\n\nI really like the craft beer community. I ran into someone who I saw regularly at 4Hands and I had nice conversation with the guy next to me. \n\nTwitter is more informational about special beers they'll sell day of versus their website, which only has a draft list."], ["This was a cute place in the middle of kind of an industrial neighborhood. It's definitely a driving situation and not a walk. We stopped in for beers while on a quick visit to St. Louis. They had fun 80s music playing (it seemed like the pick-of-the-day by the bartenders sort of music) and we were greeted as soon as we sat down.  The selection of beers was pretty awesome with a list that included some funkier options as well as some IPAs and even a cider, I believe. While we had other plans for dinner, we selected their chips and with a pimento cheese dip as a little snack. As I recall, the menu was limited and consisted mostly of snacks and quick sandwiches. Still, that pimento dip was so good I could have just eaten that. Really hit the spot.\n\nWe couldn't leave without purchasing a few bottles (I found them all to be reasonably priced for the quality and their reputation) as well as the requisite t-shirt and hat for my husband. \n\nWe would definitely stop back if we were in the area again! Neat place to check out as part of the St. Louis beer scene!"], ["Okay, okay, okay, okay. What is the deal with these bad reviews? Perennial Artisan Ales is one of the best microbreweries in the Lou. \n\nI have been there twice and both times the service was amazing. My husband and I went there this weekend and both waitresses we had were so friendly. \n\nThe beer is incredible. Have not had a bad beer. On my last visit, I got the Saison De Lis. What I call a \"Real Women's beer,\" it's a belgian-style ale with chamomile that tastes as fresh as it sounds. \n\nI am not sure what the wall color has to do with the experience. I think the decor is just as minimal-chic as 4 hands and Schlafly. \n\nOkay, what I will say, it's location is at the intersection of ghetto and nowhere BUT it's well worth it. And yes, when there is a lot of people, it takes a while to get a beer...because you know, there is a lot of people. \n\nOverall, Perennial Artisan Ales is wonderful!"], ["Perennial is my favorite St. Louis brewery, and I enjoy visiting their tasting room. It's a bit out of the way in an industrial area south of downtown, but worth the drive for their their small-batch craft beers on tap. As some of their beers (such as stout beers Abraxas or Sump ) are highly sought after, the tasting room my be the only place to drink these beers without going through a lot of effort in procuring a bottle. As far as beer goes, it's a little expensive, but worth if for those who appreciate high quality craft beer (half pours of some beers such as Sump Coffee Stout is $6, around $20 for most 375 mL bottles- aged bottles in the cellar may be more). \nThe tasting room is cozy, with seats around the bar and 10 or so small tables. \nThey have bottles of their beer to purchase (some for consumption on premise only), as well as merchandise for sale.\nA small selection of snacks are offered, mostly from local vendors. It would be nice if they expanded this a bit, or at least had some vegan offerings besides Billy Goat Potato Chips.\nIn any case, if you are into high quality craft beer, definitely check out Perennial."], ["We love this place so much, great beers, great staff, wonderful time! We always make a point of stopping in once, twice, maybe 4/5 times when we visit for a day or two... haha. If you're a newbie to perennial, you should definitely go to camp ;) just ask your friendly bartender, they'll walk you through it! Go go go! Enjoy epic beer, and make sure to visit when they release the greatest Mexican chocolate stout I've ever had, (and I'm not usually a stout guy) Abraxxas... omg"], ["After reading a few reviews I decided that this would be a great spot for date night (especially since the beau is a beer lover). I really wanted to like this place but they made it very difficult.\n\nUpon walking in we were both really confused, no sign saying to seat ourselves or any employee in sight. After standing there for a few awkward seconds I decided to walk up to the bar and ask if we should seat ourselves or if we could sit at the bar since we were going to order food. Fast forward to 15 minutes later and someone FINALLY looked in our direction. I understand they were busy since they had a new beer come out that day but there were 3 bartenders behind the bar and it took them that long to notice we were standing there. \n\nWe were already a little annoyed but decided to stay because I started to get a headache and needed to eat ASAP. We ordered some grilled cheese sandwiches and 2 of the special beers that they had just released. We chatted about the holidays and our plans and after about 45 mins we turned to each other and said \"we actually ordered our food right?\" When a bartender finally noticed our taste samples were empty (they had been for quite a while) and came over we asked about our order. After a few mins he came back and said it would be up soon... 15-20 mins later our sandwiches came out. That's an hr for 2 grilled cheese sandwiches. ONE HOUR. They were good but not that good! When he came back we asked for another beer and before my boyfriend could even respond the bartender walked away! My bf actually had to say to him \"excuse me, I would like to order a beer\" and he came back, we couldn't believe how rude he was!\n\nUnfortunately we will not be venturing back here... The bad service just ruined it for us."], ["Man, Perennial is a hidden gem. Not their beer, their beer is extremely popular in St. Louis, but the brewery/brewpub itself tucked into an industrial area of Carondelet is so neat. It's a great spot to grab some pints on a lazy weekend evening, it's rarely slammed and there are a ton of activities: darts, board games, a huge patio, etc\n\nThe beer and food are both great, I think a lot of people overlook the kitchen since it's a brewery but there are some real special dishes on the menu, especially the seasonal offerings. Some of the best stouts in the city."], ["Perennial continually improves on their beers. They make just amazing stuff there.\n\nIf you go on Thursdays, they open one of their small batches. If you go on friday, it's likely already gone.\n\nThey've also been having a contest between their brewers for \"best IPA\". The current is an imperial IPA that is likely to hang around permanently, I'm told.\n\nTheir food menu changes and is tasty as hell! I loved the chicken sandwich I had recently, but it's already disappeared from the menu.\n\nThis place: do it."], ["(4) ~ very good overall beer & service\n\nBEERS TRIED:\n** Hopfentea = (4.5) Very Refreshing!\n* Prodigal = (3.25) too sweet for me...."], ["Dear STL,\n\nYou have NO IDEA how good you have it when it comes to great beer. You have this genius, this beer guru, just casually setting up shop in your backyard. Beer genius, ain't no thang. \n\nThe owner at Perennial is doing great things. He's doing ballsy things. Like AC/DC \"Big Balls\" things. One new beer, every week, 52 weeks a year, Thursday at 6pm. That's NUTS. \n\nSTL. You are spoiled and you don't even know it. \n\nThe owner cites Jolly Pumpkin as the ballsiest brewer in the country. He's right. They use some sort of crazy wild yeast, brew some hella funky but unique and respected beers... But what he's doing? That takes a whole lot of hutzpah. \n\nThese beers are clever. They are typically a tip of the hat to the great beer country of Belgium, but meant to be lighter. Trust me, I was initially disappointed at the less than 9.0% ABV tap list... but I got over it. I understood it, appreciated it even, that I could have more than 3 beers and not be wrecked. They are different. Appreciate that they are different. This will be the Jolly Pumpkin of STL, maybe even better. \n\nHowever, the waitstaff / bartenders ... need some retraining. They cannot handle a full bar seamlessly. There are severe service glitches as the place gets busier. \n\nRedeeming plus to the inconsistent service? They have some ridiculously sexy cheeses on their cheese board. Amazing cheese with delightfully different yet familiar beers trumps sketchy service any day of the week. \n\nI beg of you, Saint Louis, love and cherish this place. It is truly one of the best things you have in your city. \n\nSincerely,\nChicagoan corrupted and spoiled by Michigan microbrews transplanted in a beer desert known as Houston, TX\n\nPS - if you don't want him, I think Houston could benefit!!!"], ["This little oasis in the middle of an old industrial complex is well worth the drive. The simplicity of the design and masterful craft beer experience is what sets this place apart from other breweries. This is my favorite brewery in St. Louis. Highest possible rating.\n\nPros: \n-A plus craft beers (some of my faves: saison de lis, IPA 10, Hommel, Foeder Saison, suburban)\n-staff are true beer enthusiasts and friendly \n-simple design with true craft microbrewery feel\n-large open seating with available patio and dart games\n-food was superb: deviled eggs, meat and cheese board, soft pretzels accompany food very well\n-great value for beer they offer a tasting for $2, a pour for 5-6$, and a growler fill for $12-15\n\nCons:\n-bit of a drive from STL city\n\nI will make sure to take part in the tour offered every Saturday at 2 pm in the near future. \n\nTip: check website perennialbeer.com and click \"tasting room\" and scroll to bottom to see availability and pricing of current draft & bottle beer. Enjoy!"], ["This is a cool, chic brewery interior. The bright space is dotted with high top tables with funky teal chairs. The staff was friendly and helpful. We chose a cozy spot in the back at one of the barrel tables. The beers we had were excellent and the space was comfortable. There are a few dart games and some other board games. It was a quiet, relaxing bar to hang out on a snowy Sunday afternoon. I would definitely return!"], ["Their Pils is probably the best around the Mid-South. Oh I love German beer. What a pleasant surprise. Meat & Cheese board and Cheese curds are  a must!"], ["Perennial was one of the first spots I ever visited in St. Louis.  We always make a stop, no matter how fast, each time we are there.  This time around we got to enjoy Maman and coffee Abraxas.  You can never go wrong with those beers or any others you choose.  \n\nThere is a lot of seating.  They serve food! Do yourself a favor and visit.  So fun!  You'll probably want to bring an Uber or Lyft... :-)"], ["I usually only think of stouts when I think of Perennial - amazing, flavour-packed stouts like Sump, Abraxas, and Fantastic Voyage.\nOn my first visit to the Perennial tasting room, though, one of the most stand-out beers - maybe because I wasn't expecting to love anything other than a stout - was their Apricot Gose. Sooooo salty and delicious!\nEach of the stouts was the best version of such that I've ever had (Sump and Abraxas available only on draught, and we missed the minty BA 17 altogether, but we were able to bring a case+ of this year's phenomenal, coconutty Fantastic Voyage home...woot!!) but the Apricot Gose really caught me by surprise with awesomeness.\nNoted, Perennial. Eff'n *noted*.\nNo one puts Baby in the corner.\n\n-Staff is supernice (unlike some of Perennial's \"side piece\" - if you kwim -  pretentious relatives).\n-The food is rockin' - the cool, herbed cheese curds were completely different than the melty mozzerella-stick-like curds I'd come to expect (not that there's anything at all wrong with mozzerella sticks - I love them, actually - but these curds were just *elevated*. This is how grown-ass adults do cheese! I *like* adulting! \n-(Currently not serving food on Sundays)\n-Perennial has steel-tip darts!(*again* with the adulting! way to take frathouse soft-tips to the next level!) Mr. Man was too intimidated by my beer-driven defensive dart skills to challenge this time though. He gets a bye, this once, but next time, sir.... it's ON!\n-No flights (other than the darts, i mean) available, but you can get half-pours of pretty much anything on the menu. Choose beer with confidence - hard to go wrong with these world-class beverages."], ["Such good beer but it's a challenge. But every person in my party found a new and exciting beer to enjoy. The food was tasty and the service was friendly. Love the location too."], ["I came here for the Abraxas of 2017. Excellent place and tons of parking. When I first started coming here in 2014 parking was a pain but it seems they have fixed the problem. I only stop by just to pick up my beer and leave but the place is awesome. They have a huge outdoor patio with fire pits and the inside bar are is very large with several couches and plenty of sits. Also the place is family friendly. I would imagine they are pet friendly because they have the outdoor seating."], ["The address is on Michigan but the parking lot and entrance is on Virginia.  The main reason to go here is for the beer.   They are the best brewery in St. Louis.  No one else comes close to putting out quality like Perennial does.  They have a limited menu with a few appetizers, cheese plates and a handful of entre's.  The food they serve is high quality ust don't expect much selection."], ["I want to start by saying I really wanted to like Perennial. My husband and I love craft beers and are always on the lookout for tasty IPA's or porters fresh from the source.\nWe were there last night around 9pm. The place was comfortably busy. Very low key and friendly vibe. Nice ambiance. We both ordered the IPA #8. \nIt wasn't good. In fact, it had a serious funky taste going on, not unlike a beer poured into a dirty soapy glass or from dirty lines. I looked over at my husband and he was staring at his beer frowning. We don't frown at beer! He agreed something was really off.\nThe bartender said the brewer used 2 different yeasts and knew not everyone would like it (so knew it was bad) but \"what the hell\" and decided to use it. ??? I said I couldn't drink it, he said no problem would you like something else? I said sure, whatever you have that is nicely hopped. He brought another beer and said That will be $5. Hmmmm.... \nI guess what he gave me was a Saison. It tasted like a bar of soap. So we decided to cut our losses after $15 of bad beer plus $3 tip and left full beers on the bar. \nWe won't go back."], ["I brew my own beer.  Because I am a home-brewer I am always excited to see a small craft brewery open in Saint Louis.  I visited Perennial Artisan Ales last Thursday after work and had a good time. I must note, however, that the tasting room is a bit difficult to find.  The address is on Michigan but the entrance is in the rear of the building near what appears to be the entrance to residential apartments or lofts.\n\nI ordered a flight of every beer that was on tap including: Hommel Bier, Southside Blonde, Strawberry Rhubarb Tart, Fresh Hop Red Saison, \"Heart of Gold\" Wheat Wine, \"Saison de Lis\" Chamomile Saison, \"Peace Offering\" American Brown with Maple Roasted Cushaw Squash (Yellow Tree Farm), and Black Walnut Dunkel Weisse.  The Fresh Hop Red Saison and Heart of Gold Wheat Wine were my favorites.  I did not care for the Strawberry Rhubarb Tart.  I have tried it once before and each time I have sampled this brew it tastes of burned plastic.  I was instructed by the bartender to let it warm up to room temperature and have another go.  The flavor did improve, but I could still taste smokey plastic.\n\nThe tasting room is sparsely decorated and has a little nook with two boards for dart play.  Growlers and glassware are available for sale but do tend to sell out quickly.\n\nStop by and try a pint or two and support your local craft brewers."], ["Perennial is located in the Temtor Lofts Building. The place reminds me of a brewery tasting room more than it does a bar. They have six beers on tap and sell beer by the 750ml bottle as well. There's a kitchen that will be ran by Entrestl.com, starting up after Thanksgiving. Until then, don't come here hungry as there is only just a few bar bites.\nI didn't care for any of the beers that I tried (Hommel, Red Top, Saison de lis) @ $5 each. Interestingly, you can go down the street to some neighborhood bars and get the same beer for $3.50. \n\nI look forward to seeing what Perennial has to offer during my next visit.\n\nThey do now accept credit cards."], ["I went here to pick up a bottle of their seasonal beer, Peace Offering. Once I managed to find it, I had a really different but enjoyable experience. The atmosphere is very welcoming, urban, and casual. The staff seemed happy and laid-back...as in walk up to them and order your own food. :) Everyone was so friendly and the two snacks we tried were wonderful. The house made salsa and cheese was smoky, unique, and delicious. I don't care for Moon Pies but theirs was ah-mazing!!! The creator :) came out and told us how he makes them...he seemed really pleased that we enjoyed it. The beers were good...the music was fun but not intrusive...I had a blast."], ["Perennial brews are the equivalent of Fizzie Instant Sparkling Drink Tablets. The  supercilious staff and the Thursday  afternoon worshipers  fuss over the latest  \"release\"  as if they had found the Holy Grail. STL and the metro area have almost 40 breweries..Move on."], ["I always enjoy my time at Perennial. The staff is all super friendly especially Emily who always has a smile on and good conversation to share. Tonight we biked in mostly for food but had some beers as well. We had the carnitas (pictured), the panzanella salad and the devilled eggs. I had the Owen a slightly sour favorite of mine and a Masterfade which was a really nice medium IPA. Then I had a small pour of La Boheme- an aged sour (pictured). My fiancee had the intentially indulgent which was a big dark beer but very smooth and followed that up with a nice easy drinking vacation dad(pictured). When I asked about other beers they were nice enough to describe them for me and give me a small taste which I always appreciate because it is the best way to know how you will like it. Always a great time at Perennial!"], ["Craft Beer at Its Finest!\n\nIn 2011, Saint Louis saw a huge burst in the craft beer scene.  Breweries were popping up all over The Lou.  One of these breweries was Perennial Artisan Ales.\n\nHonestly, I was not a big fan of Perennial at first.  During my first visit, my favorite beer was a guest tap, which was a 2nd Shift ale.  However, we will save that for another review.  Like many of the best breweries, they had some growing pains, but when they found their niche, they hit the ground running.\n\nPeople come from all over the country for Perennial's big barrel-aged beers, particularly Abraxas:  an imperial stout brewed with ancho chili peppers, cacao nibs, vanilla beans, and cinnamon sticks. This black gold has given them many accolades in the craft beer community.  Other popular imperial stouts include the minty 17 and the coffee-laddended Sump.  However, not everything on the draft wall is dark.  Perennial also dabbles in Belgian-style ales, saisons, barleywine, and the occasional IPA.\n\nIn addition, they have a pretty decent food menu, which changes periodically.  You can snack on meats, cheeses, pretzels, or even a handful of sandwich options.  Everything that I've had has been pretty good.\n\nPerennial also has one of the best staffs in the local scene.  Some breweries can get pretty pretentious and make little effort to connect with patrons.  This is not the case at Perennial.  The bartenders are incredibly courteous and friendly.  They even occasionally \"go to camp\" with the patrons.  During camp, the entire bar chugs a beer of the bartender's choice.\n\nMy only problem deals with hours.  Perennial is only open five days a week.  The tasting room is available Wednesday through Saturday in the evening, and they close at five on Sunday.  Perhaps that's a small issue, but I would like it if they expanded those hours.\n\nPerennial Artisan Ales is no secret in the craft beer community, but if you haven't been there yet, definitely check it out."], ["Really good beers. The outside seating area was awesome. However if you want to sit inside it might be a little challenging it's kinda small. The pretzels were awesome."], ["A lot of good beer here plus an excellent outdoor space. They have several picnic tables across the lawn, all socially distanced, and many with umbrellas. They also have a dedicated patio space  with good social distance.\n\nYou can order beer from their website for pick up or buy it by the can/bottle there. They have 2 pick up areas to help things go quickly. As of beginning of Sept 2020, still not filling growlers yet. \n\nI also appreciate their beer selection. They have a good mix of light and dark beers of varying abv and gravity and bitterness. They do lots of creative collaborations too."], ["Perennial seems like the most promising of all the brewers in St. Louis. From what I've tried so far, they're in the front of the industry putting out reliably flavorful and continuously inventive stuff.  \n\nWe lucked out during our visit and found a bunch of their best beers were on tap. The Abraxas chili stout and Black Walnut Dunkel were both home runs, and the experimental run of the \"IPA #8\" with brettanomyces was also excellent.  They do taster flights, which makes it all the easier to tour their entire lineup.\n\nBesides the beer, though, this place was a letdown in terms of setup.  The space felt bland and empty like an unfurnished art studio loft. It was also a really slow night during our visit, so it may be less yawn-inducing when there's an event going on involving a crowd with a purpose at the brewery.  We really enjoyed the beer, but we didn't feel like hanging around for long."], ["This one is painful for me. I used to trumpet this place like nowhere else. If you look at my Untappd, the 5 rated beers are riddled with Perennial offerings. I do not understand what happened here. \n\nThe quality has dropped off a cliff. Bottle variation is all over the place. Literally every purchase is akin to buying a $50 lottery ticket. Some will be winners, a bunch will be losers. This is true even among the same product. \n\nThe beers I used to love are butchered versions of their former selves. Abraxas is just not what it used to be. BA Abraxas was horrific this year. The IPAs are mediocre, sours border on undrinkable. \n\nWhat happened? This is the most disappointing brewery on earth to me now, simply because I know what they're capable of, and they just seem to have given up trying to be world class. My advice to any beer tourist coming to town? Don't bother with Perennial."], ["Perennially delightful, even in COVID times. Second visit in early September 2020 (first visit in fall 2019 was also 5-star). We sat out in their patio which has about 8 picnic tables, plus more over on the grassy area. Easy walk-up ordering or pick-up option. Light snacks for food. Excellent, quality beer. Friendly staff. We'll be back!"], ["Very chill brewery, welcoming atmosphere. Couches and comfy seating. Staff is extremely friendly. I don't drink beer but my SO LOVES perennial, finds their brews very unique and high quality. I only wish it were closer to the city!"], ["Not sure why Perennial Artisan Ales does not have a five star rating on Yelp. Their beers are as near to perfect as any brewery I've ever been to. And that's not just my opinion. Perennial receives award after award at a national level for their brews. They are always noted in high regard amongst the craft beer gurus. \n\nLet's just start this review out with the heaviest hitter. The creme de la creme. Abraxas. It's only available once a year. Most years you have to get on a pre-order list that is limited to four bottles per person. Is it a bit pricey? Yes. Is it worth every penny. FOR SURE. Abraxas is an imperial stout brewed with ancho chili peppers, cacao nibs, vanilla beans, and cinnamon sticks. Perennial always has a few variants of it including coffee and vanilla. They're all equally as good. This finely aged beer packs a punch at 11.5% but lacks that boozie taste. There is no beer at this high of an ABV that's as smooth as Abraxas. Each year I get so excited for the release and jump at a few extra pours on draught when I pick up my four bottles. This year was no different! \n\nWe braved the cold to share a few glasses of Abraxas on the patio of Perennials South City brewery. There were a few fire pits and outdoor heaters strewn about to help fight off the cold, but due to social distancing we tried to stay further away from them. So pro tip, if you're going to sit outside at Perennial bring some blankets because their picnic tables can get cold! \n\nIf you're hungry, you can ingest some Abraxas in the form of a slow roasted chili while you're sitting on the patio. It's the perfect way to celebrate the season and to attempt to keep as warm as possible.\n\nOverall, I know that Perennial can sometimes be misconstrued as a snobby hipster brewery. But with beer as good as they're producing. I'll accept just about anything."], ["So I had two negative experiences with Perennial until my most recent visit. Both my friend and I were definitely NOT fans and it took some serious persuasion on my part to convince her that we need to give it another go. I've read oh so many articles singing their praises and thought to myself \"what are they tasting that I'm not?\"  I decided then and there that I'm going to find out this time. \n\nWe needed some potable libation after dinner, so we made our way to Perennial. Parking was a breeze considering it was a Friday night. We found seats at the bar, skimmed through the menu and decided we needed one of everything. They specialize in Belgians and saisons, so in theory, I should be in my element. The beginning was a bit rough, but as we made our way through their offerings, I finally tasted what everyone else did! Yes, they're doing amazing things with their beer and yes, if you're in St. Louis, Perennial is a MUST."], ["Chalk it up under \"used to be great\". Perennial was the best in Saint Louis for years. Far superior to even the neckbeard haven side project. The quality has deteriorated so much over the past two years I just try to avoid it. I'll be pleased when my membership is over so I don't feel obligated to pick up beers that will be tested and poured down the drain because they are just plain terrible. The final straw was how undrinkable maman was this year. Formerly one of the best beers in the Midwest, it was poured down the drain after attempting to choke down several sips. The sours are far too gastric acid with little flavor, the stouts are either astringent-y or so full of adjunct sugars that you will go blind or get diabetes, the IPAs are bland, and everything else is just mediocre. I'm not sure what happened but once they massively ramped up production the quality control disappeared. Once in a while they will make a winner (BA coffee stout was tasty) but unfortunately most of the time it's not worth the hassle of getting down there. If you live close by, sure - if you are a price gouging secondary beer selling douche, sure. For a normal beer lover it's time to move on.  One day I hope they turn back around. Good folks work here and they can do far better. The brewers should move on to a brewery who cares about quality as I know they can make great beers."], ["Pretty good spot. Good brews and outdoor area to hang.\n\nIf its busy, can take FOREVER to get beer. No waitresses and a pretty big bottleneck at the bar.\n\nAlso, can be a bit tricky to find. Would recommend looking at pictures, as google nav isn't always perfect at locating, since its part of a larger building."], ["Had been dying to check out the home of Abraxas and Sump. The brewery is huge with lots of free parking and tables inside and out. The taproom inside is spacious with lots of table, a long bar and even a couple of old fashioned dart boards. Perennial has a good selection of merchandise available, from T-shirt's and caps to glassware, and also offers lots of bottles and cans to go. \nThey do offer a decent food menu in addition to the great beers, featuring sandwiches and the like. Tried a few beers on tap and was pleased to get hold of a bottle of 'Sump' to take away. Overall a great brewery with friendly staff and great products!"], ["I've been here a couple of times now and I really enjoy the beer. The beer is the unfortunately the only good thing about this place. The space is not adequately used and they could add several more tables for patrons to have a place to sit down. More importantly it smells like old grease inside. I was here last night and the smell was very over powering. It gave me a headache, a sore throat, and itchy eyes. My friends and I all smelled awful afterwards and decided we needed to clean our coats because of it. My car now smells like it as well and needs to be aired out. It's quite disappointing. When I asked a friend about  the smell he said it's always like that. I find that unacceptable personally. They clearly don't have adequate ventilation in the kitchen area and I certainly wouldn't want to eat anything out of there. This brewery could be really awesome with a few minor changes. Not sure how long it would take to rid the place of the awful stench tho."], ["So after going to Urban Chestnut Beer Hall ALL THE TIME, I had high hopes for Perennial Ales. While I do enjoy the beer here, and that's really the focus, a lot of other things left me wanting. \n\nFirst of all, they only allow 3 beers to be available for growler filling. That makes me growl a little. Second, their beers are quite a bit pricier than I'm used to now. And then, they have tasting room only beers and as a first-timer, I wish everything was explained well to me. \n\nHowever, the beer i had was GREAT! I'll probably come back here when the weather is warmer and give this place another try."], ["My opinion might be a little skewed because I've been hearing how great Perennial was from my friend for the past few months. So I had pretty high hopes when I decided to try to finally try the place for myself, but unfortunately was a little disappointed.  The service was alright, but it did take a while to get a beer (even though it wasn't busy).  They have 2 dart boards, but they are on their last legs, with the boards bulging out and warping in some places, making it tough to get a dart to stick in that area.  The atmosphere is pretty chill, but the bar area is pretty boring -- concrete floor, mis-matched chairs, bland walls. They use an iphone and \"square\" for credit card payments, which wouldn't be a problem if square worked better -- it took 10 tries for it to finally read my card -- but would make me nervous if I didn't have enough cash on me to cover the bill. \n\nI tried the dunkel weiss, which usually is my favorite kind of beer, but it came up short. A few friends got the peach weiss, which was very peachy, but they both really enjoyed it. There are several other better microbreweries in STL, which makes me question if I'd go back to Perennial. \n\nPros: outdoor seating, parking is easy (lot in front)\nCons: beer is mediocre, boring atmosphere, dart boards in bad shape"], ["I could not love Perennial more. Every beer they make is excellent. I particularly love their stouts, from Sump (coffee stout) to Prodigal (oatmeal milk stout w/ vanilla beans) to Maman (barrel aged imperial stout). You honestly can't go wrong. The brewers put so much heart into every beer. The bar staff is always 100%, every employee is dedicated as heck. I like to come to Perennial with a book or a crossword puzzle and just hang out. I also like coming on Thursdays for new beer releases! Every visit is a new adventure and I highly recommend Perennial for the beer, ambiance, and local pride."], ["I loved my experience at this place. The staff is super friendly and it's a great place to grab a drink with friends. I got a cocktail which was very refreshing . I'll be back!"], ["3.5 stars.\n\nPerennial has been on my radar for almost a year now, so I was really hyped to finally go. I'm not sure if I went in with unrealistically high expectations, but to be honest, I was a little disappointed. \n\nThis doesn't mean that I didn't still have a GOOD experience. I appreciate the quality of their brews. But we sampled everything they had on tap and I just didn't fall in love with any of them. The Saison de Lis was tasty, but most everything they had on tap fell into a similar light summer beer category. The 17 Mint Chocolate Stout was also solid, though I've tasted similar beers. It's also in an odd, industrial location so it was fairly empty even on a Friday night. I'm usually ok with quiet, but something about the ambience just made the whole experience feel a little bland.\n\nI'm rounding up to 4 stars because I still believe in Perennial. I love the concept of a Belgian-focused brewery in STL, and I've heard too many good things to give up just yet. So for now, Perennial falls into the \"good, not great\" category. An upgrade - hopefully - is on the horizon!"], ["Perennial Artisan Ales is a brewery and tasting room located in the Carondelete neighborhood of South Saint Louis.  According to one of the bartenders, their building is an old Coca Cola bottling plant and has been open since September 2011.  It's a bit hard to find this place, so look for the parking lot on Virginia Ave at the corner of Davis.  \n\nI stopped by on a Saturday night and had a good time trying a sampling of the brews. I'm no beer connoisseur, but I do enjoy trying the different types, so I'll try my best to summarize:\n\n*My favorite was the Saison De Lis which has a smooth and slightly flowery chamomile taste to it.  \n*The Abraxas stout, or dark beer, weighed in at 10% ABV and had a licorice and slight chocolate taste to it.  I usually avoid the dark beers, but I did enjoy trying this one.\n *The Hommel Bier is a Belgian pale ale beer but I don't really remember this one being anything special. \n*The Southside Blonde, a Belgian blonde ale, is a smooth light beer and probably the safest choice for those who don't care for micro-brews.  \n*They also make a Strawberry Rhubarb Tart beer which I've had at \"The Bridge\".  This was my other favorite out of the five that I tried.  The smooth taste isn't overly fruity like some of the others fruit beer variations.\n\nI ended my tasting with a nonalcoholic cranberry ginger soda.  This stuff was very good, and I'd recommend trying a sample.  As for the food, I only sampled the brown butter popcorn which was very tasty and went well with the brews.  \n\nI enjoyed my visit and will be sure to keep an eye out for their products on menus around the city.  I'm not sure I'll make it back to the tasting room any time soon since it's out of the way for me, but I give them 4 stars for the beer but overall a solid three solid stars for the tasting room."], ["If you're ever in St. Louis, do yourself a favor and go here. Obviously beer is top notch, but the staff made our visit feel like we were close friends. Cheers and thanks for an excellent time."], ["Love!  We just loved our time at Perennial!  We finally, after years, made it to Perennial and were not disappointed at all!  They had some really nice IPA's to choose from, which we loved!  The staff were beyond friendly and made sure to visit with each guest seated at the bar.  There were games and dart boards for guests to use as well as plenty of \"dining\" room seating.  We did not eat, but ordered the house made pub mix....pretty good!"], ["I have one word that makes this place one of my favorite breweries anywhere.  Abraxas!  One of the world's truly great stouts.  The flavor profile is just perfect.  The spices, the chocolate, the alcohol.  It all balances to be amazing.  It's extremely limited in production and is hard to find, but whether you find it elsewhere, or come down here to their tasting room, you will be in for a treat.  My only complaint is I recently learned they are not distributing it out to St. Charles County this year.  That is pretty disappointing.  I wish they would figure out how to make more of this beer more often.  Until then, I'll be on the hunt for it like Carmen Sandiego."], ["Good place for beer, but it's really lacking in service. It took forever to get our food. We tried to get attention from the waitress but she just walked passed us and ignored us. We were very sure she could hear us but she didn't bother to stop. When we were ready for our check, she said, \"there are only 2 of us working here, you have to go inside to pay your bill.\" What a attitude!!!! We will never come to this place again."], ["My first time at Perennial was in 2016 for Small Business Saturday. I saw they had a beer on tap that my husband wanted to try and they offered tours so why not stop in? The place was hopping, clearly full of regulars and also people like us. We did the tour, the place is small but the passion is real. After the tour we stopped by the bar to grab that beer...and became members of the cult of Abraxas. Seriously, if you haven't heard there are thousands of obsessed fans. \n\nFor 2017, we knew we'd be back for the beer we loved. Launch day was crazy busy but this place knows how to handle a crowd. We didn't pre-order and still managed to grab some bottles of beer. We had snagged some draft beers inside to drink while we waited in line - still some debate in our house over which version of Abraxas is the best. I loved how this was a real community event and even beyond - we saw license plates from 4 states away and people sharing tables and drinking and eating at the food truck they brought in. \n\nI've only tried 1 or 2 drinks here that weren't Abraxas related and they were all good too. They regularly post on social media and seem to have a ton of releases so I know I'll need to be in year round this next year."], ["Low key and great ambience. Do you like board games? They have at least a doze. A modest list of beer, wine, spirits, snacks, and sandwiches. For all you coffee lovers, the Sump coffee stout is pretty good. Everything except the sump is $3 on Wednesday nights! All you local craft beer seekers, hit up this bar for an authentic experience."], ["Beautiful patio, sort of odd location off the main path. I would say worth the drive. Unfortunately very limited draft list due to COVID, but you can buy several of their beers to enjoy on the patio in cans for $5. They make a great selection of beers and there is a style for everyone. I tried their tap lager and a canned hazy IPA. The IPA was definitely the winner but I was impressed by the lager and enjoyed it even though this isn't a style I typically like. \n\nHeads up, their hours are limited right now, and I was frustrated they have not reflected this on their website, as it took 2 trys to actually make it in since the first time we arrived at 8:05 only to learn they closed at 8...."], ["Perennial is consistent with prompt & friendly service.  I look forward to their food menu, which seems to change each month to make something delicious out of local & seasonal products.  The beer, of course, is also amazing & always pleases my beer enthusiast friends."], ["Great brewery! This spot is definitely worth the drive out of the city. We came here for a free tour with our passport program and loved the staff, drinks, and atmosphere. \n\nIt is obvious that the staff members and brewmasters are passionate about what they do. Plus there's two saisons on draft, so you already know I'm a done deal. \n\nThe inside is pretty loud and I have trouble hearing in these situations, so we chose to sit outside. There is great seating out front and the lights make it a cute, fun place to drink with friends. \n\nWe can't wait to go back!"], ["Perennial is one of my favorite microbreweries in St. Louis! I have been coming to Perennial for years and I keep returning because they continue to maintain their stellar service, high quality beer and amazing food and I LOVE their stouts! My favorites are Abraxas, Sump and Fantastic Voyage. \n\nPerennial has a nice, welcoming space and they play great music. They have a large patio area with tables.The patio is dog friendly. Inside the entryway of the tasting room are some comfy couches and a lounge area. The bar is large with many seats. There are also dining tables and chairs. \n\nPerennial is known for their beer, but don't forget to try their food! Their menu is small, locally sourced and typically rotates, which I love. There are several appetizers and a few main dishes/sandwiches. You MUST try the food! My favorite food items are the deviled eggs, grilled cheese and the bahn mi sandwich. \n\nIn addition to the beer and food another reason I frequent Perennial is their customer service. The staff are friendly and welcoming as you enter. Even when the whole place is packed with people, the staff ensure that each customer gets served AND with a smile. \n\nPerennial also does special beer releases throughout the year. I have attended many of these and they are well run, organized and you can tell that much planning goes into the logistics of these events."], ["I have been there 3 times...  \n\nWhat upset me the most is their credit card payment system.  It is portable with an electronic signature pad.  You have to be careful or you'll agree to a predetermined tip amount...regardless of the size of your group,,,\n\nCons: Arrogant staff.  Limited menu and beer selection is too bizarre for the majority of people...both food and beer are overpriced.  The decor has the appeal of a concrete bunker.  Oh, and how about some decent lighting for the dart boards?  \n\nPros:  Good parking since so few people go there and the only good beer is the Belgian.  \n\nHeads up...the \"Walnut\" beer is awful."], ["Perennial consistently makes a number of great beers and is worth a visit. The location is in a more out of the way spot in town than more well known breweries. The brewery is well maintained and the staff is friendly. Perennial has a modest assortment of food. The last time I was in I got some rice krispies that I really enjoyed. You could also travel a few short blocks and get a burger at nearby Stacked while you are at it. \n\nI will mention for frankness that the neighborhood around Perennial is a bit run down. I've never had any issues, but it is something to be aware of."], ["Good brews in a strange part of town.\n\nI'm not a native St. Louisan, but headed down for some Abraxas while I was in town.  It was a Saturday afternoon and reasonably easy to grab a seat, though I can definitely imagine the place filling up quick at night.  Bartenders were friendly and weren't too hard to get a hold of and the brew was good.  There was a tour being offered, but alas we had to be up and on our way.  The few food options we saw other people eating looked good, and I'd definitely give their food a shot with a little more time."], ["This place is a must try for happy hour drinks! We started off with three 5 ounce beers and Tallow Fries for only $16. After we finished our appetizer we got an order of Fish & Chips and a Grilled Cheese Sandwich with Butternut Squash Soup as a side. Tons of food to fill you up, service was fast, and beer was amazing! #cleanyourplate"], ["I have been wanting to check out Perennial for some time. That time came last Saturday. It was great and worth the wait. The atmosphere is wonderful as many of all ages come to hang out at Perennial. Their beers are well crafted. They all have unique and delicious flavors."], ["Very good coffee stout from this St. Louis based brewery! The Sump Coffee Stout I have had on more than one occasion.  This robust coffee stout is great during the colder months of the year! The coffee aspect is quite noticeable but blends in with the rest of the beer quite well! I look forward to trying it again in the future!"], ["Visiting Perennial Artisan Ales has been on my \"to do\" list for a long time.  And when I heard that Perennial's Savant Blanc won a gold medal at the Great American Beer Festival this year for the American Sour ale category, I knew I had to get there to taste their award winning beer.\n\nI went the night before Thanksgiving around seven.  The bar was fairly full.  The crowd was cheery and friendly.  The bartenders were fairly knowledgable & helpful.\n\nThe beer offerings that night were each an element of a Thanksgiving dinner, for example, a Saison with a large sage presence.  It was a very creative and impressive--brewing for an event.  Since most beers take at least two weeks to move from grain to glass, brewing just for Thanksgiving was a really neat way to celebrate a wonderful holiday.\n\nI can't wait to go again."], ["So i went here probably 6 years ago and just absolutely loved the place, probably one of the best breweries i had ever been to. I was reading some of the reviews and a lot of comments said they had been slipping lately. Still wanted to go so i went, and i think they are still one of the best breweries in the area but i do feel like they have slipped a bit. Dont get me wrong, they are still really good and worth the trip, but i had to do a double take when i tried one of their beers and didnt really like it, it just seemed so out of place. Some of their stouts are amazing, i bought two to take home as well, but a pretty bland IPA and a chalky stout kinda surprised me. I hope they turn it around, but worth it regardless."], ["One of St. Louis' many great local breweries. Perennial was one of the first breweries I checked out when I moved to STL back in 2014, and it has been in my regular brewery rotation ever since. Like others have said, it is off the beaten path just a bit, but worth the the drive. The patio is nice, and they have indoor seating too usually. During the pandemic, it appeared that the main indoor space was closed, but there is a portion of their brewing quarters that they sectioned off to be covered seating. Their beers are delicious and the staff are friendly and helpful. They have a variety of styles of beer, and some more adventurous selections as well. My favorite is Daydreaming - light, floral, and fresh. Check 'em out if you haven't yet."], ["If you don't love beer or aren't game to try something new, you probably shouldn't go here. But if you DO love beer, wow, you're in for a treat.\n\nI went here on a Wednesday night (they're only open Wednesday-Saturday, I believe), and was shocked and delighted to discover beers were only $3! A lot of these beers cost $10-15 on draught at the East Coast bars where I've seen Perennial. Absolutely loved Abraxas, the Black Walnut Dunkel and the Tart Hopfentea. I think there were 8-10 beers to choose from.\n\nThe tasting menu is small and probably changes frequently, but the \"Hand Pies\" we got were incredible. Chicken, dates, nuts, and other things stuffed into a flaky, delicious crust. We were concerned about not getting enough food, but we were absolutely stuffed and couldn't clean our plates.\n\nAs for decor, it looked nice enough to me. There were dart boards and a selection of board games if you felt like doing that. The bar area was nice and there are some tables for two and a few larger ones. \n\nThe only negative was the difficulty in getting the bartender's attention, but such is the Midwest (as I've experienced it). They were really nice people and were very enthusiastic about their beers."], ["Tried out this new local brewery last night. First let me start by saying that if you are hungry, do not go here expecting great things. The food was just odd. When you go to a brewery you expect to be able to at least read the menu? I went safe and ordered a pot pie. Needless to say it was vegetarian and was deconstructed?The kitchen needs to learn the KISS motto. Keep It Simple Stupid. They are trying way to hard, and could have easily just put some burgers and apps, on the menu!\n\nAs for the beer it was good. Not great but good. Its a tough market in St Louis with so many great small breweries. Overall i would suggest you eat before you go, and swing by and grab a couple beers before heading eleswhere. Hard to understand what they are going for? It's not a bar? Its not a resturaunt? I hate to be so critical, but with such a strong craft beer market in STL the bar has been set pretty high and unfortunatley they have yet to meet it."], ["Love their beer! Smaller brewery with a relaxed atmosphere and a nice outdoor area with a firepit. Even though their food menu is pretty limited, everything we have tried has been really good."], ["Perennial needs to get its act together...of the two times we've been there, the service was abysmal (I swear the bartenders just see right through us); they ran out of pretty much all food items for sale, and the beers were just OK (there was one particular dark beer that was beyond horrible... I couldn't remember the name but reading Tom J's review below, I'm pretty sure it was the \"mint/chocolate/burnt toast abomination\" that he referred to. How could anyone serve this?\n\nI still consider this a worthy stop on a micro-brewery tour but much improvements are needed still."]], 
            "review_rating": 4.15
        }
    ]
    
    # Create database
    db_path.parent.mkdir(exist_ok=True, parents=True)
    
    with sqlite3.connect(db_path) as conn:
        # Drop existing table
        conn.execute("DROP TABLE IF EXISTS products")
        
        # Create table
        conn.execute("""
                CREATE TABLE IF NOT EXISTS products (
                    business_id TEXT PRIMARY KEY,
                    name TEXT,
                    address TEXT,
                    city TEXT,
                    state TEXT,
                    postal_code TEXT,
                    latitude REAL,
                    longitude REAL,
                    stars REAL,
                    review_count INTEGER,
                    is_open BOOLEAN,
                    categories TEXT,
                    hours TEXT,
                    text TEXT,
                    review_rating REAL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
        
        # Insert sample data
        for product in sample_products:
            conn.execute("""
                    INSERT INTO products (business_id, name, address, city, state, postal_code, latitude, longitude, stars, review_count, review_rating, is_open, hours, text, categories)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (
                    product['business_id'],
                    product['name'],
                    product['address'],
                    product['city'],
                    product['state'],
                    product['postal_code'],
                    product['latitude'],
                    product['longitude'],
                    product['stars'],
                    product['review_count'],
                    product['review_rating'],
                    product['is_open'],
                    normalize_text(product['hours']),
                    normalize_text(product['text']),
                    normalize_text(product['categories'])
                ))
        
        conn.commit()
    
    print(f"�?Created test database with {len(sample_products)} products")

def normalize_text(value):
    """Normalize text value (handle None, lists, etc.)"""
    if value is None:
        return ""
    if isinstance(value, list):
        if not value:
            return ""
        # Join list items or take first
        return " ".join(str(x) for x in value if x) if len(value) > 1 else str(value[0])
    return str(value)

